    /**
     * The real account as a replayable fixture: written next to the usage
     * log on every query, so any in-game result can be reproduced headless
     * (./gradlew query) or attached to a bug report. Local only.
     */
    void exportProfile(PlayerProfile profile) {
        var writer = new Thread(() -> {
            try {
                Path file = new File(RuneLite.RUNELITE_DIR, "loadout-lab/profile.json").toPath();
                Files.createDirectories(file.getParent());
                Files.writeString(file, profile.toJson());
            } catch (Exception ex) { log.warn("could not export the player profile", ex); }
        }, "loadout-lab-profile-export");
        writer.setDaemon(true);
        writer.start();
    }

    /** Panel hook: set (or clear, with null) the bank-highlighted item ids. */
    void setBankHighlight(Set<Integer> itemIds) {
        bankHighlight = itemIds == null || itemIds.isEmpty() || data == null ? null : equivalents(itemIds);
    }

    /** The ids plus every variant that canonicalizes with them. */
    Set<Integer> equivalents(Set<Integer> itemIds) {
        Set<Integer> expanded = new HashSet<>();
        itemIds.forEach(id -> expanded.addAll(data.equivalentIds(id)));
        return expanded;
    }

    /** Panel hook: filter the open bank to these ids via a virtual tag, and -
     * when {@code layout} is non-null - arrange the set in the bank in the
     * equipment + inventory shape (a bank-tag layout position array). */
    void setBankFilter(Set<Integer> itemIds, int[] layout) {
        if (itemIds == null || itemIds.isEmpty() || data == null) {
            bankFilter = null;
            clientThread.invokeLater(() -> {
                if (BANK_TAG.equals(bankTagsService.getActiveTag())) bankTagsService.closeBankTag();
                dropBankTag();
                forgetRememberedTab();
            });
            return;
        }
        bankFilter = equivalents(itemIds);
        clientThread.invokeLater(() -> {
            tagManager.registerTag(BANK_TAG, ii -> {
                Set<Integer> ids = bankFilter;
                return ids != null && ids.contains(ii);
            });
            if (layout != null) {
                layoutManager.saveLayout(new Layout(BANK_TAG, layout));
                ensureBankTagTab();
                bankTagsService.openBankTag(BANK_TAG, 0);
            } else {
                layoutManager.removeLayout(BANK_TAG);
                removeBankTagTab();
                bankTagsService.openBankTag(BANK_TAG, BankTagsService.OPTION_NO_LAYOUT);
            }
        });
    }

    /** The hub "Bank Tag Layouts" plugin's config coordinates - kept only to
     * clean up the layout its auto-enable wrote for our tag before the
     * real-tab fix below existed. */
    static final String BTL_GROUP = "banktaglayouts";
    static final String BTL_LAYOUT_KEY = "layout_" + BANK_TAG;
    /** The filter tab's icon in the bank's tag strip (rune scimitar). */
    static final int BANK_TAB_ICON = 1333;

    /** With Bank Tag Layouts running, our tag must exist as a REAL tag tab
     * while the filter is on: BTL only defers to the core bank-tags layout
     * for a tab it can find (isVanillaLayoutEnabled = a TagTab AND a core
     * layout), and with "layout enabled by default" on it auto-enables its
     * own flat layout over any purely virtual tag every bank rebuild
     * (field-found 2026-07-20: the cross rendered flat under it; a config
     * mirror lost the write war). Inventory Setups escapes via a hardcoded
     * _invsetup_ prefix exemption; a real tab is the road for everyone else.
     *
     * IN-MEMORY ONLY - deliberately no TabManager.save(): save() rewrites
     * the user's whole tagtabs config from the in-memory list, which would
     * WIPE their real tabs if the list isn't loaded yet. BTL's find() and
     * the tab strip both read the live list, so persistence buys nothing;
     * the bank-build hook below re-adds it whenever core reloads the list. */
    void ensureBankTagTab() {
        if (!pluginEnabled("Bank Tag Layouts") || tabManager.find(BANK_TAG) != null) return;
        var tab = new TagTab();
        tab.setTag(BANK_TAG);
        tab.setIconItemId(BANK_TAB_ICON);
        tabManager.add(tab);
    }

    void removeBankTagTab() {
        if (tabManager.find(BANK_TAG) != null) tabManager.remove(BANK_TAG);
    }

    /** The virtual tag's layout, tab and registration all go (shutdown
     * and the filter-clear share it). */
    void dropBankTag() {
        layoutManager.removeLayout(BANK_TAG);
        removeBankTagTab();
        tagManager.unregisterTag(BANK_TAG);
    }

    /** Core bank-tags "Remember tab" reopens the last active tag at the
     * next bank open - across sessions our virtual tag then leads to
     * NOTHING (no filter registered yet; field bug 2026-07-21). Forgotten
     * whenever a session starts and whenever the filter clears. */
    void forgetRememberedTab() {
        if (BANK_TAG.equals(configManager.getConfiguration("banktags", "tab"))) {
            configManager.setConfiguration("banktags", "tab", "");
        }
    }

    /** Re-assert the real tab on every bank build while the filter is on.
     * Two hooks because BTL applies its layout at PostFired(BANKMAIN_BUILD,
     * priority -1): the PostFired hook at -0.5 slots BETWEEN core's handlers
     * (0) and BTL's apply (-1) - the decisive ordering on the first build
     * after a bank open, where core's BANKMAIN_INIT reload has just wiped
     * the in-memory list. The FINISHBUILDING hook covers rebuild variants.
     * (Priority-after-core precedent: Inventory Setups.) */

    @Subscribe(priority = -1)
    public void onScriptPreFired(ScriptPreFired event) {
        if (event.getScriptId() != ScriptID.BANKMAIN_FINISHBUILDING || !BANK_TAG.equals(bankTagsService.getActiveTag())) {
            return;
        }
        if (bankFilter == null) {
            // A remembered-tab ghost: our tag is open with no filter
            // registered - it shows an empty bank (field bug 2026-07-21).
            bankTagsService.closeBankTag();
            return;
        }
        ensureBankTagTab();
    }

    @Subscribe(priority = -0.5f)
    public void onScriptPostFired(ScriptPostFired event) {
        if (event.getScriptId() == ScriptID.BANKMAIN_BUILD && bankFilter != null && BANK_TAG.equals(bankTagsService.getActiveTag())) {
            ensureBankTagTab();
        }
    }

    /** Roster mirror of compute: same client-thread staging, then
     * ONE shared set per style across the mobs (bestPerStyleAcross). Each
     * member's own profile travels keyed by profileId: exclusions, sims,
     * pins, the pinned spell and the pinned spec (the first member's spec
     * is the roster's shared spec). */

    /** Client-thread staging shared by both computes: the profile snapshot,
     * the DWMS re-read, levels, the one owned-items merge and its presence
     * fingerprint (the optimizer cache keys on presence, not quantities). */
    class Staging {
        final RequirementProfile profile;
        final PlayerLevels live;
        final PlayerLevels real;
        final Map<Integer, Integer> mergedOwned;
        final OwnedItems owned;
        final int fingerprint;
        final PrayerUnlocks unlocks;

        Staging(ComputeParams p) {
            if (client.getGameState() == GameState.LOGGED_IN) snapshotProfileIfNeeded();
            if (config.useDwmsData()) requestDwmsStorages();
            RequirementProfile known = requirementProfile != null ? requirementProfile : RequirementProfile.MAXED;
            PlayerLevels mine = realLevels != null ? realLevels : PlayerLevels.MAXED;
            // The stat sim (ISS-01M5QY13K6YHTYDW1CCYD30CSY): simmed levels stand
            // in for yours everywhere - the maths, the live boosts (not stacked
            // on a sim), and the gear you can wear.
            boolean simmed = p != null && p.simLevels != null;
            real = simmed ? mine.overridden(p.simLevels) : mine;
            live = simmed ? real : boostedLevels != null ? boostedLevels : PlayerLevels.MAXED;
            RequirementProfile gear = simmed ? known.withLevels(real) : known;
            profile = p != null && p.simMaxCape ? gear.waiving(MaxCapeSims.ids(data, LoadoutLabPlugin.this::ownsOrSimmed)) : gear;
            pushPanelCastState(live);
            potionStorage = PotionStorage.owned(client::getVarbitValue);
            supplyUnlocks = TripSupplies.unlocked(client::getVarbitValue);
            mergedOwned = ownedItems();
            // What is at hand, so a same-stats item in the bank beats its twin
            // in the costume room (Andrew 2026-10-27).
            Set<Integer> atHand = new HashSet<>(ledger.snapshot(EQUIPMENT).keySet());
            atHand.addAll(ledger.snapshot(INVENTORY).keySet());
            atHand.addAll(ledger.snapshot(BANK).keySet());
            owned = new OwnedItems(mergedOwned, ledger.bankKnown(), atHand);
            fingerprint = data.chargeFreeFingerprint(mergedOwned);
            unlocks = prayerUnlocks != null ? prayerUnlocks : PrayerUnlocks.ALL;
        }
    }

    public void computeRoster(List<MonsterStats> mobs, ComputeParams p, Runnable od) {
        clientThread.invokeLater(() -> {
            var s = new Staging(p);
            Map<Integer, Map<CombatStyle, Map<GearSlot, Integer>>> pbm = new HashMap<>();
            Map<Integer, SpellStats> spellByMob = new HashMap<>();
            Map<Integer, Integer> sbm = new HashMap<>();
            for (MonsterStats mob : mobs) {
                int id = mob.profileId();
                pbm.put(id, pinnedByStyle(mob, id, p.onSlayerTask));
                spellByMob.put(id, resolvedPinnedSpell(id));
                sbm.put(id, mobProfiles.pinnedSpec(id));
            }
            optimizerService.bestPerStyleAcross(mobs, s.real, s.live, s.unlocks, s.profile, s.owned, s.fingerprint, p,
                excludedByStyle(-1), withMaxCape(p, dreams.snapshot()), perMobExclusions(mobs),
                perMobSims(mobs), pbm, spellByMob, sbm, protectOnly.snapshot(), roster -> invokeLater(() -> {
                    // EDT-only page assembly: it reads the ledger, profile
                    // and config stores the client thread writes (deadlock
                    // report 2026-08-12 - the callback thread had been
                    // building pages under their locks).
                    CommandEngine engine = commandEngine;
                    if (engine != null) {
                        engine.onRosterResults(roster.mobs, roster.perMob, roster.groupBook, roster.groupBookReason);
                        refreshHostedView();
                    }
                    od.run();
                }));
        });
    }

    public void compute(MonsterStats monster, ComputeParams p, Runnable od) {
        clientThread.invokeLater(() -> {
            // DWMS saves on its own cadence (ConfigSync/shutdown); the staging
            // re-read keeps imported storages as fresh as they can be (its
            // reply lands after this compute - one-query lag).
            var s = new Staging(p);
            exportProfile(new PlayerProfile( s.real, s.live, s.unlocks, s.profile, s.mergedOwned, ledger.bankKnown(), ownedBySources()));
            optimizerService.bestPerStyle(monster, s.real, s.live, s.unlocks, s.profile, s.owned, s.fingerprint, p,
                excludedByStyle(monster.id), withMaxCape(p, dreamsWithMobSims(monster)),
                pinnedByStyle(monster, monster.id, p.onSlayerTask), resolvedPinnedSpell(monster.id),
                mobProfiles.pinnedSpec(monster.id), protectOnly.snapshot(), results -> invokeLater(() -> {
                    CommandEngine engine = commandEngine;
                    if (engine != null) {
                        engine.onResults(monster, results);
                        refreshHostedView();
                    }
                    od.run();
                }));
        });
    }

    /** The one-surface mount: Core's single nav slot hosts the
     * model-driven surface. */
    void refreshHostedView() {
        invokeLater(() -> {
            if (navButton == null || companionHost == null || internalSurface == null) {
                return; // still loading
            }
            try {
                companionHost.mount(internalSurface.asFunction().apply( companionLink == null ? null : companionLink.lastPage()));
            } catch (RuntimeException ex) { log.warn("renderer failed; keeping the previous content", ex); }
        });
    }

    /** VarbitID.SPELLBOOK values -> the contract's book names. */
    static String spellbookName(int varbit) {
        switch (varbit) {
            case 1: return "ancient";
            case 2: return "lunar";
            case 3: return "arceuus";
            default: return "standard";
        }
    }

    /** The book plate reacts LIVE to a spellbook swap (classic field
     * bug 2026-07-21: the chip stayed red after swapping). */
    @Subscribe
    public void onVarbitChanged(VarbitChanged event) {
        if (PotionStorage.tracks(event.getVarbitId())) {
            potionStorage = PotionStorage.owned(client::getVarbitValue);
            ledgerRecomputeTicks = 5;
            return;
        }
        if (event.getVarbitId() != SPELLBOOK) return;
        CommandEngine engine = commandEngine;
        if (engine != null) engine.setLiveSpellbook(spellbookName(event.getValue()));
    }

    /** The classic provenance memo (rebuilt only when ownership moves):
     * an item's primary storage NAME when a fetch trip is needed, "" at
     * hand - the source dots key off it. */
    volatile ItemLocations cachedLocations;
    volatile int cachedLocationsFingerprint;

    String primaryLocationOf(int ii) {
        if (ledger == null || dwmsLink == null) return "";
        int fingerprint = ownedFingerprint();
        ItemLocations found = cachedLocations;
        if (found == null || cachedLocationsFingerprint != fingerprint) {
            found = new ItemLocations(ownedBySources(), data == null ? null : data::equivalentIds);
            cachedLocations = found;
            cachedLocationsFingerprint = fingerprint;
        }
        String where = found.primary(ii);
        return where == null ? "" : where;
    }

    /** Client-thread only. Quest scan is the expensive part - done once per login. */
    void snapshotProfileIfNeeded() {
        if (requirementProfile != null && boostedLevels != null && realLevels != null) return;
        Map<Skill, Integer> real = new EnumMap<>(Skill.class);
        Map<Skill, Integer> boosted = new EnumMap<>(Skill.class);
        for (Skill skill : Skill.values()) {
            real.put(skill, client.getRealSkillLevel(skill));
            boosted.put(skill, client.getBoostedSkillLevel(skill));
        }
        // Canary: real Hitpoints can never be below 10. A sub-10 read means
        // the client stats were not populated yet (login race) - skip the
        // snapshot so the next compute retries, instead of poisoning every
        // number this session (field report: all magic at 0.06 dps).
        if (real.getOrDefault(Skill.HITPOINTS, 0) < 10) return;
        // Stronger canary: stats stream in Skill-ordinal order at login, so a
        // fast first search can catch attack/str/def/hp populated while
        // ranged/prayer/magic still read 1 - and the HP check above passes.
        // The client's own total level is authoritative: a partial snapshot
        // always sums BELOW it (field report: ranged/magic/prayer poisoned
        // at 1 -> blisterwood-stake ranged picks and Wind Strike autocasts).
        if (real.values().stream().mapToInt(Integer::intValue).sum() < client.getTotalLevel()) return;
        Set<String> quests = Arrays.stream(Quest.values()).filter(quest -> quest.getState(client) == QuestState.FINISHED)
            .map(Enum::name).collect(Collectors.toSet());
        requirementProfile = new RequirementProfile(real, quests);
        realLevels = PlayerLevels.from(real);
        boostedLevels = PlayerLevels.from(boosted);
        if (commandEngine != null) {
            commandEngine.setLevels(realLevels); // the stat sim's boxes default to these
        }
        // Unlock-gated prayers: King's Ransom for Piety/Chivalry; scroll
        // unlock varbits for Rigour/Augury (CoX), Deadeye/Mystic Vigour
        // and Zeal (16578 = PRAYER_ZEAL_UNLOCKED).
        prayerUnlocks = new PrayerUnlocks( quests.contains(Quest.KINGS_RANSOM.name()), client.getVarbitValue(5451) == 1,
            client.getVarbitValue(5452) == 1, client.getVarbitValue(16097) == 1, client.getVarbitValue(16098) == 1,
            client.getVarbitValue(16578) == 1);
        snapshotAccount = client.getAccountHash();
    }

    // ------------------------------------------------------------------

    /**
     * Persistence scope: world type PLUS the account hash - two accounts
     * on standard worlds must never share a scanned bank (field report:
     * switching characters showed the previous character's gear).
     */
    /** Point every per-character store at the current account. ONE place, so a
     *  store added later cannot be wired into two of the three call sites and
     *  silently stay global on the third - which is how the exclude/sim lists
     *  ended up shared across characters (field report 2026-08-25). */
    void loadAllScopes() {
        String scope = worldScope();
        if (scope == null) {
            // LOGGED_IN fires before getAccountHash() is populated. Reloading
            // now would swap every store onto a hash-less bucket and drop
            // whatever the player just added (field report 2026-08-26); the
            // stores keep the last known character until the hash arrives.
            return;
        }
        for (ScopedStore store : stores) store.loadScope(scope);
    }

    /** Every per-character store, ONE list (loadAllScopes, the profile
     * reload and the reset all walk it); empty until startUp builds them. */
    ScopedStore[] stores = {};

    String worldScope() {
        long account = client.getAccountHash();
        if (account == -1) return null;
        String world = client.getWorldType().contains(WorldType.SEASONAL) ? "seasonal" : "std";
        return world + "." + account;
    }

    /** True only when logged in to a non-members world - the F2P filter default. */
    boolean onF2pWorld() {
        return client.getGameState() == GameState.LOGGED_IN && !client.getWorldType().contains(WorldType.MEMBERS);
    }

    @Provides
    LoadoutLabConfig provideConfig(ConfigManager configManager) {
        return configManager.getConfig(LoadoutLabConfig.class);
    }
}

package com.loadoutlab;
import java.util.regex.Pattern;
import java.util.regex.Matcher;
import java.nio.charset.StandardCharsets;
import java.io.InputStream;


/** The build-stamped plugin version (processResources writes
 * version.properties; VersionStampTest pins it to the hub manifest).
 * Neutral home - the report builder, seam hello and UIs all read it. */
public class PluginVersion {
    /** Bumped with every release (VersionStampTest pins it to build.gradle):
     * hub builds ship the resource unexpanded, so this is what players see. */
    public static final String FALLBACK = "0.7.1";
    public static final String VERSION = load();

    public static String stamp(String properties) {
        Matcher m = Pattern.compile("version=(\\S+)").matcher(properties);
        return m.find() && !m.group(1).contains("${") ? m.group(1) : FALLBACK;
    }


    static String load() {
        try (InputStream in = PluginVersion.class.getResourceAsStream( "/com/loadoutlab/version.properties")) {
            return stamp(new String(in.readAllBytes(), StandardCharsets.UTF_8));
        } catch (Exception ex) { return "unknown"; }
    }
}

package com.loadoutlab;

import com.google.gson.*;
import com.loadoutlab.data.*;
import com.loadoutlab.engine.*;
import java.io.IOException;
import java.util.*;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.util.LinkBrowser;
import okhttp3.*;
import static com.loadoutlab.data.JsonResources.*;

/**
 * One-click "open this exact setup in the official wiki calculator":
 * builds the calculator's ImportableData shape from a shown result, POSTs
 * it to the wiki's shortlink service (the same endpoint the calculator's
 * own Share button uses - the ONLY way a full setup can ride a URL), and
 * opens {@code ?id=<shortlink>}. Strictly user-initiated; shapes verified
 * against weirdgloop/osrs-dps-calc source 2026-07-23 (IMPORT_VERSION 10).
 */
@Slf4j
@lombok.AllArgsConstructor
public class WikiCalcLink {
    static final String SHORTLINK_API = "https://tools.runescape.wiki/osrs-dps/shortlink";
    static final String CALC_URL = "https://tools.runescape.wiki/osrs-dps/?id=";

    /** Their Prayer enum ordinals by the tier names our labels use, and
     * their Potion enum ordinals by OUR boost labels (the calculator has
     * no divine variants - identical numbers - so divines map to the
     * base). Data-driven from wiki_calc_ids.json (a token-free resource).
     * Fail SOFT like AssumeIcons: this class is constructed in startUp, so
     * a static-init throw would kill the whole plugin over a share button;
     * WikiCalcLinkTest pins the exact ordinals loudly instead. */
    static final Map<String, Integer> PRAYER_IDS = new LinkedHashMap<>();
    static final Map<String, int[]> POTION_IDS = new LinkedHashMap<>();

    static {
        JsonObject root = object("wiki_calc_ids.json");
        stringIntMap(root, "prayerIds", PRAYER_IDS);
        JsonObject potions = root == null ? null : root.getAsJsonObject("potionIds");
        for (String label : potions == null ? Set.<String>of() : potions.keySet()) {
            POTION_IDS.put(label, ints(potions.getAsJsonArray(label)));
        }
    }

    final OkHttpClient http;
    final Gson gson;

    /** POST the setup to the shortlink service, then open the calculator
     * on the returned id. Fire-and-forget; failures only log. */
    public void open(MonsterStats mob, DpsResult shown, int dartId, String assumes,
        PlayerLevels real, PlayerLevels live, boolean onSlayerTask, boolean inWilderness) {
        Map data = payload(mob, shown, dartId, assumes, real, live, onSlayerTask, inWilderness);
        Request request = new Request.Builder() .url(SHORTLINK_API)
            .post(RequestBody.create(MediaType.parse("application/json"), gson.toJson(data))) .build();
        http.newCall(request).enqueue(new Callback() {
            public void onFailure(Call call, IOException e) { log.warn("wiki calc shortlink failed", e); }

            public void onResponse(Call call, Response response) throws IOException {
                try (Response r = response) {
                    if (!r.isSuccessful() || r.body() == null) {
                        log.warn("wiki calc shortlink HTTP {}", r.code());
                        return;
                    }
                    JsonObject body = gson.fromJson(r.body().string(), JsonObject.class);
                    if (body == null || !body.has("data")) {
                        log.warn("wiki calc shortlink: unexpected response shape");
                        return;
                    }
                    LinkBrowser.browse(CALC_URL + body.get("data").getAsString());
                }
            }
        });
    }

    /** The ImportableData document, built pure for testability. */
    static Map payload(MonsterStats mob, DpsResult shown, int dartId,
        String assumes, PlayerLevels real, PlayerLevels live, boolean onSlayerTask, boolean inWilderness) {
        List<Integer> prayers = new ArrayList<>();
        BoostProfile boost = null;
        List<Integer> potions = new ArrayList<>();
        for (String token : (assumes == null ? "" : assumes).split(" \\+ ")) {
            Integer prayerId = PRAYER_IDS.get(token);
            if (prayerId != null) {
                prayers.add(prayerId);
                continue;
            }
            for (int id : POTION_IDS.getOrDefault(token, new int[0])) potions.add(id);
            for (BoostProfile profile : BoostProfile.values()) {
                if (profile.toString().equals(token)) boost = profile;
            }
        }

        Map equipment = new LinkedHashMap<>();
        GearItem quiverAmmo = shown.loadout.quiverAmmo;
        for (GearSlot slot : GearSlot.values()) {
            GearItem worn = shown.loadout.get(slot);
            // The calc has no quiver concept: the bolts the quiver carries
            // must ride the AMMO slot or their side prices an empty
            // crossbow (field report 2026-08-21). The displaced blessing
            // only carries prayer bonus - nothing the dps math reads.
            if (slot == GearSlot.AMMO && quiverAmmo != null) worn = quiverAmmo;
            int id = worn != null ? worn.id : -1;
            if (id > 0) {
                // Plain maps/lists ONLY in this document (JsonResources.map
                // is a LinkedHashMap): gson's map adapter reflects the
                // runtime type, and the JDK's private
                // Collections$*/ImmutableCollections classes throw
                // InaccessibleObjectException under the module system
                // (field-found 2026-07-23 - the button silently died).
                Map idMap = map("id", id);
                if (slot == GearSlot.WEAPON && dartId > 0) {
                    // The blowpipe's dart rides the WEAPON's itemVars -
                    // never the ammo slot (their own harness note: an
                    // ammo-slot dart is a hand-thrown weapon; and the
                    // blessing usually occupies ammo anyway, so the dart
                    // silently vanished - field report 2026-08-21: cow
                    // showed a dartless max 20 vs our dragon-dart 28).
                    idMap.put("itemVars", map("blowpipeDartId", dartId));
                }
                equipment.put(slot.jsonName, idMap);
            }
        }

        Map buffs = map("potions", potions, "onSlayerTask", onSlayerTask, "inWilderness", inWilderness);
        GearItem soulWeapon = shown.loadout.getWeapon();
        if (soulWeapon != null && soulWeapon.nameLower.contains("soulreaper")) {
            // Our sustained model prices the 5-stack steady state - the
            // calc must open there too or it prices ZERO stacks (field
            // 2026-08-21: Jad BiS -23%).
            buffs.put("soulreaperStacks", 5);
        }
        Map loadout = map("name", "Loadout Lab", "skills", skillsMap(real),
            "boosts", boostsMap(boost, real, live), "equipment", equipment, "prayers", prayers, "buffs", buffs);
        Map<String, String> style = styleOf(shown.attackType);
        String spell = shown.getSpellName();
        if (style != null && "Autocast".equals(style.get("stance")) && (spell == null || spell.isEmpty())) {
            // A powered staff: its attackType wears the "magic: <name>"
            // prefix like an autocast, but their POWERED_STAFF category
            // has no Autocast stance - the import fell back to LONGRANGE,
            // 5 ticks (field report 2026-08-21: trident vs cow showed
            // exactly 4/5 of our dps). A real autocast always carries a
            // spell name; a powered staff never does.
            style.put("stance", "Accurate");
        }
        if (style != null) loadout.put("style", style);
        if (spell != null && !spell.isEmpty()) loadout.put("spell", map("name", spell));

        Map inputs = map("defenceReductions", new LinkedHashMap<>());
        if (mob.getToaInvocationLevel() > 0) {
            // The card's Invocation chip - the calculator must open at the
            // same raid level or the cross-check numbers cannot match.
            inputs.put("toaInvocationLevel", mob.getToaInvocationLevel());
        }
        // profileId: a group's synthetic phase variant maps back to the
        // real row - the calculator only knows real npc ids. The RAW wiki
        // version - their import keys on exact strings from the shared
        // weirdgloop data ("Post-quest, Awake") and silently falls back to
        // the FIRST same-id row on a miss (field 2026-08-21: the post-quest
        // Duke opened as Awakened, def 316 vs 275 - a -24% phantom). Our
        // display labels are normalized and must never travel.
        Map monster = map("id", mob.profileId(), "version", mob.getWikiVersion(), "inputs", inputs);
        List<Map> loadouts = new ArrayList<>();
        loadouts.add(loadout);
        return map("serializationVersion", 10, "loadouts", loadouts, "selectedLoadout", 0, "monster", monster);
    }

    /** Their PlayerSkills shape. Mining/herblore are not tracked here -
     * 99 keeps the rare pickaxe-dependent checks permissive. */
    static Map skillsMap(PlayerLevels levels) {
        return map("atk", levels.attack, "str", levels.strength, "def", levels.defence,
            "hp", levels.hitpoints, "ranged", levels.ranged, "magic", levels.magic,
            "prayer", levels.prayer, "mining", 99, "herblore", 99);
    }

    /** The per-skill boost DELTAS the calculator adds to the base skills -
     * computed from our own boost model so the math matches exactly. */
    static Map boostsMap(BoostProfile boost, PlayerLevels real, PlayerLevels live) {
        PlayerLevels boosted = boost == null ? real : boost.apply(real, live);
        return map("atk", boosted.attack - real.attack,
            "str", boosted.strength - real.strength, "def", boosted.defence - real.defence,
            "hp", 0, "ranged", boosted.ranged - real.ranged, "magic", boosted.magic - real.magic,
            "prayer", 0, "mining", 0, "herblore", 0);
    }

    /** Their PlayerCombatStyle {type, stance} from our attack-type strings:
     * "slash (aggressive)", "ranged rapid - dragon dart", "magic: Fire
     * Surge". The style NAME is omitted - the calculator's math reads only
     * type and stance. */
    static Map<String, String> styleOf(String attackType) {
        if (attackType == null || attackType.isEmpty()) return null;
        Map<String, String> style = new LinkedHashMap<>();
        if (attackType.startsWith("magic")) {
            style.put("type", "magic");
            style.put("stance", attackType.startsWith("magic:") ? "Autocast" : "Accurate");
            return style;
        }
        if (attackType.startsWith("ranged")) {
            style.put("type", "ranged");
            style.put("stance", attackType.contains("rapid") ? "Rapid" : "Accurate");
            return style;
        }
        int cut = attackType.indexOf(" (");
        style.put("type", cut < 0 ? attackType : attackType.substring(0, cut));
        String stance = cut < 0 ? "aggressive" : attackType.substring(cut + 2, attackType.indexOf(')', cut));
        style.put("stance", Names.cap(stance));
        return style;
    }
}

package com.loadoutlab.collection;

import com.google.gson.Gson;
import com.google.gson.reflect.TypeToken;
import java.util.*;
import net.runelite.client.config.ConfigManager;

/**
 * The GLOBAL always-filter list (the grey member of the exclude/sim/filter
 * trio, field spec 2026-07-20): items that join EVERY filtered bank view -
 * teleport capes, boss teles, whatever the player always wants at hand.
 * Names are captured at add time (id resolution later needs the client
 * thread), matching the mob-profile filter items. Per character since
 * 0.4.1 (a main and a test account had shared this list).
 */
public class AlwaysFilterStore extends ScopedMapStore<Integer, String> {
    static final String KEY = "alwaysFilterItems";

    public AlwaysFilterStore(ConfigManager configManager, Gson gson) {
        super(configManager, gson, KEY, new TypeToken<Map<Integer, String>>(){}.getType());
    }

    public synchronized Map<Integer, String> all() { return new LinkedHashMap<>(items); }

    public synchronized void add(int itemId, String name) {
        items.put(itemId, name == null ? ("item " + itemId) : name);
        save();
    }

    public synchronized void remove(int itemId) {
        items.remove(itemId);
        save();
    }
}

package com.loadoutlab.collection;

import com.google.gson.Gson;
import com.google.gson.reflect.TypeToken;
import java.util.*;
import net.runelite.api.gameval.InventoryID;
import net.runelite.client.config.ConfigManager;

/**
 * The persistent "what I own" ledger - Loadout Lab's first differentiator.
 *
 * <p>Container snapshots (equipment, inventory, bank, looting bag), each
 * replaced wholesale when its container is seen, merged on demand into one
 * itemId → quantity view. Persisted through RuneLite's ConfigManager so the
 * ledger survives sessions: your bank from LAST visit still counts today,
 * no re-scan required (unlike per-session scanners).
 *
 * <p>Scoping: RuneLite config profiles already isolate the backing
 * .properties per profile; on top of that, keys carry a world-type prefix so
 * a leagues/seasonal login never pollutes the standard-world ledger.
 *
 * <p>Write discipline (learned on goal-planner): saves are per-snapshot and
 * only when that snapshot actually changed - callers coalesce container
 * events per tick before calling {@link #update}.
 *
 * <p>Item ids are stored RAW. Variant canonicalization (degraded/charged
 * forms mapping to the engine's canonical gear ids via equipment aliases)
 * happens at query time once the data pipeline vendors the alias table.
 */
public class CollectionLedger implements ScopedStore {
    static final String CONFIG_GROUP = "loadoutlab";
    static final TypeToken<Map<Integer, Integer>> MAP_TYPE = new TypeToken<Map<Integer, Integer>>() {};

    /** Ledger sources, each persisted under its own key. */
    @lombok.RequiredArgsConstructor
    public enum Source {
        EQUIPMENT("equipment", net.runelite.api.InventoryID.EQUIPMENT.getId()),
        INVENTORY("inventory", net.runelite.api.InventoryID.INVENTORY.getId()), BANK("bank", net.runelite.api.InventoryID.BANK.getId()),
        /** Seen when the bag is opened or checked; vital for UIM accounts.
         * The classic InventoryID enum lacks the newer containers; the
         * gameval ids are the authoritative modern constants. */
        LOOTING_BAG("lootingBag", InventoryID.LOOTING_BAG),
        /** POH costume storage: one shared container covering the armour
         * case, wardrobes, treasure chest, and cape rack, seen when a
         * costume storage interface is opened. */
        POH_COSTUMES("pohCostumes", InventoryID.POH_COSTUMES),
        /** Not container-backed: filled units' default items, read from
         * the STASH chart (see LoadoutLabPlugin.scanStashChart). The -1
         * container sentinel makes the per-tick drain's null-container
         * check clear a stray dirty flag, and keeps STASH out of the
         * {@link #forContainer} reverse lookup. */
        STASH("stash", -1),
        /** The rune pouch: varbit-backed (RunePouchScan), never a container. */
        RUNE_POUCH("runePouch", -1),
        /** Sailing boat cargo holds, one container per boat slot. */
        CARGO_HOLD_1("cargoHold1", InventoryID.SAILING_BOAT_1_CARGOHOLD), CARGO_HOLD_2("cargoHold2", InventoryID.SAILING_BOAT_2_CARGOHOLD),
        CARGO_HOLD_3("cargoHold3", InventoryID.SAILING_BOAT_3_CARGOHOLD), CARGO_HOLD_4("cargoHold4", InventoryID.SAILING_BOAT_4_CARGOHOLD),
        CARGO_HOLD_5("cargoHold5", InventoryID.SAILING_BOAT_5_CARGOHOLD);

        final String key;
        final int containerId;

        /** The item-container id this source is scanned from, or -1 when
         * the source is not container-backed (STASH). */
        public int containerId() { return containerId; }

        /**
         * Reverse lookup: the source scanned from {@code containerId}, or
         * null when no source uses it. Callers pass an UNMASKED container
         * id (the 0x8000 modified-container bit already stripped).
         */
        public static Source forContainer(int containerId) {
            // Guard the STASH sentinel: without it, -1 would resolve to
            // STASH instead of "no such container".
            return containerId < 0 ? null : Arrays.stream(values()).filter(s -> s.containerId == containerId).findFirst().orElse(null);
        }

        /** The persisted config-key segment; also the storage name in the
         * storages-response PluginMessage (see StoragesApi). */
        public String key() { return key; }
    }

    final ConfigManager configManager;
    final Gson gson;

    /** "std" or "seasonal" - set on login before any update/load. */
    String worldScope = "std";

    final Map<Source, Map<Integer, Integer>> snapshots = new HashMap<>();

    /** Cached fingerprint of the merged view; recomputed lazily. */
    transient Integer fingerprint;

    public CollectionLedger(ConfigManager configManager, Gson gson) {
        this.configManager = configManager;
        this.gson = gson;
        for (Source s : Source.values()) snapshots.put(s, new HashMap<>());
    }

    /**
     * Point the ledger at a world scope ("std" or "seasonal") and load that
     * scope's persisted snapshots, replacing in-memory state.
     */
    public void loadScope(String scope) {
        worldScope = scope;
        for (Source s : Source.values()) {
            // One-time adoption of pre-account-scoping data ("std.*"): the
            // FIRST character to load it takes it and the legacy entry is
            // removed. Copying instead of moving is what let a second account
            // open on the main's scanned bank (field report 2026-08-26).
            // A corrupt entry starts that snapshot fresh rather than failing.
            int dot = scope.indexOf('.');
            String legacy = (dot > 0 ? scope.substring(0, dot) : scope) + ".collection." + s.key;
            Map<Integer, Integer> loaded = ScopedKeys.parse(gson,
                ScopedKeys.adopt(configManager, CONFIG_GROUP, key(s), legacy), MAP_TYPE.getType());
            snapshots.put(s, loaded != null ? loaded : new HashMap<>());
        }
        fingerprint = null;
    }

    /**
     * Replace one source's snapshot. Persists only when the content actually
     * changed; returns true in that case (callers use it to invalidate caches).
     */
    public boolean update(Source source, Map<Integer, Integer> items) {
        Map<Integer, Integer> next = new HashMap<>(items);
        if (next.equals(snapshots.get(source))) return false;
        snapshots.put(source, next);
        configManager.setConfiguration(CONFIG_GROUP, key(source), gson.toJson(next, MAP_TYPE.getType()));
        fingerprint = null;
        return true;
    }

    /** One source's current snapshot, read-only (itemId → quantity). */
    public Map<Integer, Integer> snapshot(Source source) { return Collections.unmodifiableMap(snapshots.get(source)); }

    /** Merged itemId → total quantity across all sources. */
    public Map<Integer, Integer> owned() {
        Map<Integer, Integer> merged = new HashMap<>();
        snapshots.values().forEach(snap -> snap.forEach((id, n) -> merged.merge(id, n, Integer::sum)));
        return merged;
    }

    /** True once a bank snapshot exists (this session or any previous one). */
    public boolean bankKnown() { return !snapshots.get(Source.BANK).isEmpty(); }

    /**
     * Stable fingerprint of the merged view - the optimizer cache key
     * component. Changes iff ownership actually changed.
     */
    public int fingerprint() {
        if (fingerprint == null) fingerprint = owned().hashCode();
        return fingerprint;
    }

    String key(Source s) { return worldScope + ".collection." + s.key; }
}

package com.loadoutlab.collection;

import lombok.Getter;
import java.util.*;

/**
 * Live link to "Dude, Where's My Stuff?" over RuneLite's PluginMessage
 * bus (DWMS ships the contract since 2.11.5 - the old best-effort config
 * read is retired).
 *
 * <p>Contract (version 1, authored upstream): we post a request
 * (namespace "dudewheresmystuff", name "storages-request", data
 * {"source": "Loadout Lab"}); DWMS replies with "storages-response"
 * carrying "target" (our source echoed back - responses meant for other
 * plugins are ignored), "version" and "storages", a list of maps with
 * "category"/"name"/"lastUpdated" plus "items" ({"id": canonical item
 * id, "quantity"}). Requests are fire-and-forget: an absent or older
 * DWMS never replies and {@link #isLive()} stays false - its storages
 * then simply do not count as owned.
 *
 * <p>Responses arrive on DWMS's client thread; parsing is defensive
 * (drop, never guess) and the snapshot swap is a volatile write, so no
 * marshalling is needed here.
 */
public class DwmsLink {
    /** PluginMessage namespace = DWMS's config group, per RuneLite convention. */
    public static final String DWMS_NAMESPACE = "dudewheresmystuff";
    public static final String REQUEST_NAME = "storages-request";
    public static final String RESPONSE_NAME = "storages-response";
    /** The one contract version this consumer understands; anything else
     * is rejected so the fallback under-counts rather than miscounts. */
    static final int SUPPORTED_VERSION = 1;
    /** Our display name - sent as "source", echoed back as "target". */
    static final String SOURCE = "Loadout Lab";

    volatile Map<Integer, Integer> items = Map.of();
    /** Response "category" (carryable/death/poh/stash/world...) -> items -
     * the location-hint provenance families. */
    volatile Map<String, Map<Integer, Integer>> families = Map.of();
    /** True once DWMS has answered for the current identity. */
    @Getter
    volatile boolean live;

    /** The request payload for PluginMessage(DWMS_NAMESPACE, REQUEST_NAME, ...). */
    public static Map request() { return Collections.singletonMap("source", SOURCE); }

    /**
     * Consume a candidate storages-response payload (namespace/name gating
     * happens at the caller). Returns true - and replaces the snapshot -
     * only for a well-formed version-1 response addressed to us.
     */
    public boolean accept(Map data) {
        if (data == null || !SOURCE.equals(data.get("target")) || !(data.get("version") instanceof Number)
            || ((Number) data.get("version")).intValue() != SUPPORTED_VERSION || !(data.get("storages") instanceof List)) {
            return false;
        }
        Map<Integer, Integer> next = new HashMap<>();
        Map<String, Map<Integer, Integer>> nextFamilies = new HashMap<>();
        for (Object storage : (List<?>) data.get("storages")) {
            if (!(storage instanceof Map)) continue;
            Object storageItems = ((Map<?, ?>) storage).get("items");
            if (!(storageItems instanceof List)) continue;
            Object category = ((Map<?, ?>) storage).get("category");
            Map<Integer, Integer> family = nextFamilies.computeIfAbsent(
                category instanceof String ? (String) category : "world", k -> new HashMap<>());
            for (Object item : (List<?>) storageItems) {
                mergeItem(item, next);
                mergeItem(item, family);
            }
        }
        items = next.isEmpty() ? Map.of() : next;
        families = nextFamilies.isEmpty() ? Map.of() : nextFamilies;
        live = true;
        return true;
    }

    /** One {"id", "quantity"} entry; anything malformed is dropped. */
    static void mergeItem(Object item, Map<Integer, Integer> into) {
        if (!(item instanceof Map)) return;
        Object id = ((Map<?, ?>) item).get("id");
        Object quantity = ((Map<?, ?>) item).get("quantity");
        if (!(id instanceof Number) || !(quantity instanceof Number)) return;
        int itemId = ((Number) id).intValue();
        long amount = ((Number) quantity).longValue();
        if (itemId <= 0 || amount <= 0) return;
        into.merge(itemId, (int) Math.min(amount, Integer.MAX_VALUE), (a, b) -> (int) Math.min((long) a + b, Integer.MAX_VALUE));
    }

    /** A different account/profile: nothing from the previous one survives. */
    public void reset() {
        items = Map.of();
        families = Map.of();
        live = false;
    }

    /** Category -> merged items, for the location-hint provenance. */
    public Map<String, Map<Integer, Integer>> families() { return families; }

    /** Item id -> quantity from the latest response, merged across storages. */
    public Map<Integer, Integer> snapshot() { return items; }

    /** Distinct live item count - the panel's provenance line. */
    public int count() { return items.size(); }

    /** Fold the live items into an owned map (quantities sum). */
    public Map<Integer, Integer> mergeInto(Map<Integer, Integer> owned) {
        items.forEach((id, n) -> owned.merge(id, n, Integer::sum));
        return owned;
    }
}

package com.loadoutlab.collection;

import com.google.gson.Gson;
import com.google.gson.reflect.TypeToken;
import java.util.*;
import net.runelite.client.config.ConfigManager;

/** A scoped set of item ids: the exclusions ("excludedItems"), the dream
 * items ("dreamItems") and the protect-only items ("protectOnlyItems"). */
public class IdSetStore implements ScopedStore {
    static final String CONFIG_GROUP = "loadoutlab";

    final ConfigManager configManager;
    final Gson gson;
    final Set<Integer> ids = new LinkedHashSet<>();
    /** "std" / "seasonal", plus ".<accountHash>" once a character is known.
     * Field report 2026-08-25: switching from a main to a test account showed
     * the SAME exclude and sim lists, because these keys were global while the
     * bank ledger next door was already per-character. */
    String worldScope;

    /** The unscoped key this store used before 0.4.1 - read once so an
     * existing install keeps its list when the key gains the account hash. */
    final String legacyKey;

    public IdSetStore(ConfigManager configManager, Gson gson, String legacyKey) {
        this.configManager = configManager;
        this.gson = gson;
        this.legacyKey = legacyKey;
        load();
    }

    String key() { return ScopedKeys.key(worldScope, legacyKey); }

    public synchronized void loadScope(String scope) {
        worldScope = scope;
        load();
    }

    public synchronized void reload() { load(); }

    final void load() {
        ids.clear();
        Set<Integer> stored = ScopedKeys.parse(gson, ScopedKeys.read(configManager, CONFIG_GROUP, worldScope, legacyKey),
            new TypeToken<Set<Integer>>(){}.getType());
        if (stored != null) ids.addAll(stored);
    }

    final void save() { configManager.setConfiguration(CONFIG_GROUP, key(), gson.toJson(ids)); }

    public synchronized boolean toggle(int itemId) {
        boolean added = !ids.remove(itemId) && ids.add(itemId);
        save();
        return added;
    }

    public synchronized void clear() {
        ids.clear();
        save();
    }

    public synchronized boolean contains(int itemId) { return ids.contains(itemId); }

    public synchronized Set<Integer> snapshot() { return new LinkedHashSet<>(ids); }
}

package com.loadoutlab.collection;

import java.util.*;
import java.util.function.Function;
import java.util.stream.Collectors;

/**
 * Where each owned item lives - the per-source view the flattened owned
 * map erases. Built from the ledger's source snapshots plus the manual
 * stored-elsewhere list and the DWMS import families; lookups are
 * variant-aware, so a STASH'd ornamented variant answers for the base id
 * the optimizer suggests.
 */
@lombok.AllArgsConstructor
public class ItemLocations {
    /** Suffix convention for origins the DWMS import contributed. */
    public static final String VIA_DWMS = " (via DWMS)";

    /** Origin label -> itemId -> quantity, in display order. */
    final Map<String, Map<Integer, Integer>> origins;

    /** id -> all ids interchangeable with it for ownership (incl. itself);
     * null means exact-id matching only (dataset still loading). */
    final Function<Integer, Set<Integer>> equivalents;

    /** Origin labels holding this item or an interchangeable variant. */
    public List<String> where(int itemId) {
        Set<Integer> ids = equivalents == null ? Set.of(itemId) : equivalents.apply(itemId);
        return origins.entrySet().stream().filter(origin -> ids.stream().anyMatch(origin.getValue()::containsKey))
            .map(Map.Entry::getKey).collect(Collectors.toList());
    }

    /**
     * Legend label for the item's primary origin: the first origin in
     * display order, with DWMS families folded onto their native twin
     * ("STASH (via DWMS)" -> "STASH") and DWMS-only families bucketed as
     * "DWMS". "" when the location is unknown.
     */
    public String primary(int itemId) {
        List<String> where = where(itemId);
        if (where.isEmpty()) return "";
        String label = where.get(0);
        if (!label.endsWith(VIA_DWMS)) return label;
        String base = label.substring(0, label.length() - VIA_DWMS.length());
        switch (base) {
            case "POH costume room":
            case "STASH":
            case "cargo hold":
                return base;
            default:
                return "DWMS";
        }
    }

}

package com.loadoutlab.collection;

import com.google.gson.Gson;
import com.google.gson.reflect.TypeToken;
import com.loadoutlab.data.*;
import java.util.*;
import java.util.function.Function;
import java.util.stream.Stream;
import net.runelite.client.config.ConfigManager;
import com.loadoutlab.model.CommandEngine;

/**
 * Per-monster user profiles: the preferences the optimizer cannot infer,
 * remembered per mob. Each profile carries PINS (slot -> item the player
 * always brings THERE), a free-text NOTE, and extra ITEMS unioned into
 * the Show-in-bank / Filter-bank sets (trip supplies no suggestion would
 * contain). Pins and filter items are SCOPED: "ALL" applies to every
 * style card, or a specific style ("MELEE"/"RANGED"/"MAGIC") applies to
 * that card only - a super combat for melee, a ranged potion for ranged.
 * The effective view overlays ALL with the style scope (style wins a
 * pin-slot collision).
 *
 * <p>Scope-free config in v1 like dreams/exclusions: trip preferences
 * follow the player. Empty profiles are pruned on save.
 */
public class MonsterProfileStore implements CommandEngine.MobProfiles, ScopedStore {
    static final String CONFIG_GROUP = "loadoutlab";
    static final String KEY = "monsterProfiles";

    /** Per-character scope ("std"/"seasonal" plus ".<accountHash>"). Global
     * before 0.4.1, which is why a main and a test account shared this list. */
    String worldScope;

    String key() { return ScopedKeys.key(worldScope, KEY); }

    public synchronized void loadScope(String scope) {
        worldScope = scope;
        load();
    }
    /** The every-style scope key. Style scopes use CombatStyle names. */
    public static final String ALL = "ALL";

    /** Serialized form: scope -> slot-name -> id for pins; scope -> id ->
     * display name for filter items (names captured at add time - id
     * resolution later needs the client thread). */
    Stored stored(int monsterId) {
        return profiles.computeIfAbsent(MonsterStats.profileIdOf(monsterId), id -> new Stored());
    }

    Stored get(int monsterId) { return profiles.get(MonsterStats.profileIdOf(monsterId)); }

    static class Stored {
        Map<String, Map<String, Integer>> pins;
        String note;
        Map<String, Map<Integer, String>> filterItems;
        /** Per-mob simulated items (id -> add-time name) - counted as
         * owned for THIS mob only. */
        Map<Integer, String> sims;
        /** Pinned autocast spell name for the magic card ("" / null = auto). */
        String spell;
        /** Pinned SPEC weapon id (0 / null = auto-pick). */
        Integer spec;
        /** Per-mob exclusions: scope -> item ids the suggestions here must
         * never contain (the global exclusion list handles "everywhere"). */
        Map<String, Set<Integer>> exclusions;
        /** Per-mob trip-supply overrides: TripSupplies category ->
         * mode/option key ("DETECT_BEST", "NONE", "SANFEW_SERUM"...).
         * Absent category = the wrench-panel default applies. */
        Map<String, String> supplies;
        /** Degrades chip: skip degradable gear here (null = panel default). */
        Boolean skipDegradable;
    }

    Set<Integer> degradableIds = Set.of();

    public synchronized void setDegradableIds(Set<Integer> ids) { degradableIds = ids; }

    public synchronized boolean skipDegradable(int monsterId, boolean fallback) {
        return read(monsterId, p -> p.skipDegradable, fallback);
    }

    public synchronized void setSkipDegradable(int monsterId, boolean skip) {
        stored(monsterId).skipDegradable = skip;
        save();
    }

    final ConfigManager configManager;
    final Gson gson;
    final Map<Integer, Stored> profiles = new HashMap<>();

    public MonsterProfileStore(ConfigManager configManager, Gson gson) {
        this.configManager = configManager;
        this.gson = gson;
        load();
    }

    /** Re-read from config - the active RuneLite profile may have changed. */
    /** The reset-customisations control: every profile in this scope goes. */
    public synchronized void clear() {
        profiles.clear();
        save();
    }

    public synchronized void reload() { load(); }

    void load() {
        profiles.clear();
        Map<Integer, Stored> stored = ScopedKeys.parse(gson, ScopedKeys.read(configManager, CONFIG_GROUP, worldScope, KEY),
            new TypeToken<Map<Integer, Stored>>(){}.getType());
        if (stored != null) {
            // Entries saved under a phase variant's synthetic id (before
            // 2026-10-14 every write keyed the lensed card's raw id) fold
            // into the real monster's profile; its own entry wins.
            stored.forEach((id, profile) -> {
                if (id < MonsterStats.SYNTHETIC_ID_BASE) profiles.put(id, profile);
            });
            stored.forEach((id, profile) -> profiles.putIfAbsent(MonsterStats.profileIdOf(id), profile));
        }
    }

    /** A read-only copy, Map.of() for nothing. */
    static <K, V> Map<K, V> copyOf(Map<K, V> m) {
        return m == null || m.isEmpty() ? Map.of() : new LinkedHashMap<>(m);
    }

    /** A profile field, or the fallback when the mob has no profile or the field is unset. */
    <T> T read(int monsterId, Function<Stored, T> field, T fallback) {
        Stored profile = get(monsterId);
        T value = profile == null ? null : field.apply(profile);
        return value == null ? fallback : value;
    }

    /** One scope's inner collection of a scoped field, or null. */
    <V> V inner(int monsterId, Function<Stored, Map<String, V>> field, String scope) {
        Map<String, V> scoped = read(monsterId, field, null);
        return scoped == null ? null : scoped.get(scope);
    }

    /** A scoped field for the manage menus: scope -> the copied inner
     * collection, the empties dropped (the copy says null); Map.of() for none. */
    static <V, W> Map<String, W> byScope(Map<String, V> scoped, Function<V, W> copy) {
        if (scoped == null || scoped.isEmpty()) return Map.of();
        Map<String, W> out = new LinkedHashMap<>();
        scoped.forEach((scope, value) -> {
            W copied = value == null ? null : copy.apply(value);
            if (copied != null) out.put(scope, copied);
        });
        return out;
    }

    /** Effective pins for one style card: ALL overlaid by the style scope. */
    public synchronized Map<GearSlot, Integer> pinsFor(int monsterId, String style) {
        Map<String, Map<String, Integer>> scoped = read(monsterId, p -> p.pins, Map.of());
        var pins = new EnumMap<GearSlot, Integer>(GearSlot.class);
        copyPins(scoped.get(ALL), pins);
        copyPins(scoped.get(style), pins);
        return pins.isEmpty() ? Map.of() : pins;
    }

    static void copyPins(Map<String, Integer> from, EnumMap<GearSlot, Integer> into) {
        if (from == null) return;
        for (var entry : from.entrySet()) {
            try {
                into.put(GearSlot.valueOf(entry.getKey()), entry.getValue());
            } catch (IllegalArgumentException ignored) {
                // Unknown slot name in config: drop that pin.
            }
        }
    }

    /** Raw pins by scope, for the manage menu: scope -> slot -> id. */
    public synchronized Map<String, Map<GearSlot, Integer>> allPins(int monsterId) {
        return byScope(read(monsterId, p -> p.pins, null), slots -> {
            var pins = new EnumMap<GearSlot, Integer>(GearSlot.class);
            copyPins(slots, pins);
            return pins.isEmpty() ? null : pins;
        });
    }

    public synchronized void pin(int monsterId, String scope, GearSlot slot, int itemId) {
        Stored profile = stored(monsterId);
        if (profile.pins == null) profile.pins = new LinkedHashMap<>();
        profile.pins.computeIfAbsent(scope, s -> new LinkedHashMap<>()) .put(slot.name(), itemId);
        save();
    }

    public synchronized void unpin(int monsterId, String scope, GearSlot slot) {
        Map<String, Integer> slots = inner(monsterId, p -> p.pins, scope);
        if (slots != null) {
            slots.remove(slot.name());
            save();
        }
    }

    /** The user's note for this monster ("" when none). */
    public synchronized String note(int monsterId) { return read(monsterId, p -> p.note, ""); }

    public synchronized void setNote(int monsterId, String note) {
        Stored profile = stored(monsterId);
        profile.note = note == null || note.trim().isEmpty() ? null : note.trim();
        save();
    }

    /** The pinned autocast spell for this monster ("" = auto-pick). */
    public synchronized String pinnedSpell(int monsterId) { return read(monsterId, p -> p.spell, ""); }

    public synchronized void setPinnedSpell(int monsterId, String spellName) {
        Stored profile = stored(monsterId);
        profile.spell = spellName == null || spellName.trim().isEmpty() ? null : spellName.trim();
        save();
    }

    /** The pinned SPEC weapon id for this monster (0 = auto-pick). */
    public synchronized int pinnedSpec(int monsterId) { return read(monsterId, p -> p.spec, 0); }

    public synchronized void setPinnedSpec(int monsterId, int itemId) {
        Stored profile = stored(monsterId);
        profile.spec = itemId <= 0 ? null : itemId;
        save();
    }


    /** Raw filter items by scope: scope -> id -> display name. */
    public synchronized Map<String, Map<Integer, String>> allFilterItems(int monsterId) {
        return byScope(read(monsterId, p -> p.filterItems, null), items -> items.isEmpty() ? null : copyOf(items));
    }

    /** Effective per-mob exclusions for one style card: ALL plus the style
     * scope. The caller unions in the global exclusion list. */
    public synchronized Set<Integer> exclusionsFor(int monsterId, String style) {
        Stored profile = get(monsterId);
        if (profile == null) return Set.of();
        var merged = new LinkedHashSet<Integer>();
        if (Boolean.TRUE.equals(profile.skipDegradable)) merged.addAll(degradableIds);
        for (String scope : new String[]{ALL, style}) {
            Set<Integer> ids = profile.exclusions == null ? null : profile.exclusions.get(scope);
            if (ids != null) merged.addAll(ids);
        }
        return merged.isEmpty() ? Set.of() : merged;
    }

    /** Raw per-mob exclusions by scope, for the manage menu. */
    public synchronized Map<String, Set<Integer>> allExclusions(int monsterId) {
        return byScope(read(monsterId, p -> p.exclusions, null),
            ids -> ids.isEmpty() ? null : new LinkedHashSet<>(ids));
    }

    /** Per-mob sims: counted as owned for THIS mob only. */
    public synchronized Set<Integer> simsFor(int monsterId) { return allSims(monsterId).keySet(); }

    /** Raw per-mob sims (id -> add-time name), for the manage menu. */
    public synchronized Map<Integer, String> allSims(int monsterId) {
        return copyOf(read(monsterId, p -> p.sims, null));
    }

    public synchronized void addSim(int monsterId, int itemId, String name) {
        Stored profile = stored(monsterId);
        if (profile.sims == null) profile.sims = new LinkedHashMap<>();
        profile.sims.put(itemId, name == null ? ("item " + itemId) : name);
        save();
    }

    public synchronized void removeMobSim(int monsterId, int itemId) {
        Map<Integer, String> sims = read(monsterId, p -> p.sims, null);
        if (sims != null) {
            sims.remove(itemId);
            save();
        }
    }

    /** Per-mob trip-supply overrides (category -> mode/option key);
     * empty when the wrench-panel defaults apply untouched. */
    public synchronized Map<String, String> supplyOverrides(int monsterId) {
        return copyOf(read(monsterId, p -> p.supplies, null));
    }

    /** Set one category's override; null/empty choice returns the category
     * to the wrench-panel default. */
    public synchronized void setSupplyOverride(int monsterId, String category, String choice) {
        if (choice == null || choice.isEmpty()) {
            Map<String, String> supplies = read(monsterId, p -> p.supplies, null);
            if (supplies != null) {
                supplies.remove(category);
                save();
            }
            return;
        }
        Stored profile = stored(monsterId);
        if (profile.supplies == null) profile.supplies = new LinkedHashMap<>();
        profile.supplies.put(category, choice);
        save();
    }

    public synchronized void exclude(int monsterId, String scope, int itemId) {
        Stored profile = stored(monsterId);
        if (profile.exclusions == null) profile.exclusions = new LinkedHashMap<>();
        profile.exclusions.computeIfAbsent(scope, s -> new LinkedHashSet<>()).add(itemId);
        save();
    }

    public synchronized void removeMobExclusion(int monsterId, String scope, int itemId) {
        Set<Integer> ids = inner(monsterId, p -> p.exclusions, scope);
        if (ids != null) {
            ids.remove(itemId);
            save();
        }
    }

    public synchronized void addFilterItem(int monsterId, String scope, int itemId, String name) {
        Stored profile = stored(monsterId);
        if (profile.filterItems == null) profile.filterItems = new LinkedHashMap<>();
        profile.filterItems.computeIfAbsent(scope, s -> new LinkedHashMap<>()) .put(itemId, name == null ? ("item " + itemId) : name);
        save();
    }

    public synchronized void removeMobFilter(int monsterId, String scope, int itemId) {
        Map<Integer, String> items = inner(monsterId, p -> p.filterItems, scope);
        if (items != null) {
            items.remove(itemId);
            save();
        }
    }

    void save() {
        Map<Integer, Stored> out = new LinkedHashMap<>();
        for (var entry : profiles.entrySet()) {
            Stored profile = entry.getValue();
            prune(profile.pins);
            prune(profile.filterItems);
            if (profile.exclusions != null) profile.exclusions.values().removeIf(s -> s == null || s.isEmpty());
            // EVERY field participates (field bug 2026-07-18: sims was
            // missing here, so a sims-only profile was judged empty and the
            // retainAll below erased the sim in the same call that added it
            // - "Sim here" appeared to do nothing).
            boolean empty = Stream.of(profile.pins, profile.filterItems, profile.exclusions, profile.sims, profile.supplies)
                .allMatch(m -> m == null || m.isEmpty()) && (profile.note == null || profile.note.isEmpty())
                && (profile.spell == null || profile.spell.isEmpty()) && profile.spec == null && profile.skipDegradable == null;
            if (!empty) out.put(entry.getKey(), profile);
        }
        profiles.keySet().retainAll(out.keySet());
        configManager.setConfiguration(CONFIG_GROUP, key(), gson.toJson(out));
    }

    static void prune(Map<String, ? extends Map<?, ?>> scoped) {
        if (scoped != null) scoped.values().removeIf(m -> m == null || m.isEmpty());
    }
}

package com.loadoutlab.collection;

import com.google.gson.JsonObject;
import com.loadoutlab.data.JsonResources;
import java.util.*;
import java.util.function.IntUnaryOperator;

/**
 * The bank's potion storage is varbits, not an item container: one
 * POTIONSTORE_VILE_SIZE_* varbit per potion holding the doses stored.
 * potion_storage.json maps each varbit the plugin cares about to the
 * 4-dose item it detects (Andrew 2026-10-19: super antifires kept there
 * were invisible, so Detect best said shield).
 */
public class PotionStorage {
    /** varbit id -> 4-dose item id. */
    static final Map<Integer, Integer> BY_VARBIT = new LinkedHashMap<>();
    /** The master scroll book's scrolls (ISS-01M5VDZXT4W4D5DP468R5R7NSW): shown as the book when held only there. */
    static final Set<Integer> SCROLLS = new HashSet<>();

    static {
        JsonObject root = JsonResources.objectOrThrow("potion_storage.json");
        JsonResources.ints(root, "_scrolls", SCROLLS);
        for (String key : root.keySet()) {
            if (!key.startsWith("_")) BY_VARBIT.put(Integer.parseInt(key), root.get(key).getAsInt());
        }
    }


    public static boolean tracks(int varbitId) { return BY_VARBIT.containsKey(varbitId); }

    public static boolean isScroll(int itemId) { return SCROLLS.contains(itemId); }

    /** item id -> 4-dose equivalents, for every stored potion with doses. */
    public static Map<Integer, Integer> owned(IntUnaryOperator dosesOf) {
        Map<Integer, Integer> owned = new HashMap<>();
        BY_VARBIT.forEach((varbit, item) -> {
            int doses = dosesOf.applyAsInt(varbit);
            if (doses > 0) owned.merge(item, (doses + 3) / 4, Integer::sum);
        });
        return owned;
    }
}

package com.loadoutlab.collection;

import java.util.*;
import java.util.function.IntUnaryOperator;

/**
 * The rune pouch as a ledger source (Mumblerit, Discord 2026-10-10: runes
 * moved into the pouch vanished and Fire Wave fell off the magic set).
 * The pouch is not an item container: each slot is a TYPE varbit (a key
 * into the client's RUNEPOUCH_RUNE enum, 0 = empty) and a QUANTITY varbit.
 * Pure over the two value arrays so the plugin's varbit reads stay thin.
 */
public class RunePouchScan {

    /** itemId -> quantity for every filled slot; an empty or zero slot adds nothing. */
    public static Map<Integer, Integer> items(int[] types, int[] quantities, IntUnaryOperator typeToItem) {
        Map<Integer, Integer> out = new HashMap<>();
        for (int i = 0; i < types.length && i < quantities.length; i++) {
            if (types[i] > 0 && quantities[i] > 0) {
                int item = typeToItem.applyAsInt(types[i]);
                if (item > 0) out.merge(item, quantities[i], Integer::sum);
            }
        }
        return out;
    }
}

package com.loadoutlab.collection;

import com.google.gson.Gson;
import java.lang.reflect.Type;
import net.runelite.client.config.ConfigManager;

/**
 * Per-character config keys, plus the one-time adoption of the pre-0.4.1
 * unscoped entry.
 *
 * <p>Field report 2026-08-26: on an install upgraded from 0.4.0 the alt still
 * showed the main's exclude list. The first cut fell back to the unscoped key
 * whenever the scoped one was empty, which is true for EVERY new character -
 * so every character adopted the main's list. Adoption has to happen once and
 * then stop, which means MOVING the entry into the first character that loads
 * it rather than copying it.
 */
class ScopedKeys {

    /** A scope with no account hash behaves as the pre-0.4.1 bucket, so edits
     * made before login are adopted by the first character instead of landing
     * in a key nothing reads. */
    static String key(String scope, String legacyKey) {
        return scope == null || scope.isEmpty() ? legacyKey : scope + "." + legacyKey;
    }

    /** Stored JSON for this scope, adopting the legacy entry once. */
    static String read(ConfigManager configManager, String group, String scope, String legacyKey) {
        return adopt(configManager, group, key(scope, legacyKey), legacyKey);
    }

    /** A stored JSON value, or null when the entry is empty or corrupt (a
     * corrupt entry starts the store fresh rather than failing the plugin). */
    static <T> T parse(Gson gson, String json, Type type) {
        try {
            return json == null || json.isEmpty() ? null : gson.fromJson(json, type);
        } catch (RuntimeException ex) { return null; }
    }

    /** As {@link #read}, for a store whose legacy key is not simply the
     * scoped key without its prefix. */
    static String adopt(ConfigManager configManager, String group, String key, String legacyKey) {
        String json = configManager.getConfiguration(group, key);
        if (json != null && !json.isEmpty()) return json;
        if (key.equals(legacyKey)) return null;
        String legacy = configManager.getConfiguration(group, legacyKey);
        if (legacy == null || legacy.isEmpty()) return null;
        // A move, not a copy: the second character must find nothing here.
        configManager.setConfiguration(group, key, legacy);
        configManager.unsetConfiguration(group, legacyKey);
        return legacy;
    }
}

package com.loadoutlab.collection;

import com.google.gson.Gson;
import java.lang.reflect.Type;
import java.util.*;
import net.runelite.client.config.ConfigManager;

/**
 * A per-character map persisted as one JSON config entry: the always-filter
 * list and the supply defaults share this exact shape (scoped key, load on
 * scope change, unset when empty, corrupt JSON starts fresh).
 */
abstract class ScopedMapStore<K, V> implements ScopedStore {
    static final String CONFIG_GROUP = "loadoutlab";

    final ConfigManager configManager;
    final Gson gson;
    final String configKey;
    final Type type;
    String worldScope;
    final Map<K, V> items = new LinkedHashMap<>();

    ScopedMapStore(ConfigManager configManager, Gson gson, String configKey, Type type) {
        this.configManager = configManager;
        this.gson = gson;
        this.configKey = configKey;
        this.type = type;
        load();
    }

    String key() { return ScopedKeys.key(worldScope, configKey); }

    /** Per-character scope ("std"/"seasonal" plus ".<accountHash>"). */
    public synchronized void loadScope(String scope) {
        worldScope = scope;
        load();
    }

    /** Re-read from config - the active RuneLite profile may have changed. */
    public synchronized void reload() { load(); }

    public synchronized void clear() {
        items.clear();
        save();
    }

    void load() {
        items.clear();
        Map<K, V> stored = ScopedKeys.parse(gson, ScopedKeys.read(configManager, CONFIG_GROUP, worldScope, configKey), type);
        if (stored != null) items.putAll(stored);
    }

    void save() {
        if (items.isEmpty()) {
            configManager.unsetConfiguration(CONFIG_GROUP, key());
            return;
        }
        configManager.setConfiguration(CONFIG_GROUP, key(), gson.toJson(items));
    }
}

package com.loadoutlab.collection;

/** A per-character store: re-keyed when the logged-in character changes. */
public interface ScopedStore {
    void loadScope(String scope);

    /** Re-read from config - the active RuneLite profile may have changed. */
    default void reload() {
    }

    /** The reset-customisations control: a store that holds customisations
     * wipes this scope's; bank memory (the ledger) is no customisation and stays. */
    default void clear() {
    }
}

package com.loadoutlab.collection;

import com.loadoutlab.data.JsonResources;
import java.util.*;
import java.util.function.IntUnaryOperator;

/**
 * Loadout Lab's half of the bidirectional storages contract: other
 * plugins can ask US for the owned-gear ledger the same way we ask
 * Dude, Where's My Stuff - identical request/response shape, each
 * plugin under its own namespace (reciprocity decided 2026-07-11;
 * the config keys in the README's "Data sharing" section stay as the
 * works-while-disabled fallback).
 *
 * <p>Request: namespace "loadoutlab", name "storages-request", data
 * {"source": requesting plugin's display name (required)}. Response:
 * name "storages-response" with "source" ("Loadout Lab"), "target"
 * (the requester's source echoed), "version" (1), and "storages" -
 * one entry per non-empty source with "category", "name",
 * "lastUpdated" (-1; the ledger keeps no timestamps) and "items"
 * ({"id": canonical item id, "quantity": Long}).
 *
 * <p>This class is the pure, testable part; the plugin gathers the
 * snapshots and posts on the client thread (ids canonicalize there).
 */
public class StoragesApi {
    public static final String NAMESPACE = "loadoutlab";
    public static final String REQUEST_NAME = "storages-request";
    public static final String RESPONSE_NAME = "storages-response";
    static final int VERSION = 1;
    static final String SOURCE = "Loadout Lab";


    /** The validated requester name from a storages-request payload,
     * or null when the request carries no usable source. */
    public static String requester(Map data) {
        if (data == null) return null;
        Object source = data.get("source");
        return source instanceof String && !((String) source).isEmpty() ? (String) source : null;
    }

    /**
     * One storage entry for the response: items canonicalized (variants
     * that collapse to one id sum), non-positive entries dropped.
     * Returns null when nothing survives - empty storages are omitted,
     * matching the DWMS side of the contract.
     */
    public static Map storage(String category, String name, long lastUpdated,
        Map<Integer, Integer> items, IntUnaryOperator canonicalize) {
        Map<Integer, Long> canonical = new LinkedHashMap<>();
        for (var e : items.entrySet()) {
            if (e.getKey() <= 0 || e.getValue() <= 0) continue;
            canonical.merge(canonicalize.applyAsInt(e.getKey()), (long) e.getValue(), Long::sum);
        }
        if (canonical.isEmpty()) return null;
        List<Map> itemList = new ArrayList<>(canonical.size());
        for (var e : canonical.entrySet()) {
            itemList.add(JsonResources.map("id", e.getKey(), "quantity", e.getValue()));
        }
        return JsonResources.map("category", category, "name", name, "lastUpdated", lastUpdated, "items", itemList);
    }

    /** The response envelope addressed back to the requester. */
    public static Map response(String target, List<Map> storages) {
        return JsonResources.map("source", SOURCE, "target", target, "version", VERSION, "storages", storages);
    }
}

package com.loadoutlab.collection;

import com.google.gson.Gson;
