package com.loadoutlab.data;

import com.google.gson.*;
import java.util.*;

import static com.loadoutlab.data.JsonResources.*;

public class DataService {
    static final String GEAR_RESOURCE = "gear_prices.json.gz";
    static final String REQUIREMENTS_RESOURCE = "equipment_requirements.json.gz";
    static final String MONSTER_RESOURCE = "monsters.json.gz";
    static final String SPELL_RESOURCE = "spells.json.gz";
    static final String ALIAS_RESOURCE = "equipment_aliases.json.gz";
    static final String NAME_RULES_RESOURCE = "name_rules.json";

    /** Name-matching tables, generated by scripts/gen_name_rules.py. */
    static final Map<String, Integer> SPELL_LEVELS = new HashMap<>();
    static final List<String> SLAYER_CONTAINS = new ArrayList<>();
    static final List<String> SLAYER_STARTS_WITH = new ArrayList<>();
    /** Quest rules as parallel lists, held in resource order: a quest named by
     * two rules must still dedup at its FIRST position in the LinkedHashSet
     * that questsFor builds. */
    static final List<List<String>> QUEST_TERMS = new ArrayList<>();
    static final List<String> QUEST_NAMES = new ArrayList<>();

    static {
        // Fail LOUD, unlike the fail-soft tables elsewhere. An empty table here
        // would silently pin every spell to level 1 and drop every quest
        // requirement - that changes DPS and gear recommendations with no
        // visible error - so use objectOrThrow and assert non-emptiness.
        JsonObject rules = objectOrThrow(NAME_RULES_RESOURCE);
        stringIntMap(rules, "spellLevels", SPELL_LEVELS);
        strings(rules, "slayerContains", SLAYER_CONTAINS);
        strings(rules, "slayerStartsWith", SLAYER_STARTS_WITH);
        for (JsonElement rule : rules.getAsJsonArray("questRules")) {
            JsonObject row = rule.getAsJsonObject();
            List<String> terms = new ArrayList<>();
            strings(row, "terms", terms);
            QUEST_TERMS.add(terms);
            QUEST_NAMES.add(row.get("quest").getAsString());
        }
        if (SPELL_LEVELS.isEmpty() || SLAYER_CONTAINS.isEmpty() || SLAYER_STARTS_WITH.isEmpty() || QUEST_TERMS.isEmpty()) {
            throw new IllegalStateException("Empty table in " + NAME_RULES_RESOURCE);
        }
    }

    public LoadoutData load() {
        List<GearItem> gear = priceChargedTwins(loadGear());
        List<MonsterStats> monsters = normalizeQuestVersions(loadMonsters());
        List<SpellStats> spells = loadSpells();
        Map<Integer, GearItem> gbi = new HashMap<>();
        gear.forEach(item -> gbi.put(item.id, item));
        return new LoadoutData(gear, monsters, spells, gbi, loadAliases(gear));
    }

    /** Variant id -> base id (ornament/locked/degraded, identical stats),
     * plus every uncharged, inactive, broken or locked WEAPON version behind
     * its charged twin (ISS-01M5QQV2TGQ5X730T0JJ75S1RD, Andrew 2026-10-24:
     * "let's only consider charged versions of weapons, don't think about eye
     * of ayak uncharged or obligator uncharged"): never suggested, and owning
     * one is owning the twin you charge before the trip. */
    Map<Integer, Integer> loadAliases(List<GearItem> gear) {
        Map<Integer, Integer> aliases = new HashMap<>();
        for (var entry : gz(ALIAS_RESOURCE).getAsJsonObject().entrySet()) {
            int variant = Integer.parseInt(entry.getKey());
            int base = entry.getValue().getAsInt();
            if (variant != base) aliases.put(variant, base);
        }
        for (var twin : chargedTwins(gear).entrySet()) {
            if (!aliases.containsKey(twin.getKey().id)) {
                aliases.put(twin.getKey().id, aliases.getOrDefault(twin.getValue().id, twin.getValue().id));
            }
        }
        return aliases;
    }

    /** Every dead weapon version -> its live twin of the same name: the
     * "charged" one, else active, normal, fixed or regular, else the first. */
    static Map<GearItem, GearItem> chargedTwins(List<GearItem> gear) {
        Map<String, List<GearItem>> weapons = new HashMap<>();
        for (GearItem item : gear) {
            if (item.slot == GearSlot.WEAPON) {
                weapons.computeIfAbsent(item.nameLower, k -> new ArrayList<>()).add(item);
            }
        }
        Map<GearItem, GearItem> twins = new HashMap<>();
        for (List<GearItem> family : weapons.values()) {
            GearItem charged = null;
            for (String want : new String[]{"charged", "active", "normal", "fixed", "regular", ""}) {
                for (GearItem item : family) {
                    if (charged == null && !deadVersion(item) && (want.isEmpty() || item.versionLower.equals(want))) {
                        charged = item;
                    }
                }
            }
            for (GearItem item : family) {
                if (charged != null && deadVersion(item)) twins.put(item, charged);
            }
        }
        return twins;
    }

    /** The charged twin inherits the tradeable dead twin's price: the
     * uncharged Obligator is how you buy the Obligator, so the charged one
     * passes the untradeable gate and the budget modes can afford it. */
    static List<GearItem> priceChargedTwins(List<GearItem> gear) {
        Map<Integer, GearItem> priced = new HashMap<>();
        for (var twin : chargedTwins(gear).entrySet()) {
            GearItem dead = twin.getKey();
            GearItem charged = twin.getValue();
            if (dead.tradeable && dead.estimatedPrice != null && (!charged.tradeable || charged.estimatedPrice == null)) {
                priced.putIfAbsent(charged.id, charged.priced(dead.estimatedPrice));
            }
        }
        List<GearItem> out = new ArrayList<>(gear.size());
        for (GearItem item : gear) out.add(priced.getOrDefault(item.id, item));
        return out;
    }

    /** A weapon version that cannot attack as it is. */
    static boolean deadVersion(GearItem item) {
        String version = item.versionLower;
        return version.contains("uncharged") || version.contains("inactive") || version.contains("broken") || version.contains("locked");
    }

    List<GearItem> loadGear() {
        JsonArray rows = gz(GEAR_RESOURCE).getAsJsonArray();
        Map<Integer, Map<String, Integer>> sr = loadSkillRequirements();
        List<GearItem> result = new ArrayList<>(rows.size());
        for (JsonElement element : rows) {
            JsonObject row = element.getAsJsonObject();
            GearSlot slot = GearSlot.fromJson(string(row, "slot"));
            if (slot == null) continue;
            if (isLeaguesReward(string(row, "name"), string(row, "examine"))) continue;
            if (isMinigameOnly(string(row, "name"))) continue;

            GearItem item = new GearItem( integer(row, "id", 0), string(row, "name"), string(row, "version"), slot,
                string(row, "category"), integer(row, "speed", 0), bool(row, "isTwoHanded", false),
                bool(row, "isStandardGear", true) || isWronglyFlaggedUsable(string(row, "name")),
                bool(row, "tradeable", false), bool(row, "members", true), nullableInteger(row, "estimatedPrice"),
                parseOffensive(row.getAsJsonObject("offensive")), parseDefensive(row.getAsJsonObject("defensive")),
                parseBonuses(row.getAsJsonObject("bonuses")), requirementsFor( integer(row, "id", 0),
                    string(row, "name"), string(row, "version"), sr));
            if (row.has("weight") && !row.get("weight").isJsonNull()) item.setWeight(row.get("weight").getAsDouble());
            result.add(item);
        }
        result.sort(Comparator.comparing(GearItem::getName).thenComparingInt(GearItem::getId));
        return result;
    }

    /**
     * Upstream's curated isStandardGear flag marks these permanent main-game
     * upgrades as non-standard (audited 2026-07-05): the Avernic treads
     * upgrade combinations carry real ranged/magic strength, and the
     * Confliction gauntlets are a 7% magic damage glove. Force them usable.
     */
    static boolean isWronglyFlaggedUsable(String name) {
        String n = name == null ? "" : name.toLowerCase();
        return n.startsWith("avernic treads") || n.equals("confliction gauntlets");
    }

    /**
     * Leagues-only rewards never enter the corpus - the optimizer suggests
     * main-game gear only. The stat-relevant offenders are the Leagues V
     * "Echo" set (wrongly flagged isStandardGear in the wiki data); the
     * Trailblazer outfits, banners, and trophies are zero-stat cosmetics.
     * The wiki examine text says "league" only on leagues rewards.
     */
    static final List<String> LEAGUES_PREFIXES = new ArrayList<>();
    static final List<String> LEAGUES_CONTAINS = new ArrayList<>();
    static final List<String> MINIGAME_ONLY = new ArrayList<>();

    static {
        JsonObject leagues = objectOrThrow("leagues_items.json");
        strings(leagues, "prefixes", LEAGUES_PREFIXES);
        strings(leagues, "contains", LEAGUES_CONTAINS);
        strings(leagues, "minigameOnly", MINIGAME_ONLY);
    }

    static boolean isLeaguesReward(String name, String examine) {
        String n = name == null ? "" : name.toLowerCase();
        return LEAGUES_PREFIXES.stream().anyMatch(n::startsWith) || LEAGUES_CONTAINS.stream().anyMatch(n::contains)
            || (examine != null && examine.toLowerCase().contains("league"));
    }

    /**
     * Items that only function inside a minigame never enter the corpus.
     * The Barbarian Assault arrows carry ranged strength 125 - stronger
     * than dragon arrows - but can only be fired at penance inside BA
     * (upstream best-dps flagged only two of the four non-standard).
     */
    static boolean isMinigameOnly(String name) {
        return MINIGAME_ONLY.contains(name == null ? "" : name.toLowerCase());
    }

    Map<Integer, Map<String, Integer>> loadSkillRequirements() {
        JsonArray rows = gz(REQUIREMENTS_RESOURCE).getAsJsonArray();
        Map<Integer, Map<String, Integer>> result = new HashMap<>();
        for (JsonElement element : rows) {
            JsonObject row = element.getAsJsonObject();
            JsonObject skills = object(row, "skills");
            Map<String, Integer> levels = new LinkedHashMap<>();
            for (var entry : skills.entrySet()) {
                if (!entry.getValue().isJsonNull()) {
                    levels.put(entry.getKey(), Math.max(1, entry.getValue().getAsInt()));
                }
            }
            if (!levels.isEmpty()) result.put(integer(row, "id", 0), levels);
        }
        return result;
    }

    static GearRequirements requirementsFor(int id, String name, String version, Map<Integer, Map<String, Integer>> sr) {
        Map<String, Integer> skills = sr.getOrDefault(id, Map.of());
        Set<String> quests = questsFor(name, version);
        return skills.isEmpty() && quests.isEmpty() ? GearRequirements.NONE : new GearRequirements(skills, quests);
    }

    /** Version-label normalization (field spec 2026-07-18): the noise
     * tokens go ("Awake"; "Post-quest" becomes the bare name - the
     * everyday fight owns it), quest-only rows read "QUEST" loudly
     * (either the literal Quest token, or - for a two-row pair like
     * Vorkath's 'Dragon Slayer II' next to 'Post-quest' - the sibling
     * that is not the post-quest fight). versionTier already sorts
     * anything containing "quest" to the bottom of a bare-name search. */
    static List<MonsterStats> normalizeQuestVersions(List<MonsterStats> monsters) {
        Map<String, List<MonsterStats>> bn = new LinkedHashMap<>();
        for (MonsterStats monster : monsters) {
            bn.computeIfAbsent(monster.nameLower, k -> new ArrayList<>()).add(monster);
        }
        List<MonsterStats> out = new ArrayList<>(monsters.size());
        for (List<MonsterStats> group : bn.values()) {
            boolean pairWithPostQuest = group.size() == 2 && group.stream()
                .anyMatch(m -> Names.lower(m.version).contains("post-quest"));
            for (MonsterStats monster : group) {
                String version = monster.version;
                if (version == null || version.isEmpty()) {
                    out.add(monster);
                    continue;
                }
                List<String> kept = new ArrayList<>();
                boolean quest = false;
                for (String token : version.split(",\\s*")) {
                    if (token.equalsIgnoreCase("awake") || token.equalsIgnoreCase("post-quest")) continue;
                    if (token.equalsIgnoreCase("quest")) {
                        quest = true;
                        continue;
                    }
                    kept.add(token);
                }
                if (pairWithPostQuest && !quest && !Names.lower(version).contains("post-quest")) {
                    // The non-post-quest half of the pair IS the quest fight.
                    quest = true;
                    kept.clear();
                }
                String normalized = String.join(", ", kept);
                if (quest) normalized = normalized.isEmpty() ? "QUEST" : normalized + ", QUEST";
                out.add(normalized.equals(version) ? monster : monster.withVersion(normalized));
            }
        }
        return out;
    }

    /** Leagues echo bosses are seasonal, never main-game (Andrew 2026-09-03:
     * "should not be able to search 'echo' version in main mode"). */
    static boolean isEcho(JsonObject row) {
        String name = string(row, "name");
        // Nightmare Zone versions too (Andrew 2026-09-04: "nobody needs theory
        // crafting for that") - they swamped a search for the Nightmare.
        return name.contains("(Echo)") || name.contains("(Nightmare Zone)");
    }

    List<MonsterStats> loadMonsters() {
        JsonArray rows = gz(MONSTER_RESOURCE).getAsJsonArray();
        // The wiki data lists one row per SPAWN - Tormented Demon (1)..(4)
        // are four combat-identical rows. Collapse same-name rows whose
        // combat-relevant stats match, and drop the version label entirely
        // when a name has only one distinct stat block (Dusk keeps its
        // First/Second form; the four TDs become one unlabeled entry).
        Map<String, Set<String>> skbn = new HashMap<>();
        // Collapsed groups display the HIGHEST combat level among their spawns.
        Map<String, Integer> mlbg = new HashMap<>();
        for (JsonElement element : rows) {
            JsonObject row = element.getAsJsonObject();
            if (isEcho(row)) continue;
            String nk = Names.lower(string(row, "name"));
            String sk = monsterStatKey(row);
            skbn.computeIfAbsent(nk, k -> new LinkedHashSet<>()).add(sk);
            mlbg.merge(nk + "|" + sk, integer(row, "level", 0), Math::max);
        }

        Set<String> emitted = new HashSet<>();
        List<MonsterStats> result = new ArrayList<>(rows.size());
        for (JsonElement element : rows) {
            JsonObject row = element.getAsJsonObject();
            if (isEcho(row)) continue;
            String nk = Names.lower(string(row, "name"));
            String groupKey = nk + "|" + monsterStatKey(row);
            // Emit the HIGHEST-LEVEL spawn of each collapsed group, so the
            // offensive sheet (used for incoming dps) matches the combat
            // level the label displays.
            if (integer(row, "level", 0) != mlbg.get(groupKey) || !emitted.add(groupKey)) {
                continue;
            }
            boolean distinctVersions = skbn.get(nk).size() > 1;
            JsonObject skills = object(row, "skills");
            JsonObject offensive = object(row, "offensive");
            JsonObject defensive = object(row, "defensive");
            JsonObject weakness = object(row, "weakness");
            List<String> attributes = new ArrayList<>();
            JsonArray attrArray = array(row, "attributes");
            for (JsonElement attr : attrArray) {
                if (!attr.isJsonNull()) attributes.add(attr.getAsString());
            }
            // Burn immunity rides the attribute list as a synthetic marker
            // (no MonsterStats signature churn): the eclipse/scorching burn
            // class is a NORMAL burn, blocked by Normal or Strong immunity
            // (official calc isImmuneToNormalBurns; Weak does not block it).
            JsonObject immunities = row.has("immunities") && row.get("immunities").isJsonObject()
                ? row.getAsJsonObject("immunities") : null;
            String burn = immunities == null ? "" : string(immunities, "burn");
            if ("normal".equalsIgnoreCase(burn) || "strong".equalsIgnoreCase(burn)) attributes.add("burn_immune");

            // The Maggot King fights at range until ~65% hp - melee CANNOT
            // land on the Far phase (wiki: "cannot be attacked with melee
            // until it falls below ~980 hitpoints"; field report 2026-08-20:
            // Far recommended a melee set). The corpus carries no attribute
            // for it, so the marker rides here like burn_immune.
            if ("Maggot King".equals(string(row, "name")) && "Far".equalsIgnoreCase(string(row, "version"))) {
                attributes.add("immune_melee");
            }

            // The ejected core is a 1x1 target - the wiki row carries the
            // Warden's 5x5 frame, which handed the crystal halberd's sweep a
            // phantom second hit and outranked the DDS dump (field report
            // 2026-08-06). Size is the one stat the always-max rule still
            // reads (halberd sweep, scythe cleave).
            int size = "Core-ejected".equals(string(row, "version")) ? 1 : integer(row, "size", 1);
            result.add(new MonsterStats( integer(row, "id", -1), string(row, "name"),
                distinctVersions ? string(row, "version") : "", mlbg.get(groupKey), integer(skills, "hp", 1),
                size, integer(skills, "def", 1), integer(skills, "magic", 1), integer(offensive, "magic", 0),
                parseMonsterDefences(defensive), new MonsterOffence( integer(skills, "atk", 1),
                    integer(skills, "str", 1), integer(skills, "ranged", 1), integer(skills, "magic", 1),
                    integer(offensive, "atk", 0), integer(offensive, "str", 0), integer(offensive, "ranged", 0),
                    integer(offensive, "ranged_str", 0), integer(offensive, "magic", 0),
                    integer(offensive, "magic_str", 0), integer(row, "speed", 4), styleList(row),
                    MaxHits.parse(string(row, "max_hit"))), attributes,
                bool(row, "is_slayer_monster", false) || knownSlayerMonster(string(row, "name")),
                string(weakness, "element"), integer(weakness, "severity", 0)));
        }
        result.sort(Comparator.comparing(MonsterStats::getName).thenComparing(MonsterStats::getVersion).thenComparingInt(MonsterStats::getId));
        return result;
    }

    static List<String> styleList(JsonObject row) {
        List<String> styles = new ArrayList<>();
        for (JsonElement e : array(row, "style")) {
            if (e.isJsonNull()) continue;
            // "Ranged <br/> Typeless" is two styles; stray DEL characters
            // (Araxxor, Dusk) are wiki noise.
            for (String style : e.getAsString().replace('\u007f', ' ').split("(?i)<br\\s*/?>")) {
                if (!style.trim().isEmpty()) styles.add(style.trim());
            }
        }
        return styles;
    }

    /** Everything the engine reads from a monster - rows agreeing on this are one entry. */
    static String monsterStatKey(JsonObject row) {
        JsonObject skills = object(row, "skills");
        JsonObject offensive = object(row, "offensive");
        // The Wardens' Core-ejected rows are stat-identical to their
        // Active siblings, but the engine reads that version as a
        // MECHANIC (the core's always-max rule) - collapsing them would
        // erase the spec-dump phase from the corpus entirely.
        String mechanicVersion = "Core-ejected".equals(string(row, "version")) ? "Core-ejected" : "";
        return integer(skills, "def", 1) + "|" + integer(skills, "magic", 1) + "|" + integer(offensive, "magic", 0)
            + "|" + object(row, "defensive").toString() + "|" + array(row, "attributes").toString()
            + "|" + bool(row, "is_slayer_monster", false) + "|" + object(row, "weakness").toString()
            + "|" + integer(row, "size", 1) + "|" + mechanicVersion;
    }

    List<SpellStats> loadSpells() {
        JsonArray rows = gz(SPELL_RESOURCE).getAsJsonArray();
        List<SpellStats> result = new ArrayList<>(rows.size());
        for (JsonElement element : rows) {
            JsonObject row = element.getAsJsonObject();
            int mh = integer(row, "max_hit", 0);
            String name = string(row, "name");
            if (mh <= 0 && !"Magic Dart".equals(name)) continue;
            // Effect-only spells (leagues echoes, boss mechanics - e.g.
            // Flames of Cerberus) are flagged unselectable in the wiki data;
            // a player can never cast them, so they never enter the corpus.
            if (bool(row, "unselectable", false)) continue;
            result.add(new SpellStats( name, "Magic Dart".equals(name) ? 1 : mh, spellLevel(name),
                string(row, "spellbook"), string(row, "element")));
        }
        result.sort(Comparator.comparingInt(SpellStats::getMaxHit).thenComparing(SpellStats::getName));
        return result;
    }

    /** Casting level for a spell name; unknown names fall back to 1. */
    static int spellLevel(String name) { return SPELL_LEVELS.getOrDefault(name == null ? "" : name, 1); }

    static StatBlock parseOffensive(JsonObject object) {
        if (object == null) return StatBlock.ZERO;
        int[] c = combat(object);
        return new StatBlock(c[0], c[1], c[2], c[3], c[4], 0, 0, 0, 0);
    }

    static StatBlock parseDefensive(JsonObject object) {
        if (object == null) return StatBlock.ZERO;
        int[] c = combat(object);
        return new StatBlock(c[0], c[1], c[2], c[3], c[4], 0, integer(object, "light", 0),
            integer(object, "standard", 0), integer(object, "heavy", 0));
    }

    static MonsterDefences parseMonsterDefences(JsonObject object) {
        if (object == null) return MonsterDefences.ZERO;
        int[] c = combat(object);
        return new MonsterDefences(c[0], c[1], c[2], c[3], c[4], integer(object, "flat_armour", 0),
            integer(object, "light", 0), integer(object, "standard", 0), integer(object, "heavy", 0));
    }

    static StatBlock parseBonuses(JsonObject object) {
        if (object == null) return StatBlock.ZERO;
        return new StatBlock( 0, 0, 0, 0, 0, integer(object, "str", 0), integer(object, "ranged_str", 0),
            integer(object, "magic_str", 0), integer(object, "prayer", 0));
    }

    /** stab, slash, crush, magic, ranged - the five every stat block shares. */
    static int[] combat(JsonObject object) {
        return new int[]{integer(object, "stab", 0), integer(object, "slash", 0),
            integer(object, "crush", 0), integer(object, "magic", 0), integer(object, "ranged", 0)};
    }

    static boolean knownSlayerMonster(String name) {
        String normalized = name == null ? "" : Names.lower(name);
        return SLAYER_CONTAINS.stream().anyMatch(normalized::contains) || SLAYER_STARTS_WITH.stream().anyMatch(normalized::startsWith);
    }

    /**
     * Quest unlocks implied by an item's name and version, in resource rule
     * order. LinkedHashSet, so a quest named by two rules keeps the position of
     * its first match - the same behaviour the old requireIf chain had.
     */
    static Set<String> questsFor(String name, String version) {
        String item = ((name == null ? "" : name) + " " + (version == null ? "" : version)) .toLowerCase(Locale.ROOT);
        Set<String> quests = new LinkedHashSet<>();
        for (int i = 0; i < QUEST_TERMS.size(); i++) {
            for (String term : QUEST_TERMS.get(i)) {
                if (item.contains(term)) {
                    quests.add(QUEST_NAMES.get(i));
                    break;
                }
            }
        }
        return quests;
    }
}

package com.loadoutlab.data;

import com.google.gson.*;
import java.util.*;

/**
 * Per-boss defence floors for drain valuation (competitor audit
 * 2026-08-08): the official calculator hard-stops DWH/BGS/maul
 * stacking per boss, and without the floor our drain-fishing model
 * overvalues drain specs - at Nex (base 260, floor 250) a DWH is worth
 * almost nothing, at Verzik and Vardorvis exactly nothing. Id arrays
 * in defence_floors.json are copied verbatim from the wiki calc's
 * constants - the same weirdgloop ids our corpus carries.
 */
public class DefenceFloors {
    /** Sentinel: the floor IS the boss's base defence (undrainable). */
    static final int BASE = -1;

    static final Map<Integer, Integer> BY_ID = new HashMap<>();

    static {
        JsonObject root = JsonResources.objectOrThrow( "defence_floors.json");
        for (JsonElement e : root.getAsJsonArray("rules")) {
            JsonObject row = e.getAsJsonObject();
            int floor = "base".equals(row.get("floor").getAsString()) ? BASE : row.get("floor").getAsInt();
            for (JsonElement id : row.getAsJsonArray("ids")) BY_ID.put(id.getAsInt(), floor);
        }
        if (BY_ID.isEmpty()) throw new IllegalStateException("defence_floors.json loaded empty");
    }


    /** The defence level a drain cannot pass for this monster - 0 when
     * unfloored. Synthetic group rows resolve through profileId(). */
    public static int floorFor(MonsterStats monster) {
        if (monster == null) return 0;
        Integer floor = BY_ID.get(monster.profileId());
        if (floor == null) return 0;
        return floor == BASE ? monster.defence : floor;
    }
}

package com.loadoutlab.data;

import com.google.gson.JsonObject;
import java.util.*;

/** Gear that costs to use: wears down or burns charges per hit/cast
 * (degradable_gear.json; definition Andrew 2026-09-08). */
public class Degradable {
    static final List<String> FAMILIES = new ArrayList<>();
    static final List<String> EXCEPT = new ArrayList<>();

    static {
        JsonObject root = JsonResources.objectOrThrow("degradable_gear.json");
        JsonResources.strings(root, "families", FAMILIES);
        JsonResources.strings(root, "except", EXCEPT);
    }

    public static boolean matches(String nameLower) {
        return EXCEPT.stream().noneMatch(nameLower::contains) && FAMILIES.stream().anyMatch(nameLower::contains);
    }

    public static Set<Integer> ids(LoadoutData data) {
        Set<Integer> ids = new HashSet<>();
        data.gearItems.forEach(item -> {
            if (matches(item.nameLower)) ids.add(item.id);
        });
        return ids;
    }
}

