@AllArgsConstructor
public class MonsterDefences {
    public static final MonsterDefences ZERO = new MonsterDefences(0, 0, 0, 0, 0, 0, 0, 0, 0);

    final int stab;
    final int slash;
    final int crush;
    final int magic;
    final int ranged;
    @Getter
    final int flatArmour;
    final int light;
    final int standard;
    final int heavy;

    public MonsterDefences(int stab, int slash, int crush, int magic, int ranged, int light, int standard, int heavy) {
        this(stab, slash, crush, magic, ranged, 0, light, standard, heavy);
    }

    public int get(String type) {
        switch (type) {
            case "stab":
                return stab;
            case "slash":
                return slash;
            case "crush":
                return crush;
            case "magic":
                return magic;
            case "ranged":
                return ranged;
            case "light":
                return light;
            case "standard":
                return standard;
            case "heavy":
                return heavy;
            default:
                return 0;
        }
