package com.loadoutlab.data;

import java.util.*;

import lombok.Getter;

@Getter
public class MonsterStats {
    public final int id;
    public final String name;
    public final String version;
    public final int combatLevel;
    public final int hitpoints;
    public final int size;
    public final int defence;
    public final int magic;
    public final int offensiveMagic;
    public final MonsterDefences defensive;
    public final MonsterOffence offence;
    final List<String> attributes;
    public final Set<String> attributesLower;
    public final boolean slayerMonster;
    public final String weaknessElement;
    public final int weaknessSeverity;
    /** Lowercased monster name, cached (per-trial engine gates). */
    public final String nameLower;
    final boolean wilderness;
    final boolean revenant;
    /** 0, or the vampyre tier (attribute vampyre1-3): read per trial set. */
    public final int vampyreTier;

    public MonsterStats( int id, String name, String version, int combatLevel, int hitpoints, int defence, int magic,
        MonsterDefences defensive, List<String> attributes) {
        this(id, name, version, combatLevel, hitpoints, 1, defence, magic, 0, defensive, MonsterOffence.NONE, attributes, false, "", 0);
    }

    public MonsterStats( int id, String name, String version, int combatLevel, int hitpoints, int size, int defence,
        int magic, int offensiveMagic, MonsterDefences defensive, MonsterOffence offence, List<String> attributes,
        boolean slayerMonster, String weaknessElement, int weaknessSeverity) {
        this.id = id;
        this.name = name == null ? "" : name;
        this.version = version == null ? "" : version;
        this.combatLevel = combatLevel;
        this.hitpoints = hitpoints;
        this.size = Math.max(1, size);
        this.defence = defence;
        this.magic = magic;
        this.offensiveMagic = offensiveMagic;
        this.defensive = defensive == null ? MonsterDefences.ZERO : defensive;
        this.offence = offence == null ? MonsterOffence.NONE : offence;
        this.attributes = attributes == null ? List.of() : attributes;
        this.slayerMonster = slayerMonster;
        this.weaknessElement = weaknessElement == null ? "" : Names.lower(weaknessElement);
        this.weaknessSeverity = Math.max(0, weaknessSeverity);
        // hasAttribute runs per candidate set in the optimizer's inner loop;
        // lowercase once instead of per query.
        var lower = new HashSet<String>();
        for (String value : this.attributes) {
            if (value != null) lower.add(Names.lower(value));
        }
        this.attributesLower = lower;
        vampyreTier = lower.contains("vampyre3") ? 3 : lower.contains("vampyre2") ? 2 : lower.contains("vampyre1") ? 1 : 0;
        // The revenant/wilderness gates lowercase the name per DPS trial -
        // that allocation was ~20% of optimizer samples. Once, here.
        nameLower = Names.lower(this.name);
        this.wilderness = WildernessMonsters.containsName(nameLower);
        this.revenant = nameLower.startsWith("revenant");
    }

    /**
     * A synthetic per-phase variant (M-3 groups): the same stat sheet under
     * a new id + version label, with an immunity attribute the engine
     * honors ("immune_melee"...). Tormented demons' shield rotation is the
     * flagship: one variant per shielded style, so a roster shows the best
     * set for each phase. The NAME is preserved - name-keyed rules (the
     * TD damage reduction, boss overrides) keep applying.
     */
    /** Same sheet under a different version label (load-time
     * normalization of quest/post-quest noise). */
    public MonsterStats withVersion(String newVersion) { return copy(id, newVersion, attributes, defence); }

    MonsterStats copy(int newId, String newVersion, List<String> newAttributes, int newDefence) {
        var copy = new MonsterStats(newId, name, newVersion, combatLevel, hitpoints,
            size, newDefence, magic, offensiveMagic, defensive, offence, newAttributes, slayerMonster, weaknessElement, weaknessSeverity);
        copy.wikiVersion = getWikiVersion();
        copy.displayName = displayName;
        copy.toaInvocationLevel = toaInvocationLevel;
        return copy;
    }

    /** The RAW wiki version string ("Post-quest, Awake") - what the
     * official data and calculator key on. Display renames
     * (normalizeQuestVersions) preserve it; null = never renamed.
     * Field 2026-08-21: exporting the DISPLAY version made the calc's
     * import miss and silently fall back to the FIRST same-id row -
     * the post-quest Duke opened as Awakened. */
    String wikiVersion;

    public String getWikiVersion() { return wikiVersion == null ? version : wikiVersion; }

    /** What the label SHOWS when the community name beats the in-game one
     * (the Inferno's Jal- vocabulary: "Bat" for Jal-MejRah). Display only:
     * getName() stays the real name, so every name-keyed rule - notes, TD
     * damage reduction, boss overrides - keeps applying, and profile
     * pins/exclusions follow the real row. */
    String displayName;

    /** The value after a "prefix:" attribute (group stipulations), or null. */
    public String attributeValue(String prefix) {
        return attributes.stream().filter(a -> a.startsWith(prefix)) .map(a -> a.substring(prefix.length())).findFirst().orElse(null);
    }

    /** A copy carrying extra attributes (the group's stipulations). */
    public MonsterStats withAttributes(List<String> extra) {
        List<String> extended = new ArrayList<>(attributes);
        extended.addAll(extra);
        return copy(id, version, extended, defence);
    }

    public MonsterStats withDisplayName(String nick) {
        MonsterStats copy = withVersion(version);
        copy.displayName = nick;
        return copy;
    }

    /** ToA raid level carried ON the monster so every path - pool, kit
     * re-shows, spec sims - prices the same invocation; 0 everywhere
     * else. The engine scales defence rolls by (250+level)/250 (the
     * official engine's rule) for invocation-scaled rows. */
    int toaInvocationLevel;

    public int getToaInvocationLevel() { return toaInvocationLevel; }

    /** A copy priced at this raid level (SET, not compounded - re-applying
     * a different level replaces the old one); returns this when the
     * level already matches. */
    public MonsterStats withToaInvocation(int level) {
        int clamped = Math.max(0, level);
        if (clamped == toaInvocationLevel) return this;
        MonsterStats copy = withVersion(version);
        copy.toaInvocationLevel = clamped;
        return copy;
    }

    public MonsterStats immuneVariant(int syntheticId, String versionLabel, String immuneAttribute) {
        return immuneVariant(syntheticId, versionLabel, Collections.singletonList(immuneAttribute));
    }

    /** Multi-immunity variant: a phase can lock out SEVERAL styles at
     * once (Kalphite Queen's first form prays off magic AND ranged; a
     * Nylocas form takes only its own style). */
    public MonsterStats immuneVariant(int syntheticId, String versionLabel, List<String> immuneAttributes) {
        List<String> extended = new ArrayList<>(attributes);
        extended.addAll(immuneAttributes);
        return copy(syntheticId, versionLabel, extended, defence);
    }

    /** A phase variant with attributes taken away. */
    public MonsterStats withoutAttributes(int syntheticId, String versionLabel, List<String> removed) {
        List<String> kept = new ArrayList<>(attributes);
        kept.removeIf(a -> removed.contains(Names.lower(a)));
        return copy(syntheticId, versionLabel, kept, defence);
    }

    /** Lowercased monster name, cached (per-trial engine gates). */

    /** Fought in the Wilderness (see WildernessMonsters) - cached, the
     * wilderness-weapon gate asks several times per DPS trial. */
    public boolean isWildernessMonster() { return wilderness; }

    /** Name starts with "revenant" - the avarice/ethereum gates. */
    public boolean isRevenantMonster() { return revenant; }

    /** A copy at a different Defence level - defence-drain spec modeling.
     * Carries the invocation level: a drained ToA row keeps its raid
     * scaling or the drain would be valued at invocation 0. */
    public MonsterStats withDefence(int newDefence) { return copy(id, version, attributes, Math.max(0, newDefence)); }

    public boolean hasAttribute(String attribute) { return attributesLower.contains(Names.key(attribute)); }

    /** True when this variant's version label starts with the prefix - the
     * phase gate the mechanics rules share ("Phase 1..."). */
    public boolean versionStartsWith(String prefix) { return version != null && version.startsWith(prefix); }

    public String label() {
        // Level-derived version labels ("Level 137") are redundant with -
        // and after group-collapsing can contradict - the lvl suffix.
        boolean levelVersion = version.regionMatches(true, 0, "level", 0, 5);
        String suffix = version.isEmpty() || levelVersion ? "" : " (" + version + ")";
        String level = combatLevel > 0 ? " - lvl " + combatLevel : "";
        return (displayName != null ? displayName : name) + suffix + level;
    }

    public String searchText() { return normalizeQuery(name + " " + version + " " + id); }

    /** Search matching ignores punctuation: "kril" finds K'ril Tsutsaroth,
     * "kreearra" finds Kree'arra. */
    public static String normalizeQuery(String text) {
        var sb = new StringBuilder(text.length());
        for (char c : Names.lower(text).toCharArray()) {
            if (Character.isLetterOrDigit(c) || c == ' ') sb.append(c);
        }
        return sb.toString();
    }


    /** Synthetic phase-variant ids live above this base (M-3 groups):
     * base + realId * 10 + styleOrdinal. */
    public static final int SYNTHETIC_ID_BASE = 9_000_000;

    /** The id user-profile data (pins, exclusions, notes) attaches to -
     * a synthetic phase variant maps back to its real monster, so a
     * profile set on the plain mob follows it into groups. */
    public int profileId() { return profileIdOf(id); }

    /** The same mapping for a bare id (the profile store normalises every
     * read and write through it, so a pin made on a phase card is the
     * real monster's pin - Apathy, Discord 2026-10-09, Tormented Demons). */
    public static int profileIdOf(int id) { return id >= SYNTHETIC_ID_BASE ? (id - SYNTHETIC_ID_BASE) / 10 : id; }














}

package com.loadoutlab.data;

import com.google.gson.*;
import java.util.*;

/**
 * The mobs fought in multi-combat areas: multi_mobs.json, curated from the
 * wiki location tables, the crowdsourced multicombat tiles and the area
 * pages (docs/data/multi-mobs.md), keyed name + version as the loader
 * sees them. A listed mob gets the Multi switch on its card.
 */
public class MultiMobs {
    static final Map<String, List<String>> LOCATIONS = new HashMap<>();

    static {
        JsonObject root = JsonResources.objectOrThrow("/com/loadoutlab/data/multi_mobs.json");
        for (JsonElement e : root.getAsJsonArray("mobs")) {
            JsonObject mob = e.getAsJsonObject();
            List<String> locations = new ArrayList<>();
            for (JsonElement l : mob.getAsJsonArray("locations")) {
                locations.add(l.getAsJsonObject().get("location").getAsString());
            }
            LOCATIONS.put(key(mob.get("name").getAsString(), mob.get("version").getAsString()), locations);
        }
    }


    static String key(String name, String version) {
        return Names.lower(name) + "#" + Names.lower(version == null ? "" : version);
    }

    public static boolean isMultiAble(MonsterStats mob) {
        return mob != null && LOCATIONS.containsKey(key(mob.name, mob.version));
    }

    /** The multi locations the mob is fought in, for the switch's tooltip. */
    public static List<String> locations(MonsterStats mob) {
        return mob == null ? List.of() : LOCATIONS.getOrDefault(key(mob.name, mob.version), List.of());
    }
}

package com.loadoutlab.data;

import java.util.Locale;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;

/** Name matching is lower-case, locale-free, everywhere. */
public class Names {

    public static String lower(String s) { return s.toLowerCase(Locale.ROOT); }

    static final Map<String, String> KEYS = new ConcurrentHashMap<>();

    /** lower() memoised, for the fixed markers the per-set checks match on
     * (gear names, monster attributes): the profile had toLowerCase at 29% of
     * the optimizer's samples, the same few hundred strings every trial. A
     * plain get first: computeIfAbsent can lock a bin under the four workers. */
    public static String key(String s) {
        String k = KEYS.get(s);
        if (k == null) KEYS.put(s, k = lower(s));
        return k;
    }

    /** The first letter upper-cased, the rest as it was; null and "" read "". */
    public static String cap(String s) {
        return s == null || s.isEmpty() ? "" : Character.toUpperCase(s.charAt(0)) + s.substring(1);
    }
}

package com.loadoutlab.data;

import com.google.gson.*;
import java.util.*;

import static com.loadoutlab.data.JsonResources.*;

/**
 * Ship-combat data (see naval_combat.json): the seven cannon tiers, the
 * eight cannonball tiers, and the curated list of ship-eligible monsters.
 * Wiki-verified 2026-08-31; the resource's $comment records the revisions
 * that matter (dragon ball +174 -> +270 on 2026-03-18, and the stale
 * crewmate formula flag).
 *
 * <p>The corpus carries no naval attribute, so eligibility is this list -
 * every name resolves against a corpus row (NavalCombatTest proves it).
 */
public class NavalCombat {
    /** One cannon tier. Cannons are FACILITIES, not items; itemId is the
     * skill-guide item that carries the illustration (32199..32205). */
    @lombok.AllArgsConstructor
    public static class Cannon {
        public final String tier;
        public final int itemId;
        public final int sailing;
        public final int ranged;
        public final int heavyAccuracy;
        public final int strength;
        public final int privateering;
    }

    /** One cannonball tier. Steel is the classic Cannonball (item 2). */
    @lombok.AllArgsConstructor
    public static class Ball {
        public final String tier;
        public final int itemId;
        public final int accuracy;
        public final int strength;
    }

    static final Map<String, Cannon> CANNONS = new LinkedHashMap<>();
    static final Map<String, Ball> BALLS = new LinkedHashMap<>();
    static final List<String> BALL_ORDER = new ArrayList<>();
    public static final Set<String> NAVAL = new HashSet<>();
    static final List<String> KEELS = new ArrayList<>();
    /** Pre-0.5.0 builds named the keel columns after the hull woods; a
     * character's persisted ship.shipKeel may still say so. Same column,
     * right name - nobody's saved keel resets. */
    static final List<String> LEGACY_WOOD_KEELS = new ArrayList<>();
    static final Map<String, int[]> KEEL_MAX_HITS = new LinkedHashMap<>();
    static final boolean CREW_FORMULA_STALE;
    public static final int ATTACK_TICKS;

    static {
        JsonObject root = object("naval_combat.json");
        ATTACK_TICKS = root.get("attackTicks").getAsInt();
        CREW_FORMULA_STALE = root.get("crewFormulaStale").getAsBoolean();
        for (JsonElement e : root.getAsJsonArray("cannons")) {
            JsonObject c = e.getAsJsonObject();
            CANNONS.put(string(c, "tier"), new Cannon(string(c, "tier"), integer(c, "itemId", 0),
                integer(c, "sailing", 0), integer(c, "ranged", 0), integer(c, "heavyAccuracy", 0),
                integer(c, "strength", 0), integer(c, "privateering", 0)));
        }
        for (JsonElement e : root.getAsJsonArray("cannonballs")) {
            JsonObject b = e.getAsJsonObject();
            BALLS.put(string(b, "tier"), new Ball(string(b, "tier"), integer(b, "itemId", 0),
                integer(b, "accuracy", 0), integer(b, "strength", 0)));
        }
        strings(root, "ballTierOrder", BALL_ORDER);
        for (JsonElement e : root.getAsJsonArray("navalMonsters")) NAVAL.add(Names.lower(e.getAsString()));
        strings(root, "keels", KEELS);
        strings(root, "legacyWoodKeels", LEGACY_WOOD_KEELS);
        for (Map.Entry<String, JsonElement> row : root.getAsJsonObject("keelMaxHits").entrySet()) {
            KEEL_MAX_HITS.put(Names.lower(row.getKey()), ints(row.getValue().getAsJsonArray()));
        }
    }


    public static Cannon cannon(String tier) { return CANNONS.get(tier); }

    public static Ball ball(String tier) { return BALLS.get(tier); }

    public static List<Cannon> cannons() { return List.copyOf(CANNONS.values()); }

    public static List<Ball> balls() { return List.copyOf(BALLS.values()); }

    /** True when a cannon of {@code cannonTier} may fire {@code ballTier}:
     * at or below its own tier in the firing order (granite rides between
     * mithril and adamant, so mithril cannons cannot fire it). */
    public static boolean canFire(String cannonTier, String ballTier) {
        int c = BALL_ORDER.indexOf(cannonTier);
        int b = BALL_ORDER.indexOf(ballTier);
        return c >= 0 && b >= 0 && b <= c;
    }

    /** The best ball a set of cannons can SHARE (REQ-SC-2: one ammo tier for
     * all): the highest tier every cannon can fire, or null for no cannons. */
    public static String bestSharedBall(List<String> cannonTiers) {
        if (cannonTiers == null || cannonTiers.isEmpty()) return null;
        int min = Integer.MAX_VALUE;
        for (String tier : cannonTiers) {
            int i = BALL_ORDER.indexOf(tier);
            if (i < 0) return null;
            min = Math.min(min, i);
        }
        return BALL_ORDER.get(min);
    }

    /** Ship-eligible per the wiki's Ship combat roster (curated - the corpus
     * has no naval attribute). Case-insensitive on the corpus name. */
    public static boolean isNaval(String monsterName) {
        return monsterName != null && NAVAL.contains(Names.lower(monsterName));
    }

    public static List<String> keels() { return Collections.unmodifiableList(KEELS); }

    public static String normalizeKeel(String keel) {
        int i = keel == null ? -1 : LEGACY_WOOD_KEELS.indexOf(Names.lower(keel));
        return i >= 0 && i < KEELS.size() ? KEELS.get(i) : keel;
    }

    /** The monster's effective max hit against this keel (armour already
     * applied, from the wiki's Boat combat table), or -1 for an unknown
     * monster/keel. A 0 means this keel cannot be hit by it at all. */
    public static int keelMaxHit(String monsterName, String keelTier) {
        int[] row = monsterName == null ? null : KEEL_MAX_HITS.get(Names.lower(monsterName));
        int i = KEELS.indexOf(keelTier);
        return row == null || i < 0 || i >= row.length ? -1 : row[i];
    }

    /** Crew-fired numbers are estimates while the wiki flags the crewmate
     * formula out-of-date; the UI cites this on crew tooltips. */
    public static boolean crewFormulaStale() { return CREW_FORMULA_STALE; }
}

package com.loadoutlab.data;

import com.google.gson.*;
import java.util.*;
import java.util.stream.Collectors;

import static com.loadoutlab.data.JsonResources.*;
import java.util.function.IntPredicate;

/**
 * Mandatory protective slayer gear per monster (grZ field request
 * 2026-08-08: "some tasks where u need to equip something. would be
 * cool if it was autopinned"): a mirror shield vs a basilisk's gaze, a
 * lit bug lantern to harm harpies at all. The optimizer enforces the
 * slot exactly like the dragonfire shield - the pool collapses to the
 * acceptable items and non-complying weapon lines die - whenever the
 * request can actually field one; a user pin on the slot outranks.
 * Data-driven from required_gear.json (a resource - token-free), every
 * row wiki-verified before encoding.
 */
public class RequiredGear {
    /** One monster family's requirement: the slot, the acceptable item
     * specs (corpus names, optionally name#Version), and the why. */
    @lombok.RequiredArgsConstructor
    public static class Rule {
        public final GearSlot slot;
        public final String note;
        final List<String> itemSpecs;
        /** A waiver key that lifts the rule (KOUREND_ELITE), or null. */
        public final String waivedBy;
        /** A convention, not a must (the Barrows hilt, the Shayzien set):
         * enforced from what you own, never forced unowned. */
        public final boolean soft;
        /** Resolved once per corpus - the corpus never changes post-load. */
        volatile Set<Integer> resolved;

        /** The acceptable item ids, resolved against the loaded corpus
         * (standard-gear rows only; variants fold via the candidate
         * pool's own canonicalization). */
        public Set<Integer> ids(LoadoutData data) {
            Set<Integer> out = resolved;
            if (out != null) return out;
            out = new LinkedHashSet<>();
            for (String spec : itemSpecs) {
                String name = spec;
                String version = null;
                int hash = spec.indexOf('#');
                if (hash >= 0) {
                    name = spec.substring(0, hash);
                    version = spec.substring(hash + 1);
                }
                for (GearItem item : data.gearItems) {
                    if (item.nameLower.equals(name) && item.standardGear
                        && (version == null || version.equals(item.version))) {
                        out.add(item.id);
                    }
                }
            }
            resolved = out;
            return out;
        }
    }

    static final Map<String, List<Rule>> BY_NAME = new HashMap<>();

    /** The elite Kourend & Kebos diary (varbit KOUREND_DIARY_ELITE_COMPLETE):
     * once its rewards are claimed Karuulm's floor no longer burns (wiki,
     * Karuulm Slayer Dungeon) - the boots rule's waiver. */
    public static final String KOUREND_ELITE = "kourendElite";

    /** A carried slayer item the kill needs - the finishing blow (rock
     * hammer, fungicide, salt, ice cooler): acceptable items best first,
     * each with its ids (not gear, so ids rather than corpus names). */
    @lombok.RequiredArgsConstructor
    public static class Carried {
        public final String note;
        final List<String> names;
        final List<int[]> ids;
    }

    static final Map<String, List<Carried>> CARRIED_BY_NAME = new HashMap<>();
    static final Map<String, List<Carried>> SWAPS_BY_NAME = new HashMap<>();
    static final Set<String> WARD = new HashSet<>();

    static {
        // Fail LOUD (the name_rules pattern): a silently empty table would
        // drop every requirement with no visible error.
        JsonObject root = objectOrThrow("required_gear.json");
        for (JsonElement e : root.getAsJsonArray("rules")) {
            JsonObject row = e.getAsJsonObject();
            List<String> items = new ArrayList<>();
            strings(row, "items", items);
            var rule = new Rule( GearSlot.valueOf(string(row, "slot")), string(row, "note"),
                items, row.has("waivedBy") ? row.get("waivedBy").getAsString() : null,
                bool(row, "soft", false));
            for (JsonElement m : row.getAsJsonArray("monsters")) {
                BY_NAME.computeIfAbsent(m.getAsString(), k -> new ArrayList<>()).add(rule);
            }
        }
        if (BY_NAME.isEmpty()) throw new IllegalStateException("required_gear.json loaded empty");
        if (root.has("ward")) strings(root, "ward", WARD);
        for (String key : new String[]{"carried", "swaps"}) {
            if (!root.has(key)) continue;
            for (JsonElement e : root.getAsJsonArray(key)) {
                JsonObject row = e.getAsJsonObject();
                List<String> names = new ArrayList<>();
                List<int[]> ids = new ArrayList<>();
                for (JsonElement i : row.getAsJsonArray("items")) {
                    JsonObject item = i.getAsJsonObject();
                    names.add(string(item, "name"));
                    ids.add(ints(item.getAsJsonArray("ids")));
                }
                var carried = new Carried(string(row, "note"), names, ids);
                for (JsonElement m : row.getAsJsonArray("monsters")) {
                    (key.equals("swaps") ? SWAPS_BY_NAME : CARRIED_BY_NAME).computeIfAbsent(m.getAsString(), k -> new ArrayList<>()).add(carried);
                }
            }
        }
    }


    /** The fight's swap rules (ISS-01M5VCXYGF51P5NJCDNC1QJZD1): Cerberus' spectral spirit shield. */
    public static List<Carried> swaps(MonsterStats monster) {
        return monster == null ? List.of() : SWAPS_BY_NAME.getOrDefault(monster.nameLower, List.of());
    }

    /** Every swap id for the monster, each rule's best first. */
    public static List<Integer> swapIds(MonsterStats monster) {
        List<Integer> out = new ArrayList<>();
        for (Carried rule : swaps(monster)) {
            for (int[] ids : rule.ids) {
                for (int id : ids) out.add(id);
            }
        }
        return out;
    }

    /** What a carried swap is for, or "carried swap" for any other bench item. */
    public static String swapNote(int id) {
        for (List<Carried> rules : SWAPS_BY_NAME.values()) {
            for (Carried rule : rules) {
                for (int[] ids : rule.ids) {
                    for (int i : ids) if (i == id) return rule.note;
                }
            }
        }
        return "carried swap";
    }

    /** A fight whose prayer drain is demonic: Ward of Arceuus rides the trip (ISS-01M5VCXYGF51P5NJCDNC1QJZD1). */
    public static boolean ward(MonsterStats monster) { return monster != null && WARD.contains(monster.nameLower); }

    /** The requirement for this monster, or null. Name-keyed like the
     * notes, so RequiredGearTest pins every key against loaded rows. */
    /** Every rule for the monster (a full armour set is one rule per slot). */
    public static List<Rule> rulesFor(MonsterStats monster) {
        return monster == null ? List.of() : BY_NAME.getOrDefault(monster.nameLower, List.of());
    }

    /** The rules still standing once the player's waivers lift theirs. */
    public static List<Rule> rulesFor(MonsterStats monster, Set<String> waivers) {
        return rulesFor(monster).stream().filter(rule -> rule.waivedBy == null || waivers == null
            || !waivers.contains(rule.waivedBy)).collect(Collectors.toList());
    }

    /** slot -> acceptable ids, empty when nothing is required. */
    public static Map<GearSlot, Set<Integer>> requiredIds(MonsterStats monster, LoadoutData data) {
        return requiredIds(monster, data, Set.of());
    }

    /** slot -> acceptable ids, the waived rules lifted. */
    public static Map<GearSlot, Set<Integer>> requiredIds(MonsterStats monster, LoadoutData data, Set<String> waivers) {
        Map<GearSlot, Set<Integer>> out = new EnumMap<>(GearSlot.class);
        for (Rule rule : rulesFor(monster, waivers)) out.put(rule.slot, rule.ids(data));
        return out;
    }

    /** The carried slayer items this monster's kill needs, one per rule:
     * the best one you own, else the best one there is, flagged unowned
     * (Andrew 2026-10-22: "show them as necessary even when the player
     * doesn't own those items"). Each row: id, name, qty, why, owned. */
    public static List<Map> carriedPicks(MonsterStats monster, IntPredicate owns) {
        List<Map> out = new ArrayList<>();
        if (monster == null) return out;
        for (Carried rule : CARRIED_BY_NAME.getOrDefault(monster.nameLower, List.of())) {
            int pick = -1;
            for (int i = 0; i < rule.ids.size() && pick < 0; i++) {
                for (int id : rule.ids.get(i)) {
                    if (owns.test(id)) {
                        pick = i;
                        break;
                    }
                }
            }
            boolean owned = pick >= 0;
            int at = owned ? pick : 0;
            out.add(map("id", rule.ids.get(at)[0], "name", rule.names.get(at), "qty", 1,
                "why", rule.note + (owned ? "" : " - not owned: get one before the trip"), "owned", owned));
        }
        return out;
    }
}

