/**
 * Trip supplies (food, fast food, prayer restores, surge, anti-venom): the
 * curated tier tables behind the persistent supply defaults. Tiers live in
 * trip_supplies.json (hub token cap), best first per category; "Detect best"
 * walks a category in order and picks the first option the player owns any
 * dose of. Anti-venom only applies against the wiki Venom page's inflictor
 * list (the only monsters able to inflict venom).
 */
public class TripSupplies {
    public static final String FOOD = "food";
    public static final String FAST_FOOD = "fastFood";
    public static final String PRAYER_RESTORE = "prayerRestore";
    public static final String SURGE = "surge";
    public static final String SPELLBOOK_CAPE = "spellbookCape";
    public static final String ANTIVENOM = "antivenom";
    public static final String SHIP_REPAIR_KIT = "shipRepairKit";
    public static final String ANTIPOISON = "antipoison";
    /** The dwarf multicannon as a five-cell kit (miko 2026-10-17): no dps, no placement rules, never auto-detected. */
    public static final String CANNON = "cannon";
    /** Getting there (ISS-01M5JJ0Z4M988DR0M0ZGJHD139, Andrew 2026-10-22): the teleport capes,
     * best first, the Crafting cape an explicit choice. */
    public static final String TELEPORT_CAPE = "teleportCape";
    /** A boss's own teleport, carried in the inventory (ISS-01M5RMNK62507Q42KKCJ9A7AEE). */
    public static final String BOSS_TELEPORT = "bossTeleport";
    public static final String[] CATEGORY_KEYS = {FOOD, FAST_FOOD, PRAYER_RESTORE, SURGE, SPELLBOOK_CAPE, TELEPORT_CAPE, BOSS_TELEPORT, ANTIVENOM, ANTIPOISON, SHIP_REPAIR_KIT, CANNON};

    /** One supply choice: ids best-first, ids[0] the display/cell id and the
     * full list the bank-filter membership (every dose matches). */
    @lombok.AllArgsConstructor
    public static class Option {
        public final String key;
        public final String name;
        public final int[] ids;
        /** False = only selectable explicitly (prayer regeneration's
         * over-time mechanism should never win an auto-detect). */
        public final boolean detect;
        /** True = fight-relevant gear that is neither worn nor carried
         * (spellbook capes): the bank layout's third strip, below the
         * cross and the inventory block (field spec 2026-07-20). */
        public final boolean utility;
        /** True = usable only in the wilderness (blighted supplies): detect
         * prefers it on a wilderness trip and never picks it elsewhere. */
        public final boolean wildyOnly;
        /** Per-item names for a kit (one card cell each); empty for doses. */
        public final String[] names;
        /** A kit cell's ids - the display id first, then its variants (the
         * ornamented cannon parts, granite cannonballs); null = ids[i] alone. */
        public final int[][] cells;
        /** The bosses (exact lower-case names) a boss-specific option serves; empty = any trip. */
        public final String[] monsters;
        /** A varbit that must be set before the option works (the ring of shadows' tablets); 0 = none. */
        public final int unlock;
    }

    static final Map<String, List<Option>> CATEGORIES = new LinkedHashMap<>();
    static final Map<String, String> LABELS = new LinkedHashMap<>();
    static final Set<String> VENOMOUS = new HashSet<>();
    static final Set<String> POISONOUS = new HashSet<>();
    static final Set<String> NO_CANNON = new HashSet<>();

    static {
        JsonObject root = object("trip_supplies.json");
        if (root != null) {
            for (String category : CATEGORY_KEYS) {
                List<Option> options = new ArrayList<>();
                JsonArray arr = root.getAsJsonArray(category);
                if (arr != null) {
                    for (JsonElement e : arr) {
                        JsonObject o = e.getAsJsonObject();
                        options.add(new Option( string(o, "key"), string(o, "name"), ints(o.getAsJsonArray("ids")),
                            bool(o, "detect", true), "utility".equals(string(o, "placement")), bool(o, "wildyOnly", false),
                            words(o, "names"), cells(o), words(o, "monsters"), integer(o, "unlock", 0)));
                    }
                }
                CATEGORIES.put(category, options);
            }
            stringMap(root, "labels", LABELS);
            strings(root, "venomousMonsters", VENOMOUS);
            strings(root, "poisonMonsters", POISONOUS);
            strings(root, "noCannonMonsters", NO_CANNON);
        }
    }

    static String[] words(JsonObject o, String key) {
        List<String> out = new ArrayList<>();
        strings(o, key, out);
        return out.toArray(new String[0]);
    }

    static int[][] cells(JsonObject o) {
        JsonArray rows = o.getAsJsonArray("cells");
        if (rows == null) return null;
        int[][] out = new int[rows.size()][];
        for (int i = 0; i < out.length; i++) out[i] = ints(rows.get(i).getAsJsonArray());
        return out;
    }


    /** The grey chip's submenu label, or null for a category the menu never
     * shows (ship repair kits ride the sea card). */
    public static String label(String category) { return LABELS.get(category); }

    /** The category's options, best first. */
    public static List<Option> options(String category) { return CATEGORIES.getOrDefault(category, List.of()); }

    /** The option a config-enum constant names, or null (NONE/DETECT_BEST
     * and unknown keys resolve to null). */
    public static Option option(String category, String key) {
        return options(category).stream().filter(o -> o.key.equals(key)).findFirst().orElse(null);
    }

    /** Detect best for a trip: in the wilderness a banked blighted variant
     * wins outright (cheap to lose, wilderness-only); on land no
     * wilderness-only option is ever picked (Andrew 2026-09-01). */
    public static Option detectBest(List<Option> options, IntPredicate owns, boolean inWilderness) {
        Option pick = null;
        for (Option o : options) {
            if (!o.detect || (o.wildyOnly && !inWilderness)) continue;
            for (int id : o.ids) {
                if (owns.test(id)) {
                    if (o.wildyOnly) return o;
                    if (pick == null) pick = o;
                    break;
                }
            }
        }
        return pick;
    }

    /** Detect best on land: the first detectable option the player owns
     * any dose of, or null when they own none. */
    public static Option detectBest(String category, IntPredicate owns) { return detectBest(options(category), owns, false); }

    /** The options that fit a trip: any general one; a boss-specific one when a
     * trip mob is one of its bosses and its unlock (if any) is set. */
    public static List<Option> fitting(String category, List<MonsterStats> mobs, IntPredicate unlocked) {
        List<Option> out = new ArrayList<>();
        for (Option o : options(category)) {
            if ((o.monsters.length == 0 || mobs.stream().anyMatch(m -> Arrays.asList(o.monsters).contains(m.nameLower)))
                && (o.unlock == 0 || unlocked.test(o.unlock))) { out.add(o); }
        }
        return out;
    }

    /** The options' unlock varbits that are set. */
    public static Set<Integer> unlocked(IntUnaryOperator varbit) {
        Set<Integer> out = new HashSet<>();
        CATEGORIES.values().forEach(list -> list.forEach(o -> { if (o.unlock > 0 && varbit.applyAsInt(o.unlock) > 0) { out.add(o.unlock); } }));
        return out;
    }

    /** True when the monster can inflict venom (wiki Venom page inflictor
     * list, matched by name so araxyte/snakeling variants count). */
    public static boolean inflictsVenom(MonsterStats monster) { return named(monster, VENOMOUS); }

    /** Poisons but does not envenom (the Kings' spinolyps, KQ...) - the
     * antipoison category; venomous mobs keep anti-venom. */
    public static boolean inflictsPoison(MonsterStats monster) {
        return named(monster, POISONOUS) && !named(monster, VENOMOUS);
    }

    /** No cannon here: a prohibited arena or cannon-immune (exact names). */
    public static boolean noCannon(MonsterStats monster) {
        return monster != null && NO_CANNON.contains(monster.nameLower);
    }

    static boolean named(MonsterStats monster, Set<String> tokens) {
        if (monster == null) return false;
        String name = monster.nameLower;
        return tokens.stream().anyMatch(name::contains);
    }
}

package com.loadoutlab.data;

import java.util.*;
import com.google.gson.JsonObject;

/**
 * Monsters fought in the Wilderness, where dying to a PKer risks your
 * gear. Verified vs the wiki (Items Kept on Death, 2026-07-07): death
 * keeps your 3 highest-GE/alch-value items (4 with Protect Item; 0/1
 * skulled); since the June 2026 rework most untradeables are kept in
 * the Wilderness, with combat-capable ones returning broken/mangled
 * for a coin repair above level 20. A low-risk set therefore wears NO
 * MORE tradeables than the kept count - value ranking then cannot
 * drop any of them - and untradeables everywhere else.
 * Curated list: the boss ring, escape-cave counterparts, KBD, the
 * Revenant Caves, and the non-boss monsters players actually fight in
 * the Wilderness (Slayer Cave dwellers, dragons, Krystilia-task and
 * moneymaker mobs) - many also exist elsewhere, but the low-risk
 * toggles default off, so offering them costs nothing outside.
 */
public class WildernessMonsters {
    /** Curated lists live in wilderness_monsters.json (hub token cap). */
    static final Set<String> NAMES = new HashSet<>();
    /**
     * The subset that exists ONLY in the Wilderness - fighting one of these
     * IS being in the Wilderness, so the wilderness-weapon buff and the risk
     * UI apply unconditionally. Everything else on the list also spawns
     * elsewhere (Catacombs hellhounds, Taverley black dragons...), so those
     * take the user's "In the Wilderness" toggle instead (audit A3.1).
     * KBD note: the lair is reached through level-42 Wilderness; it stays
     * exclusive so the risk UI covers the walk, matching the pre-toggle
     * behaviour.
     */
    static final Set<String> EXCLUSIVE = new HashSet<>();

    static {
        JsonObject root = JsonResources.object( "wilderness_monsters.json");
        JsonResources.strings(root, "names", NAMES);
        JsonResources.strings(root, "exclusive", EXCLUSIVE);
    }


    public static boolean isWilderness(MonsterStats monster) {
        return monster != null && monster.isWildernessMonster();
    }

    /** True when the monster exists nowhere but the Wilderness. */
    public static boolean isExclusive(MonsterStats monster) {
        return monster != null && EXCLUSIVE.contains(monster.nameLower);
    }

    /** The raw name-list membership - MonsterStats caches this at build. */
    static boolean containsName(String nameLower) { return NAMES.contains(nameLower); }
}

package com.loadoutlab.engine;

import com.google.gson.*;
import com.loadoutlab.data.*;
import java.util.*;

/**
 * Blowpipes fire a LOADED dart whose ranged strength stacks on the
 * weapon's own stats - flat gear data cannot express it, which made bare
 * thrown dragon darts (35 str) outrank a dragon-dart blowpipe (20 + 35).
 *
 * <p>Game best assumes dragon darts; ownership-scoped queries use the
 * best dart tier the player owns (any poison variant counts). A blowpipe
 * with no owned darts gets no bonus and naturally falls out of the
 * suggestions - it cannot fire.
 */
public class BlowpipeDarts {
    /** Dart tiers, strongest first: {ranged strength, ids...} (all poison variants). */
    static final int[][] TIERS;
    static final String[] TIER_NAMES;

    static {
        JsonObject root = JsonResources.objectOrThrow("blowpipe_darts.json");
        List<String> names = new ArrayList<>();
        JsonResources.strings(root, "names", names);
        TIER_NAMES = names.toArray(new String[0]);
        JsonArray rows = root.getAsJsonArray("rows");
        TIERS = new int[rows.size()][];
        for (int t = 0; t < rows.size(); t++) {
            JsonArray row = rows.get(t).getAsJsonArray();
            TIERS[t] = new int[row.size()];
            for (int i = 0; i < row.size(); i++) TIERS[t][i] = row.get(i).getAsInt();
        }
    }


    /** Every tier for the pickers: [{id (unpoisoned base), name}],
     * strongest first - excluding the base id protects the whole tier. */
    public static List<Map> tiers() {
        List<Map> out = new ArrayList<>();
        for (int tier = 0; tier < TIERS.length; tier++) {
            Map node = new LinkedHashMap<>();
            node.put("id", TIERS[tier][1]);
            node.put("name", TIER_NAMES[tier]);
            out.add(node);
        }
        return out;
    }

    /** Extra ranged strength from the loaded dart, 0 for non-blowpipes. */
    public static int strength(OptimizationRequest request, GearItem weapon) {
        int tier = tierFor(request, weapon);
        return tier < 0 ? 0 : TIERS[tier][0];
    }

    /** The assumed/owned dart tier name for display, or null. */
    public static String tierName(OptimizationRequest request, GearItem weapon) {
        int tier = tierFor(request, weapon);
        return tier < 0 ? null : TIER_NAMES[tier];
    }

    /** The representative (unpoisoned) dart id for a display tier name -
     * lets the panel offer "exclude the loaded darts" on the blowpipe. */
    public static Integer baseIdForTierName(String tierName) {
        for (int tier = 0; tier < TIER_NAMES.length; tier++) {
            if (TIER_NAMES[tier].equals(tierName)) return TIERS[tier][1];
        }
        return null;
    }

    /** Excluding any variant of a dart tier protects the whole tier. */
    static boolean tierExcluded(OptimizationRequest request, int tier) {
        for (int i = 1; i < TIERS[tier].length; i++) {
            if (request.isExcluded(TIERS[tier][i])) return true;
        }
        return false;
    }

    static int tierFor(OptimizationRequest request, GearItem weapon) {
        if (weapon == null || !weapon.nameLower.contains("blowpipe")) return -1;
        boolean ownershipScoped = request.candidateMode == CandidateMode.OWNED_ONLY
            || request.candidateMode == CandidateMode.OWNED_OR_BUDGET;
        if (!ownershipScoped) {
            // Game best: the best dart tier that is not excluded.
            for (int tier = 0; tier < TIERS.length; tier++) {
                if (!tierExcluded(request, tier)) return tier;
            }
            return -1;
        }
        for (int tier = 0; tier < TIERS.length; tier++) {
            if (tierExcluded(request, tier)) continue;
            for (int i = 1; i < TIERS[tier].length; i++) {
                if (request.ownedItems.owns(TIERS[tier][i])) return tier;
            }
        }
        return -1; // owns no usable darts: the blowpipe cannot fire
    }
}

// Derived from guccifurs/best-dps (BSD-2-Clause, Copyright (c) 2026, Noid) - see licenses/best-dps-LICENSE.
package com.loadoutlab.engine;

/**
 * A potion/prayer-free stat boost applied on top of the base levels.
 *
 * <p>Every non-live profile is the same shape - floor(flat + level * factor)
 * added to a fixed set of skills - so each constant just carries its flat
 * term, its factor, and which skills it touches as letters over the alphabet
 * a(ttack) s(trength) d(efence) r(anged) m(agic). Magic potion's flat +4 is
 * encoded as factor 0.0, which makes floor(4 + level * 0.0) exactly 4.
 */
public enum BoostProfile {
    NONE("No boosts", 0, 0, ""), LIVE_CURRENT("Current boosted levels", 0, 0, ""),
    // Label deliberately avoids " + " - the assumes chips split on it.
    F2P_COMBAT("Attack & strength potions", 3, 0.10, "as"), SUPER_COMBAT("Super combat", 5, 0.15, "asd"),
    // Divine variants boost identically; they hold the boost at ceiling
    // for 5 minutes instead of decaying, so they are the preferred assumption.
    DIVINE_SUPER_COMBAT("Divine super combat", 5, 0.15, "asd"), RANGING("Ranging potion", 4, 0.10, "r"),
    DIVINE_RANGING("Divine ranging potion", 4, 0.10, "r"),
    // Same ranged numbers as the ranging potion; the super-defence half
    // is deliberately unmodeled here (outgoing dps never reads it).
    BASTION("Bastion potion", 4, 0.10, "r"), DIVINE_BASTION("Divine bastion potion", 4, 0.10, "r"),
    SUPER_RANGING("Super ranging", 5, 0.15, "r"), SATURATED_HEART("Saturated heart", 4, 0.10, "m"),
    IMBUED_HEART("Imbued heart", 1, 0.10, "m"), MAGIC("Magic potion", 4, 0.0, "m"), DIVINE_MAGIC("Divine magic potion", 4, 0.0, "m"),
    // Magic potion's flat +4 with the unmodeled super-defence half.
    BATTLEMAGE("Battlemage potion", 4, 0.0, "m"), DIVINE_BATTLEMAGE("Divine battlemage potion", 4, 0.0, "m"),
    SUPER_MAGIC("Super magic", 5, 0.15, "m"), OVERLOAD("Overload", 5, 0.13, "asdrm"),
    OVERLOAD_PLUS("Overload (+)", 6, 0.16, "asdrm"), SMELLING_SALTS("Smelling salts", 11, 0.16, "asdrm");

    final String label;
    final int flat;
    final double factor;
    /** Which skills this profile boosts, as letters from "asdrm". */
    final String skills;

    BoostProfile(String label, int flat, double factor, String skills) {
        this.label = label;
        this.flat = flat;
        this.factor = factor;
        this.skills = skills;
    }

    public PlayerLevels apply(PlayerLevels base, PlayerLevels current) {
        PlayerLevels source = base == null ? PlayerLevels.MAXED : base;
        if (this == LIVE_CURRENT) return current == null ? source : current;
        // NONE boosts nothing and must hand back the SAME instance: the
        // general path below always allocates a fresh PlayerLevels.
        if (skills.isEmpty()) return source;
        return source.withBoosts( boostIf('a', source.attack), boostIf('s', source.strength),
            boostIf('d', source.defence), boostIf('r', source.ranged), boostIf('m', source.magic));
    }

    /** True when this profile boosts the skill letter (from "asdrm") - the
     * assume-chip picker filters style-relevant boosts with it. */
    public boolean boosts(char skill) { return skills.indexOf(skill) >= 0; }

    /** floor(flat + level * factor), or 0 when this profile skips the skill. */
    int boostIf(char skill, int level) {
        return skills.indexOf(skill) < 0 ? 0 : (int) Math.floor(flat + level * factor);
    }

    public String toString() { return label; }
}

package com.loadoutlab.engine;

import com.loadoutlab.data.*;
import lombok.*;
import com.google.gson.*;
import java.util.*;

/**
 * Curated per-boss incoming-attack overrides - the D-2 layer on top of the
 * uniform v1 model in IncomingDpsCalculator. The stat sheet gets scripted
 * max hits wrong (Graardor's ranged slam is 15-35, the NPC formula derives
 * 58), rotations are not uniform, some attacks pierce protection prayers,
 * and Typeless/Dragonfire attacks are otherwise unmodeled. Each entry in
 * boss_incoming.json (keyed by lowercase display name, or name|version)
 * lists the boss's real attacks: style, scripted max hit, hits per attack,
 * rotation share, whether the matching protection prayer blocks it, whether
 * the standard play prays it on cue (flicked) and how much still leaks, an
 * optional per-attack speed. Numeric facts are wiki-sourced; see each
 * entry's note. The "_unpriced" block names the monsters the wiki cannot
 * price yet, with the reason the card shows instead of a number.
 */
public class BossIncomingOverrides {
    static final String RESOURCE = "boss_incoming.json";

    /** One curated attack in the boss's rotation. */
    @AllArgsConstructor
    @Getter
    public static class Attack {
        public final String style;
        public final int maxHit;
        final double share;
        final boolean prayable;
        /** Fraction of damage that gets THROUGH the matching protection
         * prayer: 0 = fully blocked, 0.5 = half pierces (Callisto melee,
         * Corp magic), 1 = prayer does nothing. maxHit is always the TRUE
         * unprayed value. */
        final double prayerFactor;
        /** 0 means "use the stat sheet's attack speed". */
        public final int speedTicks;
        /** Dodgeable by design (Zulrah's magma slam): the standard play
         * takes zero, so the attack is excluded from both dps totals and
         * kept in the threat list for the tooltip - the same philosophy as
         * assuming the protection prayer is up. */
        final boolean avoidable;
        /** The card's row label when the style alone would not tell two
         * rows apart ("ranged volley", "melee (x2)"); "" = the style. */
        public final String name;
        /** Hits per attack (three projectiles a volley, a 42 x2 melee):
         * the rate scales with it, the card's max hit does not. */
        final int hits;
        /** Telegraphed: the standard play prays it on cue whatever single
         * prayer it camps (ISS-01M5PBSZBBBAS9Y46X04MVMHZB). */
        final boolean flicked;
        /** The fraction of a flicked attack that still lands under standard
         * play - a mixed volley's odd projectile, a late swap. */
        final double leak;
        /** Dragonfire by protection layers (Vorkath): key "none" / "shield" /
         * "antifire" / "super" / "shield+antifire" / "shield+super" ->
         * {max without, max with Protect from Magic}; null for other attacks. */
        final Map<String, int[]> layers;
    }

    /** The full curated picture for one boss. */
    @Getter
    public static class BossOverride {
        final List<Attack> attacks;
        final String note;

        BossOverride(List<Attack> attacks, String note) {
            this.attacks = attacks;
            this.note = note;
        }
    }

    static final Map<String, BossOverride> OVERRIDES = new HashMap<>();
    /** Monsters the wiki cannot price yet, with the reason the card shows. */
    static final Map<String, String> UNPRICED = new HashMap<>();

    static {
        JsonObject root = JsonResources.objectOrThrow(RESOURCE);
        for (var entry : root.entrySet()) {
            if ("_unpriced".equals(entry.getKey())) {
                for (var why : entry.getValue().getAsJsonObject().entrySet()) {
                    UNPRICED.put(Names.lower(why.getKey()), why.getValue().getAsString());
                }
            } else if (!entry.getKey().startsWith("_")) {
                OVERRIDES.put(Names.lower(entry.getKey()), parse(entry.getValue().getAsJsonObject()));
            }
        }
    }

    /**
     * Shape-only read of one boss entry. The DATA validation that used to
     * throw from here (style whitelist, typeless-must-not-be-prayable, sane
     * maxHit/share/speed, shares summing to at most 1.0, non-empty attack
     * list) now lives in BossIncomingOverridesTest's all-overrides sweep -
     * test source is free of the hub token cap, and the sweep is coupled to a
     * hardcoded boss list so a newly added boss cannot skip it. Only the
     * "resource missing" throw stays here: that is a packaging failure, not
     * bad data.
     */
    static BossOverride parse(JsonObject json) {
        List<Attack> attacks = new ArrayList<>();
        for (JsonElement element : json.getAsJsonArray("attacks")) {
            JsonObject a = element.getAsJsonObject();
            boolean prayable = !a.has("prayable") || a.get("prayable").getAsBoolean();
            // Legacy semantics preserved: prayable = full block (0 through),
            // unprayable = full pierce (1 through), unless a factor is given.
            double prayerFactor = a.has("prayerFactor") ? a.get("prayerFactor").getAsDouble() : (prayable ? 0.0 : 1.0);
            attacks.add(new Attack( Names.lower(a.get("style").getAsString()), a.get("maxHit").getAsInt(),
                a.get("share").getAsDouble(), prayable, prayerFactor, a.has("speedTicks") ? a.get("speedTicks").getAsInt() : 0,
                a.has("avoidable") && a.get("avoidable").getAsBoolean(), a.has("name") ? a.get("name").getAsString() : "",
                a.has("hits") ? Math.max(1, a.get("hits").getAsInt()) : 1,
                a.has("flicked") && a.get("flicked").getAsBoolean(), a.has("leak") ? a.get("leak").getAsDouble() : 0.0,
                a.has("layers") ? layers(a.getAsJsonObject("layers")) : null));
        }
        return new BossOverride(attacks, json.has("note") ? json.get("note").getAsString() : "");
    }

    static Map<String, int[]> layers(JsonObject json) {
        Map<String, int[]> map = new HashMap<>();
        for (var e : json.entrySet()) {
            JsonArray pair = e.getValue().getAsJsonArray();
            map.put(e.getKey(), new int[]{pair.get(0).getAsInt(), pair.get(1).getAsInt()});
        }
        return map;
    }


    /** The curated override for this monster, or null to use the v1 model.
     * Keyed by display name so every version/phase row shares one entry. */
    public static BossOverride overridesFor(MonsterStats monster) { return lookup(OVERRIDES, monster); }

    /** Why the card shows no estimate for this monster, or null when the
     * curated data or the sheet prices it. */
    public static String unpricedReason(MonsterStats monster) { return lookup(UNPRICED, monster); }

    /** Version-keyed first ("zulrah|serpentine"): multi-form bosses fight
     * differently per form, and the roster lens shows one form at a time -
     * each must carry ITS OWN attacks and protect prayer (field report
     * 2026-07-17: every Zulrah form said pray mage). The bare name stays as
     * the whole-fight fallback. */
    static <T> T lookup(Map<String, T> map, MonsterStats monster) {
        if (monster == null) return null;
        String version = monster.version;
        if (version != null && !version.isEmpty()) {
            T byForm = map.get((monster.nameLower + "|" + version).toLowerCase(Locale.ROOT));
            if (byForm != null) return byForm;
        }
        return map.get(monster.nameLower);
    }

    /** All curated boss names (lowercase) - test and tooling surface. */
    public static Set<String> names() { return Collections.unmodifiableSet(OVERRIDES.keySet()); }
}

