package com.loadoutlab.engine;
import static java.lang.Math.*;

public class RollMath {
    static final double SECONDS_PER_TICK = 0.6;


    public static double normalAccuracy(long attackRoll, long defenceRoll) {
        double atk = attackRoll;
        double def = defenceRoll;
        if (atk < 0) atk = min(0, atk + 2);
        if (def < 0) def = min(0, def + 2);
        if (atk >= 0 && def >= 0) {
            return atk > def ? 1.0 - ((def + 2.0) / (2.0 * (atk + 1.0))) : atk / (2.0 * (def + 1.0));
        }
        if (atk >= 0) return 1.0 - 1.0 / ((-def + 1.0) * (atk + 1.0));
        if (def >= 0) return 0.0;
        double swappedAtk = -def;
        double swappedDef = -atk;
        return swappedAtk > swappedDef ? 1.0 - ((swappedDef + 2.0) / (2.0 * (swappedAtk + 1.0))) : swappedAtk / (2.0 * (swappedDef + 1.0));
    }

    public static int effectiveLevel(int level, double prayer, int stanceBonus) {
        return (int) floor(level * prayer) + stanceBonus + 8;
    }

    public static int maxHitFromEffective(int effectiveLevel, int strengthBonus) {
        return max(0, (int) floor((effectiveLevel * (strengthBonus + 64.0) + 320.0) / 640.0));
    }

    public static long attackRoll(int effectiveLevel, int attackBonus) {
        return (long) effectiveLevel * (attackBonus + 64L);
    }

    public static long defenceRoll(int effectiveLevel, int defenceBonus) {
        return (long) effectiveLevel * (defenceBonus + 64L);
    }

    public static double normalExpectedHit(double accuracy, int maxHit) {
        if (maxHit <= 0 || accuracy <= 0.0) return 0.0;
        return accuracy * (maxHit / 2.0 + 1.0 / (maxHit + 1.0));
    }

    /** The venator bow's chain in multi (wiki): two bounces, each rolled on
     * its own accuracy at a max of two-thirds of the first, floored - so
     * the whole arrow is worth 1 + 2 x E(floor(2m/3)) / E(m) single hits
     * (accuracy cancels). One target: 1. */
    public static double venatorFactor(int maxHit) {
        if (maxHit <= 0) return 1.0;
        return 1.0 + 2.0 * normalExpectedHit(1.0, maxHit * 2 / 3) / normalExpectedHit(1.0, maxHit);
    }

    /** Expected hit under the monster's FLAT ARMOUR, official-calc
     * semantics (flatAddTransformer, verified 2026-08-21): POSITIVE
     * armour clamps EVERY roll to max(0, k - armour) - the low rolls
     * become zeros, which the old shifted-bounds model missed
     * (Eclipse Moon overpriced ~16%, grey golem ~15%). Negative
     * armour (Blood/Blue Moon's flat bonus) is an exact bound shift,
     * delegated so armour-free numbers stay bit-identical. Bounds are
     * RAW (pre-armour). */
    public static double expectedHitWithFlatArmour(double accuracy, int minHit, int maxHit, int armour) {
        if (armour <= 0) {
            // NEGATIVE armour is a flat damage BONUS, and their
            // transformer applies it after the accurate-zero rule (a
            // landed 0 counts as 1). Shifting the bounds instead
            // silently dropped that bump - every Blood/Blue Moon set ran
            // 0.1-0.5% low (field 2026-08-21). Riding the bonus on top
            // of the normal expectation keeps the bump AND the shift.
            return expectedHit(accuracy, minHit, maxHit) + accuracy * -armour;
        }
        if (maxHit <= 0 || accuracy <= 0.0) return 0.0;
        int lo = max(0, min(minHit, maxHit));
        // sum(max(0, k - armour)) over k in [lo, maxHit], closed form: the
        // rolls at or under the armour contribute nothing, the rest are a
        // run of consecutive integers. Walking the rolls gave the same
        // total, but this runs on EVERY melee and ranged trial.
        long first = max((long) lo, (long) armour + 1);
        long sum = first > maxHit ? 0 : triangle(maxHit - armour) - triangle(first - armour - 1);
        return accuracy * ((double) sum / (maxHit - lo + 1));
    }

    /** The best of several damage rolls on one landed hit (the Obligator's
     * Lunge): P(best = v) weights each roll's damage under the same flat
     * armour rule as expectedHitWithFlatArmour; best of one is that hit. */
    public static double bestOfExpected(double accuracy, int maxHit, int rolls, int armour) {
        if (maxHit <= 0 || accuracy <= 0.0) return 0.0;
        double total = 0;
        double below = 0;
        for (int v = 0; v <= maxHit; v++) {
            double atMost = pow((v + 1.0) / (maxHit + 1.0), rolls);
            total += (atMost - below) * (armour > 0 ? max(0, v - armour) : max(1, v) - armour);
            below = atMost;
        }
        return accuracy * total;
    }

    /** 0 + 1 + ... + n; n below zero is an empty run. */
    static long triangle(long n) { return n <= 0 ? 0 : n * (n + 1) / 2; }

    public static double expectedHit(double accuracy, int minHit, int maxHit) {
        if (maxHit <= 0 || accuracy <= 0.0) return 0.0;
        if (minHit <= 0) return normalExpectedHit(accuracy, maxHit);
        int minimum = min(minHit, maxHit);
        return accuracy * ((minimum + maxHit) / 2.0);
    }

    /** Confliction gauntlets (official BaseCalc): casting one-handed
     * grants a SECOND accuracy roll, resolved as
     * double / (1 + double - single) - the same double-roll the fang
     * uses, folded so the extra roll cannot exceed certainty. */
    public static double conflictionAccuracy(long attackRoll, long defenceRoll) {
        double single = normalAccuracy(attackRoll, defenceRoll);
        double doubleRoll = fangAccuracy(attackRoll, defenceRoll);
        double denominator = 1 + doubleRoll - single;
        return denominator <= 0 ? single : doubleRoll / denominator;
    }

    public static double fangAccuracy(long attackRoll, long defenceRoll) {
        double atk = attackRoll;
        double def = defenceRoll;
        if (atk < 0) atk = min(0, atk + 2);
        if (def < 0) def = min(0, def + 2);
        if (atk >= 0 && def >= 0) {
            return atk > def ? 1.0 - (def + 2.0) * (2.0 * def + 3.0) / (atk + 1.0) / (atk + 1.0) / 6.0
                : atk * (4.0 * atk + 5.0) / 6.0 / (atk + 1.0) / (def + 1.0);
        }
        if (atk >= 0) return 1.0 - 1.0 / (-def + 1.0) / (atk + 1.0);
        if (def >= 0) return 0.0;
        double reversedAttack = -def;
        double reversedDefence = -atk;
        return reversedAttack < reversedDefence
            ? reversedAttack * (reversedDefence * 6.0 - 2.0 * reversedAttack + 5.0) / 6.0 / (reversedDefence + 1.0) / (reversedDefence + 1.0)
            : 1.0 - (reversedDefence + 2.0) * (2.0 * reversedDefence + 3.0) / 6.0 / (reversedDefence + 1.0) / (reversedAttack + 1.0);
    }
}

package com.loadoutlab.engine;

import com.loadoutlab.data.*;
import java.util.*;
import lombok.*;
import java.util.regex.Pattern;

/**
 * Rules a set must keep (ISS-01M5XA7NVZYGVR3EVTM05XHXKP): thresholds over the
 * worn set's totals, banned item names and an optional weapon allow-list - a
 * combat achievement's restrictions or the player's own ("at least 12
 * prayer"). Names match case-insensitively on the item name, every version.
 * The task-wide kinds (ISS-01M5ZQH7H4ZS95N6274QQ7EAJB): the styles allowed,
 * weapon categories, demonbane, one-handed, no weapon, one melee attack type,
 * no prayer, one spellbook, spell families and a level cap.
 */
@Getter
@ToString
@Builder(toBuilder = true)
@AllArgsConstructor(access = AccessLevel.PRIVATE)
public class SetRules {
    /** {stat, op, value}: op is >=, <=, > or <. */
    @Value
    public static class Rule {
        String stat;
        String op;
        double value;

        public boolean holds(double total) {
            switch (op) {
                case ">=": return total >= value;
                case "<=": return total <= value;
                case ">": return total > value;
                default: return total < value;
            }
        }

        /** Whether some total in [lo, hi] could still hold. */
        boolean reachable(double lo, double hi) { return op.startsWith(">") ? holds(hi) : holds(lo); }
    }

    @Builder.Default
    final List<Rule> rules = List.of();
    @Builder.Default
    final Set<String> banned = Set.of();
    /** Weapon names allowed; null = no name list. */
    final Set<String> weapons;
    /** Weapon categories allowed (lowercase: "spear", "salamander"); null = none. */
    final Set<String> weaponCategories;
    /** A demonbane weapon is allowed (with the lists above, any one match does). */
    final boolean demonbaneWeapon;
    final boolean bannedDemonbane;
    final boolean oneHanded;
    /** No weapon at all: melee punches, magic casts manually. */
    final boolean unarmed;
    /** Magic may search an empty weapon slot, casting manually. */
    final boolean noWeaponMagic;
    /** The combat styles allowed (other styles get no set); null = every style. */
    final Set<CombatStyle> styles;
    /** The one melee attack type ("stab", "crush"), or null. */
    public final String attackType;
    /** No prayer-restoring supplies (The Praying Mantis: pray, never restore). */
    public final boolean noPrayerRestore;
    /** The one spellbook ("arceuus"), or null. */
    public final String spellbook;
    /** Fragments a spell's name must contain (any one), or null. */
    public final List<String> spells;
    /** No item may need a level above this; 0 = no cap. */
    final int levelCap;
    /** The weapon must poison or envenom (A Slow Death, ISS-01M60HTYZT9DTZKDSFAGRNNK53). */
    final boolean poisonWeapon;
    /** A free-to-play world: the page's F2P lock rides the task. */
    public final boolean f2p;
    /** Further weapon allow-lists and spell families, each of which must also
     * hold - what and() keeps apart, since one list is an OR within itself. */
    @Builder.Default
    final List<SetRules> also = List.of();

    public static SetRules of(List<Rule> rules, Set<String> banned, Set<String> weapons) {
        return builder().rules(rules).banned(lower(banned)).weapons(weapons == null ? null : lower(weapons)).build();
    }

    /** "prayer>=12;def_ranged>=100" -> rules, in order; a part that does not parse is skipped. */
    public static List<Rule> parse(String text) {
        List<Rule> out = new ArrayList<>();
        if (text == null) return out;
        for (String part : text.split(";")) {
            var m = Pattern.compile("\\s*([a-z_]+)\\s*(>=|<=|>|<)\\s*(-?[0-9.]+)\\s*").matcher(part);
            if (m.matches() && STATS.contains(m.group(1))) out.add(new Rule(m.group(1), m.group(2), Double.parseDouble(m.group(3))));
        }
        return out;
    }

    /** The stats a rule may name. */
    public static final List<String> STATS = List.of("stab", "slash", "crush", "magic", "ranged", "def_stab", "def_slash",
        "def_crush", "def_magic", "def_ranged", "str", "ranged_str", "magic_str", "prayer", "weight");

    /** These rules plus more thresholds (everything else kept). */
    public SetRules plus(List<Rule> more) {
        List<Rule> all = new ArrayList<>(rules);
        all.addAll(more);
        return toBuilder().rules(List.copyOf(all)).build();
    }

    static Set<String> lower(Set<String> names) {
        Set<String> out = new HashSet<>();
        for (String n : names) out.add(Names.lower(n));
        return out;
    }

    /** These rules AND another set's (ISS-01M601Z57QM43W7SHNHCRMWDCE: two tasks at once, Andrew 2026-10-27:
     * "the challenge cards in the requirements seem to operate on an OR basis
     * but can and should be able to be AND"): thresholds and bans add up, the
     * styles narrow, and each weapon list must hold on its own. */
    public SetRules and(SetRules o) {
        if (o == null) return this;
        List<Rule> all = new ArrayList<>(rules);
        all.addAll(o.rules);
        Set<String> bans = new HashSet<>(banned);
        bans.addAll(o.banned);
        Set<CombatStyle> both = styles == null ? o.styles : o.styles == null ? styles : EnumSet.copyOf(styles);
        if (styles != null && o.styles != null) both.retainAll(o.styles);
        List<SetRules> parts = new ArrayList<>(also);
        parts.addAll(o.also);
        boolean mine = hasWeaponList(), theirs = o.hasWeaponList();
        if (theirs && mine || o.spells != null && spells != null) parts.add(o.weaponsAndSpellsOnly());
        int cap = levelCap == 0 ? o.levelCap : o.levelCap == 0 ? levelCap : Math.min(levelCap, o.levelCap);
        var b = toBuilder().rules(List.copyOf(all)).banned(bans).styles(both).also(List.copyOf(parts))
            .bannedDemonbane(bannedDemonbane || o.bannedDemonbane).oneHanded(oneHanded || o.oneHanded)
            .unarmed(unarmed || o.unarmed).noPrayerRestore(noPrayerRestore || o.noPrayerRestore)
            .attackType(attackType != null ? attackType : o.attackType).spellbook(spellbook != null ? spellbook : o.spellbook)
            .levelCap(cap).poisonWeapon(poisonWeapon || o.poisonWeapon).f2p(f2p || o.f2p)
            // Empty hands only when some task asks for them and no weapon list forbids them.
            .noWeaponMagic((noWeaponMagic || o.noWeaponMagic) && (noWeaponMagic || !mine) && (o.noWeaponMagic || !theirs));
        if (!mine && theirs) b.weapons(o.weapons).weaponCategories(o.weaponCategories).demonbaneWeapon(o.demonbaneWeapon);
        if (spells == null && o.spells != null) b.spells(o.spells);
        return b.build();
    }

    boolean hasWeaponList() { return weapons != null || weaponCategories != null || demonbaneWeapon; }

    SetRules weaponsAndSpellsOnly() {
        return builder().weapons(weapons).weaponCategories(weaponCategories).demonbaneWeapon(demonbaneWeapon).spells(spells).build();
    }

    /** May this style have a set at all? */
    public boolean allowsStyle(CombatStyle style) { return styles == null || styles.contains(style); }

    /** May this item be worn at all (bans, the level cap, and the weapon rules for weapons)? */
    public boolean allows(GearItem item) {
        if (item == null) return true;
        if (banned.contains(item.nameLower)) return false;
        if (levelCap > 0 && item.requirements.getSkills().values().stream().anyMatch(level -> level > levelCap)) return false;
        if (item.slot != GearSlot.WEAPON) return true;
        if (unarmed || bannedDemonbane && item.demonbane || oneHanded && item.twoHanded) return false;
        if (attackType != null && WeaponStyles.melee(item).stream().noneMatch(s -> s.attackType.equals(attackType))) return false;
        if (poisonWeapon && !poisons(item)) return false;
        for (SetRules part : also) if (!part.allows(item)) return false;
        if (weapons == null && weaponCategories == null && !demonbaneWeapon) return true;
        return weapons != null && weapons.contains(item.nameLower)
            || weaponCategories != null && weaponCategories.contains(item.categoryLower)
            || demonbaneWeapon && item.demonbane;
    }

    /** A poisoned version, or a charged venom weapon (toxic blowpipe, toxic staff). */
    public static boolean poisons(GearItem weapon) {
        if (weapon.poisonTier() > 0) return true;
        String version = Names.lower(weapon.version);
        return weapon.nameLower.startsWith("toxic ") && !version.contains("uncharged") && !version.contains("empty");
    }

    /** May magic cast with no weapon? */
    public boolean emptyHanded(CombatStyle style) {
        return unarmed && style != CombatStyle.RANGED || noWeaponMagic && style == CombatStyle.MAGIC;
    }

    /** May this spell be cast? */
    public boolean allowsSpell(String spellNameLower) {
        return (spells == null || spells.stream().anyMatch(spellNameLower::contains))
            && also.stream().allMatch(part -> part.allowsSpell(spellNameLower));
    }

    /** One item's contribution to a stat: a bonus, weight, price, "has:<name>"
     * (1 when the name starts with it) or "slot:<slot>" (1 in that slot). */
    public static double of(GearItem item, String stat) {
        if (item == null) return 0;
        if (stat.startsWith("has:")) return item.nameLower.startsWith(stat.substring(4)) ? 1 : 0;
        if (stat.startsWith("slot:")) return item.slot.name().equalsIgnoreCase(stat.substring(5)) ? 1 : 0;
        StatBlock off = item.offensive, def = item.defensive, bon = item.bonuses;
        switch (stat) {
            case "weight": return item.weight;
            case "price": return item.getPriceOrZero();
            case "str": return bon.strength;
            case "ranged_str": return bon.rangedStrength;
            case "magic_str": return bon.magicDamage;
            case "prayer": return bon.prayer;
            default:
                return stat.startsWith("def_") ? def.getAttackBonus(stat.substring(4)) : off.getAttackBonus(stat);
        }
    }

    public static double total(Loadout loadout, String stat) {
        double sum = 0;
        for (GearItem item : loadout.getGear().values()) sum += of(item, stat);
        return sum;
    }

    /** Every item is allowed and every rule holds on this finished set. */
    public boolean holds(Loadout loadout) {
        for (GearItem item : loadout.getGear().values()) {
            if (!allows(item)) return false;
        }
        if (poisonWeapon && loadout.getWeapon() == null) return false;
        for (Rule rule : rules) {
            if (!rule.holds(total(loadout, rule.getStat()))) return false;
        }
        return true;
    }
}

package com.loadoutlab.engine;

/**
 * Boat-cannon math (wiki: Boat combat / Cannons, verified 2026-08-31). Pure
 * formulas; the data (per-tier strengths, accuracies, tick rate) lives in
 * NavalCombat and callers pass numbers in.
 *
 * <p>Player-fired: max hit rides the player's EFFECTIVE ranged level - the
 * caller applies prayer/void through the engine's existing effective-level
 * machinery, exactly as land ranged does - and the worn ranged strength
 * bonus counts EXCLUDING the weapon, shield and ammo slots (wiki: those
 * three are ignored at the cannon).
 *
 * <p>Crew-fired: the last documented formula scales a base max hit by the
 * crew's Privateering level, (priv + 13) / 20. The wiki flags this formula
 * out-of-date with the real one unknown, so it is isolated HERE and marked
 * by NavalCombat.crewFormulaStale() - when the corrected formula lands,
 * this one method changes and every caller stays put.
 */
public class ShipCannon {
    /** All cannons fire on the same cycle regardless of tier. */
    public static final double ATTACK_SECONDS = 4.2;


    /**
     * Max hit for a player-fired cannon:
     * floor((level * (cannonStr + ballStr + wornStr + 64) + 320) / 640),
     * plus one when a perildance bitter keg is aboard.
     */
    public static int playerMaxHit(int effectiveRanged, int cannonStrength, int ballStrength, int wornRangedStrength, boolean perildance) {
        long strength = cannonStrength + ballStrength + wornRangedStrength + 64L;
        int hit = (int) ((effectiveRanged * strength + 320L) / 640L);
        return hit + (perildance ? 1 : 0);
    }

    /** The stale-but-documented crew scaling: floor(base * (priv + 13) / 20). */
    public static int crewMaxHit(int baseMaxHit, int privateering) {
        return (int) (baseMaxHit * (privateering + 13L) / 20L);
    }

    /** The cannon's equipment accuracy: its heavy-ranged accuracy plus the
     * ball's, plus worn ranged accuracy excluding weapon/shield/ammo. Rolls
     * against the monster's HEAVY defence through the standard machinery. */
    public static int equipmentAccuracy(int cannonHeavyAccuracy, int ballAccuracy, int wornRangedAccuracy) {
        return cannonHeavyAccuracy + ballAccuracy + wornRangedAccuracy;
    }

    /**
     * Hit chance vs the monster's HEAVY ranged defence, through the same
     * roll math the land engine uses. Effective level is visible ranged
     * + 8 (no stance bonus at a cannon); prayer accuracy multipliers are
     * the caller's concern, matching how the wiki's calculator treats
     * prayer as an input to the level term.
     */
    public static double hitChance(int effectiveRanged, int equipmentAccuracy, int monsterDefence, int monsterHeavyBonus) {
        long attack = RollMath.attackRoll(effectiveRanged + 8, equipmentAccuracy);
        long defence = RollMath.defenceRoll(monsterDefence + 9, monsterHeavyBonus);
        return RollMath.normalAccuracy(attack, defence);
    }

    /** DPS of one cannon: average landed damage over the 7-tick cycle.
     * hitChance in [0,1]; a landed hit averages (maxHit / 2) with the
     * uniform damage roll the game uses. */
    public static double dps(int maxHit, double hitChance) { return hitChance * (maxHit / 2.0) / ATTACK_SECONDS; }
}

package com.loadoutlab.engine;

import lombok.*;
import com.loadoutlab.data.*;
import java.util.*;
import static java.lang.Math.*;
import com.google.gson.JsonObject;
import com.google.gson.JsonElement;

/**
 * Special-attack definitions and expected-damage math.
 *
 * <p>Every entry's cost/modifiers were verified against the OSRS Wiki
 * "Special attacks" page (and individual weapon pages) on 2026-07-05.
 * Accuracy modifiers multiply the ATTACK ROLL (not the final hit chance),
 * matching in-game mechanics; damage modifiers scale the max hit.
 *
 * <p>Expected damage is per single use of the special attack, against the
 * monster the base result was computed for. Utility effects (defence
 * drains, heals, bolt procs) are described in {@link #getNote()} but not
 * folded into the number.
 */
@AllArgsConstructor(access = AccessLevel.PRIVATE)
@Getter
public class SpecialAttack {
    public enum Kind {
        /** One hit: accuracy and/or damage multipliers. */
        SINGLE,
        /** Two fully independent hits (dragon dagger, dragon knife). */
        DOUBLE_INDEPENDENT,
        /** Two hits that share one accuracy outcome (abyssal dagger). */
        LINKED_DOUBLE,
        /** Guaranteed damage, uniform 50-150% of max (voidwaker). */
        VOIDWAKER,
        /** Up to 4 accuracy rolls; damage tier by which roll landed (dragon claws). */
        CLAWS,
        /** Two hits, boosted damage roll with a minimum per hit, capped at 48 (dark bow). */
        DARK_BOW,
        /** Two arrows; custom prayer-less max-hit formula, 10/7 accuracy (magic shortbow). */
        MSB_SNAPSHOT,
        /** +10% damage; a second hit at 75% accuracy vs large monsters (halberds). */
        HALBERD_SWEEP,
        /** An instant extra normal attack (granite maul). */
        EXTRA_ATTACK,
        /** Level-scaled unique damage roll (volatile nightmare staff). */
        VOLATILE,
        /** One accuracy roll; a hit deals EXACTLY damageMultiplier * max, no damage roll (sunspear). */
        FIXED_FRACTION,
        /** Four independent accuracy rolls; damage tier scales with successes (crimson kisten). */
        MULTI_ROLL_TIERED,
        /** Claws-style cascade with tier means 1.25/1.00/0.75 of max (burning claws). */
        CASCADE_CLAWS,
        /** A landed cast buffs the next three, fired every two ticks (Zorya's tome). */
        BUFFED_FOLLOWUPS,
    }

    static final int DARK_BOW_CAP = 48;

    final String[] namePrefixes;
    final String displayName;
    public final CombatStyle style;
    final Kind kind;
    public final int energyCost;
    final double accuracyMultiplier;
    final double damageMultiplier;
    final String note;
    /** Defence drained on a damaging hit, as a fraction of CURRENT defence
     * (DWH 0.30, elder maul 0.35); 0 for non-drain specs. BGS drains by
     * damage dealt - modeled via {@link #drainsByDamage}. */
    final double defenceDrainFraction;
    final boolean drainsByDamage;
    /** Drains DEFENCE by this fraction of the target's MAGIC level per
     * landed spec (Tonalztics of ralos' Division - wiki 2026-08-09:
     * 12.5% per glaive hit, two glaives charged = 25% per spec). */
    final double magicDrainFraction;
    /** Targets the spec hits in a multi area (wiki); 0 = single-target. */
    final int multiTargets;

    /** Wiki-verified entries live in special_attacks.json (hub token cap:
     * data rides resources, not source). Order matters: more specific
     * prefixes ("magic shortbow (i)") come first in the file. */
    static final List<SpecialAttack> REGISTRY = loadRegistry();

    static List<SpecialAttack> loadRegistry() {
        List<SpecialAttack> specs = new ArrayList<>();
        try {
            for (JsonElement element : JsonResources.array( "special_attacks.json")) {
                JsonObject row = element.getAsJsonObject();
                List<String> prefixes = new ArrayList<>();
                JsonResources.strings(row, "prefixes", prefixes);
                specs.add(new SpecialAttack(prefixes.toArray(new String[0]), row.get("name").getAsString(),
                    CombatStyle.valueOf(row.get("style").getAsString()), Kind.valueOf(row.get("kind").getAsString()),
                    row.get("cost").getAsInt(), row.get("accuracy").getAsDouble(), row.get("damage").getAsDouble(),
                    row.get("note").getAsString(), row.get("drainFraction").getAsDouble(),
                    row.get("drainsByDamage").getAsBoolean(), row.has("drainMagicFraction")
                        ? row.get("drainMagicFraction").getAsDouble() : 0, row.has("multi") ? row.get("multi").getAsInt() : 0));
            }
        } catch (Exception e) {
            // A malformed table must never take the client down; the spec
            // tests fail loudly on an empty registry instead.
            return List.of();
        }
        return specs;
    }


    /** The definition for this weapon at this combat style, or null. */
    public static SpecialAttack match(GearItem item, CombatStyle style) {
        SpecialAttack spec = match(item);
        return spec != null && spec.style == style ? spec : null;
    }

    /** Style-free match: the spec swap is its own weapon switch, so every
     * spec weapon is a candidate for ANY set (field request 2026-07-17 -
     * "sometimes you want to use magic + chally"). */
    public static SpecialAttack match(GearItem item) {
        if (item == null || item.slot != GearSlot.WEAPON) return null;
        String name = item.nameLower;
        for (SpecialAttack spec : REGISTRY) {
            for (String prefix : spec.namePrefixes) {
                if (name.startsWith(prefix)) return spec;
            }
        }
        return null;
    }

    /**
     * Expected damage of ONE special attack, given the normal-attack result
     * for the same loadout (source of max hit and attack/defence rolls).
     */
    /** The spec's multiplier at a stack of targets (the Multi card, Andrew
     * 2026-10-19): the stack capped at the targets it hits; 1 single-target. */
    public double multiFactor(int stack) { return multiTargets <= 0 ? 1 : max(1, min(stack, multiTargets)); }

    public double expectedDamage(DpsResult base, MonsterStats monster, PlayerLevels levels) {
        // The Wardens' ejected core (wiki): melee "will always deal their
        // max hit" - hitChance and every damage roll collapse to their
        // caps. Without this, the rolls below would halve every spec's
        // value at the one place the game is built around spec dumping.
        if (style == CombatStyle.MELEE && MonsterMechanics.isWardenCore(monster)) {
            return coreMaxDamage(base, monster);
        }
        long attackRoll = base.attackRoll;
        long defenceRoll = base.defenceRoll;
        double hitChance = RollMath.normalAccuracy( (long) (attackRoll * accuracyMultiplier), defenceRoll);
        int max = base.maxHit;
        // One boosted hit's mean, and its expectation over the accuracy roll.
        double boosted = mean((int) (max * damageMultiplier));
        double hit = hitChance * boosted;

        switch (kind) {
            case SINGLE:
                return hit;
            case DOUBLE_INDEPENDENT:
                return 2 * hit;
            case LINKED_DOUBLE:
                // One accuracy outcome for both hits.
                return hit * 2;
            case VOIDWAKER:
                // Uniform 50-150% of max, no accuracy roll: averages exactly max.
                return max;
            case CLAWS:
                return clawsExpected(hitChance, max);
            case DARK_BOW:
                return darkBowExpected(hitChance, max, usesDragonArrows(base));
            case MSB_SNAPSHOT:
                return 2 * hitChance * mean(snapshotMax(base, levels));
            case HALBERD_SWEEP:
                // A second hit at 75% accuracy vs large monsters.
                return monster != null && monster.size > 1
                    ? hit + RollMath.normalAccuracy((long) (attackRoll * 0.75), defenceRoll) * boosted : hit;
            case EXTRA_ATTACK:
                return base.expectedHit;
            case FIXED_FRACTION:
                // No damage roll: a hit deals exactly damageMultiplier * max.
                return hitChance * damageMultiplier * max;
            case MULTI_ROLL_TIERED:
                return multiRollTieredExpected(hitChance, max);
            case CASCADE_CLAWS:
                return cascadeClawsExpected(hitChance, max);
            case BUFFED_FOLLOWUPS:
                return hit * (1 + 3 * hitChance);
            case VOLATILE:
            default:
                return hitChance * mean(volatileMax(base, levels));
        }
    }

    /** Every melee hit at the Warden's core deals its max (wiki) - each
     * kind collapses to its hit count at the TOP of its damage range:
     * doubles land both boosted hits, the claw cascades sit at their
     * tier-1 cap, the voidwaker's uniform roll caps at 150%. The 1x1
     * core denies the halberd sweep its second hit - which is exactly
     * why the DDS dump beats a chally there (field report 2026-08-06). */
    double coreMaxDamage(DpsResult base, MonsterStats monster) {
        int max = base.maxHit;
        switch (kind) {
            case HALBERD_SWEEP:
                return (monster.size > 1 ? 2.0 : 1.0)
                    * (int) (max * damageMultiplier);
            case DOUBLE_INDEPENDENT:
            case LINKED_DOUBLE:
                return 2.0 * (int) (max * damageMultiplier);
            case CLAWS:
                return 2.0 * max; // tier-1 cascade cap (max + halves/quarters)
            case CASCADE_CLAWS:
                return 1.5 * max; // tier-1 cap of the 1.25-mean uniform
            case MULTI_ROLL_TIERED:
                return 1.7 * max; // four successes, top of the k=4 range
            case VOIDWAKER:
                return 1.5 * max;
            case EXTRA_ATTACK:
                return base.expectedHit; // already max via calculate()
            case SINGLE:
            case FIXED_FRACTION:
            default:
                return (int) (max * damageMultiplier);
        }
    }

    /**
     * Dragon claws cascade: accuracy is rolled up to four times; the tier of
     * the successful roll sets the damage-roll modifier (100/75/50/25% of
     * max added to the minimum). Expected totals per tier: 1.5max-1,
     * 1.25max, max, 0.75max; a full miss averages ~1.
     */
    static double clawsExpected(double p, int max) {
        double miss = 1 - p;
        return p * (1.5 * max - 1) + miss * p * (1.25 * max) + miss * miss * p * max
            + miss * miss * miss * p * (0.75 * max) + pow(miss, 4) * 1.0;
    }

    /**
     * Crimson kisten Brutal Swing: four independent accuracy rolls; with
     * k >= 1 successes damage is uniform in [(50+20k)%, (90+20k)%] of max
     * (mean (0.7 + 0.2k) * max); zero successes deal nothing.
     */
    static double multiRollTieredExpected(double p, int max) {
        // Binomial coefficients C(4, k) for k = 0..4.
        int[] choose = {1, 4, 6, 4, 1};
        double expected = 0;
        for (int k = 1; k <= 4; k++) {
            expected += choose[k] * pow(p, k) * pow(1 - p, 4 - k)
                * (0.7 + 0.2 * k) * max;
        }
        return expected;
    }

    /**
     * Burning claws cascade: the first successful roll (of up to three)
     * sets the tier - uniform damage with means 1.25/1.00/0.75 of max; a
     * full miss deals 0/1/2 with 20/40/40% odds (expected 1.2). The burn
     * damage-over-time is described in the note, not counted here.
     */
    static double cascadeClawsExpected(double p, int max) {
        double miss = 1 - p;
        return p * (1.25 * max) + miss * p * (1.00 * max) + miss * miss * p * (0.75 * max) + miss * miss * miss * 1.2;
    }

    /** Dark bow: two hits, each rolled 0..boostedMax then clamped [min, 48]. */
    static double darkBowExpected(double p, int max, boolean dragonArrows) {
        int boosted = (int) (max * (dragonArrows ? 1.5 : 1.3));
        int min = dragonArrows ? 8 : 5;
        double sum = 0;
        for (int d = 0; d <= boosted; d++) sum += min(DARK_BOW_CAP, max(min, d));
        return 2 * p * (sum / (boosted + 1));
    }

    static boolean usesDragonArrows(DpsResult base) {
        GearItem ammo = base.loadout.get(GearSlot.AMMO);
        return ammo != null && ammo.nameLower.startsWith("dragon arrow");
    }

    /**
     * Snapshot max hit ignores prayers and void:
     * floor(0.5 + (visible ranged + 10) * (ammo ranged str + 64) / 640).
     */
    static int snapshotMax(DpsResult base, PlayerLevels levels) {
        GearItem ammo = base.loadout.get(GearSlot.AMMO);
        int ammoStrength = ammo == null ? 0 : ammo.bonuses.rangedStrength;
        return (int) floor(0.5 + (levels.ranged + 10) * (ammoStrength + 64) / 640.0);
    }

    /**
     * Volatile spec max: spell max is min(floor(58 * level / 99) + 1, 58)
     * - 58 from level 98 up - then the loadout's magic damage bonus
     * (tenths of a percent) scales it. Wiki anchors: level 84 gives spell
     * max 50 (57 with the staff's 15% bonus); level 99 gives 58 (66).
     */
    static int volatileMax(DpsResult base, PlayerLevels levels) {
        int spellMax = min((int) floor(58.0 * levels.magic / 99.0) + 1, 58);
        double gearBonus = 1 + base.loadout.bonuses.magicDamage / 1000.0;
        return (int) floor(spellMax * gearBonus);
    }

    static double mean(int maxHit) { return maxHit / 2.0; }

    /** Ticks a spec spends beyond its own cast: the tome's follow-ups. */
    public double extraTicks(DpsResult base) { return kind == Kind.BUFFED_FOLLOWUPS ? 6 * landChance(base) : 0; }

    /** Chance this spec lands a damaging hit, from the base result's rolls. */
    public double landChance(DpsResult base) {
        if (kind == Kind.VOIDWAKER) return 1.0;
        return RollMath.normalAccuracy( (long) (base.attackRoll * accuracyMultiplier), base.defenceRoll);
    }

    /**
     * The monster's Defence level after ONE successful use of this spec, or
     * the unchanged level for non-drain specs. BGS drains by damage dealt.
     */
    public int drainedDefence(int currentDefence, double specExpectedDamage) {
        if (drainsByDamage) return max(0, currentDefence - (int) specExpectedDamage);
        if (defenceDrainFraction > 0) return currentDefence - (int) (currentDefence * defenceDrainFraction);
        return currentDefence;
    }

    /** Monster-aware drain: the Division spec measures its DEFENCE drain
     * off the target's MAGIC level, so it shines exactly where a DWH
     * cannot reach (the wiki's example: Zulrah's 300 Magic). */
    public int drainedDefence(MonsterStats monster, double specExpectedDamage) {
        if (magicDrainFraction > 0) {
            return max(0, monster.defence - (int) (monster.magic * magicDrainFraction));
        }
        return drainedDefence(monster.defence, specExpectedDamage);
    }

    public boolean drainsDefence() { return drainsByDamage || defenceDrainFraction > 0 || magicDrainFraction > 0; }
}

package com.loadoutlab.engine;

import com.loadoutlab.data.*;
import java.util.*;

/**
 * The slayer-task bracelet preference (miko, Discord 2026-10-17: "include
 * ... Expeditious bracelet for all setups"; Andrew: an option for slayer
 * tasks, reachable from the settings panel and the bracelet slot). On task
 * every style card's hands slot is pinned to it unless the mob pins its
 * own hands slot; off task, and on raids (never a task context), nothing
 * changes. Unpriced like any pin - the model cannot value a task bracelet.
 */
public enum TaskBracelet {
    NONE(0), EXPEDITIOUS_BRACELET(21177), BRACELET_OF_SLAUGHTER(21183);

    public final int itemId;

    TaskBracelet(int itemId) { this.itemId = itemId; }

    /** The mob's pins with this bracelet in HANDS for every concrete style
     * that has no hands pin of its own; the input is never mutated. Only a
     * slayer monster on task counts - the task param can outlive the chip
     * (Andrew 2026-10-18: Orca wore the bracelet). */
    public static Map<CombatStyle, Map<GearSlot, Integer>> overlay(
        Map<CombatStyle, Map<GearSlot, Integer>> pins, MonsterStats monster, boolean onTask, TaskBracelet choice) {
        if (!onTask || monster == null || !monster.slayerMonster || choice == null || choice == NONE) {
            return pins;
        }
        var out = new EnumMap<CombatStyle, Map<GearSlot, Integer>>(CombatStyle.class);
        out.putAll(pins);
        for (CombatStyle style : CombatStyle.concreteValues()) {
            var mine = new EnumMap<GearSlot, Integer>(GearSlot.class);
            Map<GearSlot, Integer> had = pins.get(style);
            if (had != null) mine.putAll(had);
            mine.putIfAbsent(GearSlot.HANDS, choice.itemId);
            out.put(style, mine);
        }
        return out;
    }
}

package com.loadoutlab.engine;

import com.loadoutlab.data.*;

/**
 * Tormented Demon mechanics, matching the official calculator's default
 * phase view (verified against weirdgloop's engine 2026-07-05):
 *
 * <ul>
 * <li>Player accuracy is effectively 100% (their shield phases leave them
 *     defenceless to properly-aimed attacks; only the active 'Shielded'
 *     phase resists, which the official calc's default also ignores).</li>
 * <li>They take 20% reduced damage unless hit by a demonbane weapon/spell
 *     or an abyssal weapon (whip, tentacle, dagger, bludgeon).</li>
 * </ul>
 *
 * Not modeled: the Unshielded-phase bonus for crush/heavy/spell attacks.
 */
public class TormentedDemonRules {
    static final String[] ABYSSAL = {
        "abyssal whip", "abyssal tentacle", "abyssal dagger", "abyssal bludgeon", };


    public static boolean applies(MonsterStats monster) {
        return monster != null && "Tormented Demon".equalsIgnoreCase(monster.name);
    }

    /** The flat 20% reduction, bypassed by demonbane and abyssal weapons. */
    public static double damageFactor(MonsterStats monster, CombatStyle style, GearItem weapon, String spellName) {
        if (!applies(monster)) return 1.0;
        return bypassesReduction(style, weapon, spellName) ? 1.0 : 0.8;
    }

    static boolean bypassesReduction(CombatStyle style, GearItem weapon, String spellName) {
        if (style == CombatStyle.MAGIC) return spellName != null && spellName.contains("Demonbane");
        // The demonbane weapon vocabulary lives on GearItem (one list with
        // MonsterMechanics and the optimizer's demon bump); a melee name
        // can never be the weapon of a RANGED attack, so one flag serves
        // both remaining styles.
        if (weapon == null) return false;
        if (weapon.demonbane) return true;
        for (String abyssal : ABYSSAL) {
            if (weapon.nameLower.startsWith(abyssal)) return true;
        }
        return false;
    }
}

package com.loadoutlab.engine;

import com.loadoutlab.data.*;
import com.google.gson.*;
import java.util.*;

/**
 * What dying to another player above level 20 Wilderness costs per worn
 * UNTRADEABLE item, under the June 2026 Items Kept on Death rework
 * (wiki: Trouver parchment + Items Kept on Death, verified 2026-07-07):
 *
 * - Category 1 (no combat benefit): never lost, costs nothing.
 * - Category 2 (some combat bonuses): breaks; the victim pays the item's
 *   own repair/replacement fee (per-item, wiki-sourced). This bucket also
 *   carries the component-drop items (crystal armour reverts to a seed for
 *   the killer, slayer helm drops as a black mask, imbued rings drop the
 *   base ring, ...) priced at the component's value.
 * - Category 3 (strong combat bonuses): trouver-locked once (permanent);
 *   each PvP death above 20 Wilderness mangles the item and the victim
 *   pays 500,000 coins to restore it (the killer receives the fee). We
 *   assume the one-time lock has already been done, so the per-death cost
 *   is the flat 500k mangle fee.
 *
 * Entries in untradeable_death.json are keyed by lowercase item name
 * (GearItem.name, no version suffix). An UNLISTED untradeable that
 * carries any combat stats falls back to a conservative 500,000 default:
 * unknowns must not smuggle into "low-risk" sets for free - curation
 * whittles the list, the default keeps the risk budget honest meanwhile.
 * Untradeables with no combat stats (graceful class) cost nothing.
 */
public class UntradeableDeathCosts {
    static final String RESOURCE = "untradeable_death.json";

    /** Conservative fallback for combat untradeables we have not curated. */
    public static final long UNKNOWN_COMBAT_UNTRADEABLE_GP = 500_000L;

    static final Map<String, Long> COST_BY_NAME = new HashMap<>();
    static final Map<String, Integer> CATEGORY_BY_NAME = new HashMap<>();
    /** Curated rebuild-errand proxies (re-obtain/re-enchant/re-imbue time,
     * NOT gp - imbue points refund since April 2024). Counted into the
     * risk total and the risk cap so "free but a 25-minute errand" items
     * never read as safe (field request). */
    static final Map<String, Long> FRICTION_BY_NAME = new HashMap<>();

    static {
        JsonObject root = JsonResources.object(RESOURCE);
        if (root == null) {
            throw new IllegalStateException("Could not load " + RESOURCE);
        } {
            for (var entry : root.entrySet()) {
                JsonObject row = entry.getValue().getAsJsonObject();
                String name = Names.lower(entry.getKey());
                COST_BY_NAME.put(name, row.get("costGp").getAsLong());
                CATEGORY_BY_NAME.put(name, row.get("category").getAsInt());
                if (row.has("frictionGp")) FRICTION_BY_NAME.put(name, row.get("frictionGp").getAsLong());
            }
        }
    }


    /**
     * Per-death gp cost of wearing this item into PvP above 20 Wilderness.
     * Tradeables cost 0 here - their loss is priced by the kept-slot
     * ranking in PvpRisk - EXCEPT category 5 (destroyed on any death,
     * protection does not help), which charges regardless of tradeability.
     */
    public static long costFor(GearItem item) {
        if (item == null) return 0L;
        if (item.tradeable) {
            Long destroyed = categoryFor(item) == 5 ? COST_BY_NAME.get(item.nameLower) : null;
            return destroyed == null ? 0L : destroyed;
        }
        Long listed = COST_BY_NAME.get(item.nameLower);
        if (listed != null) return listed;
        return hasCombatStats(item) ? UNKNOWN_COMBAT_UNTRADEABLE_GP : 0L;
    }

    /** Rebuild-errand proxy for a death loss (0 when none curated). */
    public static long frictionFor(GearItem item) {
        if (item == null) return 0L;
        Long friction = FRICTION_BY_NAME.get(item.nameLower);
        return friction == null ? 0L : friction;
    }

    /** Category 5: destroyed on any death - never protectable. */
    public static boolean isDestroyedOnDeath(GearItem item) { return categoryFor(item) == 5; }

    /**
     * Category 4: converts to a tradeable component dropped for the
     * killer (slayer helm -> black mask, crystal -> seed). These are
     * LOSABLE, so they compete for kept-on-death protection slots at
     * their component value - protecting one prevents the drop.
     */
    public static boolean isConvertible(GearItem item) { return categoryFor(item) == 4; }

    /** Curated category (1, 2, 3 or 4-converts), or 0 when unlisted. */
    public static int categoryFor(GearItem item) {
        if (item == null) return 0;
        Integer listed = CATEGORY_BY_NAME.get(item.nameLower);
        return listed == null ? 0 : listed;
    }

    static boolean hasCombatStats(GearItem item) {
        return nonZero(item.offensive) || nonZero(item.defensive) || nonZero(item.bonuses);
    }

    static boolean nonZero(StatBlock block) {
        return block.stab != 0 || block.slash != 0 || block.crush != 0 || block.magic != 0 || block.ranged != 0
            || block.strength != 0 || block.rangedStrength != 0 || block.magicDamage != 0 || block.prayer != 0;
    }
}

package com.loadoutlab.engine;

import com.google.gson.JsonObject;
import com.loadoutlab.data.*;
import java.util.*;
import static com.loadoutlab.data.JsonResources.*;
import static com.loadoutlab.engine.CombatStyle.*;

/**
 * Vampyres at parity with the official calculator's engine
 * (ISS-01M5RM2A7FFR9XWKATPX877TDD; osrs-dps-calc 89c3e25b). Tier 1 takes
 * every weapon, silver ones at +10%; tier 2 only vampyrebane weapons, silver
 * weapons (each hit capped at 10, PR #671) or anything with Efaritay's aid
 * (each hit halved); tier 3 only a vampyrebane weapon in melee or the
 * blisterwood stake - never a spell (wiki: "no spells are capable of dealing
 * damage to vampyres"). The names and numbers ride vampyre_weapons.json,
 * whose comment carries every place this follows the wiki over the calc.
 */
public class VampyreRules {
    static final Map<String, List<String>> NAMES = new HashMap<>();
    static final Map<String, Integer> N = new HashMap<>();

    static {
        JsonObject data = objectOrThrow("vampyre_weapons.json");
        for (String key : List.of("silver", "silverRanged", "bane2", "bane3")) {
            strings(data, key, NAMES.computeIfAbsent(key, k -> new ArrayList<>()));
        }
        stringIntMap(data, "numbers", N);
    }

    static final int EFARITAY = N.get("efaritay");


    /** 1-3 for a vampyre's tier, 0 for anything else. */
    static int tier(MonsterStats m) {
        return m == null ? 0 : m.vampyreTier;
    }

    static String name(GearItem item) { return item == null ? "" : item.nameLower; }

    static boolean in(String list, GearItem item) { return NAMES.get(list).contains(name(item)); }

    /** Vampyrebane at a tier: the stake in ranged; the listed weapons in
     * melee, and vs tier 2 in any style (the calc's wearingVampyrebane). */
    static boolean bane(int tier, CombatStyle style, GearItem weapon) {
        return style == RANGED ? in("silverRanged", weapon) : (tier == 2 || style == MELEE) && in(tier == 2 ? "bane2" : "bane3", weapon);
    }

    /** Silver: the listed weapons in melee; silver ammo or the stake in ranged. */
    static boolean silver(CombatStyle style, Loadout loadout) {
        return style == RANGED ? in("silverRanged", loadout.get(GearSlot.AMMO)) || bane(0, style, loadout.getWeapon())
            : style == MELEE && in("silver", loadout.getWeapon());
    }

    static boolean ring(Loadout loadout) { return name(loadout.get(GearSlot.RING)).equals("efaritay's aid"); }

    /** The weapon-level tier-3 bar the pool filter shares: a tier-3
     * weapon, and never a spell (ISS-01M5RGMT70PG86MWHPF28DBJ3V). */
    public static boolean canDamage(MonsterStats monster, CombatStyle style, GearItem weapon) {
        return tier(monster) != 3 || bane(3, style, weapon);
    }

    /** The calc's isImmune: tier 3 without vampyrebane; tier 2 without
     * vampyrebane, Efaritay's aid or a silver weapon. */
    static boolean immune(MonsterStats monster, CombatStyle style, Loadout loadout) {
        int tier = tier(monster);
        return tier == 3 ? !bane(3, style, loadout.getWeapon())
            : tier == 2 && !bane(2, style, loadout.getWeapon()) && !ring(loadout) && !silver(style, loadout);
    }

    /** The melee roll vs any vampyre, after the post rules (the calc's
     * order): the weapon's own bonus, then a silver weapon with the ring. */
    static long accuracy(MonsterStats monster, Loadout loadout, long roll) {
        if (tier(monster) == 0) return roll;
        roll = roll * N.getOrDefault("acc " + name(loadout.getWeapon()), 100) / 100;
        return silver(MELEE, loadout) && ring(loadout) ? roll * N.get("efaritayAccuracy") / 100 : roll;
    }

    /** A result vs a vampyre with each hit through the calc's map - the
     * weapon's scale (the ring's first), the raised accurate 0, then tier
     * 2's halving or cap. Exact for one uniform hit: the expectation scales
     * by the mapped sum over the plain one, where an accurate 0 already
     * counts as 1. */
    static DpsResult apply(MonsterStats monster, CombatStyle style, Loadout loadout, DpsResult result) {
        int tier = tier(monster), top = result.maxHit;
        if (tier == 0) return result;
        GearItem weapon = loadout.getWeapon();
        boolean ring = ring(loadout), silver = silver(style, loadout);
        int scale = N.getOrDefault("dmg " + name(weapon), silver && tier == 1 ? N.get("silverTier1") : 0);
        boolean half = tier == 2 && ring && !bane(2, style, weapon), cap = tier == 2 && !half && silver;
        if (tier == 0 || top <= 0 || scale == 0 && !half && !cap) return result;
        int ringScale = ring ? N.get("efaritayDamage") : 100, v = 0;
        double plain = 0, mapped = 0;
        for (int d = 0; d <= top; d++) {
            v = Math.max(1, scale == 0 ? d : d * ringScale / 100 * scale / 100);
            mapped += v = half ? v / 2 : cap ? Math.min(v, N.get("tier2Cap")) : v;
            plain += Math.max(1, d);
        }
        double r = mapped / plain;
        return result.withHitModel(result.dps * r, result.accuracy, result.expectedHit * r, v);
    }
}

package com.loadoutlab.engine;

import com.google.gson.*;
import com.loadoutlab.data.*;
import java.util.*;
import lombok.*;

/**
 * Melee combat styles available per weapon category - game facts from the
 * wiki's weapon-type pages (cross-checked against the official calculator,
 * 2026-07-05). The upstream best-dps engine assumed every melee weapon has
 * every attack type at every stance, which invented styles weapons don't
 * have: a whip has no aggressive stance, and a Blunt weapon cannot slash -
 * that one let a barronite mace "slash" a Grey golem (slash defence 1,
 * everything else 300) for a 3x accuracy error against the official calc.
 *
 * <p>Stances: accurate = +3 attack, aggressive = +3 strength,
 * controlled = +1 both. Defensive is omitted - it adds no offence, so it
 * can never be the best-DPS pick.
 *
 * <p>The table itself lives in weapon_styles.json (hub token cap: data goes
 * in resources, not source). It is GENERATED from the old hardcoded table by
 * scripts/extract_weapon_styles.py, which asserts 24 categories, 56 style
 * entries and the 9-entry fallback row - regenerate with that script, never
 * by hand.
 */
public class WeaponStyles {
    /** One selectable style: the attack type plus its stance bonuses. */
    @RequiredArgsConstructor
    public static class MeleeStyle {
        public final String attackType;
        public final int attackStance;
        public final int strengthStance;
    }

    static final String RESOURCE = "weapon_styles.json";
    /** Resource key of the unknown-category fallback row - not a real weapon
     * category, so it can never collide with one. */
    static final String FALLBACK = "*";

    static final Map<String, List<MeleeStyle>> BY_CATEGORY = load();

    /** Every attack type x stance a full search would try - the fallback. */
    static final List<MeleeStyle> ALL = BY_CATEGORY.getOrDefault(FALLBACK, List.of());

    static Map<String, List<MeleeStyle>> load() {
        Map<String, List<MeleeStyle>> table = new HashMap<>();
        JsonObject root = JsonResources.object(RESOURCE);
        if (root == null) return table;
        for (var entry : root.entrySet()) {
            List<MeleeStyle> styles = new ArrayList<>();
            for (JsonElement element : entry.getValue().getAsJsonArray()) {
                JsonObject style = element.getAsJsonObject();
                styles.add(new MeleeStyle(style.get("attackType").getAsString(), style.get("attackStance").getAsInt(),
                    style.get("strengthStance").getAsInt()));
            }
            table.put(entry.getKey(), styles);
        }
        return table;
    }


    /** The melee styles this weapon actually offers (unknown category: all). */
    public static List<MeleeStyle> melee(GearItem weapon) {
        // Null weapon = bare fists, which is a real category row. Looking it up
        // through the same map (rather than returning it directly) is what
        // keeps a missing resource from returning null here and NPE-ing
        // DpsCalculator: an absent row falls back to ALL, and ALL itself
        // defaults to an empty list.
        List<MeleeStyle> styles = BY_CATEGORY.get( weapon == null ? "Unarmed" : weapon.category);
        return styles != null ? styles : ALL;
    }
}

