package com.loadoutlab.collection;

import com.google.gson.Gson;
import com.loadoutlab.data.SpellRunes;
import com.loadoutlab.engine.OwnedItems;
import com.loadoutlab.testsupport.InMemoryConfigManager;
import java.util.Map;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import static org.junit.jupiter.api.Assertions.*;

/** Discord (Mumblerit, 2026-10-10): "when I withdraw all of a rune type
 * (e.g. blood runes) from the bank and put them into my rune pouch, the
 * loadout simulation stops seeing those runes and drops recommended
 * spells that need them (like Fire Wave with a staff)". */
class RunePouchScanTest {
	private static final int BLOOD_RUNE = 565;
	private static final int DEATH_RUNE = 560;

	/** A stand-in for the client's RUNEPOUCH_RUNE enum: type 1 = death, 2 = blood. */
	private static int typeToItem(int type) {
		return type == 1 ? DEATH_RUNE : type == 2 ? BLOOD_RUNE : 0;
	}

	@Test
	@DisplayName("filled pouch slots map to item ids with their quantities")
	void filledSlotsCount() {
		Map<Integer, Integer> items = RunePouchScan.items(
			new int[]{2, 1, 0, 0}, new int[]{1200, 300, 0, 0}, RunePouchScanTest::typeToItem);
		assertEquals(Map.of(BLOOD_RUNE, 1200, DEATH_RUNE, 300), items);
	}

	@Test
	@DisplayName("an empty slot (type 0) or a zero quantity contributes nothing")
	void emptySlotsAddNothing() {
		assertTrue(RunePouchScan.items(new int[]{0, 2}, new int[]{500, 0}, RunePouchScanTest::typeToItem).isEmpty());
	}

	@Test
	@DisplayName("blood runes only in the pouch still let Fire Wave through the premium-rune gate")
	void pouchRunesReachTheSpellGate() {
		CollectionLedger ledger = new CollectionLedger(InMemoryConfigManager.create(), new Gson());
		ledger.loadScope("std");
		ledger.update(CollectionLedger.Source.BANK, Map.of(1387, 1));
		OwnedItems bankOnly = new OwnedItems(ledger.owned(), true);
		assertFalse(SpellRunes.premiumRunesOwned("Fire Wave", bankOnly), "no blood runes anywhere yet");

		ledger.update(CollectionLedger.Source.RUNE_POUCH, RunePouchScan.items(
			new int[]{2}, new int[]{1200}, RunePouchScanTest::typeToItem));
		OwnedItems withPouch = new OwnedItems(ledger.owned(), true);
		assertEquals(1200, ledger.owned().get(BLOOD_RUNE));
		assertTrue(SpellRunes.premiumRunesOwned("Fire Wave", withPouch));
	}
}

package com.loadoutlab.collection;

import com.google.gson.Gson;
import com.loadoutlab.testsupport.InMemoryConfigManager;
import net.runelite.client.config.ConfigManager;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import static org.junit.jupiter.api.Assertions.*;

/**
 * Field report 2026-08-26, on the 0.4.1 build: "on test pure i can't add
 * anything to my sim/exclude list right now."
 *
 * <p>PerCharacterScopeTest passes because it starts from a FRESH config. Every
 * real install upgrading from 0.4.0 has the pre-scope key already written, and
 * the plugin reloads every store on each GameState.LOGGED_IN - which fires on
 * every region change, and at least once before getAccountHash() is populated.
 * These tests recreate those two conditions.
 */
class ScopeRegressionTest {
	private ConfigManager configManager;
	private Gson gson;

	private static final String MAIN = "std.1111";
	private static final String ALT = "std.2222";

	@BeforeEach
	void setUp() {
		configManager = InMemoryConfigManager.create();
		gson = new Gson();
		// A real 0.4.0 install: the main's list under the unscoped key.
		configManager.setConfiguration("loadoutlab", "excludedItems", "[11832,4151]");
	}

	@Test
	@DisplayName("an upgraded install does not hand the main's list to a second character")
	void legacyListDoesNotLeakToTheAlt() {
		IdSetStore store = new IdSetStore(configManager, gson, "excludedItems");

		store.loadScope(MAIN);
		assertTrue(store.contains(11832), "the main lost its pre-0.4.1 list");

		store.loadScope(ALT);
		assertFalse(store.contains(11832),
			"the alt inherited the main's pre-0.4.1 exclude list");
	}

	@Test
	@DisplayName("whichever character logs in first claims the pre-0.4.1 list")
	void adoptionFollowsLoginOrder() {
		// The pre-0.4.1 entry records no owner, so there is no signal for which
		// account it belonged to - only one of them can have it, and the first
		// to load wins. Documented because it makes the UPGRADE order matter
		// even though steady-state scoping does not.
		IdSetStore store = new IdSetStore(configManager, gson, "excludedItems");

		store.loadScope(ALT);
		assertTrue(store.contains(11832), "the first character in did not adopt");

		store.loadScope(MAIN);
		assertFalse(store.contains(11832),
			"the second character in must start clean, not inherit a copy");
	}

	@Test
	@DisplayName("an item added on the alt survives the next region change")
	void addOnTheAltSurvivesAReload() {
		IdSetStore store = new IdSetStore(configManager, gson, "excludedItems");
		store.loadScope(ALT);

		store.toggle(20997); // twisted bow
		assertTrue(store.contains(20997), "the toggle did not take");

		// GameState.LOGGED_IN fires on every region change and reloads the scope.
		store.loadScope(ALT);
		assertTrue(store.contains(20997),
			"walking through a loading zone dropped the item the alt just added");
	}

	@Test
	@DisplayName("an item added before any character is known is adopted, not abandoned")
	void addBeforeTheHashArrivesIsNotLost() {
		// getAccountHash() is -1 until a character is known, and LOGGED_IN can
		// fire before then. The plugin no longer reloads at that point, so the
		// store is still unscoped and writes to the pre-0.4.1 key - which the
		// first character to load then adopts. The earlier cut scoped these
		// writes to a bare "std" bucket that nothing ever read again.
		IdSetStore store = new IdSetStore(configManager, gson, "excludedItems");
		store.toggle(20997);
		assertTrue(store.contains(20997));

		store.loadScope(ALT);
		assertTrue(store.contains(20997),
			"the add was abandoned once the character was identified");
	}
}

package com.loadoutlab.collection;

import java.util.EnumMap;
import java.util.Map;
import net.runelite.api.gameval.InventoryID;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import static org.junit.jupiter.api.Assertions.*;

/**
 * Oracle for the source -> container-id table that moved onto the enum.
 *
 * <p>ORACLE is a literal transcription of the switch statement that used to
 * live in LoadoutLabPlugin.containerFor(...), so a typo in the enum table
 * shows up here rather than as silently unscanned storage.
 */
class SourceContainerIdTest {
	private static Map<CollectionLedger.Source, Integer> oracle() {
		Map<CollectionLedger.Source, Integer> m = new EnumMap<>(CollectionLedger.Source.class);
		m.put(CollectionLedger.Source.EQUIPMENT, net.runelite.api.InventoryID.EQUIPMENT.getId());
		m.put(CollectionLedger.Source.INVENTORY, net.runelite.api.InventoryID.INVENTORY.getId());
		m.put(CollectionLedger.Source.BANK, net.runelite.api.InventoryID.BANK.getId());
		m.put(CollectionLedger.Source.LOOTING_BAG, InventoryID.LOOTING_BAG);
		m.put(CollectionLedger.Source.POH_COSTUMES, InventoryID.POH_COSTUMES);
		// STASH is chart-driven, never container-scanned.
		m.put(CollectionLedger.Source.STASH, -1);
		// The rune pouch is varbit-driven, never container-scanned.
		m.put(CollectionLedger.Source.RUNE_POUCH, -1);
		m.put(CollectionLedger.Source.CARGO_HOLD_1, InventoryID.SAILING_BOAT_1_CARGOHOLD);
		m.put(CollectionLedger.Source.CARGO_HOLD_2, InventoryID.SAILING_BOAT_2_CARGOHOLD);
		m.put(CollectionLedger.Source.CARGO_HOLD_3, InventoryID.SAILING_BOAT_3_CARGOHOLD);
		m.put(CollectionLedger.Source.CARGO_HOLD_4, InventoryID.SAILING_BOAT_4_CARGOHOLD);
		m.put(CollectionLedger.Source.CARGO_HOLD_5, InventoryID.SAILING_BOAT_5_CARGOHOLD);
		return m;
	}

	@Test
	@DisplayName("every source carries the container id the old switch returned")
	void containerIdMatchesTheOldSwitch() {
		Map<CollectionLedger.Source, Integer> oracle = oracle();
		assertEquals(12, CollectionLedger.Source.values().length,
			"the oracle covers exactly the sources that exist");
		assertEquals(12, oracle.size());
		for (CollectionLedger.Source s : CollectionLedger.Source.values()) {
			assertEquals(oracle.get(s).intValue(), s.containerId(), s.name());
		}
	}

	@Test
	@DisplayName("the reverse lookup returns the storage sources the plugin used to switch on")
	void forContainerResolvesStorageSources() {
		assertEquals(CollectionLedger.Source.LOOTING_BAG,
			CollectionLedger.Source.forContainer(InventoryID.LOOTING_BAG));
		assertEquals(CollectionLedger.Source.POH_COSTUMES,
			CollectionLedger.Source.forContainer(InventoryID.POH_COSTUMES));
		assertEquals(CollectionLedger.Source.CARGO_HOLD_1,
			CollectionLedger.Source.forContainer(InventoryID.SAILING_BOAT_1_CARGOHOLD));
		assertEquals(CollectionLedger.Source.CARGO_HOLD_5,
			CollectionLedger.Source.forContainer(InventoryID.SAILING_BOAT_5_CARGOHOLD));
	}

	@Test
	@DisplayName("the reverse lookup rejects the STASH sentinel and unknown containers")
	void forContainerRejectsSentinelAndUnknown() {
		assertNull(CollectionLedger.Source.forContainer(-1));
		assertNull(CollectionLedger.Source.forContainer(Integer.MIN_VALUE));
		assertNull(CollectionLedger.Source.forContainer(Integer.MAX_VALUE));
	}

	@Test
	@DisplayName("no two sources claim the same container id")
	void containerIdsAreUnique() {
		Map<Integer, CollectionLedger.Source> seen = new java.util.HashMap<>();
		for (CollectionLedger.Source s : CollectionLedger.Source.values()) {
			if (s.containerId() < 0) {
				continue;
			}
			CollectionLedger.Source clash = seen.put(s.containerId(), s);
			assertNull(clash, "container id collision: " + s + " vs " + clash);
		}
	}
}

package com.loadoutlab.collection;

import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.function.IntUnaryOperator;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import static org.junit.jupiter.api.Assertions.*;

class StoragesApiTest {
	private static final IntUnaryOperator IDENTITY = IntUnaryOperator.identity();

	@Test
	@DisplayName("a request needs a non-empty source; anything else has no requester")
	void requesterValidation() {
		assertEquals("Some Plugin", StoragesApi.requester(Map.of("source", "Some Plugin")));
		assertNull(StoragesApi.requester(null));
		assertNull(StoragesApi.requester(Map.of()));
		assertNull(StoragesApi.requester(Map.of("source", "")));
		assertNull(StoragesApi.requester(Map.of("source", 42)));
	}

	@Test
	@DisplayName("a storage entry carries category, name, lastUpdated, and the item list")
	void storageEntryShape() {
		Map<String, Object> entry = StoragesApi.storage(
			"collection", "bank", -1L, Map.of(4151, 1), IDENTITY);

		assertNotNull(entry);
		assertEquals("collection", entry.get("category"));
		assertEquals("bank", entry.get("name"));
		assertEquals(-1L, entry.get("lastUpdated"));
		List<?> items = (List<?>) entry.get("items");
		assertEquals(1, items.size());
		Map<?, ?> item = (Map<?, ?>) items.get(0);
		assertEquals(4151, item.get("id"));
		assertEquals(1L, item.get("quantity"), "quantities go out as Long, per the contract");
	}

	@Test
	@DisplayName("ids are canonicalized, and variants that collapse to one id sum quantities")
	void canonicalizationMergesVariants() {
		// Pretend 4151 (whip) and 12773 (whip (or)) both canonicalize to 4151.
		IntUnaryOperator canonicalize = id -> id == 12773 ? 4151 : id;
		Map<Integer, Integer> items = new HashMap<>();
		items.put(4151, 1);
		items.put(12773, 2);

		Map<String, Object> entry = StoragesApi.storage(
			"collection", "bank", -1L, items, canonicalize);

		assertNotNull(entry);
		List<?> list = (List<?>) entry.get("items");
		assertEquals(1, list.size());
		Map<?, ?> item = (Map<?, ?>) list.get(0);
		assertEquals(4151, item.get("id"));
		assertEquals(3L, item.get("quantity"));
	}

	@Test
	@DisplayName("empty or all-junk storages produce no entry, and junk items are dropped")
	void emptyStoragesProduceNoEntry() {
		assertNull(StoragesApi.storage("collection", "bank", -1L, Map.of(), IDENTITY));

		Map<Integer, Integer> junk = new HashMap<>();
		junk.put(-1, 5);
		junk.put(0, 5);
		junk.put(4151, 0);
		junk.put(11832, -2);
		assertNull(StoragesApi.storage("collection", "bank", -1L, junk, IDENTITY));
	}

	@Test
	@DisplayName("the response envelope echoes the requester and states version 1")
	void responseEnvelope() {
		List<Map> storages = List.of(
			StoragesApi.storage("collection", "bank", -1L, Map.of(4151, 1), IDENTITY));

		Map<String, Object> response = StoragesApi.response("Some Plugin", storages);

		assertEquals("Loadout Lab", response.get("source"));
		assertEquals("Some Plugin", response.get("target"));
		assertEquals(1, response.get("version"));
		assertEquals(storages, response.get("storages"));
	}
}

package com.loadoutlab.collection;

import com.google.gson.Gson;
import com.loadoutlab.testsupport.InMemoryConfigManager;
import net.runelite.client.config.ConfigManager;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import static org.junit.jupiter.api.Assertions.*;

class SupplyDefaultsStoreTest {
	private static final String SCOPE = "std.1111";
	private ConfigManager configManager;
	private SupplyDefaultsStore store;

	@BeforeEach
	void setUp() {
		configManager = InMemoryConfigManager.create();
		store = freshStore();
	}

	/** The plugin always loads a character scope before use; a store
	 * without one writes to the pre-0.4.1 unscoped key, so a reload
	 * through a second instance would read a different key entirely. */
	private SupplyDefaultsStore freshStore() {
		SupplyDefaultsStore fresh = new SupplyDefaultsStore(configManager, new Gson());
		fresh.loadScope(SCOPE);
		return fresh;
	}

	@Test
	@DisplayName("every category is Detect best (always on) until changed")
	void detectBestIsTheUniversalDefault() {
		assertEquals("DETECT_BEST", store.choice("food"));
		assertEquals("DETECT_BEST", store.choice("antivenom"));
		assertNull(configManager.getConfiguration("loadoutlab", SCOPE + ".supplyDefaults"),
			"defaults leave no config residue");
	}

	@Test
	@DisplayName("a changed choice persists; returning to Detect best removes it")
	void choicesPersistAndClear() {
		store.setChoice("prayerRestore", "SANFEW_SERUM");
		store.setChoice("surge", "NONE");
		SupplyDefaultsStore reloaded = freshStore();
		assertEquals("SANFEW_SERUM", reloaded.choice("prayerRestore"));
		assertEquals("NONE", reloaded.choice("surge"));

		store.setChoice("prayerRestore", "DETECT_BEST");
		store.setChoice("surge", null);
		assertEquals("DETECT_BEST", store.choice("prayerRestore"));
		assertNull(configManager.getConfiguration("loadoutlab", SCOPE + ".supplyDefaults"),
			"an all-default store unsets its config key");
	}

	@Test
	@DisplayName("clear() returns every category to Detect best and persists it")
	void clearReturnsToDetect() {
		SupplyDefaultsStore store = new SupplyDefaultsStore(configManager, new Gson());
		store.setChoice("food", "SHARK");
		store.clear();
		assertEquals(SupplyDefaultsStore.DETECT_BEST, store.choice("food"));
		assertEquals(SupplyDefaultsStore.DETECT_BEST, new SupplyDefaultsStore(configManager, new Gson()).choice("food"));
	}
}

package com.loadoutlab.command;

import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import java.util.ArrayList;
import java.util.List;

import static org.junit.jupiter.api.Assertions.*;

/**
 * Unit tests for {@link CommandHistory}.
 *
 * <p>Uses a tiny stub Command that pushes/pops to a shared list so we can
 * verify exactly which commands ran (and in which direction) without
 * touching the real stores.
 */
class CommandHistoryTest {
	private CommandHistory history;
	/** Trace of "apply:N" / "revert:N" calls in the order they happened. */
	private List<String> trace;

	@BeforeEach
	void setUp() {
		history = new CommandHistory();
		trace = new ArrayList<>();
	}

	private Command stubCmd(int id) {
		return new Command() {
			@Override public boolean apply() { trace.add("apply:" + id); return true; }
			@Override public boolean revert() { trace.add("revert:" + id); return true; }
			@Override public String getDescription() { return "cmd-" + id; }
		};
	}

	private Command failingApply(int id) {
		return new Command() {
			@Override public boolean apply() { trace.add("apply:" + id); return false; }
			@Override public boolean revert() { trace.add("revert:" + id); return true; }
			@Override public String getDescription() { return "cmd-" + id; }
		};
	}

	private Command failingRevert(int id) {
		return new Command() {
			@Override public boolean apply() { trace.add("apply:" + id); return true; }
			@Override public boolean revert() { trace.add("revert:" + id); return false; }
			@Override public String getDescription() { return "cmd-" + id; }
		};
	}

	private Command throwingRevert(int id) {
		return new Command() {
			@Override public boolean apply() { trace.add("apply:" + id); return true; }
			@Override public boolean revert() { throw new RuntimeException("boom"); }
			@Override public String getDescription() { return "cmd-" + id; }
		};
	}

	@Test
	@DisplayName("execute runs apply and pushes onto undo stack")
	void executePushes() {
		assertTrue(history.execute(stubCmd(1)));
		assertEquals(List.of("apply:1"), trace);
		assertTrue(history.canUndo());
		assertFalse(history.canRedo());
		assertEquals("cmd-1", history.peekUndoDescription());
	}


	@Test
	@DisplayName("undo pops the most recent entry and reverts it, moving to redo stack")
	void undoMovesToRedo() {
		history.execute(stubCmd(1));
		history.execute(stubCmd(2));
		assertTrue(history.undo());
		assertEquals(List.of("apply:1", "apply:2", "revert:2"), trace);
		assertTrue(history.canUndo());
		assertTrue(history.canRedo());
		assertEquals("cmd-1", history.peekUndoDescription());
		assertEquals("cmd-2", history.peekRedoDescription());
	}

	@Test
	@DisplayName("redo re-applies the entry and moves it back to undo stack")
	void redoMovesBack() {
		history.execute(stubCmd(1));
		history.undo();
		assertTrue(history.redo());
		assertEquals(List.of("apply:1", "revert:1", "apply:1"), trace);
		assertTrue(history.canUndo());
		assertFalse(history.canRedo());
	}

	@Test
	@DisplayName("a new execute clears the redo stack (forking history)")
	void newExecuteClearsRedo() {
		history.execute(stubCmd(1));
		history.execute(stubCmd(2));
		history.undo(); // 2 → redo
		assertTrue(history.canRedo());
		history.execute(stubCmd(3)); // forks: redo cleared
		assertFalse(history.canRedo());
	}

	@Test
	@DisplayName("undo on empty stack returns false")
	void emptyUndo() {
		assertFalse(history.undo());
	}

	@Test
	@DisplayName("redo on empty stack returns false")
	void emptyRedo() {
		assertFalse(history.redo());
	}

	@Test
	@DisplayName("execute returning false (no-op) is not pushed onto the stack")
	void failingApplyNotPushed() {
		assertFalse(history.execute(failingApply(1)));
		assertFalse(history.canUndo());
	}

	@Test
	@DisplayName("undo with failing revert drops the entry and returns false")
	void failingRevertDropped() {
		history.execute(stubCmd(1));
		history.execute(failingRevert(2));
		assertFalse(history.undo()); // revert returned false
		// Entry 2 dropped — cmd-1 is next to undo, nothing to redo
		assertEquals("cmd-1", history.peekUndoDescription());
		assertFalse(history.canRedo());
	}

	@Test
	@DisplayName("undo with throwing revert drops the entry and returns false")
	void throwingRevertDropped() {
		history.execute(stubCmd(1));
		history.execute(throwingRevert(2));
		assertFalse(history.undo());
		assertEquals("cmd-1", history.peekUndoDescription());
		assertFalse(history.canRedo());
	}

	@Test
	@DisplayName("undo stack is bounded at CAP entries — oldest are trimmed")
	void capTrim() {
		for (int i = 0; i < CommandHistory.CAP + 5; i++) {
			history.execute(stubCmd(i));
		}
		int undone = 0;
		while (history.undo()) {
			undone++;
		}
		assertEquals(CommandHistory.CAP, undone);
	}

	@Test
	@DisplayName("clear wipes both stacks")
	void clearWipes() {
		history.execute(stubCmd(1));
		history.execute(stubCmd(2));
		history.undo();
		history.clear();
		assertFalse(history.canUndo());
		assertFalse(history.canRedo());
	}

	@Test
	@DisplayName("multi-step undo/redo round-trip preserves order")
	void roundTrip() {
		history.execute(stubCmd(1));
		history.execute(stubCmd(2));
		history.execute(stubCmd(3));
		history.undo();
		history.undo();
		history.redo();
		// Sequence: apply 1,2,3 → revert 3, revert 2 → apply 2
		assertEquals(List.of("apply:1", "apply:2", "apply:3",
			"revert:3", "revert:2", "apply:2"), trace);
		assertTrue(history.canUndo()); // 1, 2 remain
		assertTrue(history.canRedo()); // 3 in redo
	}
}

package com.loadoutlab.command;

import com.google.gson.Gson;
import com.loadoutlab.collection.MonsterProfileStore;
import com.loadoutlab.collection.IdSetStore;
import com.loadoutlab.data.GearSlot;
import com.loadoutlab.testsupport.InMemoryConfigManager;
import net.runelite.client.config.ConfigManager;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import static org.junit.jupiter.api.Assertions.*;

/**
 * The store-backed commands: each one must capture its before-state at
 * construction and round-trip cleanly through execute -> undo -> redo
 * against the REAL stores (in-memory ConfigManager fake). These are the
 * semantics the undo/redo buttons stand on.
 */
class CommandsTest {
	private static final int MOB = 2042; // Zulrah, as good an id as any
	private static final int WHIP = 4151;
	private static final int FANG = 26219;

	private ConfigManager cfg;
	private CommandHistory history;

	@BeforeEach
	void setUp() {
		cfg = InMemoryConfigManager.create();
		history = new CommandHistory();
	}

	@Test
	@DisplayName("exclusion toggle: execute excludes, undo restores, redo re-excludes")
	void exclusionRoundTrip() {
		IdSetStore store = new IdSetStore(cfg, new Gson(), "excludedItems");
		Command cmd = TestCommands.toggleExclusion(store, WHIP, "Abyssal whip");
		assertEquals("Exclude Abyssal whip", cmd.getDescription());

		assertTrue(history.execute(cmd));
		assertTrue(store.contains(WHIP));
		assertTrue(history.undo());
		assertFalse(store.contains(WHIP));
		assertTrue(history.redo());
		assertTrue(store.contains(WHIP));
	}

	@Test
	@DisplayName("exclusion toggle on an excluded item reads as Include and un-excludes")
	void exclusionToggleOff() {
		IdSetStore store = new IdSetStore(cfg, new Gson(), "excludedItems");
		store.toggle(WHIP);
		Command cmd = TestCommands.toggleExclusion(store, WHIP, "Abyssal whip");
		assertEquals("Include Abyssal whip", cmd.getDescription());
		history.execute(cmd);
		assertFalse(store.contains(WHIP));
		history.undo();
		assertTrue(store.contains(WHIP));
	}

	@Test
	@DisplayName("clear exclusions is ONE undo entry and undo restores every item")
	void clearExclusionsRestoresAll() {
		IdSetStore store = new IdSetStore(cfg, new Gson(), "excludedItems");
		store.toggle(WHIP);
		store.toggle(FANG);
		store.toggle(11230);

		assertTrue(history.execute(TestCommands.clearExclusions(store)));
		assertTrue(store.snapshot().isEmpty());

		assertTrue(history.undo());
		assertFalse(history.canUndo(), "one entry for the whole clear");
		assertTrue(store.contains(WHIP));
		assertTrue(store.contains(FANG));
		assertTrue(store.contains(11230));

		assertTrue(history.redo());
		assertTrue(store.snapshot().isEmpty());
	}

	@Test
	@DisplayName("clear exclusions on an empty store is a no-op and never lands on the stack")
	void clearEmptyNoop() {
		IdSetStore store = new IdSetStore(cfg, new Gson(), "excludedItems");
		assertFalse(history.execute(TestCommands.clearExclusions(store)));
		assertFalse(history.canUndo());
	}


	@Test
	@DisplayName("pin with no prior pin: undo empties the slot")
	void pinFreshSlot() {
		MonsterProfileStore mobs = new MonsterProfileStore(cfg, new Gson());
		history.execute(TestCommands.pin(mobs, MOB, "MELEE", GearSlot.WEAPON, FANG, "Osmumten's fang"));
		assertEquals(FANG, mobs.allPins(MOB).get("MELEE").get(GearSlot.WEAPON));

		history.undo();
		assertTrue(mobs.allPins(MOB).isEmpty() || mobs.allPins(MOB).getOrDefault("MELEE", java.util.Map.of()).get(GearSlot.WEAPON) == null);

		history.redo();
		assertEquals(FANG, mobs.allPins(MOB).get("MELEE").get(GearSlot.WEAPON));
	}

	@Test
	@DisplayName("pin over an existing pin: undo restores the PRIOR item, not an empty slot")
	void pinOverExisting() {
		MonsterProfileStore mobs = new MonsterProfileStore(cfg, new Gson());
		mobs.pin(MOB, "MELEE", GearSlot.WEAPON, WHIP);

		history.execute(TestCommands.pin(mobs, MOB, "MELEE", GearSlot.WEAPON, FANG, "Osmumten's fang"));
		assertEquals(FANG, mobs.allPins(MOB).get("MELEE").get(GearSlot.WEAPON));

		history.undo();
		assertEquals(WHIP, mobs.allPins(MOB).get("MELEE").get(GearSlot.WEAPON));
	}

	@Test
	@DisplayName("unpin: undo restores the pin; unpinning an empty slot is a no-op")
	void unpinRestores() {
		MonsterProfileStore mobs = new MonsterProfileStore(cfg, new Gson());
		mobs.pin(MOB, "ALL", GearSlot.HEAD, 11665);

		history.execute(TestCommands.unpin(mobs, MOB, "ALL", GearSlot.HEAD, "Void melee helm"));
		assertNull(mobs.allPins(MOB).getOrDefault("ALL", java.util.Map.of()).get(GearSlot.HEAD));
		history.undo();
		assertEquals(11665, mobs.allPins(MOB).get("ALL").get(GearSlot.HEAD));

		assertFalse(history.execute(TestCommands.unpin(mobs, MOB, "ALL", GearSlot.LEGS, "nothing")),
			"unpinning an empty slot must be a no-op that never lands on the stack");
	}

	@Test
	@DisplayName("note: undo restores the previous text; saving identical text is a no-op")
	void noteRestores() {
		MonsterProfileStore mobs = new MonsterProfileStore(cfg, new Gson());
		mobs.setNote(MOB, "bring antivenom");

		history.execute(TestCommands.setNote(mobs, MOB, "bring antivenom + house tabs"));
		assertEquals("bring antivenom + house tabs", mobs.note(MOB));
		history.undo();
		assertEquals("bring antivenom", mobs.note(MOB));

		assertFalse(history.execute(TestCommands.setNote(mobs, MOB, "bring antivenom")),
			"no-op note save must not land on the stack");
	}

	@Test
	@DisplayName("pinned spell: undo restores the previous spell")
	void spellRestores() {
		MonsterProfileStore mobs = new MonsterProfileStore(cfg, new Gson());
		history.execute(TestCommands.setPinnedSpell(mobs, MOB, "Ice Barrage"));
		assertEquals("Ice Barrage", mobs.pinnedSpell(MOB));
		history.undo();
		assertTrue(mobs.pinnedSpell(MOB) == null || mobs.pinnedSpell(MOB).isEmpty());
	}

	@Test
	@DisplayName("mob exclusion: exclude and remove both round-trip")
	void mobExclusionRoundTrip() {
		MonsterProfileStore mobs = new MonsterProfileStore(cfg, new Gson());
		history.execute(TestCommands.excludeForMob(mobs, MOB, "RANGED", WHIP, "Abyssal whip"));
		assertTrue(mobs.allExclusions(MOB).get("RANGED").contains(WHIP));
		history.undo();
		assertTrue(mobs.allExclusions(MOB).isEmpty()
			|| !mobs.allExclusions(MOB).getOrDefault("RANGED", java.util.Set.of()).contains(WHIP));

		mobs.exclude(MOB, "RANGED", WHIP);
		history.execute(TestCommands.removeMobExclusion(mobs, MOB, "RANGED", WHIP, "Abyssal whip"));
		assertFalse(mobs.allExclusions(MOB).getOrDefault("RANGED", java.util.Set.of()).contains(WHIP));
		history.undo();
		assertTrue(mobs.allExclusions(MOB).get("RANGED").contains(WHIP));
	}

	@Test
	@DisplayName("filter item: an add is one undo step and keeps its display name")
	void filterItemKeepsName() {
		MonsterProfileStore mobs = new MonsterProfileStore(cfg, new Gson());
		history.execute(TestCommands.addFilterItem(mobs, MOB, "ALL", 12695, "Super combat potion(4)"));
		assertEquals("Super combat potion(4)", mobs.allFilterItems(MOB).get("ALL").get(12695));
		history.undo();
		assertTrue(mobs.allFilterItems(MOB).isEmpty()
			|| !mobs.allFilterItems(MOB).getOrDefault("ALL", java.util.Map.of()).containsKey(12695));
	}

}

package com.loadoutlab.command;

import com.loadoutlab.collection.IdSetStore;
import com.loadoutlab.collection.MonsterProfileStore;
import com.loadoutlab.data.GearSlot;
import java.util.LinkedHashSet;
import java.util.Map;
import java.util.Set;
import java.util.function.*;

/**
 * Command factories that only the test suite ever builds. They live here -
 * in the matching package, next to {@link Commands#of} - to keep main
 * source out of the Plugin Hub bot's 200k token budget. Behaviour is
 * byte-for-byte the production version that used to sit in
 * {@link Commands}: the plugin's StoreOps built these only to call
 * apply() and discard the revert (the engine's history is the one live
 * stack), so they moved here whole in the 2026-10 slim.
 *
 * <p>Toggles use set-to-target semantics rather than blind re-toggling:
 * apply drives the flag to the captured target, revert drives it back -
 * idempotent even if something else moved the flag in between.
 *
 * <p>Item labels are passed in by the caller (the plugin adapters resolve
 * them from the gear corpus) so this layer stays free of data-service
 * dependencies and trivially testable.
 */
final class TestCommands {
	private TestCommands() {
	}

	/** Wipe the global exclusion list as ONE undo entry; undo restores every id. */
	static Command clearExclusions(IdSetStore store) {
		Set<Integer> before = new LinkedHashSet<>(store.snapshot());
		return Commands.of("Clear exclusions (" + before.size() + ")",
			() -> {
				if (store.snapshot().isEmpty()) {
					return false; // nothing to clear - stay off the stack
				}
				store.clear();
				return true;
			},
			() -> {
				for (int id : before) {
					setFlag(store::contains, store::toggle, id, true);
				}
				return true;
			});
	}

	// ---- global item-flag toggles ------------------------------------

	static Command toggleExclusion(IdSetStore store, int itemId, String label) {
		return toggleFlag(store::contains, store::toggle, itemId, "Exclude ", "Include ", label);
	}

	/**
	 * Shared body for the four global item-flag toggles. The stores each name
	 * their state predicate differently (isExcluded/isDreamed/...), so the
	 * caller hands it in as a method reference alongside the store's flip
	 * method; the public factories keep their concrete store types so call
	 * sites are unaffected. {@code toggle} returns a boolean that is
	 * deliberately discarded - set-to-target semantics only care about the
	 * resulting state.
	 */
	private static Command toggleFlag(IntPredicate isOn, IntConsumer toggle, int itemId,
		String onPrefix, String offPrefix, String label) {
		boolean turnOn = !isOn.test(itemId);
		return Commands.of((turnOn ? onPrefix : offPrefix) + label,
			() -> setFlag(isOn, toggle, itemId, turnOn),
			() -> setFlag(isOn, toggle, itemId, !turnOn));
	}

	/** Drives the flag to {@code want}, flipping only when it is not already there. */
	static boolean setFlag(IntPredicate isOn, IntConsumer toggle, int itemId, boolean want) {
		if (isOn.test(itemId) != want) {
			toggle.accept(itemId);
		}
		return true;
	}

	// ---- per-monster profile mutations --------------------------------

	static Command pin(MonsterProfileStore store, int monsterId, String scope,
		GearSlot slot, int itemId, String label) {
		Integer prior = priorPin(store, monsterId, scope, slot);
		return Commands.of("Pin " + label,
			() -> { store.pin(monsterId, scope, slot, itemId); return true; },
			() -> {
				if (prior == null) {
					store.unpin(monsterId, scope, slot);
				} else {
					store.pin(monsterId, scope, slot, prior);
				}
				return true;
			});
	}

	static Command unpin(MonsterProfileStore store, int monsterId, String scope,
		GearSlot slot, String label) {
		Integer prior = priorPin(store, monsterId, scope, slot);
		return Commands.of("Unpin " + label,
			() -> {
				if (prior == null) {
					return false; // nothing pinned - no-op
				}
				store.unpin(monsterId, scope, slot);
				return true;
			},
			() -> {
				if (prior != null) {
					store.pin(monsterId, scope, slot, prior);
				}
				return true;
			});
	}

	private static Integer priorPin(MonsterProfileStore store, int monsterId, String scope, GearSlot slot) {
		return store.allPins(monsterId).getOrDefault(scope, Map.of()).get(slot);
	}

	static Command setNote(MonsterProfileStore store, int monsterId, String note) {
		String before = store.note(monsterId);
		String after = note == null ? "" : note;
		return Commands.of("Edit note",
			() -> {
				if (after.equals(before == null ? "" : before)) {
					return false; // unchanged text - no-op
				}
				store.setNote(monsterId, after);
				return true;
			},
			() -> { store.setNote(monsterId, before); return true; });
	}

	static Command setPinnedSpell(MonsterProfileStore store, int monsterId, String spellName) {
		String before = store.pinnedSpell(monsterId);
		String after = spellName == null ? "" : spellName;
		return Commands.of(after.isEmpty() ? "Clear pinned spell" : "Pin spell " + after,
			() -> {
				if (after.equals(before == null ? "" : before)) {
					return false;
				}
				store.setPinnedSpell(monsterId, after);
				return true;
			},
			() -> { store.setPinnedSpell(monsterId, before); return true; });
	}

	static Command setPinnedSpec(MonsterProfileStore store, int monsterId,
		int itemId, String label) {
		int before = store.pinnedSpec(monsterId);
		return Commands.of(itemId <= 0 ? "Unpin spec weapon" : "Pin spec " + label,
			() -> {
				if (itemId == before) {
					return false;
				}
				store.setPinnedSpec(monsterId, itemId);
				return true;
			},
			() -> { store.setPinnedSpec(monsterId, before); return true; });
	}

	static Command excludeForMob(MonsterProfileStore store, int monsterId, String scope,
		int itemId, String label) {
		return Commands.of("Exclude here: " + label,
			() -> { store.exclude(monsterId, scope, itemId); return true; },
			() -> { store.removeMobExclusion(monsterId, scope, itemId); return true; });
	}

	static Command removeMobExclusion(MonsterProfileStore store, int monsterId, String scope,
		int itemId, String label) {
		return Commands.of("Allow here: " + label,
			() -> { store.removeMobExclusion(monsterId, scope, itemId); return true; },
			() -> { store.exclude(monsterId, scope, itemId); return true; });
	}

	static Command simForMob(MonsterProfileStore store, int monsterId,
		int itemId, String label) {
		return Commands.of("Sim here: " + label,
			() -> { store.addSim(monsterId, itemId, label); return true; },
			() -> { store.removeMobSim(monsterId, itemId); return true; });
	}

	static Command removeMobSim(MonsterProfileStore store, int monsterId,
		int itemId, String label) {
		return Commands.of("Unsim here: " + label,
			() -> { store.removeMobSim(monsterId, itemId); return true; },
			() -> { store.addSim(monsterId, itemId, label); return true; });
	}

	static Command addFilterItem(MonsterProfileStore store, int monsterId, String scope,
		int itemId, String name) {
		return Commands.of("Add trip supply " + name,
			() -> { store.addFilterItem(monsterId, scope, itemId, name); return true; },
			() -> { store.removeMobFilter(monsterId, scope, itemId); return true; });
	}
}

