				.filter(m -> m.getName().equals("Nylocas Vasilias")).count());
		}
		// A Vasilias form takes damage ONLY from its own style.
		MonsterStats meleeForm = byName("Theatre of Blood (Hard)").getMobs().stream()
			.filter(m -> m.getVersion().contains("Melee form")).findFirst().orElseThrow(AssertionError::new);
		assertFalse(com.loadoutlab.engine.Immunity.styleImmune(
			meleeForm, com.loadoutlab.engine.CombatStyle.MELEE));
		assertTrue(com.loadoutlab.engine.Immunity.styleImmune(
			meleeForm, com.loadoutlab.engine.CombatStyle.RANGED));
		assertTrue(com.loadoutlab.engine.Immunity.styleImmune(
			meleeForm, com.loadoutlab.engine.CombatStyle.MAGIC));
		// The P2 Wardens are single-style; KQ crawling is melee-only.
		MonsterStats elidinis = byName("Tombs of Amascut").getMobs().stream()
			.filter(m -> m.getVersion().contains("magic only")).findFirst().orElseThrow(AssertionError::new);
		assertTrue(com.loadoutlab.engine.Immunity.styleImmune(
			elidinis, com.loadoutlab.engine.CombatStyle.MELEE));
		assertFalse(com.loadoutlab.engine.Immunity.styleImmune(
			elidinis, com.loadoutlab.engine.CombatStyle.MAGIC));
		MonsterStats crawling = byName("Kalphite Queen").getMobs().stream()
			.filter(m -> m.getVersion().contains("melee only")).findFirst().orElseThrow(AssertionError::new);
		assertFalse(com.loadoutlab.engine.Immunity.styleImmune(
			crawling, com.loadoutlab.engine.CombatStyle.MELEE));
		assertTrue(com.loadoutlab.engine.Immunity.styleImmune(
			crawling, com.loadoutlab.engine.CombatStyle.RANGED));
		assertEquals("Kalphite Queen",
			MonsterGroups.search(groups, "kq", 5).get(0).getName());
		// Akkha cycles prayers leaving exactly ONE style live per phase.
		java.util.List<MonsterStats> akkha = byName("Tombs of Amascut").getMobs().stream()
			.filter(m -> m.getName().equals("Akkha"))
			.collect(java.util.stream.Collectors.toList());
		// ...and makes his final stand melee-only at 20% hp with Protect from
		// Magic and Missiles both up (wiki; Andrew 2026-09-02: "missing the
		// final phase of akkha").
		assertEquals(4, akkha.size());
		assertEquals("Final stand (melee only)", akkha.get(3).getVersion());
		assertFalse(com.loadoutlab.engine.Immunity.styleImmune(
			akkha.get(3), com.loadoutlab.engine.CombatStyle.MELEE));
		for (MonsterStats phase : akkha) {
			int immune = 0;
			for (com.loadoutlab.engine.CombatStyle style : com.loadoutlab.engine.CombatStyle.concreteValues()) {
				if (com.loadoutlab.engine.Immunity.styleImmune(phase, style)) {
					immune++;
				}
			}
			assertEquals(2, immune, phase.getVersion() + " must leave exactly one style live");
		}
		assertEquals("Abyssal Sire",
			MonsterGroups.search(groups, "sire", 5).get(0).getName());
		assertEquals("Fortis Colosseum",
			MonsterGroups.search(groups, "colosseum", 5).get(0).getName());
		assertEquals("Corrupted Gauntlet",
			MonsterGroups.search(groups, "cg", 5).get(0).getName());
		// Olm is head plus both claws.
		assertEquals(3, byName("Chambers of Xeric").getMobs().stream()
			.filter(m -> m.getName().equals("Great Olm")).count());
		// Raids preset a bigger Inventory default; other groups do not.
		assertEquals(12, byName("Theatre of Blood (Entry)").getInventory());
		assertEquals(12, byName("Theatre of Blood (Hard)").getInventory());
		assertEquals(12, byName("Tombs of Amascut").getInventory());
		assertEquals(12, byName("Chambers of Xeric").getInventory());
		assertEquals(0, byName("Fight Caves").getInventory());
	}

	private static MonsterGroups.MonsterGroup byName(String name) {
		return groups.stream().filter(g -> g.getName().equals(name))
			.findFirst().orElseThrow(() -> new AssertionError("missing group " + name));
	}


	@Test
	@DisplayName("Tombs of Amascut carries its stipulations: the P2 Wardens weigh 3x in the kit and the Wardens' spec is the dragon dagger")
	void toaStipulations() {
		int weighted = 0;
		int dagger = 0;
		for (MonsterStats mob : byName("Tombs of Amascut").getMobs()) {
			if ("3".equals(mob.attributeValue("weight:"))) {
				weighted++;
				assertTrue(mob.getVersion().startsWith("P2"), mob.label());
				assertEquals(3 * mob.getHitpoints(), (int) com.loadoutlab.engine.MonsterMechanics.kitWeight(mob));
			}
			if ("dragon dagger".equals(com.loadoutlab.engine.MonsterMechanics.specStipulation(mob))) {
				dagger++;
			}
		}
		assertEquals(2, weighted, "both P2 Wardens");
		assertEquals(2, dagger, "the core and the enraged Warden");
	}
}

package com.loadoutlab.data;

import java.util.List;
import org.junit.jupiter.api.BeforeAll;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import static org.junit.jupiter.api.Assertions.*;

/**
 * Exact-name search used to return versions in corpus (alphabetical)
 * order, so the DEFAULT fight was usually the wrong one: "vorkath" gave
 * the Dragon Slayer II quest version, "vardorvis" gave Awakened, "zulrah"
 * gave Magma, "tzkal-zuk" gave Enraged (2026-07 player audit A3.3). The
 * headless harness and every name-based link-in take hits.get(0), so the
 * first exact hit must be the version a player means by the bare name.
 */
class MonsterVersionDefaultTest {
	private static LoadoutData data;

	@BeforeAll
	static void load() {
		data = new DataService().load();
	}

	private static String defaultVersion(String query) {
		List<MonsterStats> hits = data.searchMonsters(query, 5);
		assertFalse(hits.isEmpty(), "no hits for " + query);
		return hits.get(0).getVersion() == null ? "" : hits.get(0).getVersion();
	}

	@Test
	@DisplayName("bare boss names default to the everyday version, not quest/awakened/enraged")
	void everydayVersionsWin() {
		assertEquals("", defaultVersion("vorkath"));
		assertEquals("", defaultVersion("vardorvis"));
		assertEquals("", defaultVersion("the whisperer"));
		assertEquals("", defaultVersion("the leviathan"));
		// Normal and Enraged Zuk share a stat block, so the loader collapses
		// them into one unversioned row - either label would compute the same.
		assertEquals("", defaultVersion("tzkal-zuk"));
		assertEquals("Serpentine", defaultVersion("zulrah"));
	}

	@Test
	@DisplayName("multi-mode bosses default to the everyday-numbers row, delves to the first")
	void modesAndDelves() {
		// ToB's Normal-mode rows stat-collapse into the Hard-labeled ones
		// (identical defensive block), so the hard-labeled Phase 1 row IS the
		// everyday fight's numbers; Entry mode (genuinely weaker) never leads.
		assertTrue(defaultVersion("verzik vitur").toLowerCase().startsWith("hard mode, phase 1"),
			"got: " + defaultVersion("verzik vitur"));
		assertFalse(defaultVersion("doom of mokhaiotl").toLowerCase().contains("deep"),
			"deep delve must not be the default: " + defaultVersion("doom of mokhaiotl"));
	}

	@Test
	@DisplayName("asking for a specific version still finds it")
	void explicitVersionStillReachable() {
		List<MonsterStats> hits = data.searchMonsters("zulrah", 5);
		assertTrue(hits.stream().anyMatch(m -> "Magma".equals(m.getVersion())),
			"all versions stay reachable in the hit list");
		assertTrue(hits.stream().anyMatch(m -> "Tanzanite".equals(m.getVersion())));
	}
}

package com.loadoutlab.data;

import com.google.gson.Gson;
import com.google.gson.JsonArray;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.nio.charset.StandardCharsets;
import java.util.HashSet;
import java.util.List;
import java.util.Set;
import org.junit.jupiter.api.BeforeAll;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import static org.junit.jupiter.api.Assertions.*;

/**
 * multi_mobs.json (Andrew 2026-10-19, the multi-combat card design):
 * the corpus monsters fought in multi-combat areas, curated from the
 * wiki location tables, the crowdsourced multicombat varbit tiles and
 * the areas' own pages (docs/data/multi-mobs.md). Every entry must name
 * exactly one corpus monster, or the card could never find it.
 */
class MultiMobsTest {
	private static LoadoutData data;
	private static JsonArray mobs;

	@BeforeAll
	static void load() throws Exception {
		data = new DataService().load();
		try (InputStream in = MultiMobsTest.class.getResourceAsStream("/com/loadoutlab/data/multi_mobs.json")) {
			assertNotNull(in, "multi_mobs.json is on the classpath");
			JsonObject root = new Gson().fromJson(new InputStreamReader(in, StandardCharsets.UTF_8), JsonObject.class);
			assertEquals(1, root.get("version").getAsInt());
			mobs = root.getAsJsonArray("mobs");
		}
	}

	private static String version(MonsterStats m) {
		return m.getVersion() == null ? "" : m.getVersion();
	}

	@Test
	@DisplayName("crowds only: the Catacombs nechryaels are listed, a boss standing alone in a multi area is not (Andrew 2026-10-19)")
	void crowdsNotBosses() {
		java.util.Set<String> names = new HashSet<>();
		for (JsonElement e : mobs) {
			names.add(e.getAsJsonObject().get("name").getAsString());
		}
		assertTrue(names.contains("Greater Nechryael"));
		assertTrue(names.contains("Dust devil"));
		assertFalse(names.contains("General Graardor"), "one spawn in the Bandos room");
		assertFalse(names.contains("Kalphite Queen"));
		assertFalse(names.contains("Dagannoth Rex"));
	}

	@Test
	@DisplayName("every entry resolves to exactly one corpus monster by name and version, and carries a location")
	void entriesResolve() {
		assertTrue(mobs.size() > 50, "the list is not a stub: " + mobs.size());
		Set<String> seen = new HashSet<>();
		for (JsonElement e : mobs) {
			JsonObject mob = e.getAsJsonObject();
			String name = mob.get("name").getAsString();
			String version = mob.get("version").getAsString();
			assertTrue(seen.add(name + "#" + version), "repeated entry: " + name + " [" + version + "]");
			List<MonsterStats> hits = data.searchMonsters(name, 100);
			long exact = hits.stream()
				.filter(m -> m.getName().equals(name) && version(m).equals(version)).count();
			assertEquals(1, exact, name + " [" + version + "] must name one corpus monster, found " + exact);
			JsonArray locations = mob.getAsJsonArray("locations");
			assertTrue(locations.size() > 0, name + " has no location");
			for (JsonElement l : locations) {
				assertFalse(l.getAsJsonObject().get("location").getAsString().isBlank());
				assertFalse(l.getAsJsonObject().get("source").getAsString().isBlank());
			}
		}
	}
}

package com.loadoutlab.data;

import java.lang.reflect.Method;
import java.util.ArrayList;
import java.util.List;
import net.runelite.api.Quest;
import org.junit.BeforeClass;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

/**
 * Golden test for the name_rules.json extraction.
 *
 * Replays LegacyNameRules - the verbatim pre-extraction implementations - over
 * the entire real corpus and asserts the resource-driven versions in
 * DataService agree on every single row. This, plus the byte-identical golden
 * DPS run, is the proof that the extraction changed no behaviour.
 */
public class NameRulesGoldenTest {
	private static LoadoutData data;
	private static Method questsFor;
	private static Method spellLevel;
	private static Method knownSlayerMonster;

	@BeforeClass
	public static void loadCorpus() throws Exception {
		data = new DataService().load();
		questsFor = privateStatic("questsFor", String.class, String.class);
		spellLevel = privateStatic("spellLevel", String.class);
		knownSlayerMonster = privateStatic("knownSlayerMonster", String.class);
	}

	private static Method privateStatic(String name, Class<?>... params) throws Exception {
		Method method = DataService.class.getDeclaredMethod(name, params);
		method.setAccessible(true);
		return method;
	}

	/** The legacy rules, less the deliberate corrections made since the
	 * extraction (LegacyNameRules itself stays frozen): the blisterwood
	 * flail wields at 50 Attack with no quest - it is made partway through
	 * Sins of the Father and the quest's own Vanstrom fight needs it (wiki;
	 * ISS-01M5RGMT70PG86MWHPF28DBJ3V). From the quest-boss audit
	 * (ISS-01M5RRTHQ3F1FCCJA30HQKMJ5R, each on the item's wiki page): only the
	 * green and gilded d'hide bodies need Dragon Slayer I; the dwarven helmet
	 * needs Grim Tales, not Between a Rock...; the light ballista and the
	 * Dorgeshuun crossbow need no quest (the Dorgeshuun-crest heraldry keeps
	 * The Lost Tribe). */
	private static List<String> expectedQuests(GearItem item) {
		List<String> expected = new ArrayList<>(
			LegacyNameRules.forItem(item.getId(), item.getName(), item.getVersion()));
		String key = (item.getName() + " " + item.getVersion()).toLowerCase(java.util.Locale.ROOT);
		if (key.contains("blisterwood flail")) {
			expected.remove(Quest.SINS_OF_THE_FATHER.name());
		}
		if (key.contains("d'hide body") && !key.contains("green d'hide body") && !key.contains("gilded d'hide body")) {
			expected.remove(Quest.DRAGON_SLAYER_I.name());
		}
		if (key.contains("dwarven helmet")) {
			expected.replaceAll(q -> q.equals(Quest.BETWEEN_A_ROCK.name()) ? Quest.GRIM_TALES.name() : q);
		}
		if (key.contains("light ballista") && !key.contains("heavy ballista")) {
			expected.remove(Quest.MONKEY_MADNESS_II.name());
		}
		if ((key.contains("dorgeshuun") && !key.contains("(dorgeshuun)")) || key.contains("bone crossbow")) {
			expected.remove(Quest.THE_LOST_TRIBE.name());
		}
		return expected;
	}

	@Test
	public void corpusIsBigEnoughToBeMeaningful() {
		// Guards against a silently empty corpus making every assertion vacuous.
		assertTrue("gear corpus suspiciously small: " + data.getGearItems().size(),
			data.getGearItems().size() > 4000);
		assertTrue("spell corpus suspiciously small", data.getSpells().size() > 20);
		assertTrue("monster corpus suspiciously small", data.getMonsters().size() > 500);
	}

	@Test
	@SuppressWarnings("unchecked")
	public void questUnlocksMatchTheOldImplementationForEveryGearItem() throws Exception {
		List<String> mismatches = new ArrayList<>();
		int withQuests = 0;
		for (GearItem item : data.getGearItems()) {
			List<String> expected = expectedQuests(item);
			List<String> actual = new ArrayList<>(
				(java.util.Set<String>) questsFor.invoke(null, item.getName(), item.getVersion()));
			if (!expected.equals(actual)) {
				mismatches.add(item.getId() + " " + item.getName() + " [" + item.getVersion()
					+ "] expected " + expected + " but got " + actual);
			}
			if (!expected.isEmpty()) {
				withQuests++;
			}
		}
		assertTrue("no gear item resolved any quest - the table is not being exercised",
			withQuests > 0);
		assertEquals("quest unlock mismatches: " + mismatches, 0, mismatches.size());
	}

	/** The end-to-end path: the GearRequirements actually attached to items. */
	@Test
	public void attachedGearRequirementsMatchTheOldImplementation() {
		List<String> mismatches = new ArrayList<>();
		for (GearItem item : data.getGearItems()) {
			List<String> expected = expectedQuests(item);
			List<String> actual = new ArrayList<>(item.getRequirements().getQuests());
			if (!expected.equals(actual)) {
				mismatches.add(item.getId() + " " + item.getName()
					+ " expected " + expected + " but got " + actual);
			}
		}
		assertEquals("attached requirement mismatches: " + mismatches, 0, mismatches.size());
	}

	@Test
	public void spellLevelsMatchTheOldSwitchForEverySpell() throws Exception {
		for (SpellStats spell : data.getSpells()) {
			assertEquals(spell.getName(),
				LegacyNameRules.spellLevel(spell.getName()),
				((Integer) spellLevel.invoke(null, spell.getName())).intValue());
		}
		// Unknown and null names must still fall back to 1.
		assertEquals(1, ((Integer) spellLevel.invoke(null, "Not A Spell")).intValue());
		assertEquals(1, ((Integer) spellLevel.invoke(null, (Object) null)).intValue());
	}

	@Test
	public void slayerMonsterDetectionMatchesTheOldOrChain() throws Exception {
		List<String> mismatches = new ArrayList<>();
		int matched = 0;
		for (MonsterStats monster : data.getMonsters()) {
			boolean expected = LegacyNameRules.knownSlayerMonster(monster.getName());
			boolean actual = (Boolean) knownSlayerMonster.invoke(null, monster.getName());
			if (expected != actual) {
				mismatches.add(monster.getName() + " expected " + expected);
			}
			if (expected) {
				matched++;
			}
		}
		assertTrue("no monster matched the slayer table - it is not being exercised", matched > 0);
		assertEquals("slayer detection mismatches: " + mismatches, 0, mismatches.size());
		assertEquals(false, knownSlayerMonster.invoke(null, (Object) null));
	}

	/**
	 * BLOCKER guard: every quest name frozen into name_rules.json must still
	 * resolve through Quest.valueOf. RuneLite is not pinned
	 * (runeLiteVersion = 'latest.release'), so an upstream enum rename would
	 * otherwise silently degrade an item to "no quest requirement".
	 */
	@Test
	public void everyQuestNameStillResolvesAgainstTheRuneLiteEnum() {
		List<String> unknown = new ArrayList<>();
		List<String> names = questNames();
		for (String name : names) {
			try {
				Quest.valueOf(name);
			} catch (IllegalArgumentException ex) {
				unknown.add(name);
			}
		}
		assertEquals("name_rules.json has 34 quest rules (35 at the extraction; the blisterwood flail gate went, ISS-01M5RGMT70PG86MWHPF28DBJ3V)", 34, names.size());
		assertTrue("quest names no longer in net.runelite.api.Quest: " + unknown,
			unknown.isEmpty());
	}

	private static List<String> questNames() {
		com.google.gson.JsonObject root =
			JsonResources.objectOrThrow("/com/loadoutlab/data/name_rules.json");
		List<String> names = new ArrayList<>();
		for (com.google.gson.JsonElement rule : root.getAsJsonArray("questRules")) {
			names.add(rule.getAsJsonObject().get("quest").getAsString());
		}
		return names;
	}

	/** The resource must carry the full tables, not a truncated file. */
	@Test
	public void resourceTableSizesAreTheVerifiedCounts() {
		com.google.gson.JsonObject root =
			JsonResources.objectOrThrow("/com/loadoutlab/data/name_rules.json");
		assertEquals("spell rows", 48, root.getAsJsonObject("spellLevels").size());
		assertEquals("slayer contains terms", 29, root.getAsJsonArray("slayerContains").size());
		assertEquals("slayer startsWith terms", 1, root.getAsJsonArray("slayerStartsWith").size());
		assertEquals("quest rules", 34, root.getAsJsonArray("questRules").size());
	}
}

package com.loadoutlab.data;

import java.util.List;
import org.junit.jupiter.api.BeforeAll;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import static org.junit.jupiter.api.Assertions.*;

/**
 * The naval roster is a CURATED list (the corpus carries no naval flag), so
 * this net proves every name still resolves to a real corpus row - a corpus
 * regeneration that renames a sea monster goes red here instead of silently
 * un-navaling it.
 */
class NavalCombatTest {
	private static LoadoutData data;

	@BeforeAll
	static void load() {
		data = new DataService().load();
	}

	@Test
	@DisplayName("every curated naval name resolves to a corpus row with heavy defence")
	void rosterResolvesAgainstTheCorpus() {
		assertFalse(NavalCombat.NAVAL.isEmpty());
		StringBuilder missing = new StringBuilder();
		for (String name : NavalCombat.NAVAL) {
			List<MonsterStats> hits = data.searchMonsters(name, 1);
			if (hits.isEmpty() || !hits.get(0).getName().equalsIgnoreCase(name)) {
				missing.append("\n  ").append(name)
					.append(hits.isEmpty() ? " (no hit)" : " (top hit: " + hits.get(0).getName() + ")");
			}
		}
		assertEquals(0, missing.length(),
			"curated naval names without a matching corpus row:" + missing);
	}

	@Test
	@DisplayName("naval detection is name-exact and case-insensitive")
	void detection() {
		assertTrue(NavalCombat.isNaval("Hammerhead shark"));
		assertTrue(NavalCombat.isNaval("hammerhead SHARK"));
		assertFalse(NavalCombat.isNaval("General Graardor"));
		assertFalse(NavalCombat.isNaval(null));
		// The land shark stays a land monster: only the exact curated names
		// count, never substring matches.
		assertFalse(NavalCombat.isNaval("Shark"));
	}

	@Test
	@DisplayName("every roster mob carries an 8-keel max-hit row")
	void keelRowsCoverTheRoster() {
		assertEquals(8, NavalCombat.keels().size());
		// Keels are METAL tiers (wiki Keel page; Andrew 2026-09-02: "there is
		// a rune keel but not a mahogany keel"). The Boat combat table's
		// columns read None, Bronze, Iron, Steel, Mithril, Adamant, Rune,
		// Dragon - the numbers were parsed right, the names were the hull
		// wood ladder.
		assertEquals(java.util.List.of("none", "bronze", "iron", "steel", "mithril",
			"adamant", "rune", "dragon"), NavalCombat.keels());
		// A persisted pre-0.5.0 wood name lands on the same column.
		assertEquals("rune", NavalCombat.normalizeKeel("rosewood"));
		assertEquals("none", NavalCombat.normalizeKeel("regular"));
		assertEquals("dragon", NavalCombat.normalizeKeel("dragon"));
		assertEquals("steel", NavalCombat.normalizeKeel("steel"));
		for (String name : NavalCombat.NAVAL) {
			for (String keel : NavalCombat.keels()) {
				assertTrue(NavalCombat.keelMaxHit(name, keel) >= 0,
					name + " has no keel row for " + keel);
			}
		}
		// Spot pins straight off the wiki table.
		assertEquals(7, NavalCombat.keelMaxHit("Hammerhead shark", "none"));
		assertEquals(0, NavalCombat.keelMaxHit("Hammerhead shark", "rune"));
		assertEquals(0, NavalCombat.keelMaxHit("Hammerhead shark", "dragon"));
		assertEquals(12, NavalCombat.keelMaxHit("Vampyre kraken", "dragon"));
		assertEquals(-1, NavalCombat.keelMaxHit("General Graardor", "regular"));
	}
}

package com.loadoutlab.data;

import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.stream.Collectors;
import org.junit.jupiter.api.BeforeAll;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import static org.junit.jupiter.api.Assertions.*;

/**
 * The bonecrusher, ash sanctifier and soul bearer ride along like the herb
 * sack (ISS-01M5TNBSP28AAHJTYWAWJHHZKB, Andrew 2026-10-25: "the soul bearer,
 * ash sanctifier, and bone crusher should all have options to be brought for
 * certain mobs that qualify for those drops").
 */
class PrayerCarryTest {
	private static final int BONECRUSHER = 13116;
	private static final int BONECRUSHER_NECKLACE = 22986;
	private static final int ASH_SANCTIFIER = 25781;
	private static final int SOUL_BEARER = 19634;
	private static final Set<Integer> ALL = Set.of(BONECRUSHER, ASH_SANCTIFIER, SOUL_BEARER);
	private static LoadoutData data;

	@BeforeAll
	static void load() {
		data = new DataService().load();
	}

	private static List<Map> picks(String mob, Set<Integer> bank) {
		return LootContainers.picks(data.searchMonsters(mob, 1).get(0), bank::contains, false);
	}

	private static List<String> names(List<Map> picks) {
		return picks.stream().map(r -> (String) r.get("name")).collect(Collectors.toList());
	}

	@Test
	@DisplayName("an abyssal demon brings the ash sanctifier and the soul bearer, not the bonecrusher")
	void abyssalDemon() {
		List<String> names = names(picks("abyssal demon", ALL));
		assertTrue(names.contains("Ash sanctifier"), names.toString());
		assertTrue(names.contains("Soul bearer"), names.toString());
		assertFalse(names.contains("Bonecrusher"), "abyssal demons drop ashes: " + names);
	}

	@Test
	@DisplayName("a black dragon brings the bonecrusher - or the necklace - which crushes its bones")
	void blackDragon() {
		Map<String, Object> crusher = picks("black dragon", ALL).stream()
