/**
 * The Fractured Archive (released 2026-10-20) lands in one pass: the
 * encounters with published stats as a raid group, the rewards as gear
 * rows (scripts/wiki_intake.py, ids from runelite-api 1.13.3 gameval).
 */
class TfaIntakeTest {
	private static LoadoutData data;
	private static MonsterGroups.MonsterGroup tfa;

	@BeforeAll
	static void load() {
		data = new DataService().load();
		tfa = MonsterGroups.load(data).stream()
			.filter(g -> g.getName().equals("The Fractured Archive"))
			.findFirst().orElseThrow();
	}

	private static MonsterStats guardian() {
		return tfa.getMobs().stream().filter(m -> m.getName().equals("Archive Guardian")).findFirst().orElseThrow();
	}

	@Test
	@DisplayName("the raid group lists the encounters that have stats: the Guardian and Xarth in two phases, the Dagon'hai trio, Ocellus in three")
	void groupRoster() {
		assertTrue(tfa.isRaid());
		// The two Monks share one stat block, so the corpus folds them into one row.
		assertEquals(14, tfa.getMobs().size());
		Set<String> names = tfa.getMobs().stream().map(MonsterStats::getName).collect(Collectors.toSet());
		for (String name : new String[]{"Archive Guardian", "Ezekiel", "Bork", "The Smorks",
			"Dreadnoth the Jellied", "Moia", "Xarth", "Ocellus", "Dagon'hai Elder", "Dagon'hai Monk"}) {
			assertTrue(names.contains(name), name);
		}
		assertEquals(3, tfa.getMobs().stream().filter(m -> m.getName().equals("Ocellus")).count());
	}

	@Test
	@DisplayName("the Archive Guardian reads 550 hitpoints and an 80% fire weakness")
	void guardianStats() {
		MonsterStats guardian = guardian();
		assertEquals(550, guardian.getHitpoints());
		assertEquals("fire", guardian.getWeaknessElement());
		assertEquals(80, guardian.getWeaknessSeverity());
	}

	@Test
	@DisplayName("every style computes a set against the Guardian")
	void everyStyleComputes() {
		for (CombatStyle style : CombatStyle.values()) {
			OptimizationRequest request = TestRequests.of(guardian(), style, PlayerLevels.MAXED,
				PrayerBonuses.bestAvailable(PlayerLevels.MAXED), null, 0, CandidateMode.ALL_STANDARD,
				true, false, OwnedItems.EMPTY, 1);
			assertFalse(new LoadoutOptimizer().optimize(data, request).isEmpty(), style.name());
		}
	}

	@Test
	@DisplayName("the tradeable rewards are priced so the game-best pool admits them; a charged weapon is priced as the uncharged twin you buy")
	void rewardsArePricedAndTradeableByVersion() {
		for (int id : new int[]{34681, 34719, 34717, 34727, 34684, 34702}) {
			GearItem item = data.getGear(id);
			assertTrue(item.isTradeable(), item.getName());
			assertNotNull(item.getEstimatedPrice(), item.getName() + " needs a price for ALL_STANDARD");
		}
		// Charged versions only (ISS-01M5QQV2TGQ5X730T0JJ75S1RD): the uncharged
		// twin is a variant, and the charged one carries its price and trades.
		assertTrue(data.isVariant(34717), "Obligator (uncharged) stands behind the charged one");
		assertTrue(data.getGear(34715).isTradeable(), "Obligator (charged) is bought as the uncharged one");
		assertEquals(data.getGear(34717).getEstimatedPrice(), data.getGear(34715).getEstimatedPrice(), "at its price");
		assertTrue(data.getGear(34725).isTradeable(), "Zorya's tome (charged) the same way");
		GearItem xbow = data.getGear(34681);
		OptimizationRequest request = TestRequests.of(guardian(), CombatStyle.RANGED, PlayerLevels.MAXED,
			PrayerBonuses.bestAvailable(PlayerLevels.MAXED), null, 0, CandidateMode.ALL_STANDARD,
			true, false, OwnedItems.EMPTY, 1);
		java.util.Map<GearSlot, Integer> pin = new java.util.EnumMap<>(GearSlot.class);
		pin.put(GearSlot.WEAPON, xbow.getId());
		assertFalse(new LoadoutOptimizer().optimize(data, request.withPinnedItems(pin)).isEmpty(),
			"the crossbows find their bolts without a pinned ammo slot");
	}

	@Test
	@DisplayName("the rewards are gear rows: the Obligator a crush two-hander, the tome a powered staff, the crossbows and bolts, the Rondache")
	void rewardsInTheCorpus() {
		GearItem obligator = data.getGear(34715);
		assertNotNull(obligator);
		assertEquals("Obligator", obligator.getName());
		assertTrue(obligator.isTwoHanded());
		assertEquals(120, obligator.getOffensive().getCrush());
		GearItem tome = data.getGear(34725);
		assertNotNull(tome);
		assertTrue(tome.isPoweredStaff(), "Zorya's tome is a powered staff");
		assertTrue(tome.isTwoHanded());
		assertNotNull(data.getGear(34681), "Ascension crossbows");
		assertNotNull(data.getGear(34719), "Rondache");
		for (int bolts : new int[]{34684, 34690, 34696, 34702, 34708}) {
			assertEquals(GearSlot.AMMO, data.getGear(bolts).getSlot(), "bolts " + bolts);
		}
	}
}

package com.loadoutlab.data;

import com.loadoutlab.engine.CandidateMode;
import com.loadoutlab.engine.CombatStyle;
import com.loadoutlab.engine.DpsResult;
import com.loadoutlab.engine.Loadout;
import com.loadoutlab.engine.LoadoutOptimizer;
import com.loadoutlab.engine.MonsterMechanics;
import com.loadoutlab.engine.OptimizationRequest;
import com.loadoutlab.engine.OwnedItems;
import com.loadoutlab.engine.PlayerLevels;
import com.loadoutlab.engine.PrayerBonuses;
import com.loadoutlab.engine.TestRequests;
import java.util.EnumMap;
import java.util.List;
import org.junit.jupiter.api.BeforeAll;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import static org.junit.jupiter.api.Assertions.*;

/**
 * Andrew, client test 2026-10-20: "all of my bis recommendations for TFA
 * are melee". The published defences favour crush nearly everywhere, but
 * two phases cannot be meleed (wiki, read 2026-10-20): the Archive
 * Guardian flies until its shield breaks (ranged, magic or a halberd),
 * and Xarth's first phase is fought from behind the pillars. The Guardian
 * is also immune to Ancient Magicks.
 */
class TfaStipulationsTest {
	private static LoadoutData data;
	private static List<MonsterStats> tfa;

	@BeforeAll
	static void load() {
		data = new DataService().load();
		tfa = MonsterGroups.load(data).stream()
			.filter(g -> g.getName().equals("The Fractured Archive"))
			.findFirst().orElseThrow().getMobs();
	}

	private static MonsterStats member(String label) {
		return tfa.stream().filter(m -> label.equals(m.getVersion()))
			.findFirst().orElseThrow(() -> new AssertionError("no member " + label));
	}

	private static List<DpsResult> best(MonsterStats mob, CombatStyle style) {
		OptimizationRequest request = TestRequests.of(mob, style, PlayerLevels.MAXED,
			PrayerBonuses.bestAvailable(PlayerLevels.MAXED), null, 0, CandidateMode.ALL_STANDARD,
			true, false, OwnedItems.EMPTY, 3);
		return new LoadoutOptimizer().optimize(data, request);
	}

	@Test
	@DisplayName("the roster carries the Guardian's two phases, Xarth's two phases and the Dagon'hai Elder and Monk: fourteen rows")
	void fourteenRows() {
		// The Dagon'hai joined 2026-10-22 (ISS-01M5JBYYKPE7192Z24NTR432M8).
		assertEquals(14, tfa.size());
	}

	@Test
	@DisplayName("the shielded Guardian flies: a melee set must be a halberd")
	void shieldFlies() {
		MonsterStats shield = member("Shield (flying)");
		assertTrue(shield.hasAttribute("flying"));
		for (DpsResult r : best(shield, CombatStyle.MELEE)) {
			assertEquals("Polearm", r.getLoadout().getWeapon().getCategory(), r.getLoadout().getWeapon().getName());
		}
	}

	@Test
	@DisplayName("the grounded Guardian takes any melee weapon")
	void groundedTakesMelee() {
		MonsterStats grounded = member("Grounded");
		assertFalse(grounded.hasAttribute("flying"));
		List<DpsResult> melee = best(grounded, CombatStyle.MELEE);
		assertFalse(melee.isEmpty());
		assertNotEquals("Polearm", melee.get(0).getLoadout().getWeapon().getCategory());
	}

	@Test
	@DisplayName("Xarth's first phase has no melee card; his second does")
	void xarthPhases() {
		assertTrue(com.loadoutlab.engine.Immunity.styleImmune(member("P1 (from the pillars)"), CombatStyle.MELEE));
		assertFalse(com.loadoutlab.engine.Immunity.styleImmune(member("P2"), CombatStyle.MELEE));
		assertFalse(best(member("P2"), CombatStyle.MELEE).isEmpty());
	}

	@Test
	@DisplayName("the Guardian takes no Ancient Magicks in either phase")
	void guardianShrugsOffAncients() {
		SpellStats barrage = data.getSpells().stream().filter(s -> s.getName().equals("Ice Barrage")).findFirst().orElseThrow();
		SpellStats surge = data.getSpells().stream().filter(s -> s.getName().equals("Fire Surge")).findFirst().orElseThrow();
		EnumMap<GearSlot, GearItem> worn = new EnumMap<>(GearSlot.class);
		worn.put(GearSlot.WEAPON, data.getGear(21006));
		Loadout kodai = new Loadout(worn);
		for (String phase : new String[]{"Shield (flying)", "Grounded"}) {
			MonsterStats guardian = member(phase);
			assertTrue(MonsterMechanics.isImmune(guardian, CombatStyle.MAGIC, kodai, barrage), phase);
			assertFalse(MonsterMechanics.isImmune(guardian, CombatStyle.MAGIC, kodai, surge), phase);
		}
	}

	@Test
	@DisplayName("Ocellus is a demon in phases 1 and 3 only - the wiki leaves phase 2's attributes blank")
	void ocellusDemonPhases() {
		for (MonsterStats m : tfa) {
			if (m.getName().equals("Ocellus")) {
				assertEquals(!"Phase 2".equals(m.getVersion()), m.hasAttribute("demon"), m.getVersion());
			}
		}
	}

	@Test
	@DisplayName("Ocellus's third phase reads its own 5,250 hitpoints")
	void ocellusThree() {
		assertEquals(5250, tfa.stream().filter(m -> "Phase 3".equals(m.getVersion()) && m.getName().equals("Ocellus"))
			.findFirst().orElseThrow().getHitpoints());
	}
}

package com.loadoutlab.data;

import java.util.HashSet;
import java.util.List;
import java.util.Set;
import org.junit.Assert;
import org.junit.Test;

/**
 * The trip-supply tier tables (field direction 2026-07-20): persistent
 * food/fast-food/prayer/surge/anti-venom defaults with a "Detect best"
 * that picks the best owned tier, and anti-venom gated on the wiki's
 * venom-inflictor list.
 */
public class TripSuppliesTest {
	@Test
	public void everyCategoryLoadsWithBestFirstOrdering() {
		// Spot-check the verified tier heads (wiki 2026-07-20): moonlight
		// antelope 26 hp leads food, karambwan leads fast food, super
		// restore leads prayer, extended anti-venom+ leads anti-venom.
		Assert.assertEquals("MOONLIGHT_ANTELOPE", TripSupplies.options(TripSupplies.FOOD).get(0).key);
		Assert.assertEquals("KARAMBWAN", TripSupplies.options(TripSupplies.FAST_FOOD).get(0).key);
		Assert.assertEquals("SUPER_RESTORE", TripSupplies.options(TripSupplies.PRAYER_RESTORE).get(0).key);
		Assert.assertEquals("SURGE_POTION", TripSupplies.options(TripSupplies.SURGE).get(0).key);
		Assert.assertEquals("MAX_CAPE", TripSupplies.options(TripSupplies.SPELLBOOK_CAPE).get(0).key);
		Assert.assertEquals("EXTENDED_ANTIVENOM", TripSupplies.options(TripSupplies.ANTIVENOM).get(0).key);
	}

	@Test
	public void detectBestPicksTheBestOwnedTierAcrossAnyDose() {
		// Owning only a 1-dose prayer potion (id 143) must still detect
		// PRAYER_POTION - the filter and detection cover every dose.
		Set<Integer> owned = new HashSet<>();
		owned.add(143);
		TripSupplies.Option pick = TripSupplies.detectBest(TripSupplies.PRAYER_RESTORE, owned::contains);
		Assert.assertNotNull(pick);
		Assert.assertEquals("PRAYER_POTION", pick.key);

		// Adding a super restore (3-dose, 3026) upgrades the pick.
		owned.add(3026);
		Assert.assertEquals("SUPER_RESTORE",
			TripSupplies.detectBest(TripSupplies.PRAYER_RESTORE, owned::contains).key);
	}

	/** Andrew 2026-09-01: "wildy food / supplies should prefer blighted
	 * options". Blighted variants are wilderness-only (wiki), so a trip
	 * there takes a banked one over any tradeable tier, and a land trip
	 * never picks one (ids objtypes-verified 2026-09-02). */
	@Test
	public void blightedSuppliesWinInTheWildernessAndNeverOnLand() {
		Set<Integer> bank = new HashSet<>(List.of(29143, 24592, 3024, 24598, 3144, 24595));
		Assert.assertEquals("BLIGHTED_ANGLERFISH",
			TripSupplies.detectBest(TripSupplies.options(TripSupplies.FOOD), bank::contains, true).key);
		Assert.assertEquals("BLIGHTED_SUPER_RESTORE",
			TripSupplies.detectBest(TripSupplies.options(TripSupplies.PRAYER_RESTORE), bank::contains, true).key);
		Assert.assertEquals("BLIGHTED_KARAMBWAN",
			TripSupplies.detectBest(TripSupplies.options(TripSupplies.FAST_FOOD), bank::contains, true).key);
		// Land: the best tradeable tier, blighted ignored even when owned.
		Assert.assertEquals("MOONLIGHT_ANTELOPE",
			TripSupplies.detectBest(TripSupplies.options(TripSupplies.FOOD), bank::contains, false).key);
		Set<Integer> onlyBlighted = Set.of(24592);
		Assert.assertNull("blighted cannot be eaten outside the wilderness",
			TripSupplies.detectBest(TripSupplies.options(TripSupplies.FOOD), onlyBlighted::contains, false));
		// Wilderness without a blighted stack falls through to the tiers.
		Set<Integer> sharks = Set.of(385);
		Assert.assertEquals("SHARK",
			TripSupplies.detectBest(TripSupplies.options(TripSupplies.FOOD), sharks::contains, true).key);
		// The two-arg detect is the land rule.
		Assert.assertNull(TripSupplies.detectBest(TripSupplies.FOOD, onlyBlighted::contains));
	}

	@Test
	public void detectBestReturnsNullWhenNothingIsOwned() {
		Assert.assertNull(TripSupplies.detectBest(TripSupplies.FOOD, id -> false));
	}

	@Test
	public void prayerRegenerationIsNeverAutoDetected() {
		// Its over-time mechanism must not win a detect - explicitly
		// selectable only (detect:false in the resource).
		Set<Integer> owned = new HashSet<>();
		owned.add(30125); // Prayer regeneration potion(4)
		Assert.assertNull(TripSupplies.detectBest(TripSupplies.PRAYER_RESTORE, owned::contains));
		Assert.assertNotNull(TripSupplies.option(TripSupplies.PRAYER_RESTORE, "PRAYER_REGENERATION"));
	}

	@Test
	public void spellbookCapeDetectPrefersTheMaxCape() {
		Set<Integer> owned = new HashSet<>();
		owned.add(9763); // Magic cape(t)
		Assert.assertEquals("MAGIC_CAPE",
			TripSupplies.detectBest(TripSupplies.SPELLBOOK_CAPE, owned::contains).key);
		owned.add(13280); // Max cape
		Assert.assertEquals("MAX_CAPE",
			TripSupplies.detectBest(TripSupplies.SPELLBOOK_CAPE, owned::contains).key);
	}

	@Test
	public void onlyTheSpellbookCapesAreUtilityPlacement() {
		// Utility = fight-relevant gear that is neither worn nor carried:
		// the bank layout's third strip. Consumables stay inventory-placed.
		for (TripSupplies.Option o : TripSupplies.options(TripSupplies.SPELLBOOK_CAPE)) {
			Assert.assertTrue(o.key + " should be utility", o.utility);
		}
		for (String category : new String[]{TripSupplies.FOOD, TripSupplies.FAST_FOOD,
			TripSupplies.PRAYER_RESTORE, TripSupplies.SURGE, TripSupplies.ANTIVENOM}) {
			for (TripSupplies.Option o : TripSupplies.options(category)) {
				Assert.assertFalse(o.key + " should not be utility", o.utility);
			}
		}
	}

	@Test
	public void theCannonIsAnExplicitFiveCellKit() {
		// miko (Discord 2026-10-17) wanted the cannon in every setup; AKAddons:
		// "an easy option to include it in inventory" - no dps modelled, so
		// Detect best never picks it; chosen, it is one cell per part.
		List<TripSupplies.Option> cannon = TripSupplies.options(TripSupplies.CANNON);
		Assert.assertEquals(1, cannon.size());
		Assert.assertEquals("DWARF_MULTICANNON", cannon.get(0).key);
		Assert.assertArrayEquals(new int[]{6, 8, 10, 12, 2}, cannon.get(0).ids);
		Assert.assertEquals(5, cannon.get(0).names.length);
		Assert.assertFalse(cannon.get(0).detect);
		Assert.assertNull(TripSupplies.detectBest(TripSupplies.CANNON, id -> true));
		// Each cell carries its variants too (Andrew 2026-10-18: the ornamented
		// parts and granite cannonballs must light up in the filter).
		Assert.assertEquals(5, cannon.get(0).cells.length);
		Assert.assertArrayEquals(new int[]{6, 26520}, cannon.get(0).cells[0]);
		Assert.assertArrayEquals(new int[]{2, 21728}, cannon.get(0).cells[4]);
		Assert.assertEquals("Cannon", TripSupplies.label(TripSupplies.CANNON));
		Assert.assertEquals("Food", TripSupplies.label(TripSupplies.FOOD));
		Assert.assertNull("repair kits never show in the chip menu",
			TripSupplies.label(TripSupplies.SHIP_REPAIR_KIT));
	}

	@Test
	public void unknownAndModeKeysResolveToNoOption() {
		Assert.assertNull(TripSupplies.option(TripSupplies.FOOD, "DETECT_BEST"));
		Assert.assertNull(TripSupplies.option(TripSupplies.FOOD, "NONE"));
		Assert.assertNull(TripSupplies.option(TripSupplies.FOOD, "NO_SUCH"));
	}

	@Test
	public void venomInflictorsMatchByNameIncludingVariants() {
		Assert.assertTrue(TripSupplies.inflictsVenom(named("Zulrah")));
		Assert.assertTrue(TripSupplies.inflictsVenom(named("Araxxor")));
		Assert.assertTrue(TripSupplies.inflictsVenom(named("Dreadborn Araxyte")));
		Assert.assertTrue(TripSupplies.inflictsVenom(named("Vorkath")));
		Assert.assertFalse(TripSupplies.inflictsVenom(named("General Graardor")));
		Assert.assertFalse(TripSupplies.inflictsVenom(named("Abyssal demon")));
		Assert.assertFalse(TripSupplies.inflictsVenom(null));
	}

	@Test
	public void displayIdLeadsEachIdList() {
		// ids[0] is the display/cell id: the 4-dose potion or cooked food.
		for (String category : new String[]{TripSupplies.FOOD, TripSupplies.FAST_FOOD,
			TripSupplies.PRAYER_RESTORE, TripSupplies.SURGE, TripSupplies.SPELLBOOK_CAPE,
			TripSupplies.ANTIVENOM}) {
			List<TripSupplies.Option> options = TripSupplies.options(category);
			Assert.assertFalse(category + " must not be empty", options.isEmpty());
			for (TripSupplies.Option o : options) {
				Assert.assertTrue(o.key + " needs at least one id", o.ids.length >= 1);
			}
		}
	}

	private static MonsterStats named(String name) {
		if (name == null) {
			return null;
		}
		return new MonsterStats(1, name, "", 100, 100, 1, 1, null, null);
	}

	@Test
	public void cureMeAndThePrayerBookAreChoicesNeverADetectBestPick() {
		TripSupplies.Option cureMe = TripSupplies.option(TripSupplies.ANTIVENOM, "CURE_ME");
		TripSupplies.Option book = TripSupplies.option(TripSupplies.ANTIVENOM, "PRAYER_BOOK");
		org.junit.jupiter.api.Assertions.assertNotNull(cureMe, "Cure Me option");
		org.junit.jupiter.api.Assertions.assertNotNull(book, "Prayer book option");
		org.junit.jupiter.api.Assertions.assertFalse(cureMe.detect);
		org.junit.jupiter.api.Assertions.assertFalse(book.detect);
		org.junit.jupiter.api.Assertions.assertEquals(9075, cureMe.ids[0], "astral rune leads the Cure Me kit");
		org.junit.jupiter.api.Assertions.assertEquals(10890, book.ids[0], "the prayer book itself leads its kit");
		// Kits name every item so the card shows each one (field 2026-09-08: the holy symbol was filter-only).
		org.junit.jupiter.api.Assertions.assertArrayEquals(new String[]{"Astral rune (Cure Me)", "Cosmic rune (Cure Me)", "Law rune (Cure Me)"}, cureMe.names);
		org.junit.jupiter.api.Assertions.assertArrayEquals(new String[]{"Prayer book", "Holy symbol"}, book.names);
		org.junit.jupiter.api.Assertions.assertEquals(0, TripSupplies.option(TripSupplies.ANTIVENOM, "ANTIVENOM_PLUS").names.length, "potions are one cell");
		// Owning every rune and the book still leaves Detect-best on the potions.
		TripSupplies.Option detected = TripSupplies.detectBest(TripSupplies.ANTIVENOM,
			id -> id == 9075 || id == 564 || id == 563 || id == 10890 || id == 1718);
		org.junit.jupiter.api.Assertions.assertNull(detected);
	}

	@Test
	public void antipoisonCoversThePoisonersTheVenomListDoesNot() {
		LoadoutData data = new DataService().load();
		MonsterStats rex = data.searchMonsters("Dagannoth Rex", 1).get(0);
		MonsterStats zulrah = data.searchMonsters("Zulrah", 1).get(0);
		Assert.assertTrue(TripSupplies.inflictsPoison(rex));
		Assert.assertFalse(TripSupplies.inflictsVenom(rex));
		Assert.assertFalse("venom is its own category", TripSupplies.inflictsPoison(zulrah));
		Assert.assertEquals("ANTIDOTE_PP", TripSupplies.options(TripSupplies.ANTIPOISON).get(0).key);
		Assert.assertEquals("ANTIPOISON",
			TripSupplies.detectBest(TripSupplies.ANTIPOISON, id -> id == 175 || id == 9075).key);
		Assert.assertNotNull(TripSupplies.option(TripSupplies.ANTIPOISON, "CURE_ME"));
		Assert.assertTrue(java.util.Arrays.asList(TripSupplies.CATEGORY_KEYS).contains(TripSupplies.ANTIPOISON));
	}

	/** Kendyy (Discord 2026-10-19): antipoison rode the Sarachnis trip; her
	 * wiki infobox says poisonous = No. The name had been on the list. */
	@Test
	public void sarachnisDoesNotPoison() {
		MonsterStats sarachnis = new DataService().load().searchMonsters("sarachnis", 1).get(0);
		Assert.assertEquals("Sarachnis", sarachnis.getName());
		Assert.assertFalse("wiki infobox: poisonous = No", TripSupplies.inflictsPoison(sarachnis));
		Assert.assertFalse(TripSupplies.inflictsVenom(sarachnis));
	}
}

package com.loadoutlab.data;

import java.util.List;
import java.util.Set;
import java.util.stream.Collectors;
import org.junit.jupiter.api.BeforeAll;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import static org.junit.jupiter.api.Assertions.*;

/**
 * Searching a Warden phase (ISS-01M5HKWBZNJF0V8ZD58FH9XS5B, Andrew
 * 2026-10-22: "its hard to do an individual search for the phase 2 version
 * of elidinis/tumeken ward without searching for toa").
 */
class WardenSearchTest {
	private static LoadoutData data;

	@BeforeAll
	static void load() {
		data = new DataService().load();
	}

	private static List<String> rows(String query) {
		return data.searchMonsters(query, 20).stream()
			.map(m -> m.getName() + " (" + m.getVersion() + ")")
			.collect(Collectors.toList());
	}

	@Test
	@DisplayName("'tumeken warden', 'wardens' and 'elidinis active' find their rows - each word starts a word")
	void wordMatching() {
		assertTrue(rows("tumeken warden").contains("Tumeken's Warden (Active)"), rows("tumeken warden").toString());
		assertTrue(rows("wardens").contains("Elidinis' Warden (Active)"), rows("wardens").toString());
		assertEquals(List.of("Elidinis' Warden (Active)"), rows("elidinis active"));
	}

	@Test
	@DisplayName("'warden p2' finds exactly the phase-2 rows of both Wardens; p3 the phase-3 ones")
	void phaseWords() {
		assertEquals(Set.of("Elidinis' Warden (Active)", "Elidinis' Warden (Core-ejected)",
			"Tumeken's Warden (Active)", "Tumeken's Warden (Core-ejected)"), Set.copyOf(rows("warden p2")));
		assertEquals(Set.of("Elidinis' Warden (Active)", "Elidinis' Warden (Core-ejected)"),
			Set.copyOf(rows("elidinis p2")));
		assertEquals(Set.of("Tumeken's Warden (Active)", "Tumeken's Warden (Core-ejected)"),
			Set.copyOf(rows("tumeken phase 2")));
		List<String> p3 = rows("warden p3");
		assertTrue(p3.contains("Elidinis' Warden (Damaged)") && p3.contains("Tumeken's Warden (Enraged)"), p3.toString());
		assertTrue(p3.stream().noneMatch(r -> r.contains("Active")), p3.toString());
	}

	@Test
	@DisplayName("nothing found before is lost: 'core' still finds the Manticore, 'kril' still K'ril first")
	void noRegressions() {
		assertTrue(rows("core").contains("Manticore ()"), rows("core").toString());
		assertTrue(rows("kril").get(0).startsWith("K'ril Tsutsaroth"), rows("kril").toString());
		assertEquals(rows("elidinis").subList(0, 2), rows("elidinis").subList(0, 2), "stable order");
	}
}

package com.loadoutlab.engine;

import com.loadoutlab.data.DataService;
import com.loadoutlab.data.GearItem;
import com.loadoutlab.data.LoadoutData;
import com.loadoutlab.data.MonsterStats;
import java.util.Map;
import org.junit.Assert;
import org.junit.BeforeClass;
import org.junit.Test;

/** Stat-identical analogs (god d'hide) must track what the player owns. */
public class AnalogTest {
	private static LoadoutData data;
	private static MonsterStats callisto;

	@BeforeClass
	public static void load() {
		data = new DataService().load();
		callisto = data.searchMonsters("callisto", 1).get(0);
	}

	private static GearItem headPick(int ownedCoif) {
		OptimizationRequest req = TestRequests.of(callisto, CombatStyle.RANGED,
			PlayerLevels.MAXED, PrayerBonuses.bestAvailable(PlayerLevels.MAXED, PrayerUnlocks.ALL),
			null, 0, CandidateMode.ALL_STANDARD, true, false,
			new OwnedItems(data.canonicalizeOwned(Map.of(ownedCoif, 1)), true), 1)
			.withMaxTradeables(3);
		LoadoutOptimizer optimizer = new LoadoutOptimizer();
		// Mirror production: the dps-neutral fill is what populates a head
		// slot the raw beam legally leaves empty (post Summer Sweep-Up
		// 2026-07-22, every risk-surviving ranged head is dps-neutral here).
		DpsResult best = optimizer.fillDpsNeutralSlots(data, req,
			optimizer.optimize(data, req).get(0));
		return best.getLoadout().get(com.loadoutlab.data.GearSlot.HEAD);
	}

	@Test
	public void legAnalogsAreStatIdenticalInTheData() {
		// Platelegs vs plateskirts, proselyte cuisse vs tasset: the
		// dedupe's owned-preference and the gold border's stat
		// equivalence both rest on these being true stat clones.
		assertClones(1079, 1093);  // rune platelegs / plateskirt
		assertClones(4087, 4585);  // dragon platelegs / plateskirt
		assertClones(9676, 9678);  // proselyte cuisse / tasset
	}

	private static void assertClones(int a, int b) {
		GearItem left = data.getGear(a);
		GearItem right = data.getGear(b);
		Assert.assertNotNull(left);
		Assert.assertNotNull(right);
		Assert.assertEquals(left.getSlot(), right.getSlot());
		for (java.util.function.Function<GearItem, com.loadoutlab.data.StatBlock> block
			: java.util.List.<java.util.function.Function<GearItem, com.loadoutlab.data.StatBlock>>of(
				GearItem::getOffensive, GearItem::getDefensive, GearItem::getBonuses)) {
			com.loadoutlab.data.StatBlock l = block.apply(left);
			com.loadoutlab.data.StatBlock r = block.apply(right);
			Assert.assertEquals(l.getStab(), r.getStab());
			Assert.assertEquals(l.getSlash(), r.getSlash());
			Assert.assertEquals(l.getCrush(), r.getCrush());
			Assert.assertEquals(l.getMagic(), r.getMagic());
			Assert.assertEquals(l.getRanged(), r.getRanged());
			Assert.assertEquals(l.getStrength(), r.getStrength());
			Assert.assertEquals(l.getRangedStrength(), r.getRangedStrength());
			Assert.assertEquals(l.getMagicDamage(), r.getMagicDamage());
			Assert.assertEquals(l.getPrayer(), r.getPrayer());
		}
	}

	@Test
	public void prayerDistinguishesStatClones_radasBlessingBeatsAncientBlessing() {
		// Both are zero-offense ammo-slot blessings; Rada's 4 gives +2
		// prayer vs +1. The old dedupe key ignored prayer, collapsed them,
		// and the tradeable preference picked the ancient blessing.
		java.util.Map<Integer, Integer> owned = new java.util.HashMap<>();
		owned.put(4151, 1);   // abyssal whip
