public class FlyingRulesTest {
	private static LoadoutData data;

	private static LoadoutData data() {
		if (data == null) {
			data = new DataService().load();
		}
		return data;
	}

	private static GearItem byName(String name) {
		return data().getGearItems().stream()
			.filter(g -> g.getName().equalsIgnoreCase(name))
			.findFirst()
			.orElseThrow(() -> new AssertionError("missing item: " + name));
	}

	@Test
	public void meleeCannotReachFlyingMonstersExceptHalberds() {
		MonsterStats kree = data().searchMonsters("kree'arra", 1).get(0);
		Assert.assertTrue(kree.hasAttribute("flying"));
		Assert.assertFalse(FlyingRules.canReach(kree, CombatStyle.MELEE, byName("Abyssal whip")));
		Assert.assertFalse(FlyingRules.canReach(kree, CombatStyle.MELEE, byName("Voidwaker")));
		Assert.assertTrue(FlyingRules.canReach(kree, CombatStyle.MELEE, byName("Crystal halberd")));
		Assert.assertTrue(FlyingRules.canReach(kree, CombatStyle.RANGED, byName("Twisted bow")));
	}

	@Test
	public void meleeVsDawnOnlyProducesHalberdSets() {
		MonsterStats dawn = data().searchMonsters("dawn", 1).get(0);
		Assert.assertTrue(dawn.hasAttribute("flying"));

		// A whip-only owner has no melee answer for Dawn at all.
		Map<Integer, Integer> owned = new HashMap<>();
		owned.put(4151, 1);
		OptimizationRequest ownedRequest = new OptimizationRequest(
			dawn, CombatStyle.MELEE, PlayerLevels.MAXED,
			PrayerBonuses.bestAvailable(PlayerLevels.MAXED), null, 0,
			CandidateMode.OWNED_ONLY, true, false,
			new OwnedItems(owned, true), RequirementProfile.MAXED, 5);
		Assert.assertTrue(new LoadoutOptimizer().optimize(data(), ownedRequest).isEmpty());

		// Game best melee vs Dawn: a polearm or salamander, never a sword.
		OptimizationRequest gameRequest = new OptimizationRequest(
			dawn, CombatStyle.MELEE, PlayerLevels.MAXED,
			PrayerBonuses.bestAvailable(PlayerLevels.MAXED), null, 0,
			CandidateMode.ALL_STANDARD, true, false,
			OwnedItems.EMPTY, RequirementProfile.MAXED, 1);
		List<DpsResult> results = new LoadoutOptimizer().optimize(data(), gameRequest);
		Assert.assertFalse(results.isEmpty());
		String category = results.get(0).getLoadout().getWeapon().getCategory();
		Assert.assertTrue("expected halberd/salamander, got " + category,
			"Polearm".equals(category) || "Salamander".equals(category));
	}
}

package com.loadoutlab.engine;

import com.loadoutlab.data.DataService;
import com.loadoutlab.data.GearItem;
import com.loadoutlab.data.LoadoutData;
import com.loadoutlab.data.MonsterStats;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import org.junit.jupiter.api.BeforeAll;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import static org.junit.jupiter.api.Assertions.*;

/**
 * Gauntlet fights are locked to raid-crafted gear (field report
 * 2026-07-18: the Corrupted Hunllef card recommended the player's
 * mainland bank - impossible inside). Every recommendation vs a
 * Crystalline/Corrupted mob must wear ONLY the matching family's
 * basic/attuned/perfected tiers, regardless of what is owned.
 */
class GauntletRulesTest {
	private static LoadoutData data;
	private static final LoadoutOptimizer optimizer = new LoadoutOptimizer();

	@BeforeAll
	static void load() {
		data = new DataService().load();
	}

	private static void assertGauntletOnly(String mobName, String family) {
		MonsterStats mob = data.searchMonsters(mobName, 1).get(0);
		// A stacked mainland bank that must be IGNORED inside.
		Map<Integer, Integer> owned = new HashMap<>();
		for (int id : new int[]{4151, 29589, 29591, 21326, 29594, 19553, 13239, 22981, 11832, 11834}) {
			owned.put(id, 1);
		}
		for (CombatStyle style : CombatStyle.concreteValues()) {
			OptimizationRequest request = new OptimizationRequest(mob, style,
				PlayerLevels.MAXED, PrayerBonuses.NONE, null, 0,
				CandidateMode.OWNED_ONLY, true, false,
				new OwnedItems(owned, true), RequirementProfile.MAXED, 1);
			List<DpsResult> best = optimizer.optimize(data, request);
			if (best.isEmpty() || best.get(0) == null) {
				continue; // a style with no in-raid answer is honest
			}
			for (GearItem item : best.get(0).getLoadout().getGear().values()) {
				if (item == null) {
					continue;
				}
				assertTrue(GauntletRules.allowed(family, item),
					mobName + " " + style + " recommended mainland gear: " + item.getNameLower());
			}
			GearItem weapon = best.get(0).getLoadout().getWeapon();
			assertNotNull(weapon, mobName + " " + style + " has no in-raid weapon");
		}
	}

	@Test
	@DisplayName("the Corrupted Hunllef wears only corrupted raid tiers")
	void corruptedHunllef() {
		assertGauntletOnly("Corrupted Hunllef", "corrupted");
	}

	@Test
	@DisplayName("the Crystalline Hunllef wears only crystal raid tiers")
	void crystallineHunllef() {
		assertGauntletOnly("Crystalline Hunllef", "crystal");
	}
}

package com.loadoutlab.engine;

import com.loadoutlab.data.DataService;
import com.loadoutlab.data.GearItem;
import com.loadoutlab.data.GearSlot;
import com.loadoutlab.data.LoadoutData;
import com.loadoutlab.data.MonsterStats;
import java.util.EnumMap;
import org.junit.Assert;
import org.junit.Test;

public class GolembaneTest {
	private static LoadoutData data;

	private static LoadoutData data() {
		if (data == null) {
			data = new DataService().load();
		}
		return data;
	}

	private static GearItem weapon(String weaponName) {
		return data().getGearItems().stream()
			.filter(g -> g.getName().equalsIgnoreCase(weaponName) && g.isStandardGear())
			.findFirst().orElseThrow(() -> new AssertionError("missing " + weaponName));
	}

	private static DpsResult calculate(MonsterStats monster, String weaponName) {
		GearItem weapon = weapon(weaponName);
		OptimizationRequest request = new OptimizationRequest(
			monster, CombatStyle.MELEE, PlayerLevels.MAXED,
			PrayerBonuses.bestAvailable(PlayerLevels.MAXED), null, 0,
			CandidateMode.ALL_STANDARD, true, false,
			OwnedItems.EMPTY, RequirementProfile.MAXED, 1);
		EnumMap<GearSlot, GearItem> gear = new EnumMap<>(GearSlot.class);
		gear.put(GearSlot.WEAPON, weapon);
		return new DpsCalculator().calculate(request, new Loadout(gear));
	}

	@Test
	public void graniteHammerGolembaneBeatsTheTentacleAgainstDusk() {
		// Aug 2025: the granite hammer deals 30% extra damage AND accuracy
		// vs golem-type monsters (Dusk, Dawn, gargoyles...).
		MonsterStats dusk = data().searchMonsters("dusk", 1).get(0);
		Assert.assertTrue(dusk.hasAttribute("golem"));
		Assert.assertTrue(calculate(dusk, "Granite hammer").getDps()
			> calculate(dusk, "Abyssal tentacle").getDps());
	}

	@Test
	public void golembaneDoesNotApplyToNonGolems() {
		MonsterStats goblin = data().searchMonsters("goblin", 1).get(0);
		// Against a non-golem the hammer is just its stat sheet: the
		// tentacle wins comfortably.
		Assert.assertTrue(calculate(goblin, "Abyssal tentacle").getDps()
			> calculate(goblin, "Granite hammer").getDps());
	}

	@Test
	public void optimizerPicksTheHammerAtAGolem() {
		// The pool lesson, which the model tests above do NOT cover: golembane
		// lives in the DPS model, not in the hammer's raw stats (crush +57 /
		// str +56), so the weapon-pool cut dropped it before the bonus could
		// ever be applied. Field-found 2026-08-01 at the Mad Angel - a
		// Zamorakian hasta was suggested and the owned melee answer came in
		// ~2 dps low (6.58 vs 8.58).
		MonsterStats madAngel = data().searchMonsters("mad angel", 1).get(0);
		Assert.assertTrue(madAngel.hasAttribute("golem"));

		// The FULL standard pool is the point: the cut keeps 24 weapons by
		// raw score, and the hammer only survives it because of the golem
		// boost. A two-weapon owned pool would never reach the cut and would
		// re-prove the DPS model instead of the pool behaviour.
		OptimizationRequest request = new OptimizationRequest(
			madAngel, CombatStyle.MELEE, PlayerLevels.MAXED,
			PrayerBonuses.bestAvailable(PlayerLevels.MAXED), null, 0,
			CandidateMode.ALL_STANDARD, true, false,
			OwnedItems.EMPTY, RequirementProfile.MAXED, 3)
			// The Obligator (2026-10-20) out-lunges the hammer at the 3x3,
			// crush-weak Mad Angel (9.91 vs 8.58); this test pins the pool
			// lesson, so it is set aside.
			.withExcludedItems(java.util.Set.of(34715, 34717));
		java.util.List<DpsResult> results = new LoadoutOptimizer().optimize(data(), request);
		Assert.assertFalse(results.isEmpty());
		Assert.assertEquals("granite hammer",
			results.get(0).getLoadout().getWeapon().getNameLower());
	}

	@Test
	public void barroniteMaceGetsItsFifteenPercentAgainstGolems() {
		// Grey golem: golem-typed with zero flat armour, so the max-hit
		// ratio is exactly the 15% golembane factor.
		MonsterStats golem = data().searchMonsters("grey golem", 1).get(0);
		MonsterStats goblin = data().searchMonsters("goblin", 1).get(0);
		int vsGolem = calculate(golem, "Barronite mace").getMaxHit();
		int vsGoblin = calculate(goblin, "Barronite mace").getMaxHit();
		Assert.assertEquals((int) (vsGoblin * 23L / 20), vsGolem);
	}
}

package com.loadoutlab.engine;

import com.loadoutlab.data.DataService;
import com.loadoutlab.data.GearItem;
import com.loadoutlab.data.GearSlot;
import com.loadoutlab.data.LoadoutData;
import com.loadoutlab.data.MonsterStats;
import com.loadoutlab.optimizer.OptimizerService;
import java.util.Collections;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.concurrent.CountDownLatch;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicReference;
import org.junit.jupiter.api.BeforeAll;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import static org.junit.jupiter.api.Assertions.*;

/**
 * God Wars Dungeon protection (ISS-01M5G9KPDQWBR014Z10F79B29T): followers
 * leave you alone while you WEAR an item of their god; each general's walk
 * needs the wiki route table's gods (corner + encampment), worn when it
 * costs no DPS, otherwise carried - Andrew 2026-10-21.
 */
class GwdProtectionTest {
	private static LoadoutData data;

	@BeforeAll
	static void load() {
		data = new DataService().load();
	}

	private static MonsterStats mob(String name) {
		return data.searchMonsters(name, 1).get(0);
	}

	private static int id(String nameLower) {
		return data.getGearItems().stream()
			.filter(g -> g.getNameLower().equals(nameLower) && g.isStandardGear() && !data.isVariant(g.getId()))
			.findFirst().orElseThrow(() -> new AssertionError("corpus is missing " + nameLower)).getId();
	}

	private static OwnedItems owned(String... names) {
		Map<Integer, Integer> owned = new HashMap<>();
		for (String name : names) {
			owned.put(id(name), 1);
		}
		return new OwnedItems(data.canonicalizeOwned(owned), true);
	}

	@Test
	@DisplayName("each general's route needs the wiki table's gods; bodyguards share their general's")
	void routeGods() {
		assertEquals(List.of("armadyl", "bandos", "zamorak"), GwdProtection.godsFor(mob("general graardor"), false));
		assertEquals(List.of("armadyl", "bandos", "saradomin", "zamorak"), GwdProtection.godsFor(mob("kree'arra"), false));
		assertEquals(List.of("armadyl", "saradomin", "zamorak"), GwdProtection.godsFor(mob("commander zilyana"), false));
		assertEquals(List.of("bandos", "saradomin", "zamorak"), GwdProtection.godsFor(mob("k'ril tsutsaroth"), false));
		assertEquals(GwdProtection.godsFor(mob("general graardor"), false),
			GwdProtection.godsFor(mob("sergeant strongstack"), false));
		assertEquals(List.of("armadyl", "bandos", "zamorak", "zaros"),
			GwdProtection.godsFor(mob("general graardor"), true), "the Ancient chip adds Zaros");
		assertTrue(GwdProtection.godsFor(mob("vorkath"), true).isEmpty(), "nowhere near GWD");
	}

	@Test
	@DisplayName("an item's gods come from the wiki table; the Staff of light counts twice")
	void itemGods() {
		GearItem light = data.getGear(id("staff of light"));
		assertEquals(Set.of("saradomin", "zamorak"), GwdProtection.godsOf(light));
		assertEquals(Set.of("bandos"), GwdProtection.godsOf(data.getGear(id("war blessing"))));
		assertTrue(GwdProtection.godsOf(data.getGear(id("abyssal whip"))).isEmpty());
	}

	@Test
	@DisplayName("a god item is worn only when it costs no DPS; the rest are carried")
	void wornWhenFreeElseCarried() {
		MonsterStats graardor = mob("general graardor");
		OwnedItems owned = owned("abyssal whip", "dragon defender", "fighter torso", "dragon platelegs",
			"barrows gloves", "dragon boots", "amulet of fury", "berserker ring", "fire cape", "helm of neitiznot",
			"war blessing", "unholy blessing", "honourable blessing", "zamorak stole", "armadyl stole");
		OptimizationRequest request = TestRequests.of(graardor, CombatStyle.MELEE, PlayerLevels.MAXED,
			PrayerBonuses.bestAvailable(PlayerLevels.MAXED, PrayerUnlocks.ALL), null, 0,
			CandidateMode.OWNED_ONLY, true, false, owned, 1);
		LoadoutOptimizer optimizer = new LoadoutOptimizer();
		DpsResult plain = optimizer.fillDpsNeutralSlots(data, request, optimizer.optimize(data, request).get(0));
		List<String> gods = GwdProtection.godsFor(graardor, false);
		DpsResult worn = optimizer.wearGodItems(data, request, plain, gods);
		assertEquals(plain.getDps(), worn.getDps(), 1e-9, "protection never costs DPS");
		Set<String> covered = GwdProtection.coveredGods(worn.getLoadout());
		assertFalse(covered.isEmpty(), "a blessing in the free ammo slot covers one god");
		List<GearItem> carried = optimizer.carriedGodItems(data, request, worn.getLoadout(), gods);
		Set<String> all = new HashSet<>(covered);
		for (GearItem item : carried) {
			Set<String> adds = GwdProtection.godsOf(item);
			assertFalse(adds.isEmpty(), item.getName() + " protects nothing");
			all.addAll(adds);
		}
		assertTrue(all.containsAll(gods), "every route god covered: " + all);
		assertTrue(carried.size() < gods.size() + 1 && carried.size() <= gods.size() - covered.size() + 1);
		for (GearItem item : carried) {
			assertTrue(owned.owns(item.getId()), "owned protection is preferred: " + item.getName());
		}
	}

	@Test
	@DisplayName("the card's set covers every route god between what it wears and what it carries")
	void serviceCoversTheRoute() throws Exception {
		MonsterStats kree = mob("kree'arra");
		OwnedItems owned = owned("magic shortbow", "rune arrow", "black d'hide body", "black d'hide chaps",
			"zamorak stole", "saradomin stole", "bandos stole", "armadyl stole", "honourable blessing");
		OptimizerService service = new OptimizerService(data);
		try {
			CountDownLatch done = new CountDownLatch(1);
			AtomicReference<Map<CombatStyle, OptimizerService.StyleResult>> out = new AtomicReference<>();
			ComputeParams p = new ComputeParams();
			p.maxSwaps = 6;
			p.gwdAncient = true;
			service.bestPerStyle(kree, PlayerLevels.MAXED, PlayerLevels.MAXED, PrayerUnlocks.ALL,
				RequirementProfile.MAXED, owned, 1, p, Collections.emptyMap(), Collections.emptySet(),
				Collections.emptyMap(), null, 0, Collections.<Integer>emptySet(), result -> {
					out.set(result);
					done.countDown();
				});
			assertTrue(done.await(300, TimeUnit.SECONDS));
			OptimizerService.StyleResult ranged = out.get().get(CombatStyle.RANGED);
			Set<String> all = new HashSet<>(GwdProtection.coveredGods(ranged.owned.get(0).getLoadout()));
			for (GearItem item : ranged.protection) {
				all.addAll(GwdProtection.godsOf(item));
				assertTrue(ranged.bench.contains(item), "carried protection rides the Inventory");
			}
			assertTrue(all.containsAll(GwdProtection.godsFor(kree, true)), "all four + Zaros: " + all);
		} finally {
			service.shutdown();
		}
	}
}

package com.loadoutlab.engine;

