/**
 * Hallowfell as the melee multi tool (ISS-01M5TPEWE9AQM3B55ZH02PHGE4, Andrew 2026-10-25: "can we also
 * consider hallowfell as a melee aoe option for multimob"). Wiki passive: up
 * to two more unique targets at half the max hit, rounded down, each its own
 * accuracy roll.
 */
class HallowfellMultiTest {
	@Test
	@DisplayName("the cleave factor: 1 alone, two extra targets at most, each at half the max hit rounded down")
	void factor() {
		assertEquals(1.0, MultiTool.factor("cleave", 1, 40), 1e-9);
		assertEquals(1.5, MultiTool.factor("cleave", 2, 40), 1e-9);
		assertEquals(2.0, MultiTool.factor("cleave", 3, 40), 1e-9);
		assertEquals(2.0, MultiTool.factor("cleave", 9, 40), 1e-9, "two extras cap");
		assertEquals(1 + 2 * 20 / 41.0, MultiTool.factor("cleave", 3, 41), 1e-9, "half of 41 rounds down to 20");
	}

	@Test
	@DisplayName("with the Multi card on at abyssal demons, owning Hallowfell, the hallowfell tool's Yours wears it")
	void toolWearsHallowfell() throws Exception {
		LoadoutData data = new DataService().load();
		MonsterStats demon = data.searchMonsters("abyssal demon", 1).get(0);
		ComputeParams p = new ComputeParams();
		p.multiView = true;
		OptimizerService service = new OptimizerService(data);
		try {
			CountDownLatch done = new CountDownLatch(1);
			AtomicReference<Map<CombatStyle, OptimizerService.StyleResult>> out = new AtomicReference<>();
			service.bestPerStyle(demon, PlayerLevels.MAXED, PlayerLevels.MAXED, PrayerUnlocks.ALL,
				RequirementProfile.MAXED, new OwnedItems(Map.of(MultiTool.HALLOWFELL_SWORD, 1), true), 1, p,
				Collections.emptyMap(), Collections.emptySet(), Collections.emptyMap(), null, 0,
				Collections.<Integer>emptySet(), result -> {
					out.set(result);
					done.countDown();
				});
			assertTrue(done.await(300, TimeUnit.SECONDS));
			OptimizerService.StyleResult tool = out.get().values().iterator().next().multiTools.get("hallowfell");
			assertNotNull(tool, "the hallowfell tool is on the Multi card");
			GearItem weapon = tool.owned.get(0).getLoadout().get(GearSlot.WEAPON);
			assertEquals(MultiTool.HALLOWFELL_SWORD, weapon.getId());
		} finally {
			service.shutdown();
		}
	}
}

package com.loadoutlab.engine;

import com.loadoutlab.data.MonsterStats;

/** Style-level immunity, independent of the weapon - a test probe of the
 * immunity data (it left main source in slim 5: nothing there asked it). */
public final class Immunity {
    private Immunity() {
    }

    public static boolean styleImmune(MonsterStats monster, CombatStyle style) {
        if (monster == null) return false;
        // Data-driven immunity (synthetic group variants - the tormented
        // demon shield phases): the attribute wins before the id lists.
        if (monster.hasAttribute(MonsterMechanics.IMMUNE_ATTR[style.ordinal()])) return true;
        switch (style) {
            case MAGIC: return MonsterMechanics.IMMUNE_MAGIC.contains(monster.getId());
            case RANGED: return MonsterMechanics.IMMUNE_RANGED.contains(monster.getId());
            case MELEE: return MonsterMechanics.IMMUNE_MELEE.contains(monster.getId()) && !MonsterMechanics.ZULRAH.contains(monster.getId());
            default: return false;
        }
    }
}

package com.loadoutlab.engine;

import com.loadoutlab.data.DataService;
import com.loadoutlab.data.GearSlot;
import com.loadoutlab.data.MonsterDefences;
import com.loadoutlab.data.MonsterOffence;
import com.loadoutlab.data.MonsterStats;
import java.util.EnumMap;
import java.util.List;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import static org.junit.jupiter.api.Assertions.*;

/**
 * The player's defence roll (ISS-01M5G5CZC9SK46499FACRSJ8ZT): level =
 * Defence + 8 + stance for melee/ranged (wiki DPS/Melee), and
 * floor(0.7 Magic) + floor(0.3 Defence) + 8 against magic - the
 * official calculator's NPCVsPlayerCalc. The old Defence + 9 sat the +9
 * inside the 30% and read magic damage taken 4-7% high.
 */
class IncomingDefenceRollTest {
	private static final Loadout NAKED = new Loadout(new EnumMap<>(GearSlot.class));

	@Test
	@DisplayName("matches the official calculator's own Abyssal demon vectors")
	void abyssalDemonVectors() {
		MonsterStats demon = new DataService().load().searchMonsters("abyssal demon", 1).get(0);
		// Roll (97+9)*64 = 6784 vs 576 at Defence 1 and 6848 at Defence 99
		// (osrs-dps-calc DamageTaken.test.ts: 1.596 and 0.825 dps).
		assertEquals(1.5957, IncomingDpsCalculator.calculate(demon, NAKED, 1, 1).unprayedDps, 0.0005);
		assertEquals(0.8254, IncomingDpsCalculator.calculate(demon, NAKED, 99, 1).unprayedDps, 0.0005);
	}

	@Test
	@DisplayName("magic defence is 70% Magic plus 30% Defence plus 8, each floored")
	void magicDefenceLevel() {
		// Magic 99, Defence 70: 69 + 21 + 8 = 98 -> roll 98 * 64 = 6272.
		MonsterStats mage = new MonsterStats(1, "Test mage", "", 300, 255, 1, 1, 200, 0,
			MonsterDefences.ZERO, new MonsterOffence(1, 1, 1, 200, 0, 0, 0, 0, 0, 0, 4,
				List.of("Magic")),
			java.util.Collections.emptyList(), false, "", 0);
		// Npc roll (200+9)*64 = 13376 > 6272: acc = 1 - 6274/(2*13377).
		double acc = 1 - 6274.0 / (2 * 13377.0);
		int max = (int) (((long) 209 * 64 + 320) / 640);
		double expected = acc * (max / 2.0) / 2.4;
		assertEquals(expected, IncomingDpsCalculator.calculate(mage, NAKED, 70, 99).unprayedDps, 1e-9);
	}
}

package com.loadoutlab.engine;

import com.loadoutlab.data.GearItem;
import com.loadoutlab.data.GearSlot;
import com.loadoutlab.data.MonsterDefences;
import com.loadoutlab.data.MonsterOffence;
import com.loadoutlab.data.MonsterStats;
import com.loadoutlab.data.StatBlock;
import java.util.Arrays;
import java.util.List;
import java.util.Map;
import org.junit.Assert;
import org.junit.Test;

public class IncomingDpsCalculatorTest {
	/** Graardor-shaped melee stats: atk 280 (+120), str 350 (+43), 6t. */
	private static MonsterOffence offence(List<String> styles) {
		return new MonsterOffence(280, 350, 350, 80,
			120, 43, 100, 40, 0, 0, 6, styles);
	}

	private static MonsterStats monster(List<String> styles) {
		return new MonsterStats(1, "Test Boss", "", 600, 255, 4, 250, 80, 0,
			MonsterDefences.ZERO, offence(styles),
			java.util.Collections.emptyList(), false, "", 0);
	}

	/** A single armour piece carrying the whole set's defensive block. */
	private static Loadout armour(int stab, int slash, int crush, int magic, int ranged) {
		GearItem body = new GearItem(1, "Test platebody", "", GearSlot.BODY, "", 0,
			false, true, true, true, 0,
			StatBlock.ZERO,
			new StatBlock(stab, slash, crush, magic, ranged, 0, 0, 0, 0),
			StatBlock.ZERO, null);
		return new Loadout(Map.of(GearSlot.BODY, body));
	}

	@Test
	public void singleStyleMonsterIsFullyBlockedByTheProtectionPrayer() {
		IncomingDpsCalculator.Result result = IncomingDpsCalculator.calculate(
			monster(List.of("Crush")), armour(200, 200, 200, 0, 150), 99, 99);
		Assert.assertEquals("Protect from Melee", result.protectPrayer);
		Assert.assertEquals(0.0, result.totalDps, 1e-9);
		Assert.assertTrue(result.unprayedDps > 0);
		Assert.assertTrue(result.fullyModeled);
		Assert.assertTrue(result.threats.get(0).blocked);
	}

	@Test
	public void hybridStylesProtectByDeliveryNotRoll() {
		// Wiki (Magical melee / Magical ranged pages): the accuracy roll
		// is vs magic defence, but the PRAYER follows the delivery - a
		// Pyrefiend's magical melee is blocked by Protect from MELEE
		// (field report 2026-08-08, grZ: "this is wrong should be melee
		// protect"), magical ranged by Protect from MISSILES.
		IncomingDpsCalculator.Result melee = IncomingDpsCalculator.calculate(
			monster(List.of("Magical melee")), armour(200, 200, 200, 0, 150), 99, 99);
		Assert.assertEquals("Protect from Melee", melee.protectPrayer);
		IncomingDpsCalculator.Result ranged = IncomingDpsCalculator.calculate(
			monster(List.of("Magical ranged")), armour(200, 200, 200, 0, 150), 99, 99);
		Assert.assertEquals("Protect from Missiles", ranged.protectPrayer);
		// The inverse hybrids: ranged magic (Kree'arra, Spinolyps) is a
		// CAST that rolls vs ranged defence - Protect from Magic blocks
		// it; ranged melee (dust devils) is melee-blocked.
		IncomingDpsCalculator.Result cast = IncomingDpsCalculator.calculate(
			monster(List.of("Ranged magic")), armour(200, 200, 200, 0, 150), 99, 99);
		Assert.assertEquals("Protect from Magic", cast.protectPrayer);
		IncomingDpsCalculator.Result swing = IncomingDpsCalculator.calculate(
			monster(List.of("Ranged melee")), armour(200, 200, 200, 0, 150), 99, 99);
		Assert.assertEquals("Protect from Melee", swing.protectPrayer);
	}

	@Test
	public void chipStyleContributesItsRotationShareWhilePrayingTheWorst() {
		// Hand-computed: crush roll 289*184=53176 vs def (99+8)*(200+64)=28248
		// -> acc 0.73438, max hit (359*107+320)/640=60, 6t
		// -> crush dps 0.73438*30/3.6 = 6.1198.
		// Ranged roll 359*164=58876 vs 107*214=22898 -> acc 0.80553,
		// max (359*104+320)/640=58 -> dps 0.80553*29/3.6 = 6.4890 (worst).
		// Protect Missiles; chip = crush share 6.1198/2 = 3.0599.
		IncomingDpsCalculator.Result result = IncomingDpsCalculator.calculate(
			monster(Arrays.asList("Crush", "Ranged")), armour(200, 200, 200, 0, 150), 99, 99);
		Assert.assertEquals("Protect from Missiles", result.protectPrayer);
		Assert.assertEquals(3.0599, result.totalDps, 0.0005);
		// Unprayed adds the blocked ranged share: 3.0599 + 6.4890/2 = 6.3044.
		Assert.assertEquals(6.3044, result.unprayedDps, 0.0005);
		Assert.assertEquals(60, result.threats.get(0).maxHit);
	}

	@Test
	public void aPreparedCalculatorMatchesTheFullCalculationExactly() {
		// The defense-weighted beam scores thousands of candidate sets per
		// optimize; prepare() hoists the monster-side constants and must
		// reproduce calculate() bit-for-bit on both model paths.
		MonsterStats sheet = monster(Arrays.asList("Crush", "Ranged", "Magic", "Dragonfire"));
		Loadout[] armours = {
			armour(0, 0, 0, 0, 0),
			armour(200, 180, 210, 40, 150),
			armour(-20, 300, 5, 120, 60),
		};
		IncomingDpsCalculator.Prepared prepared = new IncomingDpsCalculator.Prepared(sheet, BossIncomingOverrides.overridesFor(sheet), 82, 91);
		for (Loadout loadout : armours) {
			IncomingDpsCalculator.Result full = IncomingDpsCalculator.calculate(sheet, loadout, 82, 91);
			Assert.assertEquals(full.totalDps, prepared.totalDps(loadout), 0.0);
		}
	}

	@Test
	public void aPreparedCalculatorMatchesOnCuratedOverrideBosses() {
		com.loadoutlab.data.LoadoutData data = new com.loadoutlab.data.DataService().load();
		for (String name : new String[]{"Callisto", "Zulrah", "Corporeal Beast"}) {
			MonsterStats boss = data.searchMonsters(name, 1).get(0);
			IncomingDpsCalculator.Prepared prepared = new IncomingDpsCalculator.Prepared(boss, BossIncomingOverrides.overridesFor(boss), 85, 89);
			for (Loadout loadout : new Loadout[]{
				armour(0, 0, 0, 0, 0), armour(220, 240, 230, 80, 200)}) {
				IncomingDpsCalculator.Result full = IncomingDpsCalculator.calculate(boss, loadout, 85, 89);
				Assert.assertEquals(full.totalDps, prepared.totalDps(loadout), 0.0);
			}
		}
	}

	@Test
	public void aPreparedCalculatorMatchesAcrossTheWholeCorpus() {
		// Layer 1 (ISS-01M5FZ3KYCGEMMX1A45D3J9NQ9) changed the sheet model's
		// max hits, styles, speeds and shares - the beam's scorer must still
		// agree with the display path on every monster we ship.
		com.loadoutlab.data.LoadoutData data = new com.loadoutlab.data.DataService().load();
		Loadout[] armours = {armour(0, 0, 0, 0, 0), armour(220, 240, 230, 80, 200)};
		for (MonsterStats mob : data.getMonsters()) {
			IncomingDpsCalculator.Prepared prepared = new IncomingDpsCalculator.Prepared(mob, BossIncomingOverrides.overridesFor(mob), 85, 89);
			for (Loadout loadout : armours) {
				IncomingDpsCalculator.Result full = IncomingDpsCalculator.calculate(mob, loadout, 85, 89);
				Assert.assertEquals(mob.getName() + " " + mob.getVersion(),
					full.totalDps, prepared.totalDps(loadout), 0.0);
			}
		}
	}

	@Test
	public void betterArmourMeansLessIncomingDps() {
		double tank = IncomingDpsCalculator.calculate(
			monster(Arrays.asList("Crush", "Ranged")), armour(300, 300, 300, 0, 300), 99, 99).totalDps;
		double naked = IncomingDpsCalculator.calculate(
			monster(Arrays.asList("Crush", "Ranged")), armour(0, 0, 0, 0, 0), 99, 99).totalDps;
		Assert.assertTrue(tank + " < " + naked, tank < naked);
	}

	@Test
	public void magicDefenceUsesMagicLevelAndMagicDefBonus() {
		MonsterStats mage = monster(List.of("Magic", "Ranged"));
		double lowMagic = IncomingDpsCalculator.calculate(mage, armour(0, 0, 0, 0, 0), 99, 1).totalDps;
		double highMagic = IncomingDpsCalculator.calculate(mage, armour(0, 0, 0, 0, 0), 99, 99).totalDps;
		Assert.assertTrue(highMagic <= lowMagic);
		double magicArmour = IncomingDpsCalculator.calculate(mage, armour(0, 0, 0, 120, 0), 99, 99).totalDps;
		Assert.assertTrue(magicArmour < highMagic);
	}

	@Test
	public void unmodeledStylesAreSurfacedNotSilentlyDropped() {
		IncomingDpsCalculator.Result result = IncomingDpsCalculator.calculate(
			monster(Arrays.asList("Typeless")), armour(200, 200, 200, 0, 150), 99, 99);
		Assert.assertFalse(result.fullyModeled);
		Assert.assertNull(result.protectPrayer);
		Assert.assertEquals(0.0, result.totalDps, 1e-9);
		Assert.assertFalse(result.threats.get(0).modeled);
	}

	@Test
	public void genericMeleeAssumesTheWeakestDefensiveSide() {
		// Generic "Melee" must use min(stab, slash, crush) = 50 here,
		// so it hits harder than a typed Crush attack against crush 300.
		double generic = IncomingDpsCalculator.calculate(
			monster(List.of("Melee", "Ranged")), armour(50, 300, 300, 0, 0), 99, 99).totalDps;
		double typed = IncomingDpsCalculator.calculate(
			monster(List.of("Crush", "Ranged")), armour(50, 300, 300, 0, 0), 99, 99).totalDps;
		Assert.assertTrue(generic >= typed);
	}
}

package com.loadoutlab.engine;

import com.loadoutlab.data.DataService;
import com.loadoutlab.data.GearItem;
import com.loadoutlab.data.GearSlot;
import com.loadoutlab.data.LoadoutData;
import com.loadoutlab.data.MonsterStats;
import com.loadoutlab.data.StatBlock;
import java.util.Map;
import org.junit.jupiter.api.BeforeAll;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import static org.junit.jupiter.api.Assertions.*;

/**
 * Layer 1 of the defensive rebuild (F-01M5FY64VERY7X0PG7S1A5J373): the
 * stat-sheet model reads the wiki's listed max hits, understands the
 * corpus's messy style strings, refuses to guess an unknown attack
 * speed, never dilutes a real attack with an unmodeled one, and says how
 * much of the monster it actually covers.
 */
class IncomingHygieneTest {
	private static LoadoutData data;

	@BeforeAll
	static void load() {
		data = new DataService().load();
	}

	private static MonsterStats mob(String name, String version) {
		return data.getMonsters().stream()
			.filter(m -> m.getName().equals(name) && (version == null || m.getVersion().equals(version)))
			.findFirst().orElseThrow(() -> new AssertionError("corpus is missing " + name + " " + version
				+ "; has " + data.getMonsters().stream().filter(m -> m.getName().equals(name))
					.map(MonsterStats::getVersion).collect(java.util.stream.Collectors.toList())));
	}

	private static Loadout armour(int each) {
		GearItem body = new GearItem(1, "Test platebody", "", GearSlot.BODY, "", 0,
			false, true, true, true, 0, StatBlock.ZERO,
			new StatBlock(each, each, each, each, each, 0, 0, 0, 0), StatBlock.ZERO, null);
		return new Loadout(Map.of(GearSlot.BODY, body));
	}

	private static IncomingDpsCalculator.Result hit(MonsterStats mob) {
		return IncomingDpsCalculator.calculate(mob, armour(100), 90, 90);
	}

	@Test
	@DisplayName("the wiki's listed max hit beats the stat formula")
	void listedMaxHitWins() {
		assertEquals(8, hit(mob("Aberrant spectre", null)).threats.get(0).maxHit,
			"magic max from the infobox, not the formula's 11");
		assertEquals(37, hit(mob("Vardorvis", "QUEST")).threats.get(0).maxHit,
			"30-37 (Melee) is 37, not the str-0 formula's 1");
		// "22 (Magic)" with Crush + Magic: the label feeds the magic attack
		// only; the unlabelled crush keeps the formula.
		IncomingDpsCalculator.Result druid = hit(mob("Undead Druid", null));
		IncomingDpsCalculator.StyleThreat magic = druid.threats.stream()
			.filter(t -> t.style.equals("Magic")).findFirst().orElseThrow(AssertionError::new);
		assertEquals(22, magic.maxHit);
	}

	@Test
	@DisplayName("Typeless slash rolls slash accuracy and no prayer blocks it")
	void typelessIsUnblockable() {
		IncomingDpsCalculator.Result moon = hit(mob("Blue Moon", null));
		assertEquals("full", moon.coverage);
		assertTrue(moon.totalDps > 0, "the moons hit you through any prayer");
		assertNull(moon.protectPrayer);
		assertEquals(32, moon.threats.get(0).maxHit);
		assertEquals(moon.unprayedDps, moon.totalDps, 1e-12);
	}

	@Test
	@DisplayName("stray control characters and parenthesised types are cleaned")
	void messyStylesAreModeled() {
		IncomingDpsCalculator.Result araxxor = hit(mob("Araxxor", null));
		assertEquals("full", araxxor.coverage, "\\x7f\\x7f Magic is magic");
		assertEquals(3, araxxor.threats.size());
		assertEquals("full", hit(mob("Dusk", "First form")).coverage, "Slash \\x7f\\x7f is slash");
		assertEquals("full", hit(mob("Yama", "Normal")).coverage, "Melee (Slash) is slash");
	}

	@Test
	@DisplayName("an unknown attack speed is unmodeled, never one tick")
	void unknownSpeedIsUnmodeled() {
		// Skotizo: Stab + Magic on the sheet, speed "Random" (0). The Leviathan
		// used to sit here until its curated entry priced it (ISS-01M5PBSZBBBAS9Y46X04MVMHZB).
		IncomingDpsCalculator.Result skotizo = hit(mob("Skotizo", ""));
		assertEquals("none", skotizo.coverage);
		assertEquals(0.0, skotizo.unprayedDps, 0.0);
	}

	@Test
	@DisplayName("an unmodeled style takes no share - the real attack keeps the cadence")
	void noDilution() {
		IncomingDpsCalculator.Result dragon = hit(mob("Blue dragon", "1"));
		assertEquals("partial", dragon.coverage);
		assertTrue(dragon.unmodeled.contains("Dragonfire"), dragon.unmodeled.toString());
		IncomingDpsCalculator.StyleThreat slash = dragon.threats.stream()
			.filter(t -> t.modeled).findFirst().orElseThrow(AssertionError::new);
		assertEquals(1.0, slash.share, 0.0);
	}

	@Test
	@DisplayName("a monster that does not attack is fully modeled at zero")
	void nonAttackerIsZero() {
		IncomingDpsCalculator.Result flower = hit(mob("Flower", null));
		assertEquals("full", flower.coverage);
		assertEquals(0.0, flower.unprayedDps, 0.0);
	}

	@Test
	@DisplayName("curated bosses report curated coverage")
	void curatedCoverage() {
		assertEquals("curated", hit(data.searchMonsters("general graardor", 1).get(0)).coverage);
	}
}

package com.loadoutlab.engine;

import com.loadoutlab.data.DataService;
import com.loadoutlab.data.GearItem;
import com.loadoutlab.data.GearSlot;
import com.loadoutlab.data.LoadoutData;
import com.loadoutlab.data.MonsterGroups;
import com.loadoutlab.data.MonsterStats;
import java.util.EnumMap;
import java.util.List;
import org.junit.jupiter.api.BeforeAll;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import static org.junit.jupiter.api.Assertions.*;

/**
 * KQ's phase immunity is a protection PRAYER, and Verac's set pierces it
 * (wiki: 25% guaranteed hit, +1 damage, "includes monsters that make use
 * of protection prayers"). Field report 2026-08-06: pinning full Verac's
 * rendered "No usable owned set found" because the synthetic phase
 * encoded the prayer as absolute immunity - the classic full-Verac's KQ
 * kill was impossible in the model.
 */
class KalphiteVeracTest {
	private static LoadoutData data;
	private static MonsterStats airborne;

	@BeforeAll
	static void load() {
		data = new DataService().load();
		airborne = MonsterGroups.load(data).stream()
			.filter(g -> "Kalphite Queen".equals(g.getName()))
			.flatMap(g -> g.getMobs().stream())
			.filter(m -> m.getVersion().contains("no mel")
				|| m.hasAttribute("immune_melee"))
			.findFirst().orElseThrow();
		assertTrue(airborne.hasAttribute("prayer_immunity"),
			"test premise: the airborne form's immunity is prayer-based");
	}

	private static Loadout verac(boolean full) {
		EnumMap<GearSlot, GearItem> gear = new EnumMap<>(GearSlot.class);
		for (GearItem g : data.getGearItems()) {
			String n = g.getNameLower();
			if (!g.isStandardGear()) {
				continue;
			}
			if (n.startsWith("verac's flail")) {
				gear.put(GearSlot.WEAPON, g);
			}
			if (full && n.startsWith("verac's helm")) {
				gear.put(GearSlot.HEAD, g);
			}
			if (full && n.startsWith("verac's brassard")) {
				gear.put(GearSlot.BODY, g);
			}
			if (full && n.startsWith("verac's plateskirt")) {
				gear.put(GearSlot.LEGS, g);
			}
		}
		return new Loadout(gear);
	}

	private static OptimizationRequest req() {
		return TestRequests.of(airborne, CombatStyle.MELEE,
			PlayerLevels.MAXED, PrayerBonuses.bestAvailable(PlayerLevels.MAXED),
			null, 0, CandidateMode.ALL_STANDARD, true, false, OwnedItems.EMPTY, 1);
	}

	@Test
	@DisplayName("full Verac's pierces the airborne prayer at exactly the proc rate")
	void fullSetPierces() {
		DpsResult r = new DpsCalculator().calculate(req(), verac(true));
		assertNotNull(r, "the flail must gate melee entry through the prayer");
		assertTrue(r.getDps() > 0, "the classic full-Verac's kill must be possible");
		assertEquals(0.25, r.getAccuracy(), 1e-9, "only the proc lands");
		assertEquals(0.25 * RollMath.normalExpectedHit(1.0, r.getMaxHit()),
			r.getExpectedHit(), 0.05, "expectation is the proc quarter, +1 damage");
	}

	@Test
	@DisplayName("the flail without the set lands nothing - but stays a zero, not a null")
	void partialSetIsZeroNotNull() {
		DpsResult r = new DpsCalculator().calculate(req(), verac(false));
		assertNotNull(r, "partial Verac states must survive for the beam to finish the set");
		assertEquals(0.0, r.getDps(), 1e-9);
	}

	@Test
	@DisplayName("a whip is still simply immune")
	void whipStaysImmune() {
		EnumMap<GearSlot, GearItem> gear = new EnumMap<>(GearSlot.class);
		for (GearItem g : data.getGearItems()) {
			if (g.getNameLower().equals("abyssal whip")) {
				gear.put(GearSlot.WEAPON, g);
			}
		}
		assertNull(new DpsCalculator().calculate(req(), new Loadout(gear)));
	}

	@Test
	@DisplayName("the optimizer assembles the set on its own when the pieces are owned")
	void optimizerAssemblesTheSet() {
