	@Test
	public void dpsNeutralSlotsFillWithPrayerGearWithoutChangingDps() {
		LoadoutData data = new DataService().load();
		MonsterStats monster = data.searchMonsters("goblin", 1).get(0);
		GearItem blessing = data.getGearItems().stream()
			.filter(g -> g.getName().equalsIgnoreCase("Holy blessing"))
			.findFirst().orElseThrow(AssertionError::new);
		Map<Integer, Integer> owned = new HashMap<>();
		owned.put(4151, 1);            // whip - the DPS pick
		owned.put(blessing.getId(), 1); // +1 prayer, zero offence
		OptimizationRequest request = new OptimizationRequest(
			monster,
			CombatStyle.MELEE,
			PlayerLevels.MAXED,
			PrayerBonuses.bestAvailable(PlayerLevels.MAXED),
			null,
			0,
			CandidateMode.OWNED_ONLY,
			true,
			false,
			new OwnedItems(owned, true),
			RequirementProfile.MAXED,
			3);

		LoadoutOptimizer optimizer = new LoadoutOptimizer();
		List<DpsResult> results = optimizer.optimize(data, request);
		Assert.assertFalse(results.isEmpty());
		DpsResult bare = results.get(0);
		// The results-level utility tie-break may seat the blessing straight
		// from the main search (same DPS, +1 prayer beats an empty slot);
		// the fill pass guarantees it either way, at unchanged DPS.
		DpsResult filled = optimizer.fillDpsNeutralSlots(data, request, bare);
		Assert.assertEquals(blessing.getId(), filled.getLoadout().get(GearSlot.AMMO).getId());
		Assert.assertEquals(bare.getDps(), filled.getDps(), 1e-9);
	}

	private static RequirementProfile requirements(int level, Set<String> quests) {
		EnumMap<Skill, Integer> levels = new EnumMap<>(Skill.class);
		for (Skill skill : Skill.values()) {
			if (skill != Skill.OVERALL) {
				levels.put(skill, level);
			}
		}
		return new RequirementProfile(levels, quests);
	}
}

package com.loadoutlab.engine;

import com.loadoutlab.data.GearItem;

/**
 * Loadout queries only the test suite asks for. Kept out of main source so
 * they do not count against the Plugin Hub bot's 200k token budget; the
 * logic is the production version verbatim, over the public
 * {@link Loadout#getGear()} view.
 */
public final class LoadoutTestSupport {
	private LoadoutTestSupport() {
	}

	/** Items in this set you would risk in PvP (tradeables). */
	public static int tradeableCount(Loadout loadout) {
		int count = 0;
		for (GearItem item : loadout.getGear().values()) {
			if (item != null && item.isTradeable()) {
				count++;
			}
		}
		return count;
	}
}

package com.loadoutlab.engine;

import com.loadoutlab.data.DataService;
import com.loadoutlab.data.LoadoutData;
import com.loadoutlab.data.MonsterGroups;
import com.loadoutlab.data.MonsterStats;
import org.junit.Assert;
import org.junit.Test;

/**
 * Maggot King phase model (field report grZ 2026-08-20: "checking
 * maggot king far, it does recommend melee, which is impossible";
 * wiki-verified: "it cannot be attacked with melee until it falls
 * below ~980 hitpoints (65%)" - the Far phase IS the out-of-reach
 * state, he closes in for the Nearby/Roaring rows). Royal Titans
 * pattern: the Far row is melee-immune, the group rosters all three
 * corpus versions so the fight reads as one result.
 */
public class MaggotKingTest {
	private static LoadoutData data;

	private static LoadoutData data() {
		if (data == null) {
			data = new DataService().load();
		}
		return data;
	}

	private static MonsterStats version(String version) {
		for (MonsterStats monster : data().getMonsters()) {
			if ("Maggot King".equalsIgnoreCase(monster.getName())
				&& version.equalsIgnoreCase(monster.getVersion())) {
				return monster;
			}
		}
		throw new AssertionError("no Maggot King (" + version + ") row");
	}

	@Test
	public void theFarPhaseIsMeleeImmuneTheOthersAreNot() {
		MonsterStats far = version("Far");
		Assert.assertTrue("Far is out of melee reach",
			com.loadoutlab.engine.Immunity.styleImmune(far, CombatStyle.MELEE));
		Assert.assertFalse(com.loadoutlab.engine.Immunity.styleImmune(far, CombatStyle.RANGED));
		Assert.assertFalse(com.loadoutlab.engine.Immunity.styleImmune(far, CombatStyle.MAGIC));
		Assert.assertFalse("he closes in - Nearby takes melee",
			com.loadoutlab.engine.Immunity.styleImmune(version("Nearby"), CombatStyle.MELEE));
		Assert.assertFalse("the punish window takes melee",
			com.loadoutlab.engine.Immunity.styleImmune(version("Roaring"), CombatStyle.MELEE));
	}

	/** The version cache-collision (field report 2026-08-20, grZ + Andrew):
	 * all three MK versions share id 15742 with IDENTICAL melee stats, and
	 * both optimizer cache keys carried only getId() - so whichever version
	 * computed first served its answer to the siblings. Nearby-then-Far on
	 * ONE service is the deterministic poisoning: Far's melee must still
	 * come back empty (it is immune), not Nearby's cached 5.92. */
	@Test
	public void aWarmSiblingCacheNeverLendsFarAMeleeSet() throws Exception {
		com.loadoutlab.optimizer.OptimizerService service =
			new com.loadoutlab.optimizer.OptimizerService(data());
		try {
			Assert.assertNotNull("Nearby answers melee",
				singleStyles(service, version("Nearby"))
					.get(CombatStyle.MELEE).overallBest);
			com.loadoutlab.optimizer.OptimizerService.StyleResult far =
				singleStyles(service, version("Far")).get(CombatStyle.MELEE);
			Assert.assertTrue("Far melee owned must stay empty on a warm cache",
				far == null || far.owned == null || far.owned.isEmpty());
			Assert.assertTrue("Far melee BiS must stay empty on a warm cache",
				far == null || far.overallBest == null);
		} finally {
			service.shutdown();
		}
	}

	private static java.util.Map<CombatStyle, com.loadoutlab.optimizer.OptimizerService.StyleResult>
		singleStyles(com.loadoutlab.optimizer.OptimizerService service, MonsterStats mob)
		throws Exception {
		java.util.concurrent.CountDownLatch done = new java.util.concurrent.CountDownLatch(1);
		java.util.concurrent.atomic.AtomicReference<java.util.Map<CombatStyle,
			com.loadoutlab.optimizer.OptimizerService.StyleResult>> out =
			new java.util.concurrent.atomic.AtomicReference<>();
		com.loadoutlab.optimizer.ServiceCalls.bestPerStyle(service, mob,
			PlayerLevels.MAXED, PlayerLevels.MAXED, PrayerUnlocks.ALL,
			RequirementProfile.MAXED, OwnedItems.EMPTY, 0,
			false, false, "", new java.util.EnumMap<>(CombatStyle.class), -1,
			com.loadoutlab.engine.OptimizationRequest.DEFAULT_RISK_BUDGET_GP, false, false,
			java.util.Collections.emptySet(), 0,
			java.util.Collections.emptyMap(), null, 0, java.util.Collections.emptySet(),
			r -> {
				out.set(r);
				done.countDown();
			});
		Assert.assertTrue(done.await(300, java.util.concurrent.TimeUnit.SECONDS));
		return out.get();
	}

	@Test
	public void theGroupRostersAllThreePhases() {
		for (MonsterGroups.MonsterGroup group : MonsterGroups.load(data())) {
			if ("Maggot King".equals(group.getName())) {
				Assert.assertEquals(3, group.getMobs().size());
				long meleeImmune = group.getMobs().stream()
					.filter(m -> com.loadoutlab.engine.Immunity.styleImmune(m, CombatStyle.MELEE))
					.count();
				Assert.assertEquals("exactly the Far phase is out of reach",
					1, meleeImmune);
				return;
			}
		}
		throw new AssertionError("Maggot King group missing");
	}
}

package com.loadoutlab.engine;

import com.loadoutlab.data.DataService;
import com.loadoutlab.data.GearItem;
import com.loadoutlab.data.GearSlot;
import com.loadoutlab.data.LoadoutData;
import com.loadoutlab.data.MonsterStats;
import com.loadoutlab.data.SpellStats;
import java.util.EnumMap;
import org.junit.jupiter.api.BeforeAll;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import static org.junit.jupiter.api.Assertions.*;

/**
 * The eclipse atlatl's melee-side damage scaling and the Eclipse /
 * Frostweaver set effects, wiki-verified 2026-07-17. The atlatl base
 * model mirrors the official calc (strength level + worn melee strength
 * bonuses, ranged accuracy untouched); the two set effects go BEYOND the
 * official calc, which flags both sets unsupported - the wiki quantifies
 * them, so we model the expectation and say so in the chips.
 */
class MoonWeaponsTest {
	private static LoadoutData data;
	private static MonsterStats ankou;

	@BeforeAll
	static void load() {
		data = new DataService().load();
		ankou = data.searchMonsters("ankou", 1).get(0);
	}

	private static GearItem byNameVersion(String nameLower, String version) {
		for (GearItem item : data.getGearItems()) {
			if (item.getNameLower().equals(nameLower)
				&& (version == null || version.equalsIgnoreCase(item.getVersion()))) {
				return item;
			}
		}
		throw new AssertionError("corpus is missing: " + nameLower + " " + version);
	}

	private static SpellStats spell(String name) {
		return data.getSpells().stream()
			.filter(s -> s.getName().equalsIgnoreCase(name))
			.findFirst().orElseThrow(() -> new AssertionError("no spell " + name));
	}

	private static OptimizationRequest request(CombatStyle style, MonsterStats monster) {
		return new OptimizationRequest(monster, style, PlayerLevels.MAXED,
			PrayerBonuses.NONE, null, 0,
			CandidateMode.ALL_STANDARD, true, false,
			OwnedItems.EMPTY, RequirementProfile.MAXED, 1);
	}

	private static EnumMap<GearSlot, GearItem> atlatlGear(boolean fullSet) {
		EnumMap<GearSlot, GearItem> gear = new EnumMap<>(GearSlot.class);
		gear.put(GearSlot.WEAPON, byNameVersion("eclipse atlatl", null));
		gear.put(GearSlot.AMMO, byNameVersion("atlatl dart", null));
		if (fullSet) {
			gear.put(GearSlot.HEAD, byNameVersion("eclipse moon helm", "New"));
			gear.put(GearSlot.BODY, byNameVersion("eclipse moon chestplate", "New"));
			gear.put(GearSlot.LEGS, byNameVersion("eclipse moon tassets", "New"));
		}
		return gear;
	}

	@Test
	@DisplayName("the atlatl's max hit comes from Strength level and worn MELEE strength bonuses")
	void atlatlScalesWithStrength() {
		Loadout loadout = new Loadout(atlatlGear(false));
		DpsResult result = new DpsCalculator().calculate(request(CombatStyle.RANGED, ankou), loadout);
		// Rapid (stance 0), no prayer: effective 99+8, strength term is the
		// worn melee str total (the atlatl's own +40) - NOT ranged strength,
		// which is 0 on both the weapon and the darts.
		int effective = RollMath.effectiveLevel(PlayerLevels.MAXED.getStrength(), 1.0, 0);
		assertEquals(RollMath.maxHitFromEffective(effective, loadout.getBonuses().getStrength()),
			result.getMaxHit());
		// The old ranged-strength model derived a near-zero max hit.
		assertTrue(result.getMaxHit() >= 10);
	}

	@Test
	@DisplayName("Eclipse: the full set adds ~2 burn damage per landed hit against a burnable monster")
	void eclipseBurnExpectation() {
		DpsResult set = new DpsCalculator().calculate(
			request(CombatStyle.RANGED, ankou), new Loadout(atlatlGear(true)));
		// The burn rides expected damage on top of the plain roll: recover
		// the bonus from the result's own accuracy and max hit.
		double base = RollMath.normalExpectedHit(set.getAccuracy(), set.getMaxHit());
		assertEquals(set.getAccuracy() * 2.0, set.getExpectedHit() - base, 1e-9);
		assertTrue(set.getCountedBonuses().stream()
			.anyMatch(line -> line.toLowerCase().contains("eclipse set")));
	}

	@Test
	@DisplayName("Eclipse: burn-immune monsters take no burn and show no chip")
	void eclipseBurnRespectsImmunity() {
		MonsterStats immune = data.getMonsters().stream()
			.filter(m -> m.hasAttribute("burn_immune"))
			.findFirst().orElseThrow(() -> new AssertionError("corpus premise: some monster is burn-immune"));
		DpsResult set = new DpsCalculator().calculate(
			request(CombatStyle.RANGED, immune), new Loadout(atlatlGear(true)));
		double base = RollMath.normalExpectedHit(set.getAccuracy(), set.getMaxHit());
		assertEquals(0.0, set.getExpectedHit() - base, 1e-9);
		assertTrue(set.getCountedBonuses().stream()
			.noneMatch(line -> line.toLowerCase().contains("eclipse set")));
	}

	private DpsResult castWithBlueMoon(SpellStats spell) {
		EnumMap<GearSlot, GearItem> gear = new EnumMap<>(GearSlot.class);
		gear.put(GearSlot.WEAPON, byNameVersion("blue moon spear", null));
		gear.put(GearSlot.HEAD, byNameVersion("blue moon helm", "New"));
		gear.put(GearSlot.BODY, byNameVersion("blue moon chestplate", "New"));
		gear.put(GearSlot.LEGS, byNameVersion("blue moon tassets", "New"));
		return new DpsCalculator().calculate(
			request(CombatStyle.MAGIC, ankou).withSpell(spell), new Loadout(gear));
	}

	private static double bonus(DpsResult result) {
		return result.getExpectedHit()
			- RollMath.normalExpectedHit(result.getAccuracy(), result.getMaxHit());
	}

	@Test
	@DisplayName("Frostweaver: grasps proc at 50% and ice spells at 20% - the bonus ratio is exactly 2.5")
	void frostweaverChancesBydSpellClass() {
		DpsResult grasp = castWithBlueMoon(spell("Undead Grasp"));
		DpsResult ice = castWithBlueMoon(spell("Ice Barrage"));
		assertTrue(bonus(grasp) > 0, "grasp cast should carry a spear-hit expectation");
		assertTrue(bonus(ice) > 0, "ice cast should carry a spear-hit expectation");
		// Same monster, same spear - the melee expectation cancels, leaving
		// the 0.5 / 0.2 chance ratio.
		assertEquals(2.5, bonus(grasp) / bonus(ice), 1e-9);
		assertTrue(grasp.getCountedBonuses().stream()
			.anyMatch(line -> line.toLowerCase().contains("frostweaver")));
	}

	@Test
	@DisplayName("Frostweaver: non-binding spells get nothing")
	void frostweaverIgnoresPlainSpells() {
		DpsResult surge = castWithBlueMoon(spell("Fire Surge"));
		assertEquals(0.0, bonus(surge), 1e-9);
		assertTrue(surge.getCountedBonuses().stream()
			.noneMatch(line -> line.toLowerCase().contains("frostweaver")));
	}
}

package com.loadoutlab.engine;

import com.loadoutlab.data.DataService;
import com.loadoutlab.data.GearItem;
import com.loadoutlab.data.GearSlot;
import com.loadoutlab.data.LoadoutData;
import com.loadoutlab.data.MonsterStats;
import java.util.EnumMap;
import java.util.HashMap;
import java.util.Map;
import org.junit.Assert;
import org.junit.Test;

/**
 * Andrew, Copy report 2026-10-20 (the Fractured Archive): "why is it
 * simming mythical cape over fire cape". The Mythical cape's +6 crush
 * beat the fire cape's +3 strength by ~0.1% with the Obligator - a real
 * but meaningless gap. Andrew: near-ties should prefer prayer and defence.
 * The dps-neutral polish now accepts a higher-utility swap while the set
 * stays within 0.5% of its original dps (the budget is the whole set's,
 * so swaps cannot stack past it).
 */
public class NearTieTest {
	private static GearItem item(LoadoutData data, String name, String version) {
		return data.getGearItems().stream().filter(g -> g.getName().equalsIgnoreCase(name)
			&& (version == null || version.equals(g.getVersion())) && g.isStandardGear())
			.findFirst().orElseThrow(() -> new AssertionError(name));
	}

	@Test
	public void theFireCapeWinsAWithinHalfAPercentTieOnPrayerAndDefence() {
		LoadoutData data = new DataService().load();
		MonsterStats ezekiel = data.searchMonsters("ezekiel", 1).get(0);
		EnumMap<GearSlot, GearItem> worn = new EnumMap<>(GearSlot.class);
		worn.put(GearSlot.HEAD, item(data, "Neitiznot faceguard", null));
		worn.put(GearSlot.CAPE, item(data, "Mythical cape", null));
		worn.put(GearSlot.NECK, item(data, "Amulet of torture", null));
		worn.put(GearSlot.WEAPON, data.getGear(34715));
		worn.put(GearSlot.BODY, item(data, "Bandos chestplate", null));
		worn.put(GearSlot.LEGS, item(data, "Blood moon tassets", "New"));
		worn.put(GearSlot.HANDS, item(data, "Ferocious gloves", null));
		worn.put(GearSlot.FEET, item(data, "Primordial boots", null));
		worn.put(GearSlot.RING, item(data, "Berserker ring (i)", null));
		Map<Integer, Integer> owned = new HashMap<>();
		for (GearItem g : worn.values()) {
			owned.put(g.getId(), 1);
		}
		owned.put(item(data, "Fire cape", "Normal").getId(), 1);
		// The report's assumptions: Piety (no Zeal) + Divine super combat.
		PlayerLevels boosted = PlayerLevels.MAXED.boosted(BoostProfile.DIVINE_SUPER_COMBAT, PlayerLevels.MAXED);
		OptimizationRequest request = TestRequests.of(ezekiel, CombatStyle.MELEE, boosted,
			PrayerBonuses.bestAvailable(boosted, new PrayerUnlocks(true, false, false, true, false)), null, 0,
			CandidateMode.OWNED_ONLY, true, false, new OwnedItems(owned, true), 1);
		LoadoutOptimizer optimizer = new LoadoutOptimizer();
		// Everything is owned: the search hands the polish a set that cost
		// nothing to buy (the raw calculator prices every piece).
		DpsResult start = new DpsCalculator().calculate(request, new Loadout(worn)).withPurchaseCost(0);
		DpsResult polished = optimizer.fillDpsNeutralSlots(data, request, start);
		Assert.assertEquals("Fire cape", polished.getLoadout().get(GearSlot.CAPE).getName());
		Assert.assertTrue("a real, small loss: " + polished.getDps() + " vs " + start.getDps(),
			polished.getDps() < start.getDps() && polished.getDps() >= start.getDps() * 0.995);
	}

	@Test
	public void thePolishNeverCostsMoreThanHalfAPercentInTotal() {
		LoadoutData data = new DataService().load();
		for (String q : new String[]{"ezekiel", "vorkath", "general graardor", "zulrah"}) {
			MonsterStats mob = data.searchMonsters(q, 1).get(0);
			for (CombatStyle style : new CombatStyle[]{CombatStyle.MELEE, CombatStyle.RANGED, CombatStyle.MAGIC}) {
				OptimizationRequest request = TestRequests.of(mob, style, PlayerLevels.MAXED,
					PrayerBonuses.bestAvailable(PlayerLevels.MAXED), null, 0, CandidateMode.ALL_STANDARD, true, false,
					OwnedItems.EMPTY, 1);
				LoadoutOptimizer optimizer = new LoadoutOptimizer();
				java.util.List<DpsResult> best = optimizer.optimize(data, request);
				if (best.isEmpty()) {
					continue;
				}
				DpsResult polished = optimizer.fillDpsNeutralSlots(data, request, best.get(0));
				Assert.assertTrue(q + " " + style, polished.getDps() >= best.get(0).getDps() * 0.995 - 1e-9);
			}
		}
	}
}

package com.loadoutlab.engine;

import com.loadoutlab.data.DataService;
import com.loadoutlab.data.LoadoutData;
import com.loadoutlab.data.MonsterStats;
import java.util.List;
import org.junit.jupiter.api.BeforeAll;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import static org.junit.jupiter.api.Assertions.*;

/**
 * The nibblers' role is being barraged: three per wave, one AoE cast
 * clears the set. The magic answer is LOCKED to Ice/Blood Barrage, and
 * the trio multiplier (3x - one cast hits all three) is what makes the
 * barrage win the row on honest math instead of a blowpipe headlining
 * (field decision 2026-08-06).
 */
class NibblerBarrageTest {
	private static LoadoutData data;
	private static MonsterStats nibbler;

	@BeforeAll
	static void load() {
		data = new DataService().load();
		nibbler = data.searchMonsters("jal-nib", 1).get(0);
		assertEquals(7691, nibbler.getId());
	}

	private static OptimizationRequest req(CombatStyle style) {
		return TestRequests.of(nibbler, style, PlayerLevels.MAXED,
			PrayerBonuses.bestAvailable(PlayerLevels.MAXED), null, 0,
			CandidateMode.ALL_STANDARD, true, false, OwnedItems.EMPTY, 1);
	}

	@Test
	@DisplayName("the magic autocast is locked to the barrages")
	void magicLockedToBarrages() {
		List<DpsResult> out = new LoadoutOptimizer().optimize(data, req(CombatStyle.MAGIC));
		assertFalse(out.isEmpty());
		String spell = out.get(0).getSpellName();
		assertNotNull(spell);
		assertTrue("Ice Barrage".equals(spell) || "Blood Barrage".equals(spell),
			"nibblers are a barrage target, picked: " + spell);
	}

	@Test
	@DisplayName("the trio multiplier makes the barrage the row's best answer")
	void barrageWinsTheRow() {
		DpsResult magic = new LoadoutOptimizer().optimize(data, req(CombatStyle.MAGIC)).get(0);
		DpsResult ranged = new LoadoutOptimizer().optimize(data, req(CombatStyle.RANGED)).get(0);
		assertTrue(magic.getDps() > ranged.getDps(),
			"one cast hits all three - the barrage must out-rank single-target ranged: "
				+ magic.getDps() + " vs " + ranged.getDps());
		assertTrue(magic.getCountedBonuses().stream().anyMatch(b -> b.contains("trio")),
			"the 3x must be a COUNTED assumption, visible in the assurance line");
	}
}

package com.loadoutlab.engine;

import com.loadoutlab.data.DataService;
import com.loadoutlab.data.GearItem;
import com.loadoutlab.data.GearSlot;
import com.loadoutlab.data.LoadoutData;
import com.loadoutlab.data.MonsterDefences;
import com.loadoutlab.data.MonsterStats;
import java.util.Collections;
import java.util.EnumMap;
import org.junit.Assert;
import org.junit.Test;

/**
 * The Obligator (the Fractured Archive, release post 2026-10-20): Lunge
 * (5 ticks) rolls damage twice, three times when crush is the target's
 * second-weakest melee defence, four when weakest, and keeps the best;
 * +20% damage on 2x2, +40% on 3x3 or bigger. Smash (3 ticks) drops the
 * re-rolls and the size bonus. Assumed: one accuracy roll (the post says
 * "rolls damage"), a defence tie is not weaker.
 */
public class ObligatorTest {
	private static MonsterStats dummy(int size, int stab, int slash, int crush) {
		return new MonsterStats(-50 - size, "Obligator Dummy", "", 300, 2000, size, 150, 1, 0,
			new MonsterDefences(stab, slash, crush, 100, 0, 60, 60, 60), null,
			Collections.emptyList(), false, "", 0);
	}

	private static DpsResult swing(MonsterStats target) {
		LoadoutData data = new DataService().load();
		EnumMap<GearSlot, GearItem> worn = new EnumMap<>(GearSlot.class);
		worn.put(GearSlot.WEAPON, data.getGear(34715));
		OptimizationRequest request = new OptimizationRequest(target, CombatStyle.MELEE, PlayerLevels.MAXED,
			PrayerBonuses.NONE, null, 0, CandidateMode.ALL_STANDARD, false, false, OwnedItems.EMPTY,
			RequirementProfile.MAXED, 10);
		return new DpsCalculator().calculate(request, new Loadout(worn));
	}

	@Test
	public void bestOfOneIsTheOrdinaryHit() {
		for (int max : new int[]{1, 7, 42}) {
			Assert.assertEquals(RollMath.normalExpectedHit(0.7, max), RollMath.bestOfExpected(0.7, max, 1, 0), 1e-9);
			Assert.assertEquals(RollMath.expectedHitWithFlatArmour(0.7, 0, max, 3), RollMath.bestOfExpected(0.7, max, 1, 3), 1e-9);
			Assert.assertEquals(RollMath.expectedHitWithFlatArmour(0.7, 0, max, -5), RollMath.bestOfExpected(0.7, max, 1, -5), 1e-9);
		}
		Assert.assertTrue(RollMath.bestOfExpected(1, 40, 4, 0) > RollMath.bestOfExpected(1, 40, 2, 0));
		// Best of two on 0..2: P(max=0)=1/9 (counts 1), P(1)=3/9, P(2)=5/9.
		Assert.assertEquals((1 + 3 + 10) / 9.0, RollMath.bestOfExpected(1, 2, 2, 0), 1e-9);
	}

	@Test
	public void lungeRollsFourTimesWithTheSizeBonusOnABigCrushWeakTarget() {
		DpsResult small = swing(dummy(1, 0, 0, 300));
		DpsResult big = swing(dummy(3, 200, 200, 10));
		Assert.assertEquals(5, big.getAttackSpeed());
		Assert.assertTrue(big.getAttackType(), big.getAttackType().contains("lunge"));
		Assert.assertEquals(small.getMaxHit() * 7 / 5, big.getMaxHit());
		Assert.assertEquals(RollMath.bestOfExpected(big.getAccuracy(), big.getMaxHit(), 4, 0), big.getExpectedHit(), 1e-9);
	}

	@Test
	public void crushSecondWeakestRollsThreeTimesAndATwoByTwoTakesTwentyPercent() {
		DpsResult small = swing(dummy(1, 0, 0, 300));
		DpsResult mid = swing(dummy(2, 200, 0, 100));
		Assert.assertTrue(mid.getAttackType(), mid.getAttackType().contains("lunge"));
		Assert.assertEquals(small.getMaxHit() * 6 / 5, mid.getMaxHit());
		Assert.assertEquals(RollMath.bestOfExpected(mid.getAccuracy(), mid.getMaxHit(), 3, 0), mid.getExpectedHit(), 1e-9);
	}

	@Test
	public void theGameBestSearchReachesItOnABigCrushWeakBoss() {
		// Cerberus (5x5, crush the weakest melee defence): the Lunge beats
		// every other melee weapon (pinned 11.7 vs 9.8 in the 2026-10-20
		// sweep), so the unpinned search must reach it - the raw-stat
		// shortlist used to cut it before the damage step.
		LoadoutData data = new DataService().load();
		MonsterStats cerberus = data.searchMonsters("cerberus", 1).get(0);
		OptimizationRequest request = TestRequests.of(cerberus, CombatStyle.MELEE, PlayerLevels.MAXED,
			PrayerBonuses.bestAvailable(PlayerLevels.MAXED), null, 0, CandidateMode.ALL_STANDARD,
			true, false, OwnedItems.EMPTY, 1);
		String weapon = new LoadoutOptimizer().optimize(data, request).get(0).getLoadout().getWeapon().getName();
		Assert.assertEquals("Obligator", weapon);
	}

	@Test
	public void smashWinsWhereTheLungeHasLittleToRoll() {
		DpsResult small = swing(dummy(1, 0, 0, 300));
		Assert.assertEquals(3, small.getAttackSpeed());
		Assert.assertTrue(small.getAttackType(), small.getAttackType().contains("smash"));
		Assert.assertEquals(RollMath.normalExpectedHit(small.getAccuracy(), small.getMaxHit()), small.getExpectedHit(), 1e-9);
	}
}

