import com.loadoutlab.data.MonsterStats;
import java.util.EnumMap;
import java.util.List;
import java.util.Map;
import java.util.Set;
import net.runelite.api.Skill;
import org.junit.jupiter.api.BeforeAll;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertTrue;

/**
 * A simmed max cape is wearable (ISS-01M5RYC2TB43AEGQ96TTNEKEJN, Andrew
 * 2026-10-25: "if i have the max cape simmed i am NOT seeing the max+fire cape
 * being suggested"): every max cape needs 99 in all 23 skills, and the stat sim
 * only replaces the seven combat levels.
 */
class SimmedMaxCapeWearTest {
	private static final int FIRE_MAX_CAPE = 13329;
	private static LoadoutData data;

	@BeforeAll
	static void load() {
		data = new DataService().load();
	}

	private static RequirementProfile seventies() {
		Map<Skill, Integer> levels = new EnumMap<>(Skill.class);
		for (Skill skill : Skill.values()) { levels.put(skill, 70); }
		return new RequirementProfile(levels, RequirementProfile.MAXED.getCompletedQuests());
	}

	@Test
	@DisplayName("the waiver lets a 70s player wear the fire max cape and nothing else above them")
	void waiverCoversOnlyTheSimmedCapes() {
		GearItem cape = data.getGear(FIRE_MAX_CAPE);
		GearItem fang = data.getGearItems().stream().filter(g -> g.getNameLower().equals("osmumten's fang")).findFirst().get();
		assertFalse(seventies().canWear(cape), "no waiver: 99s required");
		RequirementProfile simmed = seventies().waiving(Set.of(FIRE_MAX_CAPE));
		assertTrue(simmed.canWear(cape));
		assertFalse(simmed.canWear(fang), "the fang still needs 82 Attack");
	}

	@Test
	@DisplayName("a 70s player owning the fire max cape under the sim's waiver wears it in the best melee set")
	void optimizerWearsTheSimmedCape() {
		MonsterStats graardor = data.searchMonsters("general graardor", 1).get(0);
		PlayerLevels levels = new PlayerLevels(70, 70, 70, 70, 70, 70, 70);
		OptimizationRequest request = new OptimizationRequest(graardor, CombatStyle.MELEE, levels,
			PrayerBonuses.bestAvailable(levels), null, 0, CandidateMode.OWNED_ONLY, true, false,
			new OwnedItems(Map.of(FIRE_MAX_CAPE, 1, 4151, 1), true), seventies().waiving(Set.of(FIRE_MAX_CAPE)), 1);
		List<DpsResult> best = new LoadoutOptimizer().optimize(data, request);
		GearItem cape = best.get(0).getLoadout().get(GearSlot.CAPE);
		assertEquals(FIRE_MAX_CAPE, cape == null ? -1 : cape.getId());
	}
}

package com.loadoutlab.engine;

import com.loadoutlab.data.DataService;
import com.loadoutlab.data.GearItem;
import com.loadoutlab.data.LoadoutData;
import com.loadoutlab.data.MonsterStats;
import java.util.HashMap;
import java.util.Map;
import org.junit.Assert;
import org.junit.Test;

public class SlayerInvariantTest {
	/**
	 * Turning the slayer task ON only ADDS options (the slayer helm), so
	 * the resulting DPS can never be lower. This regressed once: with the
	 * helm taking the head slot, the beam pruned lone crystal-body states
	 * before the legs completed the set (whale-bank repro from the field).
	 */
	@Test
	public void slayerTaskNeverLowersTheAnswer() {
		LoadoutData data = new DataService().load();
		MonsterStats graardor = data.searchMonsters("general graardor", 1).get(0);
		Map<Integer, Integer> owned = new HashMap<>();
		for (GearItem g : data.getGearItems()) {
			String n = g.getName().toLowerCase();
			if (!n.contains("twisted bow") && !n.contains("dragon knife")
				&& !n.contains("masori") && !n.contains("scorching")) {
				owned.put(g.getId(), 100);
			}
		}
		double offTask = best(data, graardor, owned, false);
		double onTask = best(data, graardor, owned, true);
		Assert.assertTrue("on-task dps (" + onTask + ") must be >= off-task (" + offTask + ")",
			onTask >= offTask - 1e-9);
	}

	private static double best(LoadoutData data, MonsterStats monster, Map<Integer, Integer> owned, boolean task) {
		OptimizationRequest request = new OptimizationRequest(
			monster, CombatStyle.RANGED, PlayerLevels.MAXED,
			PrayerBonuses.bestAvailable(PlayerLevels.MAXED), null, 0,
			CandidateMode.OWNED_ONLY, true, task,
			new OwnedItems(owned, true), RequirementProfile.MAXED, 1);
		return new LoadoutOptimizer().optimize(data, request).get(0).getDps();
	}
}

package com.loadoutlab.engine;

import com.loadoutlab.data.DataService;
import com.loadoutlab.data.GearItem;
import com.loadoutlab.data.GearSlot;
import com.loadoutlab.data.LoadoutData;
import com.loadoutlab.data.MonsterStats;
import com.loadoutlab.data.SpellStats;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import java.util.HashMap;
import java.util.Map;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertTrue;

/**
 * The smoke battlestaff and the mystic smoke staff grant the Twinflame's +10%
 * accuracy and damage on standard spells (wiki) - and NOTHING else. Only the
 * Twinflame staff splits a Bolt/Blast/Wave into a second 40% hit. The engine
 * had handed that second hit to the smoke staves too, so an Earth Wave off a
 * smoke battlestaff read ~28% high and the swaps strip called it an upgrade
 * over the Purging staff the optimizer rightly wore (Andrew 2026-10-24: "it
 * literally says smoke battlestaff is better, why isn't it showing it in the
 * sim as my highest dps").
 */
class SmokeStaffNoSecondHitTest {
	@Test
	@DisplayName("a smoke battlestaff's Earth Wave gets the +10% but no second hit; the Twinflame's does, so it hits harder")
	void onlyTheTwinflameSplits() {
		LoadoutData data = new DataService().load();
		MonsterStats giant = data.searchMonsters("fire giant", 1).get(0);
		SpellStats wave = data.getSpells().stream().filter(s -> s.getName().equals("Earth Wave")).findFirst()
			.orElseThrow(() -> new AssertionError("no Earth Wave"));
		Map<Integer, Integer> owned = new HashMap<>();
		for (int rune : new int[]{554, 555, 556, 557, 560, 565, 566, 21880}) {
			owned.put(rune, 10000);
		}
		OptimizationRequest request = new OptimizationRequest(giant, CombatStyle.MAGIC, PlayerLevels.MAXED,
			PrayerBonuses.bestAvailable(PlayerLevels.MAXED, PrayerUnlocks.ALL), null, 0, CandidateMode.OWNED_ONLY, true, false,
			new OwnedItems(owned, true), RequirementProfile.MAXED, 3).withSpell(wave);

		DpsResult smoke = cast(data, request, "smoke battlestaff");
		DpsResult mystic = cast(data, request, "mystic smoke staff");
		DpsResult twinflame = cast(data, request, "twinflame staff");

		for (DpsResult staff : new DpsResult[]{smoke, mystic}) {
			assertTrue(staff.getCountedBonuses().stream().anyMatch(b -> b.contains("+10% accuracy and damage")),
				"the smoke staves keep the +10%: " + staff.getCountedBonuses());
			assertFalse(staff.getCountedBonuses().stream().anyMatch(b -> b.contains("second hit")),
				"no second hit for a smoke staff: " + staff.getCountedBonuses());
		}
		assertTrue(twinflame.getCountedBonuses().stream().anyMatch(b -> b.contains("second hit")),
			"the Twinflame splits: " + twinflame.getCountedBonuses());
		assertTrue(twinflame.getExpectedHit() > smoke.getExpectedHit() * 1.15,
			"the Twinflame's Wave hits well over a smoke staff's: " + twinflame.getExpectedHit() + " vs " + smoke.getExpectedHit());
		assertEquals(smoke.getMaxHit(), twinflame.getMaxHit(), "same max hit: the split rides on expected damage, not the max");
	}

	private static DpsResult cast(LoadoutData data, OptimizationRequest request, String staffName) {
		GearItem staff = data.getGearItems(GearSlot.WEAPON).stream()
			.filter(g -> g.getNameLower().equals(staffName) && g.isStandardGear() && !data.isVariant(g.getId()))
			.findFirst().orElseThrow(() -> new AssertionError("corpus is missing " + staffName));
		DpsResult result = new DpsCalculator().calculate(request, new Loadout(Map.of(GearSlot.WEAPON, staff)));
		assertTrue(result != null, staffName + " casts Earth Wave");
		return result;
	}
}

package com.loadoutlab.engine;

import com.loadoutlab.data.DataService;
import com.loadoutlab.data.GearItem;
import com.loadoutlab.data.GearSlot;
import com.loadoutlab.data.LoadoutData;
import com.loadoutlab.data.MonsterStats;
import java.util.EnumMap;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import org.junit.Assert;
import org.junit.Test;

/**
 * Soul stacks (wiki, mirrored from the official calc): each stack adds
 * 6% of the boosted strength level, flat, AFTER the prayer factor -
 * "does not stack multiplicatively with prayers" - to a cap of +30% at
 * five stacks. Stacks build one per swing (even misses), persist
 * between kills, and only decay after 30s idle, so a sustained grind
 * sits at five stacks; the engine prices that steady state.
 * (Field report 2026-08-09: simmed Soulreaper axe lost to Noxious
 * halberd on Thermy because the axe was priced as a plain axe.)
 */
public class SoulreaperAxeTest {
	private static LoadoutData data;

	private static LoadoutData data() {
		if (data == null) {
			data = new DataService().load();
		}
		return data;
	}

	private static GearItem byName(String nameLower) {
		return data().getGearItems().stream()
			.filter(g -> g.getNameLower().equals(nameLower) && g.isStandardGear())
			.findFirst().orElseThrow(() -> new AssertionError("corpus is missing: " + nameLower));
	}

	@Test
	public void fiveSoulStacksBeatTheNoxiousHalberdOnThermy() {
		MonsterStats thermy = data().searchMonsters("thermonuclear smoke devil", 1).get(0);
		Map<Integer, Integer> owned = new HashMap<>();
		owned.put(byName("soulreaper axe").getId(), 1);
		owned.put(byName("noxious halberd").getId(), 1);
		OptimizationRequest request = new OptimizationRequest(
			thermy, CombatStyle.MELEE, PlayerLevels.MAXED,
			PrayerBonuses.bestAvailable(PlayerLevels.MAXED), null, 0,
			CandidateMode.OWNED_ONLY, true, false,
			new OwnedItems(owned, true), RequirementProfile.MAXED, 1);
		List<DpsResult> results = new LoadoutOptimizer().optimize(data(), request);
		Assert.assertFalse(results.isEmpty());
		String weapon = results.get(0).getLoadout().get(GearSlot.WEAPON).labelLower();
		Assert.assertTrue("at 5 stacks the axe outhits the halberd: " + weapon,
			weapon.contains("soulreaper axe"));
	}

	@Test
	public void theStackBonusIsFlatPostPrayerOffTheBoostedLevel() {
		// The exact wiki-calc chain: effective strength gains
		// floor(level * 30/100) on top of the prayer-multiplied level -
		// never level * prayer * 1.30 (that would over-price the axe).
		MonsterStats thermy = data().searchMonsters("thermonuclear smoke devil", 1).get(0);
		OptimizationRequest request = new OptimizationRequest(
			thermy, CombatStyle.MELEE, PlayerLevels.MAXED,
			PrayerBonuses.bestAvailable(PlayerLevels.MAXED), null, 0,
			CandidateMode.ALL_STANDARD, true, false,
			OwnedItems.EMPTY, RequirementProfile.MAXED, 1);
		EnumMap<GearSlot, GearItem> gear = new EnumMap<>(GearSlot.class);
		gear.put(GearSlot.WEAPON, byName("soulreaper axe"));
		DpsResult result = new DpsCalculator().calculate(request, new Loadout(gear));
		Assert.assertNotNull(result);

		int level = request.getLevels().getStrength();
		double prayer = request.getPrayers().getMeleeStrength();
		// The engine reports the winning stance; the axe's strength
		// bonus is 125.
		int stance = stanceBonus(result);
		int expectedEffective = RollMath.effectiveLevel(level, prayer, stance) + level * 30 / 100;
		Assert.assertEquals(RollMath.maxHitFromEffective(expectedEffective, 125),
			result.getMaxHit());
	}

	@Test
	public void otherAxesDoNotInheritTheStackBonus() {
		MonsterStats thermy = data().searchMonsters("thermonuclear smoke devil", 1).get(0);
		OptimizationRequest request = new OptimizationRequest(
			thermy, CombatStyle.MELEE, PlayerLevels.MAXED,
			PrayerBonuses.bestAvailable(PlayerLevels.MAXED), null, 0,
			CandidateMode.ALL_STANDARD, true, false,
			OwnedItems.EMPTY, RequirementProfile.MAXED, 1);
		EnumMap<GearSlot, GearItem> gear = new EnumMap<>(GearSlot.class);
		gear.put(GearSlot.WEAPON, byName("dragon axe"));
		DpsResult result = new DpsCalculator().calculate(request, new Loadout(gear));
		Assert.assertNotNull(result);
		int level = request.getLevels().getStrength();
		double prayer = request.getPrayers().getMeleeStrength();
		int plainEffective = RollMath.effectiveLevel(level, prayer, stanceBonus(result));
		Assert.assertEquals(RollMath.maxHitFromEffective(plainEffective,
				byName("dragon axe").getBonuses().getStrength()),
			result.getMaxHit());
	}

	/** The strength-stance bonus of the variant the engine chose. */
	private static int stanceBonus(DpsResult result) {
		return result.getAttackType().contains("aggressive") ? 3
			: result.getAttackType().contains("controlled") ? 1 : 0;
	}
}

package com.loadoutlab.engine;

import com.loadoutlab.data.DataService;
import com.loadoutlab.data.GearItem;
import com.loadoutlab.data.LoadoutData;
import org.junit.jupiter.api.BeforeAll;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import static org.junit.jupiter.api.Assertions.*;

/**
 * Andrew (client test 2026-10-19): "for spec, dragon 2h is a really good
 * multi spec". Wiki: Powerstab hits every target within one square of the
 * player (60% energy, no modifiers); Annihilate hits up to nine in a 3x3;
 * Shield Bash up to ten in an 11x11 (+20% accuracy, 50%); the halberd
 * sweep a 3x1 line on 1x1 targets. A spec's factor at a stack is the
 * stack capped at its targets; a single-target spec stays at one.
 */
class SpecMultiTest {
	private static LoadoutData data;

	@BeforeAll
	static void load() {
		data = new DataService().load();
	}

	private static SpecialAttack spec(String nameLower) {
		GearItem item = data.getGearItems().stream().filter(g -> g.getNameLower().equals(nameLower))
			.findFirst().orElseThrow(() -> new AssertionError("corpus is missing: " + nameLower));
		SpecialAttack spec = SpecialAttack.match(item);
		assertNotNull(spec, nameLower + " has no special attack on record");
		return spec;
	}

	@Test
	@DisplayName("Powerstab scales with the stack up to nine; the sweep caps at three; the claws stay at one")
	void factors() {
		SpecialAttack d2h = spec("dragon 2h sword");
		assertEquals(60, d2h.getEnergyCost());
		assertEquals(3, d2h.multiFactor(3), 1e-12);
		assertEquals(9, d2h.multiFactor(12), 1e-12);
		assertEquals(1, d2h.multiFactor(1), 1e-12);
		assertEquals(3, spec("crystal halberd").multiFactor(9), 1e-12, "a 3x1 line");
		assertEquals(9, spec("dragon crossbow").multiFactor(9), 1e-12);
		assertEquals(10, spec("dinh's bulwark").multiFactor(12), 1e-12);
		assertEquals(1, spec("dragon claws").multiFactor(9), 1e-12, "single-target");
	}
}

package com.loadoutlab.engine;

import com.loadoutlab.data.DataService;
import com.loadoutlab.data.GearItem;
import com.loadoutlab.data.GearSlot;
import com.loadoutlab.data.LoadoutData;
import com.loadoutlab.data.MonsterStats;
import java.util.EnumMap;
import java.util.List;
import org.junit.Assert;
import org.junit.Test;

public class SpecialAttackTest {
	private static LoadoutData data;

	private static LoadoutData data() {
		if (data == null) {
			data = new DataService().load();
		}
		return data;
	}

	private static GearItem byName(String name) {
		return data().getGearItems().stream()
			.filter(g -> g.getName().equalsIgnoreCase(name) && g.isStandardGear())
			.findFirst()
			.orElseThrow(() -> new AssertionError("missing item: " + name));
	}

	private static OptimizationRequest request(CombatStyle style) {
		MonsterStats monster = data().searchMonsters("goblin", 1).get(0);
		return new OptimizationRequest(
			monster,
			style,
			PlayerLevels.MAXED,
			PrayerBonuses.bestAvailable(PlayerLevels.MAXED),
			null,
			0,
			CandidateMode.ALL_STANDARD,
			true,
			false,
			OwnedItems.EMPTY,
			RequirementProfile.MAXED,
			1);
	}

	private static DpsResult calculate(CombatStyle style, GearItem... items) {
		EnumMap<GearSlot, GearItem> gear = new EnumMap<>(GearSlot.class);
		for (GearItem item : items) {
			gear.put(item.getSlot(), item);
		}
		return new DpsCalculator().calculate(request(style), new Loadout(gear));
	}

	@Test
	public void voidwakerSpecAveragesExactlyTheMaxHit() {
		GearItem voidwaker = byName("Voidwaker");
		DpsResult base = calculate(CombatStyle.MELEE, voidwaker);
		SpecialAttack spec = SpecialAttack.match(voidwaker, CombatStyle.MELEE);
		Assert.assertNotNull(spec);
		// Guaranteed hit, uniform 50-150% of max: the mean IS the max hit,
		// independent of the target's defence.
		Assert.assertEquals(base.getMaxHit(),
			spec.expectedDamage(base, request(CombatStyle.MELEE).getMonster(), PlayerLevels.MAXED), 0.0001);
	}

	@Test
	public void dragonDaggerSpecBeatsTwoUnboostedHits() {
		GearItem dagger = byName("Dragon dagger");
		DpsResult base = calculate(CombatStyle.MELEE, dagger);
		SpecialAttack spec = SpecialAttack.match(dagger, CombatStyle.MELEE);
		Assert.assertNotNull(spec);
		// Two hits, both accuracy and damage boosted 15%: strictly better
		// than two normal expected hits.
		Assert.assertTrue(spec.expectedDamage(base, request(CombatStyle.MELEE).getMonster(), PlayerLevels.MAXED)
			> 2 * base.getExpectedHit());
	}

	@Test
	public void clawsCascadeApproachesOneAndAHalfMaxAtGuaranteedAccuracy() {
		GearItem claws = byName("Dragon claws");
		SpecialAttack spec = SpecialAttack.match(claws, CombatStyle.MELEE);
		Assert.assertNotNull(spec);
		EnumMap<GearSlot, GearItem> gear = new EnumMap<>(GearSlot.class);
		gear.put(GearSlot.WEAPON, claws);
		// Fabricated rolls: astronomically accurate -> first cascade tier
		// dominates, expected total ~ 1.5 * max - 1.
		DpsResult sureHit = new DpsResult(new Loadout(gear), 0, 0, 0, 40, 4, "melee: slash",
			1_000_000_000L, 1L);
		double expected = spec.expectedDamage(sureHit, null, PlayerLevels.MAXED);
		Assert.assertEquals(1.5 * 40 - 1, expected, 0.5);
	}

	@Test
	public void magicShortbowImbuedCostsLessThanRegular() {
		SpecialAttack imbued = SpecialAttack.match(byName("Magic shortbow (i)"), CombatStyle.RANGED);
		SpecialAttack regular = SpecialAttack.match(byName("Magic shortbow"), CombatStyle.RANGED);
		Assert.assertNotNull(imbued);
		Assert.assertNotNull(regular);
		Assert.assertEquals(50, imbued.getEnergyCost());
		Assert.assertEquals(55, regular.getEnergyCost());
	}

	@Test
	public void specWeaponsOnlyMatchTheirOwnStyle() {
		Assert.assertNull(SpecialAttack.match(byName("Dragon dagger"), CombatStyle.RANGED));
		Assert.assertNull(SpecialAttack.match(byName("Dark bow"), CombatStyle.MELEE));
		Assert.assertNull(SpecialAttack.match(byName("Abyssal whip"), CombatStyle.MELEE));
	}

	/**
	 * Fabricated result with hand-picked rolls. normalAccuracy gives
	 * exact hit chances for these: (1_000_000_000, 1) is ~1,
	 * (1, 0) is exactly 0.5, (0, 1) is exactly 0.
	 */
	private static DpsResult fabricated(GearItem weapon, int maxHit, long attackRoll, long defenceRoll) {
		EnumMap<GearSlot, GearItem> gear = new EnumMap<>(GearSlot.class);
		gear.put(GearSlot.WEAPON, weapon);
		return new DpsResult(new Loadout(gear), 0, 0, 0, maxHit, 4, "melee: slash",
			attackRoll, defenceRoll);
	}

	@Test
	public void sunspearSpecDealsExactlySeventyPercentOfMaxOnAHit() {
		GearItem sunspear = byName("Sunspear");
		SpecialAttack spec = SpecialAttack.match(sunspear, CombatStyle.MELEE);
		Assert.assertNotNull(spec);
		Assert.assertEquals(SpecialAttack.Kind.FIXED_FRACTION, spec.getKind());
		// Guaranteed accuracy: a hit is always exactly 70% of max, no damage roll.
		Assert.assertEquals(0.70 * 40,
			spec.expectedDamage(fabricated(sunspear, 40, 1_000_000_000L, 1L), null, PlayerLevels.MAXED), 1e-5);
		// Exactly half the hits land: half of 70% of max.
		Assert.assertEquals(0.35 * 40,
			spec.expectedDamage(fabricated(sunspear, 40, 1L, 0L), null, PlayerLevels.MAXED), 1e-9);
	}

	@Test
	public void crimsonKistenLandsAllFourRollsAtGuaranteedAccuracyForOneAndAHalfMax() {
		GearItem kisten = byName("Crimson kisten");
		SpecialAttack spec = SpecialAttack.match(kisten, CombatStyle.MELEE);
		Assert.assertNotNull(spec);
		Assert.assertEquals(SpecialAttack.Kind.MULTI_ROLL_TIERED, spec.getKind());
		// k = 4 tier: uniform 130-170% of max, mean (0.7 + 0.8) * max.
		Assert.assertEquals(1.5 * 40,
			spec.expectedDamage(fabricated(kisten, 40, 1_000_000_000L, 1L), null, PlayerLevels.MAXED), 1e-5);
	}

	@Test
	public void crimsonKistenDealsNothingWhenEveryRollMisses() {
		GearItem kisten = byName("Crimson kisten");
		SpecialAttack spec = SpecialAttack.match(kisten, CombatStyle.MELEE);
		Assert.assertNotNull(spec);
		Assert.assertEquals(0.0,
			spec.expectedDamage(fabricated(kisten, 40, 0L, 1L), null, PlayerLevels.MAXED), 1e-9);
	}

	@Test
	public void crimsonKistenMidAccuracyMatchesTheBinomialClosedForm() {
		GearItem kisten = byName("Crimson kisten");
		SpecialAttack spec = SpecialAttack.match(kisten, CombatStyle.MELEE);
		Assert.assertNotNull(spec);
		// p = 0.5 exactly: sum over k of C(4,k) p^k (1-p)^(4-k) (0.7 + 0.2k) max
		// = (4*0.9 + 6*1.1 + 4*1.3 + 1*1.5) / 16 * max = 16.9 / 16 * max.
		Assert.assertEquals(16.9 / 16.0 * 40,
			spec.expectedDamage(fabricated(kisten, 40, 1L, 0L), null, PlayerLevels.MAXED), 1e-9);
	}

	@Test
	public void burningClawsFirstCascadeTierAveragesFiveQuartersOfMaxAtGuaranteedAccuracy() {
		GearItem claws = byName("Burning claws");
		SpecialAttack spec = SpecialAttack.match(claws, CombatStyle.MELEE);
		Assert.assertNotNull(spec);
		Assert.assertEquals(SpecialAttack.Kind.CASCADE_CLAWS, spec.getKind());
		Assert.assertEquals(1.25 * 40,
			spec.expectedDamage(fabricated(claws, 40, 1_000_000_000L, 1L), null, PlayerLevels.MAXED), 1e-5);
	}

	@Test
	public void burningClawsFullMissStillAveragesOnePointTwo() {
		GearItem claws = byName("Burning claws");
		SpecialAttack spec = SpecialAttack.match(claws, CombatStyle.MELEE);
		Assert.assertNotNull(spec);
		// All three rolls miss: 20% 0 / 40% 1 / 40% 2 = 1.2 expected.
		Assert.assertEquals(1.2,
			spec.expectedDamage(fabricated(claws, 40, 0L, 1L), null, PlayerLevels.MAXED), 1e-9);
	}

	@Test
	public void burningClawsMidAccuracyMatchesTheCascadeClosedForm() {
		GearItem claws = byName("Burning claws");
		SpecialAttack spec = SpecialAttack.match(claws, CombatStyle.MELEE);
		Assert.assertNotNull(spec);
		// p = 0.5 exactly: 0.5*1.25*40 + 0.25*1.0*40 + 0.125*0.75*40 + 0.125*1.2.
		Assert.assertEquals(0.5 * 1.25 * 40 + 0.25 * 40 + 0.125 * 0.75 * 40 + 0.125 * 1.2,
			spec.expectedDamage(fabricated(claws, 40, 1L, 0L), null, PlayerLevels.MAXED), 1e-9);
	}

	@Test
	public void newAuditSpecWeaponsResolveFromTheRegistry() {
		SpecialAttack zgs = SpecialAttack.match(byName("Zamorak godsword"), CombatStyle.MELEE);
		Assert.assertNotNull(zgs);
		Assert.assertEquals("Zamorak godsword", zgs.getDisplayName());
		Assert.assertEquals(SpecialAttack.Kind.SINGLE, zgs.getKind());
		Assert.assertEquals(50, zgs.getEnergyCost());

		SpecialAttack sunspear = SpecialAttack.match(byName("Sunspear"), CombatStyle.MELEE);
		Assert.assertNotNull(sunspear);
		Assert.assertEquals("Sunspear", sunspear.getDisplayName());
		Assert.assertEquals(50, sunspear.getEnergyCost());

		SpecialAttack kisten = SpecialAttack.match(byName("Crimson kisten"), CombatStyle.MELEE);
		Assert.assertNotNull(kisten);
		Assert.assertEquals("Crimson kisten", kisten.getDisplayName());
		Assert.assertEquals(50, kisten.getEnergyCost());

		SpecialAttack burningClaws = SpecialAttack.match(byName("Burning claws"), CombatStyle.MELEE);
		Assert.assertNotNull(burningClaws);
		Assert.assertEquals("Burning claws", burningClaws.getDisplayName());
		// 35% since the Summer Sweep-Up gear changes (wiki, 7 August 2026).
		Assert.assertEquals(35, burningClaws.getEnergyCost());
	}

	@Test
	public void ornateGraniteMaulSpecCostsFiftyWhileThePlainMaulCostsSixty() {
		SpecialAttack ornate = SpecialAttack.match(byName("Granite maul (ornate handle)"), CombatStyle.MELEE);
		SpecialAttack plain = SpecialAttack.match(byName("Granite maul"), CombatStyle.MELEE);
		Assert.assertNotNull(ornate);
		Assert.assertNotNull(plain);
		Assert.assertEquals(SpecialAttack.Kind.EXTRA_ATTACK, ornate.getKind());
		Assert.assertEquals(SpecialAttack.Kind.EXTRA_ATTACK, plain.getKind());
		Assert.assertEquals(50, ornate.getEnergyCost());
		Assert.assertEquals(60, plain.getEnergyCost());
	}

	@Test
	public void accursedSceptreSpecBoostsDamageByHalf() {
		GearItem sceptre = byName("Accursed sceptre");
		SpecialAttack spec = SpecialAttack.match(sceptre, CombatStyle.MAGIC);
		Assert.assertNotNull(spec);
		// Rolls (2, 0) with the 1.5x accuracy boost give attack roll 3:
		// hit chance 1 - 2/8 = 0.75 exactly; damage rolls 0..(1.5 * 40).
		Assert.assertEquals(0.75 * ((int) (40 * 1.5)) / 2.0,
			spec.expectedDamage(fabricated(sceptre, 40, 2L, 0L), null, PlayerLevels.MAXED), 1e-9);
	}

	@Test
	public void volatileSpellMaxMatchesTheWikiAnchorsAtEightyFourAndNinetyNineMagic() {
		GearItem staff = byName("Volatile nightmare staff");
		SpecialAttack spec = SpecialAttack.match(staff, CombatStyle.MAGIC);
		Assert.assertNotNull(spec);
		DpsResult sureHit = fabricated(staff, 30, 1_000_000_000L, 1L);
		// Level 84: spell max min(floor(58*84/99) + 1, 58) = 50; the staff's
		// 15% magic damage takes it to 57. Expected = mean = 28.5.
		PlayerLevels magic84 = new PlayerLevels(99, 99, 99, 99, 84, 99, 99);
		Assert.assertEquals(57 / 2.0, spec.expectedDamage(sureHit, null, magic84), 1e-4);
		// Level 99: spell max caps at 58; 15% gear takes it to 66. Mean 33.
		Assert.assertEquals(66 / 2.0, spec.expectedDamage(sureHit, null, PlayerLevels.MAXED), 1e-4);
		// A boosted 98 already hits the 58 cap.
		PlayerLevels magic98 = new PlayerLevels(99, 99, 99, 99, 98, 99, 99);
		Assert.assertEquals(66 / 2.0, spec.expectedDamage(sureHit, null, magic98), 1e-4);
	}
}

package com.loadoutlab.engine;

import com.loadoutlab.data.DataService;
import com.loadoutlab.data.LoadoutData;
import com.loadoutlab.data.MonsterStats;
import com.loadoutlab.data.SpellRunes;
import com.loadoutlab.data.SpellStats;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import org.junit.jupiter.api.BeforeAll;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import static org.junit.jupiter.api.Assertions.*;

/**
 * Wiring net for the premium-rune spell gate: PremiumRuneGateTest proves the
 * predicate, this proves the optimizer's pool actually consults it - on the
 * OWNED side only, and before the mob whitelists so a nibbler lock cannot
 * resurrect a spell the bank cannot pay for.
 */
class SpellRuneWiringTest {
	private static LoadoutData data;
	private static MonsterStats zulrah;

	@BeforeAll
	static void load() {
		data = new DataService().load();
		zulrah = data.searchMonsters("zulrah", 1).get(0);
	}

	private static OptimizationRequest request(CandidateMode mode, OwnedItems owned) {
		return new OptimizationRequest(
			zulrah, CombatStyle.MAGIC, PlayerLevels.MAXED,
			PrayerBonuses.NONE, null, 0,
			mode, true, false,
			owned, RequirementProfile.MAXED, 1);
	}

	@Test
	@DisplayName("a runeless bank's own spell pool holds no premium-rune spell")
	void ownedPoolDropsPremiumSpells() {
		List<SpellStats> pool = LoadoutOptimizer.spellsFor(data,
			request(CandidateMode.OWNED_ONLY, OwnedItems.EMPTY));
		assertFalse(pool.isEmpty(), "the pool should still hold shop-rune spells");
		for (SpellStats spell : pool) {
			assertTrue(SpellRunes.premiumRunesOwned(spell.getName(), OwnedItems.EMPTY),
				spell.getName() + " needs premium runes the bank does not hold");
		}
	}

	@Test
	@DisplayName("owning the runes restores the barrage-class spells")
	void owningRunesRestoresThePool() {
		Map<Integer, Integer> runes = new HashMap<>();
		runes.put(565, 1000); // blood
		runes.put(560, 1000); // death
		runes.put(566, 1000); // soul
		runes.put(21880, 1000); // wrath
		List<SpellStats> pool = LoadoutOptimizer.spellsFor(data,
			request(CandidateMode.OWNED_ONLY, new OwnedItems(runes, true)));
		boolean premium = false;
		for (SpellStats spell : pool) {
			premium |= !SpellRunes.premiumRunesOwned(spell.getName(), OwnedItems.EMPTY);
		}
		assertTrue(premium, "with the runes banked, premium spells should be back");
	}

	@Test
	@DisplayName("the ceiling keeps every spell - it prices the game, not the bank")
	void ceilingIsUngated() {
		List<SpellStats> pool = LoadoutOptimizer.spellsFor(data,
			request(CandidateMode.ALL_STANDARD, OwnedItems.EMPTY));
		boolean premium = false;
		for (SpellStats spell : pool) {
			premium |= !SpellRunes.premiumRunesOwned(spell.getName(), OwnedItems.EMPTY);
		}
		assertTrue(premium, "the BiS side must not be rune-gated");
	}
}

package com.loadoutlab.engine;

import com.loadoutlab.data.DataService;
import com.loadoutlab.data.LoadoutData;
import com.loadoutlab.data.MonsterStats;
import java.util.List;
import org.junit.Assert;
import org.junit.Test;

public class SpellbookLockTest {
	private static LoadoutData data;

	private static LoadoutData data() {
		if (data == null) {
			data = new DataService().load();
		}
		return data;
	}

	@Test
	public void lockRestrictsAutoSpellToTheChosenBook() {
		MonsterStats td = data().searchMonsters("tormented demon", 1).get(0);
		OptimizationRequest base = new OptimizationRequest(
			td, CombatStyle.MAGIC, PlayerLevels.MAXED,
			PrayerBonuses.bestAvailable(PlayerLevels.MAXED), null, 0,
			CandidateMode.ALL_STANDARD, true, false,
			OwnedItems.EMPTY, RequirementProfile.MAXED, 1);

		// Unlocked vs demons: arceuus demonbane or a powered staff wins.
		DpsResult any = new LoadoutOptimizer().optimize(data(), base).get(0);
		Assert.assertTrue(any.getSpellName() == null
			|| any.getSpellName().contains("Demonbane"));

		// Locked to standard: no arceuus spell may appear.
		DpsResult standard = new LoadoutOptimizer().optimize(data(),
			base.withSpellbookLock("standard")).get(0);
		if (standard.getSpellName() != null) {
			Assert.assertEquals("standard", bookOf(standard.getSpellName()));
		}

		// Locked to ancient: the pick is an ancient spell or a powered staff.
		DpsResult ancient = new LoadoutOptimizer().optimize(data(),
			base.withSpellbookLock("ancient")).get(0);
		if (ancient.getSpellName() != null) {
			Assert.assertEquals("ancient", bookOf(ancient.getSpellName()));
		}
	}

	@Test
	public void purgingStaffAutocastsAncientsAndNoSpellMeansNoResult() {
		MonsterStats graardor = data().searchMonsters("general graardor", 1).get(0);
		java.util.Map<Integer, Integer> owned = new java.util.HashMap<>();
		data().getGearItems().stream().filter(g -> g.getName().equalsIgnoreCase("Purging staff"))
			.findFirst().ifPresent(g -> owned.put(g.getId(), 1));
		// Premium runes: the rune-ownership gate (0.4.1) would otherwise
		// drop the blood/death spells and shift the arithmetic this test
		// pins - rune poverty has its own net (SpellRuneWiringTest).
		owned.put(565, 1000);   // blood
		owned.put(560, 1000);   // death
		owned.put(566, 1000);   // soul
		owned.put(21880, 1000); // wrath
		OptimizationRequest ancientLock = new OptimizationRequest(
			graardor, CombatStyle.MAGIC, PlayerLevels.MAXED,
			PrayerBonuses.bestAvailable(PlayerLevels.MAXED), null, 0,
			CandidateMode.OWNED_ONLY, true, false,
			new OwnedItems(owned, true), RequirementProfile.MAXED, 1)
			.withSpellbookLock("ancient");
		List<DpsResult> results = new LoadoutOptimizer().optimize(data(), ancientLock);
		// The purging staff CAN autocast ancients - a real barrage result,
		// never a spell-less max-0 garbage row (the field 0.04-dps report).
		Assert.assertFalse(results.isEmpty());
		Assert.assertNotNull(results.get(0).getSpellName());
		Assert.assertTrue(results.get(0).getMaxHit() > 0);
	}

	private static String bookOf(String spellName) {
		return data().getSpells().stream()
			.filter(s -> s.getName().equals(spellName))
			.findFirst().orElseThrow(AssertionError::new).getSpellbook();
	}

	@Test
	public void eyeOfAyakEvaluatesAsAPoweredStaffInTheOptimizer() {
		// The optimizer once had its own powered-staff list missing the
		// eye of ayak, sending it down the autocast path. A powered staff
		// result carries no spell name.
		com.loadoutlab.data.LoadoutData data = new com.loadoutlab.data.DataService().load();
		com.loadoutlab.data.MonsterStats zulrah = data.searchMonsters("zulrah", 1).get(0);
		java.util.Map<Integer, Integer> owned = java.util.Map.of(31113, 1); // eye of ayak (charged)
		OptimizationRequest req = TestRequests.of(zulrah, CombatStyle.MAGIC,
			PlayerLevels.MAXED, PrayerBonuses.bestAvailable(PlayerLevels.MAXED, PrayerUnlocks.ALL),
			null, 0, CandidateMode.OWNED_ONLY, true, false,
			new com.loadoutlab.engine.OwnedItems(data.canonicalizeOwned(owned), true), 1);
		java.util.List<DpsResult> out = new LoadoutOptimizer().optimize(data, req);
		org.junit.Assert.assertFalse(out.isEmpty());
		org.junit.Assert.assertEquals("Eye of Ayak", out.get(0).getLoadout().getWeapon().getName());
		org.junit.Assert.assertNull("powered staff results carry no spell name",
			out.get(0).getSpellName());
		org.junit.Assert.assertTrue(out.get(0).getDps() > 0);
	}
}

