 * should be able to sim as any stat, defaulted to your current ones. lower
 * or higher should work too"; "max cape should automatically unlock the
 * fire/inferno, mage/ rage cape combo versions").
 */
class StatSimTest {
	private static LoadoutData data;

	@BeforeAll
	static void load() {
		data = new DataService().load();
	}

	private static GearItem item(String name) {
		return data.getGearItems().stream()
			.filter(g -> g.getNameLower().equals(name) && g.isStandardGear() && !data.isVariant(g.getId()))
			.findFirst().orElseThrow(() -> new AssertionError("corpus is missing " + name));
	}

	private static RequirementProfile profile(int attack) {
		Map<Skill, Integer> levels = new EnumMap<>(Skill.class);
		levels.put(Skill.ATTACK, attack);
		levels.put(Skill.STRENGTH, 70);
		levels.put(Skill.DEFENCE, 70);
		levels.put(Skill.RANGED, 80);
		levels.put(Skill.MAGIC, 85);
		levels.put(Skill.PRAYER, 60);
		levels.put(Skill.HITPOINTS, 80);
		return new RequirementProfile(levels, Set.of());
	}

	@Test
	@DisplayName("a sim of 99 Attack over 70/70/70/80/85/60/80 keeps the other six; zero means your own")
	void aSimReplacesOnlyTheLevelsItNames() {
		PlayerLevels mine = new PlayerLevels(70, 70, 70, 80, 85, 60, 80);
		PlayerLevels simmed = mine.overridden(new int[]{99, 0, 0, 0, 0, 0, 0});
		assertEquals(99, simmed.getAttack());
		assertEquals(70, simmed.getStrength());
		assertEquals(80, simmed.getHitpoints());
		assertEquals(mine.toString(), mine.overridden(null).toString(), "no sim: your own levels");
		assertEquals(50, mine.overridden(new int[]{0, 0, 0, 0, 0, 0, 50}).getHitpoints(), "lower works too");
	}

	@Test
	@DisplayName("the requirement profile follows the sim: 60 Attack cannot wear the fang, simmed to 99 it can, back to 60 it cannot")
	void gearFollowsTheSim() {
		GearItem fang = item("osmumten's fang");
		RequirementProfile sixty = profile(60);
		assertFalse(sixty.canEquip(fang.getRequirements()));
		PlayerLevels ninetyNine = PlayerLevels.from(sixty).overridden(new int[]{99, 0, 0, 0, 0, 0, 0});
		assertTrue(sixty.withLevels(ninetyNine).canEquip(fang.getRequirements()), "99 Attack admits the fang");
		assertFalse(sixty.withLevels(ninetyNine).withLevels(PlayerLevels.from(sixty)).canEquip(fang.getRequirements()), "and 60 drops it again");
		assertEquals(85, sixty.withLevels(ninetyNine).getLevels().get(Skill.MAGIC), "the other skills ride along unchanged");
	}

	@Test
	@DisplayName("max cape sims: with a fire cape owned the max cape and the fire max cape; with nothing, the max cape alone; an imbued Zamorak cape brings its imbued max cape")
	void maxCapeCombos() {
		int fireCape = item("fire cape").getId();
		int imbuedZamorak = item("imbued zamorak cape").getId();
		Set<String> withFire = names(MaxCapeSims.ids(data, id -> id == fireCape));
		assertEquals(Set.of("max cape", "fire max cape"), withFire);
		assertEquals(Set.of("max cape"), names(MaxCapeSims.ids(data, id -> false)));
		assertTrue(names(MaxCapeSims.ids(data, id -> id == imbuedZamorak)).contains("imbued zamorak max cape"));
	}

	private static Set<String> names(Set<Integer> ids) {
		return ids.stream().map(id -> data.getGear(id).getNameLower()).collect(Collectors.toSet());
	}
}

package com.loadoutlab.engine;

import com.loadoutlab.data.DataService;
import com.loadoutlab.data.GearItem;
import com.loadoutlab.data.GearSlot;
import com.loadoutlab.data.LoadoutData;
import com.loadoutlab.data.MonsterStats;
import com.loadoutlab.data.SpellStats;
import java.util.EnumMap;
import org.junit.jupiter.api.BeforeAll;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import static org.junit.jupiter.api.Assertions.*;

/**
 * Kendyy (Discord 2026-10-19): "same goes for if you are using sunfire
 * runes or not". Wiki (Sunfire rune, read 2026-10-19): any successful
 * hit with an offensive fire spell deals a minimum of 10% of the max
 * hit. The official calc takes trunc(maxHit / 10) after the magic
 * damage pool and the elemental weakness and BEFORE the tome step, so
 * a charged tome of fire lifts the max hit without lifting the floor.
 */
class SunfireTest {
	private static LoadoutData data;
	private static MonsterStats araxxor;

	@BeforeAll
	static void load() {
		data = new DataService().load();
		araxxor = data.searchMonsters("araxxor", 1).get(0);
		assertEquals("Araxxor", araxxor.getName());
		assertEquals("fire", araxxor.getWeaknessElement(), "the fixture needs a fire-weak target");
	}

	private static SpellStats spell(String name) {
		return data.getSpells().stream().filter(s -> s.getName().equalsIgnoreCase(name))
			.findFirst().orElseThrow(AssertionError::new);
	}

	private static GearItem item(String nameLower, String versionLower) {
		return data.getGearItems().stream()
			.filter(g -> g.getNameLower().equals(nameLower)
				&& (versionLower == null ? g.isStandardGear() : g.getVersionLower().equals(versionLower)))
			.findFirst().orElseThrow(() -> new AssertionError("corpus is missing: " + nameLower));
	}

	/** A magic-damage set, so the fixture's max hits sit where the tenth
	 * is worth testing: Fire Wave reads 37 pre-tome and 40 with the tome
	 * (floors 3 and 4) - a bare wand gave 39 and 42, the same floor. */
	private static final String[] MAGIC_SET = {"kodai wand", "occult necklace",
		"tormented bracelet", "ancestral hat", "ancestral robe top", "ancestral robe bottom"};

	private static DpsResult cast(SpellStats spell, boolean sunfire, boolean fireTome) {
		EnumMap<GearSlot, GearItem> gear = new EnumMap<>(GearSlot.class);
		for (String name : MAGIC_SET) {
			GearItem piece = item(name, null);
			gear.put(piece.getSlot(), piece);
		}
		if (fireTome) {
			gear.put(GearSlot.SHIELD, item("tome of fire", "charged"));
		}
		OptimizationRequest request = new OptimizationRequest(
			araxxor, CombatStyle.MAGIC, PlayerLevels.MAXED,
			PrayerBonuses.bestAvailable(PlayerLevels.MAXED), spell, 0,
			CandidateMode.ALL_STANDARD, true, false,
			OwnedItems.EMPTY, RequirementProfile.MAXED, 1).withSunfireRunes(sunfire);
		DpsResult result = new DpsCalculator().calculate(request, new Loadout(gear));
		assertNotNull(result);
		return result;
	}

	@Test
	@DisplayName("sunfire runes give Fire Surge a minimum hit of a tenth of its max, priced uniform over [min, max]")
	void sunfireRunesRaiseTheFloor() {
		DpsResult plain = cast(spell("Fire Surge"), false, false);
		DpsResult sunfire = cast(spell("Fire Surge"), true, false);
		assertEquals(plain.getMaxHit(), sunfire.getMaxHit(), "the max hit is untouched");
		assertEquals(plain.getAccuracy(), sunfire.getAccuracy(), 1e-12, "accuracy is untouched");
		int min = sunfire.getMaxHit() / 10;
		assertTrue(min >= 1, "the fixture's max hit must be at least 10 for a floor to exist");
		assertEquals(sunfire.getAccuracy() * (min + sunfire.getMaxHit()) / 2.0,
			sunfire.getExpectedHit(), 1e-9, "a landed hit is uniform over [min, max]");
		assertTrue(sunfire.getDps() > plain.getDps(), "the floor raises the dps");
	}

	@Test
	@DisplayName("the floor is a tenth of the pre-tome max: a charged tome of fire lifts the max, not the minimum")
	void floorIsTakenBeforeTheTome() {
		DpsResult bare = cast(spell("Fire Wave"), true, false);
		DpsResult tome = cast(spell("Fire Wave"), true, true);
		assertTrue(tome.getMaxHit() > bare.getMaxHit(), "the charged fire tome adds damage");
		int floor = bare.getMaxHit() / 10;
		assertNotEquals(tome.getMaxHit() / 10, floor,
			"fixture guard: the post-tome tenth must differ or the ordering is untested");
		assertEquals(tome.getAccuracy() * (floor + tome.getMaxHit()) / 2.0,
			tome.getExpectedHit(), 1e-9, "the minimum is still the pre-tome tenth");
	}

	@Test
	@DisplayName("the flag does nothing to a water spell")
	void waterSpellsIgnoreTheFlag() {
		DpsResult plain = cast(spell("Water Surge"), false, false);
		DpsResult flagged = cast(spell("Water Surge"), true, false);
		assertEquals(plain.getDps(), flagged.getDps(), 1e-12);
		assertEquals(plain.getExpectedHit(), flagged.getExpectedHit(), 1e-12);
	}
}

package com.loadoutlab.engine;

import com.loadoutlab.data.DataService;
import com.loadoutlab.data.GearSlot;
import com.loadoutlab.data.LoadoutData;
import com.loadoutlab.data.MonsterStats;
import java.util.EnumMap;
import java.util.Map;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import static org.junit.jupiter.api.Assertions.*;

/**
 * miko (Discord 2026-10-17) wanted the Expeditious bracelet in every
 * setup; Andrew made it a slayer-task option. The overlay turns the
 * preference into hands pins the optimizer already honours.
 */
class TaskBraceletTest {
	private static final LoadoutData DATA = new DataService().load();
	private static final MonsterStats DEMON = DATA.searchMonsters("abyssal demon", 1).get(0);
	private static final MonsterStats ORCA = DATA.searchMonsters("orca", 1).get(0);

	private static final int EXPEDITIOUS = 21177;
	private static final int BARROWS_GLOVES = 7462;

	private static Map<CombatStyle, Map<GearSlot, Integer>> meleeHandsPinned() {
		EnumMap<CombatStyle, Map<GearSlot, Integer>> pins = new EnumMap<>(CombatStyle.class);
		EnumMap<GearSlot, Integer> melee = new EnumMap<>(GearSlot.class);
		melee.put(GearSlot.HANDS, BARROWS_GLOVES);
		pins.put(CombatStyle.MELEE, melee);
		return pins;
	}

	@Test
	@DisplayName("on task: every concrete style's hands slot is pinned to the bracelet")
	void onTaskPinsEveryStyle() {
		Map<CombatStyle, Map<GearSlot, Integer>> out =
			TaskBracelet.overlay(Map.of(), DEMON, true, TaskBracelet.EXPEDITIOUS_BRACELET);
		for (CombatStyle style : CombatStyle.concreteValues()) {
			assertEquals(EXPEDITIOUS, out.get(style).get(GearSlot.HANDS), style.name());
		}
	}

	@Test
	@DisplayName("the mob's own hands pin wins on its style; the others still get the bracelet")
	void mobPinWins() {
		Map<CombatStyle, Map<GearSlot, Integer>> in = meleeHandsPinned();
		Map<CombatStyle, Map<GearSlot, Integer>> out =
			TaskBracelet.overlay(in, DEMON, true, TaskBracelet.BRACELET_OF_SLAUGHTER);
		assertEquals(BARROWS_GLOVES, out.get(CombatStyle.MELEE).get(GearSlot.HANDS));
		assertEquals(21183, out.get(CombatStyle.RANGED).get(GearSlot.HANDS));
		assertEquals(21183, out.get(CombatStyle.MAGIC).get(GearSlot.HANDS));
		assertNull(in.get(CombatStyle.RANGED), "the input map must not be mutated");
	}

	@Test
	@DisplayName("a monster that is never a slayer task gets no bracelet, task param or not (Orca, 2026-10-18)")
	void nonSlayerMonsterIsUntouched() {
		Map<CombatStyle, Map<GearSlot, Integer>> in = meleeHandsPinned();
		assertFalse(ORCA.isSlayerMonster(), "the fixture needs a non-slayer monster");
		assertSame(in, TaskBracelet.overlay(in, ORCA, true, TaskBracelet.EXPEDITIOUS_BRACELET));
		assertSame(in, TaskBracelet.overlay(in, null, true, TaskBracelet.EXPEDITIOUS_BRACELET));
	}

	@Test
	@DisplayName("off task, or with None chosen, the pins pass through untouched")
	void offTaskOrNoneIsIdentity() {
		Map<CombatStyle, Map<GearSlot, Integer>> in = meleeHandsPinned();
		assertSame(in, TaskBracelet.overlay(in, DEMON, false, TaskBracelet.EXPEDITIOUS_BRACELET));
		assertSame(in, TaskBracelet.overlay(in, DEMON, true, TaskBracelet.NONE));
		assertSame(in, TaskBracelet.overlay(in, DEMON, true, null));
	}
}

package com.loadoutlab.engine;

import com.loadoutlab.data.MonsterStats;
import com.loadoutlab.data.SpellStats;

/**
 * Test-only factory for the requirement-profile-less request shape. This
 * used to be an 11-arg convenience constructor on OptimizationRequest whose
 * only job was to supply {@link RequirementProfile#MAXED}, but no main-source
 * caller ever used it (OptimizerService always passes a profile explicitly),
 * so it lived on only for the tests while counting against the Plugin Hub's
 * main-source token cap. Moved here, where test sources are free.
 */
public final class TestRequests {
	private TestRequests() {
	}

	/** A request with the requirement profile defaulted to MAXED. */
	public static OptimizationRequest of(
		MonsterStats monster,
		CombatStyle style,
		PlayerLevels levels,
		PrayerBonuses prayers,
		SpellStats spell,
		int budget,
		CandidateMode candidateMode,
		boolean includeUntradeables,
		boolean onSlayerTask,
		OwnedItems ownedItems,
		int resultLimit) {
		return new OptimizationRequest(
			monster,
			style,
			levels,
			prayers,
			spell,
			budget,
			candidateMode,
			includeUntradeables,
			onSlayerTask,
			ownedItems,
			RequirementProfile.MAXED,
			resultLimit);
	}
}

package com.loadoutlab.engine;

import com.loadoutlab.data.DataService;
import com.loadoutlab.data.GearItem;
import com.loadoutlab.data.GearSlot;
import com.loadoutlab.data.LoadoutData;
import com.loadoutlab.data.MonsterStats;
import java.util.EnumMap;
import org.junit.jupiter.api.BeforeAll;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertTrue;

/** Kendyy, Discord 2026-09-29: "Aquanites slayer task giving keris as bis
 * ... calc isn't adding up to the same on wiki DPS calc ... only seems to
 * happen with black gem attached". Micah: "black keris gets recommended a
 * lot when it has terrible stats outside of TOA". Wiki: the keris partisan
 * of Amascut is +108 stab / +67 strength INSIDE the Tombs and the base
 * partisan's +58 / +45 outside; Tumeken's shadow multiplies by four inside
 * and three outside. */
class ToaGearRulesTest {
	private static LoadoutData data;

	@BeforeAll
	static void load() {
		data = new DataService().load();
	}

	private static DpsResult swing(String monster, CombatStyle style, String... gearNames) {
		MonsterStats mob = data.searchMonsters(monster, 1).get(0);
		OptimizationRequest request = TestRequests.of(mob, style, PlayerLevels.MAXED,
			PrayerBonuses.NONE, null, 0, CandidateMode.ALL_STANDARD, true, false, OwnedItems.EMPTY, 1);
		EnumMap<GearSlot, GearItem> gear = new EnumMap<>(GearSlot.class);
		for (String name : gearNames) {
			GearItem item = data.getGearItems().stream()
				.filter(g -> g.getNameLower().equals(name) && g.isStandardGear())
				.findFirst().orElseThrow(() -> new AssertionError("corpus is missing: " + name));
			gear.put(item.getSlot(), item);
		}
		return new DpsCalculator().calculate(request, new Loadout(gear));
	}

	@Test
	@DisplayName("outside the Tombs the keris partisan of Amascut is a plain keris partisan")
	void amascutPartisanOutside() {
		DpsResult amascut = swing("aquanite", CombatStyle.MELEE, "keris partisan of amascut");
		DpsResult plain = swing("aquanite", CombatStyle.MELEE, "keris partisan");
		assertEquals(plain.getMaxHit(), amascut.getMaxHit(), "strength +45, not +67");
		assertEquals(plain.getAccuracy(), amascut.getAccuracy(), 1e-9, "stab +58, not +108");
	}

	@Test
	@DisplayName("inside the Tombs it keeps its +108 stab and +67 strength")
	void amascutPartisanInside() {
		DpsResult amascut = swing("akkha", CombatStyle.MELEE, "keris partisan of amascut");
		DpsResult plain = swing("akkha", CombatStyle.MELEE, "keris partisan");
		assertTrue(amascut.getMaxHit() > plain.getMaxHit());
		assertTrue(amascut.getAccuracy() > plain.getAccuracy());
	}

	@Test
	@DisplayName("Tumeken's shadow multiplies by four inside the Tombs, three outside")
	void shadowInside() {
		DpsResult inside = swing("akkha", CombatStyle.MAGIC, "tumeken's shadow", "occult necklace");
		DpsResult outside = swing("goblin", CombatStyle.MAGIC, "tumeken's shadow", "occult necklace");
		assertTrue(inside.getAttackRoll() > outside.getAttackRoll(), "the magic attack bonus is quadrupled");
		assertTrue(inside.getMaxHit() > outside.getMaxHit(), "the occult's 5% is 20% inside, 15% outside");
	}
}

package com.loadoutlab.engine;

import com.loadoutlab.data.DataService;
import com.loadoutlab.data.GearItem;
import com.loadoutlab.data.LoadoutData;
import com.loadoutlab.data.MonsterGroups;
import com.loadoutlab.data.MonsterStats;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import org.junit.jupiter.api.BeforeAll;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import static org.junit.jupiter.api.Assertions.*;

/**
 * ToA invocation scaling (official engine rule, verified against the
 * weirdgloop engine 2026-08-07): defence rolls x (250+invocation)/250,
 * truncated, for every invocation-scaled ToA row. Field report
 * 2026-08-06: at invocation 0 a blowpipe edges the bowfa at the Enraged
 * Warden by ~1%, but at any real raid level the scaling craters the
 * blowpipe's small attack roll and the bowfa wins - modeling zero
 * silently told the wrong story.
 */
class ToaInvocationTest {
	private static LoadoutData data;
	private static MonsterStats enraged;

	@BeforeAll
	static void load() {
		data = new DataService().load();
		enraged = data.searchMonsters("tumeken's warden", 8).stream()
			.filter(m -> "Enraged".equals(m.getVersion()))
			.findFirst().orElseThrow();
		assertTrue(MonsterMechanics.isToaInvocationScaled(enraged));
	}

	private static GearItem byName(String nameLower, String versionLower) {
		for (GearItem g : data.getGearItems()) {
			if (g.getNameLower().equals(nameLower)
				&& (versionLower == null || g.getVersionLower().equals(versionLower))) {
				return g;
			}
		}
		throw new AssertionError("corpus is missing: " + nameLower);
	}

	private static OptimizationRequest req(MonsterStats monster, CandidateMode mode,
		OwnedItems owned) {
		return TestRequests.of(monster, CombatStyle.RANGED, PlayerLevels.MAXED,
			PrayerBonuses.bestAvailable(PlayerLevels.MAXED), null, 0,
			mode, true, false, owned, 1);
	}

	@Test
	@DisplayName("the defence roll scales by exactly (250+invocation)/250, truncated")
	void defenceRollScalesExactly() {
		java.util.EnumMap<com.loadoutlab.data.GearSlot, GearItem> gear =
			new java.util.EnumMap<>(com.loadoutlab.data.GearSlot.class);
		gear.put(com.loadoutlab.data.GearSlot.WEAPON, byName("bow of faerdhinen", "charged"));
		Loadout bofa = new Loadout(gear);

		DpsResult at0 = new DpsCalculator().calculate(
			req(enraged, CandidateMode.ALL_STANDARD, OwnedItems.EMPTY), bofa);
		DpsResult at300 = new DpsCalculator().calculate(
			req(enraged.withToaInvocation(300), CandidateMode.ALL_STANDARD, OwnedItems.EMPTY), bofa);
		assertEquals(at0.getDefenceRoll() * 550 / 250, at300.getDefenceRoll(),
			"long math, multiply before divide - matches the official trackFactor");
		assertEquals(at0.getAttackRoll(), at300.getAttackRoll(),
			"invocation touches the DEFENCE side only");
		assertTrue(at300.getAccuracy() < at0.getAccuracy());
	}

	@Test
	@DisplayName("the field report both ways: blowpipe wins invocation 0, bowfa wins 300")
	void bowfaOvertakesTheBlowpipeAtRealRaidLevels() {
		Map<Integer, Integer> owned = new HashMap<>();
		for (GearItem g : new GearItem[]{
			byName("toxic blowpipe", "charged"), byName("bow of faerdhinen", "charged"),
			byName("crystal helm", "active"), byName("crystal body", "active"),
			byName("crystal legs", "active"),
			byName("masori mask (f)", null), byName("masori body (f)", null),
			byName("masori chaps (f)", null), byName("necklace of anguish", null),
			byName("zaryte vambraces", null), byName("dragon dart", "unpoisoned")}) {
			owned.put(g.getId(), 10000);
		}
		OwnedItems bank = new OwnedItems(owned, true);

		List<DpsResult> at0 = new LoadoutOptimizer().optimize(data,
			req(enraged, CandidateMode.OWNED_ONLY, bank));
		assertFalse(at0.isEmpty());
		assertTrue(at0.get(0).getLoadout().getWeapon().getNameLower().startsWith("toxic blowpipe"),
			"invocation 0: the blowpipe genuinely edges it, was: "
				+ at0.get(0).getLoadout().getWeapon().label());

		List<DpsResult> at300 = new LoadoutOptimizer().optimize(data,
			req(enraged.withToaInvocation(300), CandidateMode.OWNED_ONLY, bank));
		assertFalse(at300.isEmpty());
		assertTrue(at300.get(0).getLoadout().getWeapon().getNameLower().startsWith("bow of faerdhinen"),
			"invocation 300: the scaling flips it to the bowfa, was: "
				+ at300.get(0).getLoadout().getWeapon().label());
	}

	@Test
	@DisplayName("the group's synthetic warden phases scale too (profileId mapping)")
	void syntheticVariantsScale() {
		MonsterStats p2 = MonsterGroups.load(data).stream()
			.filter(g -> "Tombs of Amascut".equals(g.getName()))
			.flatMap(g -> g.getMobs().stream())
			.filter(m -> m.getId() >= MonsterStats.SYNTHETIC_ID_BASE)
			.findFirst().orElseThrow();
		assertTrue(MonsterMechanics.isToaInvocationScaled(p2),
			"immuneVariant rows carry synthetic ids - profileId maps them back");
		assertEquals(300,
			MonsterMechanics.atToaInvocation(p2, 300).getToaInvocationLevel());
	}

	@Test
	@DisplayName("non-ToA monsters and level 0 are no-ops; re-applying replaces, never compounds")
	void scalingIsScopedAndSetNotCompounded() {
		MonsterStats goblin = data.searchMonsters("goblin", 1).get(0);
		assertSame(goblin, MonsterMechanics.atToaInvocation(goblin, 300),
			"a goblin has no raid level");
		assertSame(enraged, MonsterMechanics.atToaInvocation(enraged, 0),
			"level 0 on an unfactored row stays the same instance");
		MonsterStats rescaled = enraged.withToaInvocation(300).withToaInvocation(150);
		assertEquals(150, rescaled.getToaInvocationLevel(), "SET semantics");
		assertEquals(0, MonsterMechanics.atToaInvocation(
				enraged.withToaInvocation(300), 0).getToaInvocationLevel(),
			"cycling the chip back to 0 clears the factor");
	}
}

package com.loadoutlab.engine;

import com.loadoutlab.data.DataService;
import com.loadoutlab.data.GearItem;
import com.loadoutlab.data.GearSlot;
import com.loadoutlab.data.LoadoutData;
import com.loadoutlab.data.MonsterStats;
import com.loadoutlab.data.SpellStats;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import org.junit.jupiter.api.BeforeAll;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import static org.junit.jupiter.api.Assertions.*;

/**
 * rakaykhan1512 (Discord 2026-10-18): "it wasn't including the tome of
 * water in my bank when using water surge on drakes as my best mage dps
 * instead it suggested elidinis ward though its clearly lower dps".
 * Wiki (Tome of Water): a charged tome raises a standard-spellbook
 * spell of its element by 10% accuracy and 10% damage against NPCs,
 * multiplicative with the magic damage pool. Empty tomes, off-element
 * spells and Ancients get nothing.
 */
class TomeTest {
	private static LoadoutData data;
	private static MonsterStats drake;

	@BeforeAll
	static void load() {
		data = new DataService().load();
		drake = data.searchMonsters("drake", 1).get(0);
		assertEquals("Drake", drake.getName());
	}

	private static SpellStats spell(String name) {
		return data.getSpells().stream().filter(s -> s.getName().equalsIgnoreCase(name))
			.findFirst().orElseThrow(AssertionError::new);
	}

	private static void own(Map<Integer, Integer> owned, String nameLower, String versionLower) {
		GearItem item = data.getGearItems().stream()
			.filter(g -> g.getNameLower().equals(nameLower)
				&& (versionLower == null ? g.isStandardGear() : g.getVersionLower().equals(versionLower)))
			.findFirst().orElseThrow(() -> new AssertionError("corpus is missing: " + nameLower + " " + versionLower));
		owned.put(item.getId(), 1);
	}

	/** The reporter's shape: a full magic set, so accuracy is near its
	 * cap and the shield decides damage; wrath runes so Water Surge is
	 * castable (the auto-pick skips a spell whose premium runes are not
	 * banked). */
	private static final String[] MAGIC_SET = {"ancestral hat", "ancestral robe top",
		"ancestral robe bottom", "occult necklace", "tormented bracelet", "eternal boots"};
	private static final int WRATH_RUNE = 21880;

	private static DpsResult best(SpellStats pinned, String... ownedNames) {
		Map<Integer, Integer> owned = new HashMap<>();
		owned.put(WRATH_RUNE, 1000);
		for (String name : MAGIC_SET) {
			own(owned, name, null);
		}
		for (String name : ownedNames) {
			String[] parts = name.split("#");
			own(owned, parts[0], parts.length > 1 ? parts[1] : null);
		}
		OptimizationRequest request = new OptimizationRequest(
			drake, CombatStyle.MAGIC, PlayerLevels.MAXED,
			PrayerBonuses.bestAvailable(PlayerLevels.MAXED), null, 0,
			CandidateMode.OWNED_ONLY, true, false,
			new OwnedItems(owned, true), RequirementProfile.MAXED, 1);
		List<DpsResult> results = new LoadoutOptimizer().optimize(data,
			pinned == null ? request : request.withSpell(pinned));
		assertFalse(results.isEmpty(), "a kodai set must exist");
		return results.get(0);
	}

	@Test
	@DisplayName("a charged tome of water lifts Water Surge above the fortified ward at a drake")
	void chargedTomeBeatsTheWard() {
		DpsResult tome = best(spell("Water Surge"), "kodai wand", "tome of water#charged");
		DpsResult ward = best(spell("Water Surge"), "kodai wand", "elidinis' ward (f)");
		assertEquals("tome of water", tome.getLoadout().get(GearSlot.SHIELD).getNameLower());
		assertTrue(tome.getMaxHit() > ward.getMaxHit(),
			"tome max hit " + tome.getMaxHit() + " vs ward " + ward.getMaxHit());
		assertTrue(tome.getDps() > ward.getDps(),
			"tome dps " + tome.getDps() + " vs ward " + ward.getDps());
	}

	@Test
	@DisplayName("an empty tome, an off-element tome and an Ancients spell get nothing")
	void onlyAChargedMatchingTomeCounts() {
		DpsResult bare = best(spell("Water Surge"), "kodai wand");
		assertEquals(bare.getMaxHit(), best(spell("Water Surge"), "kodai wand", "tome of water#empty").getMaxHit());
		assertEquals(bare.getMaxHit(), best(spell("Water Surge"), "kodai wand", "tome of fire#charged").getMaxHit());
		DpsResult barrage = best(spell("Ice Barrage"), "ancient staff");
		assertEquals(barrage.getMaxHit(),
			best(spell("Ice Barrage"), "ancient staff", "tome of water#charged").getMaxHit());
	}

	@Test
	@DisplayName("the fire and earth tomes boost damage only; the water tome alone adds accuracy (wiki)")
	void onlyTheWaterTomeAddsAccuracy() {
		// The empty tome carries the same +8 magic attack, so it isolates
		// the charge's own effect.
		DpsResult empty = best(spell("Fire Surge"), "kodai wand", "tome of fire#empty");
		DpsResult fire = best(spell("Fire Surge"), "kodai wand", "tome of fire#charged");
		assertEquals("tome of fire", fire.getLoadout().get(GearSlot.SHIELD).getNameLower());
		assertTrue(fire.getMaxHit() > empty.getMaxHit(), "the fire tome still lifts the max hit");
		assertEquals(empty.getAccuracy(), fire.getAccuracy(), 1e-9, "no accuracy term on the fire tome");
		DpsResult emptyWater = best(spell("Water Surge"), "kodai wand", "tome of water#empty");
		DpsResult water = best(spell("Water Surge"), "kodai wand", "tome of water#charged");
		assertTrue(water.getAccuracy() > emptyWater.getAccuracy(), "the water tome adds accuracy");
	}

	@Test
	@DisplayName("with both owned, the drake's magic card wears the charged tome, not the ward")
	void optimizerPicksTheTome() {
		DpsResult best = best(null, "kodai wand", "tome of water#charged", "elidinis' ward (f)");
		assertEquals("tome of water", best.getLoadout().get(GearSlot.SHIELD).getNameLower());
		assertEquals("Water Surge", best.getSpellName());
	}
}

package com.loadoutlab.engine;

import com.loadoutlab.data.DataService;
import com.loadoutlab.data.GearItem;
import com.loadoutlab.data.LoadoutData;
import com.loadoutlab.data.MonsterStats;
import org.junit.jupiter.api.BeforeAll;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import static org.junit.jupiter.api.Assertions.*;

/**
 * The Tormented Demons' 20% reduction and its bypass classes (wiki:
 * "reduces damage done by non-demonbane weapons/spells and non-abyssal
 * weapons by 20%"). Pinned after the 2026-08-06 simplify pass moved the
 * demonbane vocabulary onto GearItem - the restructure must not change
 * who bypasses. Verified 2026-08-06: the Purging staff is an AUTOCAST
 * demonbane-spell staff, so on the magic side the SPELL governs - a
 * demonbane cast bypasses, a plain elemental cast through any staff
 * does not.
 */
class TormentedDemonRulesTest {
	private static LoadoutData data;
	private static MonsterStats demon;

	@BeforeAll
	static void load() {
		data = new DataService().load();
		demon = data.searchMonsters("tormented demon", 1).get(0);
		assertTrue(TormentedDemonRules.applies(demon), "test premise: the TD row");
	}

	private static GearItem byName(String nameLower) {
		for (GearItem item : data.getGearItems()) {
			if (item.getNameLower().equals(nameLower)) {
				return item;
			}
		}
		throw new AssertionError("corpus is missing: " + nameLower);
	}

	private static double factor(CombatStyle style, String weapon, String spellName) {
		return TormentedDemonRules.damageFactor(demon, style,
			weapon == null ? null : byName(weapon), spellName);
	}

	@Test
	@DisplayName("demonbane and abyssal melee bypass the reduction; plain melee pays it")
	void meleeBypasses() {
		assertEquals(1.0, factor(CombatStyle.MELEE, "arclight", null), 1e-9);
		assertEquals(1.0, factor(CombatStyle.MELEE, "burning claws", null), 1e-9,
			"the claws are demonbane - the pre-restructure list carried them");
		assertEquals(1.0, factor(CombatStyle.MELEE, "abyssal whip", null), 1e-9);
		assertEquals(0.8, factor(CombatStyle.MELEE, "dragon scimitar", null), 1e-9);
	}

	@Test
	@DisplayName("the Scorching bow bypasses on the ranged side; a blowpipe pays")
	void rangedBypasses() {
		assertEquals(1.0, factor(CombatStyle.RANGED, "scorching bow", null), 1e-9);
		assertEquals(0.8, factor(CombatStyle.RANGED, "toxic blowpipe", null), 1e-9);
	}

	@Test
	@DisplayName("magic bypasses by the SPELL being demonbane, not the staff held")
	void magicGoesBySpell() {
		assertEquals(1.0, factor(CombatStyle.MAGIC, "purging staff", "Dark Demonbane"), 1e-9);
		assertEquals(0.8, factor(CombatStyle.MAGIC, "purging staff", "Fire Surge"), 1e-9,
			"a plain cast is not demonbane damage, whatever stick throws it");
		assertEquals(0.8, factor(CombatStyle.MAGIC, "kodai wand", null), 1e-9);
	}

	@Test
	@DisplayName("the reduction exists only at Tormented Demons")
	void scopedToTds() {
		MonsterStats goblin = data.searchMonsters("goblin", 1).get(0);
		assertEquals(1.0, TormentedDemonRules.damageFactor(goblin,
			CombatStyle.MELEE, byName("dragon scimitar"), null), 1e-9);
	}
}

package com.loadoutlab.engine;

import com.loadoutlab.data.DataService;
import com.loadoutlab.data.GearItem;
import com.loadoutlab.data.GearSlot;
import com.loadoutlab.data.LoadoutData;
import com.loadoutlab.data.MonsterStats;
import com.loadoutlab.data.SpellStats;
import java.util.EnumMap;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import org.junit.jupiter.api.BeforeAll;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import static org.junit.jupiter.api.Assertions.*;

/**
 * The twinflame staff's 40% second hit applies to Bolt/Blast/Wave, not
 * Strike/Surge - so spell DOMINANCE depends on the weapon. The elemental
 * prune used to keep only the top max-hit spell per class, which dropped
 * every doubled tier before evaluation: a pinned twinflame was told to
 * autocast Wind Surge while Wind Wave computed ~18% more dps (field
 * report 2026-08-06, reproduced at Guthan).
 */
class TwinflameSpellPickTest {
	private static LoadoutData data;
	private static MonsterStats guthan;
	private static GearItem staff;

	@BeforeAll
	static void load() {
		data = new DataService().load();
		guthan = data.searchMonsters("guthan", 1).get(0);
		for (GearItem g : data.getGearItems()) {
			if (g.getNameLower().contains("twinflame") && g.isStandardGear()) {
				staff = g;
			}
		}
		assertNotNull(staff, "test premise: the twinflame staff exists");
	}

	@Test
	@DisplayName("a pinned twinflame autocasts a doubled tier, not the pruned-to Surge")
	void pinnedTwinflamePicksADoubledTier() {
		Map<Integer, Integer> owned = new HashMap<>();
		owned.put(staff.getId(), 1);
		// The premium runes, so the rune-ownership gate (0.4.1) leaves the
		// full spell ladder in play - this test is about twinflame doubling
		// economics, and without blood/wrath runes Wave and Surge both
		// (correctly) drop from an owned-only pool.
		owned.put(565, 1000);   // blood
		owned.put(560, 1000);   // death
		owned.put(566, 1000);   // soul
		owned.put(21880, 1000); // wrath
		Map<GearSlot, Integer> pins = new EnumMap<>(GearSlot.class);
		pins.put(GearSlot.WEAPON, staff.getId());
		OptimizationRequest request = TestRequests.of(guthan,
			CombatStyle.MAGIC, PlayerLevels.MAXED,
			PrayerBonuses.bestAvailable(PlayerLevels.MAXED), null, 0,
			CandidateMode.OWNED_ONLY, true, false,
			new OwnedItems(owned, true), 1)
			.withPinnedItems(pins);
		List<DpsResult> out = new LoadoutOptimizer().optimize(data, request);
		assertFalse(out.isEmpty());
		String spell = out.get(0).getSpellName();
		assertNotNull(spell);
		assertTrue(spell.endsWith("Wave") || spell.endsWith("Blast") || spell.endsWith("Bolt"),
			"the doubled tier must win under a twinflame, picked: " + spell);

		// And the pick genuinely out-damages the surge it used to recommend.
		EnumMap<GearSlot, GearItem> gear = new EnumMap<>(GearSlot.class);
		gear.put(GearSlot.WEAPON, staff);
		SpellStats surge = data.getSpells().stream()
			.filter(s -> "Wind Surge".equals(s.getName())).findFirst().orElseThrow();
		DpsResult surged = new DpsCalculator().calculate(request.withSpell(surge),
			new Loadout(gear));
		assertTrue(out.get(0).getDps() > surged.getDps(),
			"picked " + spell + " at " + out.get(0).getDps()
				+ " must beat Wind Surge at " + surged.getDps());
	}

	@Test
	@DisplayName("without a twinflame the surge tier still wins - no over-correction")
	void plainStaffStillPicksSurge() {
		OptimizationRequest request = TestRequests.of(guthan,
			CombatStyle.MAGIC, PlayerLevels.MAXED,
			PrayerBonuses.bestAvailable(PlayerLevels.MAXED), null, 0,
			CandidateMode.ALL_STANDARD, true, false, OwnedItems.EMPTY, 1);
		List<DpsResult> out = new LoadoutOptimizer().optimize(data, request);
		assertFalse(out.isEmpty());
		String spell = out.get(0).getSpellName();
		// Powered staves carry their own builtin; only assert when the pick
		// is a plain elemental autocast.
		if (spell != null && DpsCalculator.isPlainElemental(
			data.getSpells().stream().filter(s -> spell.equals(s.getName()))
				.findFirst().orElse(null))) {
			assertFalse(spell.endsWith("Wave") || spell.endsWith("Blast"),
				"with no twinflame the doubled tiers have no edge, picked: " + spell);
		}
	}
}

package com.loadoutlab.engine;

import com.loadoutlab.data.DataService;
import com.loadoutlab.data.GearItem;
import com.loadoutlab.data.GearSlot;
import com.loadoutlab.data.LoadoutData;
import com.loadoutlab.data.MonsterStats;
import com.loadoutlab.data.SpellStats;
import java.util.EnumMap;
import org.junit.jupiter.api.BeforeAll;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import static org.junit.jupiter.api.Assertions.*;

/**
 * Twinflame staff (wiki, verified 2026-07-18): cast speed 6, +10%
 * accuracy and damage on standard-book spells, and elemental
 * Bolt/Blast/Wave spells fire a second hit at 40% - Strike and Surge
 * do not double. Field question that found the gap: Barrows brothers
 * are air-weak (severity 50), and the un-modeled staff lost to a
 * powered staff it should beat.
 */
class TwinflameStaffTest {
	private static LoadoutData data;
	private static MonsterStats dharok;
	private static final DpsCalculator calc = new DpsCalculator();

	@BeforeAll
	static void load() {
		data = new DataService().load();
		dharok = data.searchMonsters("dharok", 1).get(0);
	}

	private static Loadout wielding(int weaponId) {
		GearItem weapon = data.getGear(weaponId);
		assertNotNull(weapon, "corpus is missing item " + weaponId);
		EnumMap<GearSlot, GearItem> gear = new EnumMap<>(GearSlot.class);
		gear.put(GearSlot.WEAPON, weapon);
		return new Loadout(gear);
	}

	private static SpellStats spell(String name) {
		return data.getSpells().stream().filter(s -> s.getName().equalsIgnoreCase(name))
			.findFirst().orElseThrow(() -> new AssertionError("no spell " + name));
	}

	private static OptimizationRequest request() {
		return new OptimizationRequest(dharok, CombatStyle.MAGIC, PlayerLevels.MAXED,
			PrayerBonuses.NONE, null, 0,
			CandidateMode.ALL_STANDARD, true, false,
			OwnedItems.EMPTY, RequirementProfile.MAXED, 1);
	}

	@Test
	@DisplayName("the twinflame casts at 6 ticks and doubles Wave but not Surge")
	void doublesWaveNotSurge() {
		DpsResult wave = calc.calculate(request().withSpell(spell("Wind Wave")), wielding(30634));
		DpsResult surge = calc.calculate(request().withSpell(spell("Wind Surge")), wielding(30634));
		assertNotNull(wave);
		assertNotNull(surge);
		assertEquals(6, wave.getAttackSpeed(), "wiki: attack and cast speed of 6");
		// Surge's higher base max (23 vs 19) loses to the Wave's 40%
		// second hit - the doubling excludes Surge by name.
		assertTrue(wave.getDps() > surge.getDps(),
			"Wind Wave " + wave.getDps() + " must beat Wind Surge " + surge.getDps());
	}

	@Test
	@DisplayName("vs an air-weak brother the swamp trident legitimately wins")
	void tridentBeatsTwinflameVsBarrows() {
		// REFEREE'D 2026-08-21 (vectors twinflame-dharok 6.02 vs
		// swamptrident-dharok 6.53, both engines agreeing to <0.1%):
		// the July field pin ("twinflame must beat the trident") was an
		// artifact of the old inflated twinflame model - a separate
		// 1.10x damage multiplier instead of +100 into the magic-damage
		// pool, and a smooth 1.4x second hit instead of the per-roll
		// trunc(0.4 x roll). The honest ordering flips.
		DpsResult twinflame = calc.calculate(request().withSpell(spell("Wind Wave")), wielding(30634));
		DpsResult trident = calc.calculate(request(), wielding(12899));
		assertNotNull(twinflame);
		assertNotNull(trident);
		assertTrue(trident.getDps() > twinflame.getDps(),
			"swamp trident " + trident.getDps() + " over twinflame " + twinflame.getDps()
				+ " vs the air-weak Dharok (official-calc referee'd)");
	}
}

package com.loadoutlab.engine;

import com.loadoutlab.data.DataService;
import com.loadoutlab.data.GearItem;
import com.loadoutlab.data.GearSlot;
import com.loadoutlab.data.LoadoutData;
import com.loadoutlab.data.MonsterStats;
import java.util.EnumMap;
import org.junit.Assert;
import org.junit.Test;

/**
 * N, Discord 2026-09-26 (glacial temotli): "is flat armor taken into
 * account? ... an additional 4 damage every hit seems pretty big boost
 * to dps". Wiki (Multi-hit weapons, 2026-09-27): the twin weapons and
 * Torag's hammers roll TWO INDEPENDENT hits on a halved max; the dark
 * bow fires two full arrows; charged Tonalztics throw twice at 75%.
 * Flat armour applies to each hitsplat.
 */
public class TwoHitWeaponsTest {
	private static LoadoutData data;

	private static LoadoutData data() {
		if (data == null) {
			data = new DataService().load();
		}
		return data;
	}

	private static GearItem byName(String nameLower, String version) {
		return data().getGearItems().stream()
			.filter(g -> g.getNameLower().equals(nameLower) && g.isStandardGear()
				&& (version == null || version.equalsIgnoreCase(g.getVersion())))
			.findFirst().orElseThrow(() -> new AssertionError("corpus is missing: " + nameLower));
	}

	private static DpsResult swing(String monster, CombatStyle style, GearItem weapon, String ammo) {
		MonsterStats mob = data().searchMonsters(monster, 1).get(0);
		OptimizationRequest request = TestRequests.of(mob, style,
			PlayerLevels.MAXED, PrayerBonuses.bestAvailable(PlayerLevels.MAXED), null, 0,
			CandidateMode.ALL_STANDARD, true, false, OwnedItems.EMPTY, 1);
		EnumMap<GearSlot, GearItem> gear = new EnumMap<>(GearSlot.class);
		gear.put(GearSlot.WEAPON, weapon);
		if (ammo != null) {
			gear.put(GearSlot.AMMO, byName(ammo, null));
		}
		DpsResult result = new DpsCalculator().calculate(request, new Loadout(gear));
		Assert.assertNotNull(result);
		return result;
	}

	private static void assertTwoIndependentHits(String weapon, String version) {
		MonsterStats moon = data().searchMonsters("blue moon", 1).get(0);
		int armour = moon.getDefensive().getFlatArmour();
		Assert.assertTrue("blue moon carries negative flat armour", armour < 0);
		DpsResult result = swing("blue moon", CombatStyle.MELEE, byName(weapon, version), null);
		int rawMax = result.getMaxHit() + armour;
		int firstRaw = rawMax / 2;
		int secondRaw = rawMax - firstRaw;
		double acc = result.getAccuracy();
		double expected = RollMath.expectedHitWithFlatArmour(acc, 0, firstRaw, armour)
			+ RollMath.expectedHitWithFlatArmour(acc, 0, secondRaw, armour);
		Assert.assertEquals(weapon + ": two independent hitsplats, each with the flat bonus",
			expected, result.getExpectedHit(), 1e-9);
	}

	@Test
	public void theTwinWeaponsRollTwoIndependentHits() {
		assertTwoIndependentHits("glacial temotli", null);
		assertTwoIndependentHits("sulphur blades", null);
		assertTwoIndependentHits("earthbound tecpatl", null);
		assertTwoIndependentHits("torag's hammers", "Undamaged");
	}

	@Test
	public void theDarkBowFiresTwoFullArrows() {
		DpsResult bow = swing("goblin", CombatStyle.RANGED, byName("dark bow", "Regular"), "dragon arrow");
		double one = RollMath.expectedHitWithFlatArmour(bow.getAccuracy(), 0, bow.getMaxHit(), 0);
		Assert.assertEquals("two arrows, each a full roll", 2 * one, bow.getExpectedHit(), 1e-9);
	}

	@Test
	public void chargedTonalzticsThrowTwiceAtThreeQuarters() {
		DpsResult charged = swing("goblin", CombatStyle.RANGED, byName("tonalztics of ralos", "Charged"), null);
		DpsResult uncharged = swing("goblin", CombatStyle.RANGED, byName("tonalztics of ralos", "Uncharged"), null);
		Assert.assertEquals("both versions roll 75% of the max", uncharged.getMaxHit(), charged.getMaxHit());
		double one = RollMath.expectedHitWithFlatArmour(charged.getAccuracy(), 0, charged.getMaxHit(), 0);
		Assert.assertEquals("charged throws twice", 2 * one, charged.getExpectedHit(), 1e-9);
		Assert.assertEquals("uncharged throws once", one, uncharged.getExpectedHit(), 1e-9);
	}
}

package com.loadoutlab.engine;

import com.loadoutlab.data.DataService;
import com.loadoutlab.data.GearItem;
import com.loadoutlab.data.GearSlot;
import com.loadoutlab.data.LoadoutData;
import com.loadoutlab.data.MonsterStats;
import org.junit.jupiter.api.BeforeAll;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import java.util.EnumMap;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.stream.Collectors;

import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertTrue;

/**
 * Charged versions only (ISS-01M5QQV2TGQ5X730T0JJ75S1RD, Andrew 2026-10-24:
 * "let's only consider charged versions of weapons, don't think about eye
 * of ayak uncharged or obligator uncharged"): an uncharged, inactive,
 * broken or locked weapon is a variant of its charged twin - never a pool
 * candidate, a swap or a spec pick - and owning it counts as owning the
 * charged one.
 */
class UnchargedStepTest {
	private static final int OBLIGATOR_CHARGED = 34715;
	private static final int OBLIGATOR_UNCHARGED = 34717;
	private static final int EYE_OF_AYAK_CHARGED = 31113;
	private static final int EYE_OF_AYAK_UNCHARGED = 31115;
	private static LoadoutData data;
	private static MonsterStats spectre;

	@BeforeAll
	static void load() {
		data = new DataService().load();
		spectre = data.searchMonsters("aberrant spectre", 1).get(0);
	}

	private static GearItem item(String name) {
		return data.getGearItems().stream()
			.filter(g -> g.getNameLower().equals(name) && g.isStandardGear() && !data.isVariant(g.getId()))
			.findFirst().orElseThrow(() -> new AssertionError("corpus is missing " + name));
	}

	@Test
	@DisplayName("an uncharged weapon is a variant of its charged twin, and owning it is owning the charged one")
	void unchargedIsTheChargedTwinsVariant() {
		assertTrue(data.isVariant(OBLIGATOR_UNCHARGED), "Obligator (Uncharged) stands behind the charged one");
		assertTrue(data.isVariant(EYE_OF_AYAK_UNCHARGED), "Eye of Ayak (Uncharged) too");
		assertFalse(data.isVariant(OBLIGATOR_CHARGED));
		assertFalse(data.isVariant(EYE_OF_AYAK_CHARGED));
		Map<Integer, Integer> bank = new HashMap<>();
		bank.put(OBLIGATOR_UNCHARGED, 1);
		OwnedItems owned = new OwnedItems(data.canonicalizeOwned(bank), true);
		assertTrue(owned.owns(OBLIGATOR_CHARGED), "the uncharged one in the bank is the Obligator you charge before the trip");
	}

	@Test
	@DisplayName("the Aberrant spectre's weapon swaps hold the charged Obligator and never the uncharged one")
	void swapsAreChargedOnly() {
		Map<Integer, Integer> owned = new HashMap<>();
		EnumMap<GearSlot, GearItem> g = new EnumMap<>(GearSlot.class);
		for (String name : new String[]{"neitiznot faceguard", "fire cape", "amulet of torture", "rada's blessing 4",
			"noxious halberd", "bandos chestplate", "ahrim's robeskirt", "ferocious gloves", "aranea boots", "berserker ring (i)"}) {
			GearItem it = item(name);
			owned.put(it.getId(), 1);
			g.put(it.getSlot(), it);
		}
		OptimizationRequest request = new OptimizationRequest(spectre, CombatStyle.MELEE, PlayerLevels.MAXED,
			PrayerBonuses.bestAvailable(PlayerLevels.MAXED, PrayerUnlocks.ALL), null, 0, CandidateMode.OWNED_ONLY, true, false,
			new OwnedItems(owned, true), RequirementProfile.MAXED, 3);
		DpsResult shown = new DpsCalculator().calculate(request, new Loadout(g));
		List<Integer> swaps = new LoadoutOptimizer().slotSwaps(data, request, shown, GearSlot.WEAPON).stream()
			.map(r -> r.getLoadout().getWeapon().getId()).collect(Collectors.toList());
		assertTrue(swaps.contains(OBLIGATOR_CHARGED), "the charged Obligator is a swap");
		assertFalse(swaps.contains(OBLIGATOR_UNCHARGED), "the uncharged one is never a step");
		for (DpsResult swap : new LoadoutOptimizer().slotSwaps(data, request, shown, GearSlot.WEAPON)) {
			assertFalse(swap.getLoadout().getWeapon().getVersionLower().contains("uncharged"),
				"no uncharged weapon anywhere on the strip: " + swap.getLoadout().getWeapon().getName());
		}
	}
}

package com.loadoutlab.engine;

import com.loadoutlab.data.DataService;
import com.loadoutlab.data.LoadoutData;
import com.loadoutlab.data.MonsterStats;
import java.util.List;
import org.junit.jupiter.api.BeforeAll;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import static org.junit.jupiter.api.Assertions.*;

/**
 * A weapon that cannot attack must never be RECOMMENDED (2026-07 player
 * audit A3.4): charged wilderness weapons are untradeable so only their
 * dead Uncharged twins pass the budget-affordability gate, and the budget
 * pool used to tell players to buy a Webweaver bow (Uncharged) - an item
 * that cannot fire at all until fed 1,000 ether. badVersion() is a pool
 * FILTER for the weapon slot now, not just a dedupe tie-break.
 */
class UnchargedWeaponPoolTest {
	private static LoadoutData data;

	@BeforeAll
	static void load() {
		data = new DataService().load();
	}

	private static boolean bad(String versionLower) {
		return versionLower.contains("uncharged") || versionLower.contains("broken")
			|| versionLower.contains("locked") || versionLower.contains("inactive");
	}

	@Test
	@DisplayName("a 500m budget never recommends buying an uncharged/broken weapon")
	void budgetNeverBuysDeadWeapons() {
		MonsterStats graardor = data.searchMonsters("general graardor", 1).get(0);
		for (CombatStyle style : new CombatStyle[]{CombatStyle.MELEE, CombatStyle.RANGED, CombatStyle.MAGIC}) {
			OptimizationRequest request = new OptimizationRequest(graardor, style,
				PlayerLevels.MAXED, PrayerBonuses.bestAvailable(PlayerLevels.MAXED),
				null, 500_000_000, CandidateMode.BUDGET, true, false,
				OwnedItems.EMPTY, RequirementProfile.MAXED, 3);
			List<DpsResult> results = new LoadoutOptimizer().optimize(data, request);
			for (DpsResult result : results) {
				if (result.getLoadout().getWeapon() == null) {
					continue;
				}
				String version = result.getLoadout().getWeapon().getVersionLower();
				assertFalse(bad(version),
					style + " recommended a weapon that cannot attack: "
						+ result.getLoadout().getWeapon().getNameLower() + " (" + version + ")");
			}
		}
	}

	@Test
	@DisplayName("game-best pools never surface an uncharged weapon either")
	void allStandardNeverPicksDeadWeapons() {
		MonsterStats revDragon = data.searchMonsters("revenant dragon", 1).get(0);
		for (CombatStyle style : new CombatStyle[]{CombatStyle.MELEE, CombatStyle.RANGED}) {
			OptimizationRequest request = new OptimizationRequest(revDragon, style,
				PlayerLevels.MAXED, PrayerBonuses.bestAvailable(PlayerLevels.MAXED),
				null, 0, CandidateMode.ALL_STANDARD, true, false,
				OwnedItems.EMPTY, RequirementProfile.MAXED, 3);
			for (DpsResult result : new LoadoutOptimizer().optimize(data, request)) {
				if (result.getLoadout().getWeapon() == null) {
					continue;
				}
				assertFalse(bad(result.getLoadout().getWeapon().getVersionLower()),
					style + " picked " + result.getLoadout().getWeapon().getNameLower());
			}
		}
	}
}

package com.loadoutlab.engine;

import com.loadoutlab.data.GearItem;
import com.loadoutlab.data.GearSlot;
import com.loadoutlab.data.StatBlock;
import org.junit.Assert;
import org.junit.Test;

public class UntradeableDeathCostsTest {
	private static final StatBlock COMBAT = new StatBlock(0, 0, 0, 0, 0, 4, 0, 0, 2);

	private static GearItem gear(String name, boolean tradeable, StatBlock bonuses) {
		return new GearItem(1, name, "", GearSlot.CAPE, "", 0, false, true,
			tradeable, true, null, StatBlock.ZERO, StatBlock.ZERO, bonuses, null);
	}

	@Test
	public void nullAndTradeableItemsCostNothingHere() {
		Assert.assertEquals(0, UntradeableDeathCosts.costFor(null));
		// Tradeable losses are priced by the kept-slot ranking instead.
		Assert.assertEquals(0, UntradeableDeathCosts.costFor(gear("Fire cape", true, COMBAT)));
	}

	@Test
	public void trouverClassItemsCostTheFlatMangleFee() {
		Assert.assertEquals(500_000, UntradeableDeathCosts.costFor(gear("Infernal cape", false, COMBAT)));
		Assert.assertEquals(500_000, UntradeableDeathCosts.costFor(gear("Elite void top", false, COMBAT)));
		Assert.assertEquals(500_000, UntradeableDeathCosts.costFor(gear("Dizana's quiver", false, COMBAT)));
		Assert.assertEquals(3, UntradeableDeathCosts.categoryFor(gear("Infernal cape", false, COMBAT)));
	}

	@Test
	public void breakableItemsCostTheirOwnWikiRepairFee() {
		Assert.assertEquals(150_000, UntradeableDeathCosts.costFor(gear("Fire cape", false, COMBAT)));
		Assert.assertEquals(96_000, UntradeableDeathCosts.costFor(gear("Imbued saradomin cape", false, COMBAT)));
		Assert.assertEquals(35_000, UntradeableDeathCosts.costFor(gear("Rune defender", false, COMBAT)));
		Assert.assertEquals(600_000, UntradeableDeathCosts.costFor(gear("Avernic defender", false, COMBAT)));
		Assert.assertEquals(2, UntradeableDeathCosts.categoryFor(gear("Fire cape", false, COMBAT)));
	}

	@Test
	public void componentDropItemsArePricedAtTheComponentTheKillerGets() {
		Assert.assertEquals(6_000_000, UntradeableDeathCosts.costFor(gear("Crystal body", false, COMBAT)));
		Assert.assertEquals(1_500_000, UntradeableDeathCosts.costFor(gear("Slayer helmet (i)", false, COMBAT)));
		Assert.assertEquals(3_000_000, UntradeableDeathCosts.costFor(gear("Berserker ring (i)", false, COMBAT)));
	}

	@Test
	public void cheapReclaimsAndFreeUntradeablesStayCheap() {
		// Trivial reclaims (diary rewards, 200gp at Perdu) are FREE TIER:
		// noise that must not evict them from a zero-risk-cap set.
		Assert.assertEquals(0, UntradeableDeathCosts.costFor(gear("Ardougne cloak 4", false, COMBAT)));
		Assert.assertEquals(0, UntradeableDeathCosts.costFor(gear("Rada's blessing 4", false, COMBAT)));
		Assert.assertEquals(0, UntradeableDeathCosts.costFor(gear("Salve amulet(ei)", false, COMBAT)));
		Assert.assertEquals(130_000, UntradeableDeathCosts.costFor(gear("Barrows gloves", false, COMBAT)));
	}

	@Test
	public void nameMatchingIgnoresCase() {
		Assert.assertEquals(150_000, UntradeableDeathCosts.costFor(gear("FIRE CAPE", false, COMBAT)));
	}

	@Test
	public void unknownCombatUntradeablesFallBackToTheConservativeDefault() {
		Assert.assertEquals(UntradeableDeathCosts.UNKNOWN_COMBAT_UNTRADEABLE_GP,
			UntradeableDeathCosts.costFor(gear("Some future combat relic", false, COMBAT)));
		Assert.assertEquals(0, UntradeableDeathCosts.categoryFor(gear("Some future combat relic", false, COMBAT)));
	}

	@Test
	public void unknownStatlessUntradeablesCostNothing() {
		Assert.assertEquals(0, UntradeableDeathCosts.costFor(gear("Party hood", false, StatBlock.ZERO)));
	}
}

package com.loadoutlab.engine;

import com.loadoutlab.data.DataService;
import com.loadoutlab.data.GearItem;
import com.loadoutlab.data.GearSlot;
import com.loadoutlab.data.LoadoutData;
import com.loadoutlab.data.MonsterStats;
import com.loadoutlab.data.SpellStats;
import java.util.EnumMap;
import java.util.List;
import java.util.Map;
import java.util.function.IntUnaryOperator;
import org.junit.jupiter.api.BeforeAll;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertNotNull;
import static org.junit.jupiter.api.Assertions.assertNull;
import static org.junit.jupiter.api.Assertions.assertTrue;

/**
 * Vampyre maths at parity with the official calculator's engine
 * (ISS-01M5RM2A7FFR9XWKATPX877TDD; osrs-dps-calc 89c3e25b PlayerVsNPCCalc
 * vampyre accuracy, damage, tier-2 transforms and immunity; PR #671). Each
 * vampyre is compared with its own twin minus the vampyre attribute, so the
 * expected numbers come from the same set's plain max hit and roll.
 */
class VampyreParityTest {
	private static final int SENTINEL = 9756;
	/** Any loaded juvinate: the loader folds combat-identical versions. */
	private static final int JUVINATE = -2;
	private static final int FERAL = 3237;
	private static final int EFARITAY = 21140;
	private static LoadoutData data;

	@BeforeAll
	static void load() {
		data = new DataService().load();
	}

	private static MonsterStats monster(int id) {
		return data.getMonsters().stream()
			.filter(m -> id == JUVINATE ? m.getNameLower().equals("vampyre juvinate") && m.hasAttribute("vampyre2")
				: m.getId() == id)
			.findFirst().orElseThrow(() -> new AssertionError("corpus is missing monster " + id));
	}

	/** The same monster without its vampyre tier: the plain baseline. */
	private static MonsterStats plain(int id) {
		MonsterStats m = monster(id);
		return m.withoutAttributes(-m.getId(), m.getVersion(), List.of("vampyre1", "vampyre2", "vampyre3"));
	}

	private static GearItem named(String name) {
		return data.getGearItems().stream()
			.filter(g -> g.getNameLower().equals(name) && !data.isVariant(g.getId()))
			.findFirst().orElseThrow(() -> new AssertionError("corpus is missing " + name));
	}

	private static Loadout wearing(Object... items) {
		Map<GearSlot, GearItem> gear = new EnumMap<>(GearSlot.class);
		for (Object item : items) {
			GearItem g = item instanceof Integer ? data.getGear((Integer) item) : named((String) item);
			gear.put(g.getSlot(), g);
		}
		return new Loadout(gear);
	}

	private static DpsResult calc(MonsterStats monster, CombatStyle style, PlayerLevels levels, PrayerBonuses prayers,
		SpellStats spell, Loadout loadout) {
		OptimizationRequest request = new OptimizationRequest(monster, style, levels, prayers, spell, 0,
			CandidateMode.ALL_STANDARD, true, false, OwnedItems.EMPTY, RequirementProfile.MAXED, 1);
		return new DpsCalculator().calculate(request, loadout);
	}

	private static DpsResult melee(MonsterStats monster, Loadout loadout) {
		return calc(monster, CombatStyle.MELEE, PlayerLevels.MAXED, PrayerBonuses.bestAvailable(PlayerLevels.MAXED),
			null, loadout);
	}

	/** Expected damage per attack of one uniform hit 0..max at this
	 * accuracy, each roll mapped through the transform. */
	private static double expected(double accuracy, int max, IntUnaryOperator perHit) {
		double sum = 0;
		for (int d = 0; d <= max; d++) {
			sum += perHit.applyAsInt(d);
		}
		return accuracy * sum / (max + 1);
	}

	@Test
	@DisplayName("the reference's own sentinel case: blisterwood stakes max 26, and 28 with Efaritay's aid")
	void referenceStakeCase() {
		PlayerLevels levels = new PlayerLevels(99, 99, 99, 112, 99, 99, 99);
		PrayerBonuses deadeye = PrayerBonuses.forPick(CombatStyle.RANGED, "Deadeye", PrayerBonuses.bestAvailable(levels));
		Object[] set = {11664, 22109, 19547, 33716, 13072, 13073, 8842, 19933};
		DpsResult without = calc(monster(SENTINEL), CombatStyle.RANGED, levels, deadeye, null, wearing(set));
		Object[] withRing = java.util.Arrays.copyOf(set, set.length + 1);
		withRing[set.length] = EFARITAY;
		DpsResult with = calc(monster(SENTINEL), CombatStyle.RANGED, levels, deadeye, null, wearing(withRing));
		assertNotNull(without, "the stake hurts a tier-3 vampyre");
		assertEquals(26, without.getMaxHit());
		assertEquals(28, with.getMaxHit());
	}

	@Test
	@DisplayName("the hallowed flail vs a sentinel: roll x1.25, then x23/20 with Efaritay's aid; max x1.25, the ring's x1.1 first")
	void hallowedFlailVsSentinel() {
		DpsResult base = melee(plain(SENTINEL), wearing("hallowed flail"));
		DpsResult bane = melee(monster(SENTINEL), wearing("hallowed flail"));
		DpsResult ring = melee(monster(SENTINEL), wearing("hallowed flail", EFARITAY));
		int max = base.getMaxHit();
		long roll = base.getAttackRoll();
		assertEquals(max * 125 / 100, bane.getMaxHit());
		assertEquals(roll * 125 / 100, bane.getAttackRoll());
		assertEquals((max * 11 / 10) * 125 / 100, ring.getMaxHit());
		assertEquals((roll * 125 / 100) * 23 / 20, ring.getAttackRoll());
	}

	@Test
	@DisplayName("the blisterwood flail and sickle get +5% accuracy and their own damage; the Ivandis flail damage only")
	void flailAndSickleBonuses() {
		for (Object[] row : new Object[][]{{"blisterwood flail", 105, 125}, {"blisterwood sickle", 105, 115},
			{"ivandis flail", 100, 120}}) {
			String name = (String) row[0];
			DpsResult base = melee(plain(SENTINEL), wearing(name));
			DpsResult bane = melee(monster(SENTINEL), wearing(name));
			assertEquals(base.getAttackRoll() * (int) row[1] / 100, bane.getAttackRoll(), name + " roll");
			assertEquals(base.getMaxHit() * (int) row[2] / 100, bane.getMaxHit(), name + " max");
		}
	}

	@Test
	@DisplayName("a juvinate: a whip is immune, Efaritay's aid halves every hit (the raised accurate 0 too)")
	void tierTwoRegularWeapon() {
		assertNull(melee(monster(JUVINATE), wearing("abyssal whip")), "regular weapons cannot hurt tier 2");
		DpsResult base = melee(plain(JUVINATE), wearing("abyssal whip"));
		DpsResult ring = melee(monster(JUVINATE), wearing("abyssal whip", EFARITAY));
		assertNotNull(ring);
		assertEquals(base.getMaxHit() / 2, ring.getMaxHit());
		double perAttack = expected(ring.getAccuracy(), base.getMaxHit(), d -> Math.max(1, d) / 2);
		assertEquals(perAttack / (ring.getAttackSpeed() * 0.6), ring.getDps(), 1e-9);
	}

	@Test
	@DisplayName("a juvinate: silver weapons cap at 10 (halved with the ring), the Ivandis flail x1.2 then capped, the sunspear x1.5 uncapped")
	void tierTwoSilverAndBane() {
		int silverlight = melee(plain(JUVINATE), wearing("silverlight")).getMaxHit();
		assertEquals(Math.min(silverlight, 10), melee(monster(JUVINATE), wearing("silverlight")).getMaxHit());
		assertEquals(silverlight / 2, melee(monster(JUVINATE), wearing("silverlight", EFARITAY)).getMaxHit());
		int ivandis = melee(plain(JUVINATE), wearing("ivandis flail")).getMaxHit();
		assertEquals(Math.min(ivandis * 6 / 5, 10), melee(monster(JUVINATE), wearing("ivandis flail")).getMaxHit());
		int sunspear = melee(plain(JUVINATE), wearing("sunspear")).getMaxHit();
		assertEquals(sunspear * 150 / 100, melee(monster(JUVINATE), wearing("sunspear")).getMaxHit());
		assertEquals(Math.min(melee(plain(JUVINATE), wearing("blisterwood sickle (e)")).getMaxHit(), 10),
			melee(monster(JUVINATE), wearing("blisterwood sickle (e)")).getMaxHit(), "the (e) sickle is tier-2 silver");
		assertNull(melee(monster(SENTINEL), wearing("blisterwood sickle (e)")), "and no tier-3 weapon");
	}

	@Test
	@DisplayName("a juvinate: silver bolts let a crossbow through, capped at 10; other bolts are immune; magic needs the ring")
	void tierTwoRangedAndMagic() {
		PrayerBonuses best = PrayerBonuses.bestAvailable(PlayerLevels.MAXED);
		int bolts = calc(plain(JUVINATE), CombatStyle.RANGED, PlayerLevels.MAXED, best, null,
			wearing("rune crossbow", 9145)).getMaxHit();
		assertEquals(Math.min(bolts, 10), calc(monster(JUVINATE), CombatStyle.RANGED, PlayerLevels.MAXED, best, null,
			wearing("rune crossbow", 9145)).getMaxHit());
		assertNull(calc(monster(JUVINATE), CombatStyle.RANGED, PlayerLevels.MAXED, best, null,
			wearing("rune crossbow", "adamant bolts")));
		SpellStats bolt = data.getSpells().stream().filter(s -> s.getName().equals("Fire Bolt")).findFirst().get();
		assertNull(calc(monster(JUVINATE), CombatStyle.MAGIC, PlayerLevels.MAXED, best, bolt, wearing("staff of fire")));
		int spell = calc(plain(JUVINATE), CombatStyle.MAGIC, PlayerLevels.MAXED, best, bolt, wearing("staff of fire")).getMaxHit();
		assertEquals(spell / 2, calc(monster(JUVINATE), CombatStyle.MAGIC, PlayerLevels.MAXED, best, bolt,
			wearing("staff of fire", EFARITAY)).getMaxHit());
	}

	@Test
	@DisplayName("a tier-1 vampyre: silverlight x1.1 (x1.1 again and +15% accuracy with the ring); a whip unchanged, ring or not")
	void tierOne() {
		DpsResult base = melee(plain(FERAL), wearing("silverlight"));
		assertEquals(base.getMaxHit() * 11 / 10, melee(monster(FERAL), wearing("silverlight")).getMaxHit());
		DpsResult ring = melee(monster(FERAL), wearing("silverlight", EFARITAY));
		assertEquals((base.getMaxHit() * 11 / 10) * 11 / 10, ring.getMaxHit());
		assertEquals(base.getAttackRoll() * 23 / 20, ring.getAttackRoll());
		int whip = melee(plain(FERAL), wearing("abyssal whip")).getMaxHit();
		assertEquals(whip, melee(monster(FERAL), wearing("abyssal whip")).getMaxHit());
		assertEquals(whip, melee(monster(FERAL), wearing("abyssal whip", EFARITAY)).getMaxHit());
	}

	@Test
	@DisplayName("the optimizer pairs an owned whip with an owned Efaritay's aid vs a juvinate, and finds nothing without the ring")
	void optimizerFindsTheRing() {
		OwnedItems both = new OwnedItems(Map.of(4151, 1, EFARITAY, 1), true);
		OptimizationRequest request = new OptimizationRequest(monster(JUVINATE), CombatStyle.MELEE, PlayerLevels.MAXED,
			PrayerBonuses.bestAvailable(PlayerLevels.MAXED), null, 0, CandidateMode.OWNED_ONLY, true, false, both,
			RequirementProfile.MAXED, 5);
		List<DpsResult> sets = new LoadoutOptimizer().optimize(data, request);
		assertFalse(sets.isEmpty(), "the ring makes the whip work");
		GearItem ring = sets.get(0).getLoadout().get(GearSlot.RING);
		assertNotNull(ring, "the set wears a ring");
		assertEquals("Efaritay's aid", ring.getName());
		assertEquals("Abyssal whip", sets.get(0).getLoadout().getWeapon().getName());
		OptimizationRequest whipOnly = new OptimizationRequest(monster(JUVINATE), CombatStyle.MELEE, PlayerLevels.MAXED,
			PrayerBonuses.bestAvailable(PlayerLevels.MAXED), null, 0, CandidateMode.OWNED_ONLY, true, false,
			new OwnedItems(Map.of(4151, 1), true), RequirementProfile.MAXED, 5);
		assertTrue(new LoadoutOptimizer().optimize(data, whipOnly).isEmpty(), "and nothing works without it");
	}

	@Test
	@DisplayName("Efaritay's aid stays in the ring pool vs a vampyre")
	void ringPoolKeepsEfaritay() {
		OptimizationRequest request = new OptimizationRequest(monster(SENTINEL), CombatStyle.MELEE, PlayerLevels.MAXED,
			PrayerBonuses.bestAvailable(PlayerLevels.MAXED), null, 0, CandidateMode.ALL_STANDARD, true, false,
			OwnedItems.EMPTY, RequirementProfile.MAXED, 1);
		assertTrue(new LoadoutOptimizer().preparePools(data, request).slotCandidates.get(GearSlot.RING).stream()
			.anyMatch(g -> g != null && g.getId() == EFARITAY));
	}
}

package com.loadoutlab.engine;

import com.loadoutlab.data.DataService;
import com.loadoutlab.data.GearItem;
import com.loadoutlab.data.LoadoutData;
import com.loadoutlab.data.MonsterStats;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import org.junit.Assert;
import org.junit.Test;

public class VampyreRulesTest {
	private static LoadoutData data;

	private static LoadoutData data() {
		if (data == null) {
			data = new DataService().load();
		}
		return data;
	}

	private static MonsterStats monster(String query) {
		return data().searchMonsters(query, 1).get(0);
	}

	private static GearItem byName(String name) {
		return data().getGearItems().stream()
			.filter(g -> g.getName().equalsIgnoreCase(name))
			.findFirst()
			.orElseThrow(() -> new AssertionError("missing item: " + name));
	}

	@Test
	public void regularWeaponsCannotDamageVyrewatchSentinels() {
		MonsterStats sentinel = monster("vyrewatch sentinel");
		Assert.assertTrue(sentinel.hasAttribute("vampyre3"));
		Assert.assertFalse(VampyreRules.canDamage(sentinel, CombatStyle.MELEE, byName("Abyssal whip")));
		Assert.assertTrue(VampyreRules.canDamage(sentinel, CombatStyle.MELEE, byName("Blisterwood flail")));
		Assert.assertTrue(VampyreRules.canDamage(sentinel, CombatStyle.MELEE, byName("Ivandis flail")));
	}

	@Test
	public void optimizerNeverSuggestsNonVyreWeaponsAgainstSentinels() {
		MonsterStats sentinel = monster("vyrewatch sentinel");
		Map<Integer, Integer> owned = new HashMap<>();
		owned.put(4151, 1); // abyssal whip - must NOT be suggested
		OptimizationRequest request = new OptimizationRequest(
			sentinel,
			CombatStyle.MELEE,
			PlayerLevels.MAXED,
			PrayerBonuses.bestAvailable(PlayerLevels.MAXED),
			null,
			0,
			CandidateMode.OWNED_ONLY,
			true,
			false,
			new OwnedItems(owned, true),
			RequirementProfile.MAXED,
			5);
		Assert.assertTrue("a whip cannot hit a tier-3 vampyre",
			new LoadoutOptimizer().optimize(data(), request).isEmpty());
	}

	@Test
	public void gameBestAgainstSentinelsUsesAVyreWeapon() {
		MonsterStats sentinel = monster("vyrewatch sentinel");
		OptimizationRequest request = new OptimizationRequest(
			sentinel,
			CombatStyle.MELEE,
			PlayerLevels.MAXED,
			PrayerBonuses.bestAvailable(PlayerLevels.MAXED),
			null,
			0,
			CandidateMode.ALL_STANDARD,
			true,
			false,
			OwnedItems.EMPTY,
			RequirementProfile.MAXED,
			1);
		List<DpsResult> results = new LoadoutOptimizer().optimize(data(), request);
		Assert.assertFalse(results.isEmpty());
		String weapon = results.get(0).getLoadout().getWeapon().getName().toLowerCase();
		Assert.assertTrue("expected a vyre-baneful weapon, got: " + weapon,
			VampyreRules.canDamage(sentinel, CombatStyle.MELEE, results.get(0).getLoadout().getWeapon()));
	}

	@Test
	public void tormentedDemonRangedBisUsesRealStatGearDespiteGuaranteedHits() {
		// Vs guaranteed-hit monsters all accuracy gear ties on DPS; the
		// attack-roll tie-break must still pick the strongest gear, and the
		// Avernic treads combos (wrongly non-standard upstream) must be in.
		MonsterStats td = data().searchMonsters("tormented demon", 1).get(0);
		OptimizationRequest request = new OptimizationRequest(
			td, CombatStyle.RANGED, PlayerLevels.MAXED,
			PrayerBonuses.bestAvailable(PlayerLevels.MAXED), null, 0,
			CandidateMode.ALL_STANDARD, true, false,
			OwnedItems.EMPTY, RequirementProfile.MAXED, 1);
		DpsResult best = new LoadoutOptimizer().optimize(data(), request).get(0);
		GearItem feet = best.getLoadout().get(com.loadoutlab.data.GearSlot.FEET);
		GearItem hands = best.getLoadout().get(com.loadoutlab.data.GearSlot.HANDS);
		Assert.assertNotNull(feet);
		Assert.assertTrue("expected avernic treads, got " + feet.getName(),
			feet.getName().toLowerCase().startsWith("avernic treads"));
		Assert.assertNotNull(hands);
		Assert.assertEquals("Zaryte vambraces", hands.getName());
	}

	/** The 2026-07-05 rule halved non-silver weapons vs tier 2; the
	 * official calc makes them immune unless Efaritay's aid is worn
	 * (ISS-01M5RM2A7FFR9XWKATPX877TDD - VampyreParityTest pins the maths). */
	@Test
	public void juvinatesNeedSilverAVampyrebaneWeaponOrEfaritaysAid() {
		MonsterStats juvinate = monster("vampyre juvinate");
		Assert.assertTrue(juvinate.hasAttribute("vampyre2"));
		Assert.assertTrue(VampyreRules.immune(juvinate, CombatStyle.MELEE, wearing("Abyssal whip")));
		Assert.assertFalse(VampyreRules.immune(juvinate, CombatStyle.MELEE, wearing("Abyssal whip", "Efaritay's aid")));
		Assert.assertFalse(VampyreRules.immune(juvinate, CombatStyle.MELEE, wearing("Blisterwood flail")));
		Assert.assertFalse(VampyreRules.immune(juvinate, CombatStyle.MELEE, wearing("Silverlight")));
		// Tier 1 and normal monsters: anything lands.
		Assert.assertFalse(VampyreRules.immune(monster("feral vampyre"), CombatStyle.MELEE, wearing("Abyssal whip")));
		Assert.assertFalse(VampyreRules.immune(monster("goblin"), CombatStyle.MELEE, wearing("Abyssal whip")));
	}

	private static Loadout wearing(String... names) {
		Map<com.loadoutlab.data.GearSlot, GearItem> gear = new java.util.EnumMap<>(com.loadoutlab.data.GearSlot.class);
		for (String name : names) {
			GearItem item = byName(name);
			gear.put(item.getSlot(), item);
		}
		return new Loadout(gear);
	}
}

