import net.runelite.api.Skill;
import org.junit.jupiter.api.BeforeAll;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertTrue;

/**
 * Vanstrom Klause in Sins of the Father (ISS-01M5RGMT70PG86MWHPF28DBJ3V,
 * raw on Discord 2026-10-24: "it tells me no usable melee set but I was
 * expecting it to tell me to use my blisterwood flail as the quest needs
 * you to defeat him with it"). The wiki files the flails and the rod of
 * Ivandis as one-handed staves that fight in melee (Bash/Pound/Focus,
 * crush); "no spells are capable of dealing damage to vampyres", and the
 * reference calculator makes a tier-3 vampyre immune to anything but a
 * melee flail/sickle/sunspear or a thrown blisterwood stake.
 */
class VanstromFlailTest {
	private static final int VANSTROM_SOTF = 9567;
	private static final int BLISTERWOOD_FLAIL = 24699;
	private static final int STAFF_OF_FIRE = 1387;
	private static LoadoutData data;

	@BeforeAll
	static void load() {
		data = new DataService().load();
	}

	private static MonsterStats vanstrom() {
		return data.searchMonsters("vanstrom klause", 10).stream()
			.filter(m -> m.getId() == VANSTROM_SOTF).findFirst()
			.orElseThrow(() -> new AssertionError("corpus is missing Vanstrom Klause (Sins of the Father)"));
	}

	private static GearItem named(String name) {
		return data.getGearItems().stream()
			.filter(g -> g.getNameLower().equals(name) && !data.isVariant(g.getId()))
			.findFirst().orElseThrow(() -> new AssertionError("corpus is missing " + name));
	}

	/** An ironman mid-quest: 70s in combat, Sins of the Father not finished. */
	private static OptimizationRequest request(CombatStyle style, CandidateMode mode, Map<Integer, Integer> owned) {
		PlayerLevels levels = new PlayerLevels(70, 70, 70, 70, 70, 52, 70);
		RequirementProfile profile = new RequirementProfile(Map.of(Skill.ATTACK, 70, Skill.STRENGTH, 70,
			Skill.DEFENCE, 70, Skill.RANGED, 70, Skill.MAGIC, 70, Skill.PRAYER, 52, Skill.HITPOINTS, 70), Set.of());
		return new OptimizationRequest(vanstrom(), style, levels, PrayerBonuses.bestAvailable(levels), null, 0,
			mode, true, false, new OwnedItems(owned, true), profile, 5);
	}

	@Test
	@DisplayName("the blisterwood flail, the Ivandis flail and the rod of Ivandis fight in melee; a plain staff still does not")
	void vampyreStavesAreMeleeWeapons() {
		for (String name : List.of("blisterwood flail", "ivandis flail", "rod of ivandis")) {
			assertTrue(named(name).isWeaponFor(CombatStyle.MELEE), name + " fights in melee");
		}
		assertTrue(named("blisterwood flail").isWeaponFor(CombatStyle.MAGIC), "and the flail still autocasts");
		assertFalse(named("staff of fire").isWeaponFor(CombatStyle.MELEE), "an ordinary staff stays out of melee");
	}

	@Test
	@DisplayName("an ironman owning the blisterwood flail gets a melee set for Vanstrom (Sins of the Father) that wields it")
	void ironmanMeleeSetWieldsTheFlail() {
		List<DpsResult> melee = new LoadoutOptimizer().optimize(data,
			request(CombatStyle.MELEE, CandidateMode.OWNED_ONLY, Map.of(BLISTERWOOD_FLAIL, 1)));
		assertFalse(melee.isEmpty(), "a melee set exists");
		assertEquals("Blisterwood flail", melee.get(0).getLoadout().getWeapon().getName());
		assertTrue(melee.get(0).getDps() > 0);
	}

	@Test
	@DisplayName("no spell damages a tier-3 vampyre: magic has no set vs Vanstrom, owned flail or best in slot")
	void magicCannotHurtVanstrom() {
		assertTrue(new LoadoutOptimizer().optimize(data, request(CombatStyle.MAGIC, CandidateMode.OWNED_ONLY,
			Map.of(BLISTERWOOD_FLAIL, 1, STAFF_OF_FIRE, 1))).isEmpty(), "the flail cannot autocast past the immunity");
		assertTrue(new LoadoutOptimizer().optimize(data, request(CombatStyle.MAGIC, CandidateMode.ALL_STANDARD,
			Map.of())).isEmpty(), "nor can any staff in the game");
		MonsterStats vanstrom = vanstrom();
		assertFalse(VampyreRules.canDamage(vanstrom, CombatStyle.MAGIC, named("blisterwood flail")));
		assertTrue(VampyreRules.canDamage(vanstrom, CombatStyle.MELEE, named("blisterwood flail")));
		assertTrue(VampyreRules.canDamage(vanstrom, CombatStyle.RANGED, named("blisterwood stake")));
		assertFalse(VampyreRules.canDamage(vanstrom, CombatStyle.MELEE, named("abyssal whip")));
	}
}

package com.loadoutlab.engine;

import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import static org.junit.jupiter.api.Assertions.*;

/**
 * Wiki (Venator bow, read 2026-10-19): in a multi area the arrow bounces
 * up to twice; each bounce rolls its own accuracy with a max hit of
 * two-thirds of the first, floored. Accuracy cancels, so the chain is
 * worth 1 + 2 x E(floor(2m/3)) / E(m) single hits.
 */
class VenatorFactorTest {
	@Test
	@DisplayName("a 30 max hit chains to about 2.34 single hits: 20-max bounces at the same accuracy")
	void thirtyMax() {
		double e30 = 30 / 2.0 + 1.0 / 31;
		double e20 = 20 / 2.0 + 1.0 / 21;
		assertEquals(1 + 2 * e20 / e30, RollMath.venatorFactor(30), 1e-12);
		assertEquals(2.337, RollMath.venatorFactor(30), 0.001);
	}

	@Test
	@DisplayName("the bounce max floors (31 -> 20) and a zero max hit chains nothing")
	void flooringAndZero() {
		double e31 = 31 / 2.0 + 1.0 / 32;
		double e20 = 20 / 2.0 + 1.0 / 21;
		assertEquals(1 + 2 * e20 / e31, RollMath.venatorFactor(31), 1e-12);
		assertEquals(1.0, RollMath.venatorFactor(0), 1e-12);
	}

	@Test
	@DisplayName("the tool factors: area tools scale with the stack up to nine, the chain needs a second target")
	void toolFactors() {
		assertEquals(3, MultiTool.factor("area", 3, 30), 1e-12);
		assertEquals(9, MultiTool.factor("area", 12, 30), 1e-12);
		assertEquals(1, MultiTool.factor("area", 1, 30), 1e-12);
		assertEquals(1, MultiTool.factor("chain", 1, 30), 1e-12);
		assertEquals(RollMath.venatorFactor(30), MultiTool.factor("chain", 5, 30), 1e-12);
	}
}

package com.loadoutlab.engine;

import com.loadoutlab.data.DataService;
import com.loadoutlab.data.GearItem;
import com.loadoutlab.data.GearSlot;
import com.loadoutlab.data.LoadoutData;
import com.loadoutlab.data.MonsterStats;
import java.util.EnumMap;
import org.junit.jupiter.api.BeforeAll;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import static org.junit.jupiter.api.Assertions.*;

/**
 * Void's set value lives entirely in the DPS model - the pieces carry
 * ~zero raw stats, so without pool seeding the zero-score prune dropped
 * the helm/gloves and a stocked bank's top-N cut dropped the top/robe:
 * the set could never assemble for a well-geared account (field question
 * 2026-07-17). These tests pin the seeding and the set math, including
 * the previously missing elite magic void damage.
 */
class VoidSetTest {
	private static LoadoutData data;
	private static MonsterStats ankou;

	@BeforeAll
	static void load() {
		data = new DataService().load();
		ankou = data.searchMonsters("ankou", 1).get(0);
	}

	private static GearItem byId(int id) {
		GearItem item = data.getGear(id);
		assertNotNull(item, "corpus is missing item " + id);
		return item;
	}

	private static OptimizationRequest request(CombatStyle style) {
		return new OptimizationRequest(ankou, style, PlayerLevels.MAXED,
			PrayerBonuses.NONE, null, 0,
			CandidateMode.ALL_STANDARD, true, false,
			OwnedItems.EMPTY, RequirementProfile.MAXED, 1);
	}

	@Test
	@DisplayName("every void piece is seeded into its style's candidate pool")
	void voidPiecesScoreIntoThePool() {
		// The shared pieces enter every style's pool; each helm only its own.
		int[] shared = {8839, 8840, 8842, 13072, 13073}; // top, robe, gloves, elite top, elite robe
		for (CombatStyle style : new CombatStyle[]{CombatStyle.MELEE, CombatStyle.RANGED, CombatStyle.MAGIC}) {
			for (int id : shared) {
				assertTrue(LoadoutOptimizer.candidateScore(request(style), byId(id), false) > 0,
					"piece " + id + " must be seeded for " + style);
			}
		}
		assertTrue(LoadoutOptimizer.candidateScore(request(CombatStyle.RANGED), byId(11664), false) > 0,
			"ranger helm seeds the ranged pool");
		assertTrue(LoadoutOptimizer.candidateScore(request(CombatStyle.MAGIC), byId(11663), false) > 0,
			"mage helm seeds the magic pool");
		assertTrue(LoadoutOptimizer.candidateScore(request(CombatStyle.MELEE), byId(11665), false) > 0,
			"melee helm seeds the melee pool");
		// The off-style helm stays unseeded (zero score - pruned).
		assertEquals(0.0, LoadoutOptimizer.candidateScore(request(CombatStyle.MELEE), byId(11664), false),
			1e-9, "ranger helm has no business in the melee pool");
	}

	@Test
	@DisplayName("elite magic void grants +2.5% magic damage on top of the 45% accuracy")
	void eliteMagicVoidDamage() {
		DpsResult regular = calcMagic(8839, 8840); // regular top + robe
		DpsResult elite = calcMagic(13072, 13073); // elite top + robe
		assertTrue(regular.getMaxHit() > 0);
		assertEquals((int) Math.floor(regular.getMaxHit() * 1.025), elite.getMaxHit(),
			"elite = floor(regular x 1.025)");
	}

	private DpsResult calcMagic(int topId, int robeId) {
		com.loadoutlab.data.SpellStats surge = data.getSpells().stream()
			.filter(sp -> sp.getName().equalsIgnoreCase("Fire Surge"))
			.findFirst().orElseThrow(() -> new AssertionError("no Fire Surge"));
		EnumMap<GearSlot, GearItem> gear = new EnumMap<>(GearSlot.class);
		gear.put(GearSlot.WEAPON, byName("kodai wand"));
		gear.put(GearSlot.HEAD, byId(11663));
		gear.put(GearSlot.BODY, byId(topId));
		gear.put(GearSlot.LEGS, byId(robeId));
		gear.put(GearSlot.HANDS, byId(8842));
		return new DpsCalculator().calculate(
			request(CombatStyle.MAGIC).withSpell(surge), new Loadout(gear));
	}

	private static GearItem byName(String nameLower) {
		for (GearItem item : data.getGearItems()) {
			if (item.getNameLower().equals(nameLower)) {
				return item;
			}
		}
		throw new AssertionError("corpus is missing: " + nameLower);
	}
}

