import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;

/** Andrew, 2026-10-15: "for the ancient wyvern it's not recommending wyvern
 * shield". Wiki (Skeletal Wyvern): an elemental, mind, dragonfire shield or
 * ward, or the ancient wyvern shield cuts the icy breath's max hit to 10;
 * Protect from Magic alone only brings it to 20. */
class WyvernShieldTest {
	@Test
	@DisplayName("the ancient wyvern's owned ranged set wears a breath shield with a one-handed weapon over a two-handed bow; without one the card keeps an answer")
	void breathShieldWins() {
		LoadoutData data = new DataService().load();
		MonsterStats wyvern = data.searchMonsters("ancient wyvern", 1).get(0);
		Map<Integer, Integer> owned = new HashMap<>();
		for (int id : new int[]{20997, 11212, 9185, 9144, 9731}) {
			owned.put(id, 1); // twisted bow + dragon arrows, rune crossbow + runite bolts, mind shield
		}
		List<DpsResult> results = new LoadoutOptimizer().optimize(data, request(data, wyvern, owned));
		assertFalse(results.isEmpty(), "a usable set exists");
		Loadout worn = results.get(0).getLoadout();
		assertEquals("rune crossbow", worn.getWeapon().getNameLower(), "the two-handed bow leaves the card");
		assertEquals("mind shield", worn.get(GearSlot.SHIELD).getNameLower());

		owned.remove(9731);
		List<DpsResult> without = new LoadoutOptimizer().optimize(data, request(data, wyvern, owned));
		assertFalse(without.isEmpty(), "no breath shield owned never empties the card");
	}

	private static OptimizationRequest request(LoadoutData data, MonsterStats mob, Map<Integer, Integer> owned) {
		return TestRequests.of(mob, CombatStyle.RANGED, PlayerLevels.MAXED,
			PrayerBonuses.bestAvailable(PlayerLevels.MAXED), null, 0, CandidateMode.OWNED_ONLY, true, false,
			new OwnedItems(owned, true), 1);
	}
}

package com.loadoutlab.engine;

import org.junit.Assert;
import org.junit.Test;

/**
 * Zeal (the Fractured Archive, 2026-10-20; wiki): 84 Prayer, 75 Attack
 * and 75 Strength, +25% accuracy / +28% strength, the tier above Piety.
 * Unlocked by a raid reward (VarbitID.PRAYER_ZEAL_UNLOCKED).
 */
public class ZealTest {
	private static final PrayerUnlocks NO_ZEAL = new PrayerUnlocks(true, true, true, true, true, false);

	@Test
	public void zealIsTheMeleeTierAbovePietyWithTheUnlock() {
		PrayerBonuses all = PrayerBonuses.bestAvailable(PlayerLevels.MAXED, PrayerUnlocks.ALL);
		Assert.assertEquals(1.25, all.getMeleeAccuracy(), 1e-9);
		Assert.assertEquals(1.28, all.getMeleeStrength(), 1e-9);
		Assert.assertEquals("Zeal", all.nameFor(CombatStyle.MELEE));
	}

	@Test
	public void withoutTheUnlockPietyStands() {
		PrayerBonuses noZeal = PrayerBonuses.bestAvailable(PlayerLevels.MAXED, NO_ZEAL);
		Assert.assertEquals(1.20, noZeal.getMeleeAccuracy(), 1e-9);
		Assert.assertEquals(1.23, noZeal.getMeleeStrength(), 1e-9);
		Assert.assertEquals("Piety", noZeal.nameFor(CombatStyle.MELEE));

		// The five-field form (older profiles, the harness) has no Zeal.
		PrayerBonuses legacy = PrayerBonuses.bestAvailable(PlayerLevels.MAXED,
			new PrayerUnlocks(true, true, true, true, true));
		Assert.assertEquals("Piety", legacy.nameFor(CombatStyle.MELEE));
		Assert.assertFalse(PrayerUnlocks.F2P.zeal());
		Assert.assertTrue(PrayerUnlocks.ALL.zeal());
		Assert.assertNotEquals("the cache key tells the two apart",
			PrayerUnlocks.ALL.key(), NO_ZEAL.key());
	}

	@Test
	public void theLevelGatesHoldPrayerAttackAndStrength() {
		Assert.assertEquals("Piety", PrayerBonuses.bestAvailable(
			new PlayerLevels(99, 99, 99, 99, 99, 83, 99), PrayerUnlocks.ALL).nameFor(CombatStyle.MELEE));
		Assert.assertEquals("Zeal", PrayerBonuses.bestAvailable(
			new PlayerLevels(99, 99, 99, 99, 99, 84, 99), PrayerUnlocks.ALL).nameFor(CombatStyle.MELEE));
		Assert.assertEquals("Piety", PrayerBonuses.bestAvailable(
			new PlayerLevels(74, 99, 99, 99, 99, 99, 99), PrayerUnlocks.ALL).nameFor(CombatStyle.MELEE));
		Assert.assertEquals("Piety", PrayerBonuses.bestAvailable(
			new PlayerLevels(99, 74, 99, 99, 99, 99, 99), PrayerUnlocks.ALL).nameFor(CombatStyle.MELEE));
	}

	@Test
	public void thePickerOffersZealFirst() {
		Assert.assertEquals("Zeal", PrayerBonuses.optionsFor(CombatStyle.MELEE)[0]);
		Assert.assertEquals("Piety", PrayerBonuses.optionsFor(CombatStyle.MELEE)[1]);
		PrayerBonuses best = PrayerBonuses.bestAvailable(PlayerLevels.MAXED, NO_ZEAL);
		PrayerBonuses zeal = PrayerBonuses.forPick(CombatStyle.MELEE, "Zeal", best);
		Assert.assertEquals(1.25, zeal.getMeleeAccuracy(), 1e-9);
		Assert.assertEquals(1.28, zeal.getMeleeStrength(), 1e-9);
		Assert.assertEquals("Zeal", zeal.nameFor(CombatStyle.MELEE));
	}
}

package com.loadoutlab.engine;

import com.loadoutlab.data.DataService;
