		}
		Map<?, ?> entry = (Map<?, ?>) ((List<?>) link.published.get("entries")).get(0);
		java.util.List<Object> categories = new java.util.ArrayList<>();
		for (Object node : (List<?>) entry.get("supplies")) {
			categories.add(((Map<?, ?>) node).get("category"));
		}
		assertEquals(List.of("shipRepairKit"), categories,
			"at sea the boat takes the hits - repair kits, no food");
	}

	@Test
	@DisplayName("repair kits recommend only when the mob can damage YOUR keel")
	void repairKitsFollowTheKeel() {
		java.util.function.BiFunction<String, String, Boolean> kitShown = (mobName, keel) -> {
			PageState state = new PageState();
			state.setParam("shipKeel", keel);
			CaptureLink link = new CaptureLink();
			CommandEngine engine = new CommandEngine(data, state,
				(mob, p, onDone) -> {
				},
				link);
			engine.setStoreOps(new TestStoreOps());
			engine.setOwnedCheck(id -> id == 31982); // a rosewood kit banked
			engine.setSupplyDefaults(() -> Map.of(
				com.loadoutlab.data.TripSupplies.SHIP_REPAIR_KIT, "DETECT_BEST"));
			MonsterStats mob = data.searchMonsters(mobName, 1).get(0);
			engine.execute("select", Map.of("id", mob.getId()));
			engine.onResults(mob, Map.of());
			try {
				javax.swing.SwingUtilities.invokeAndWait(() -> {
				});
			} catch (Exception ex) {
				throw new AssertionError(ex);
			}
			Map<?, ?> entry = (Map<?, ?>) ((List<?>) link.published.get("entries")).get(0);
			for (Object node : (List<?>) entry.get("supplies")) {
				if ("shipRepairKit".equals(((Map<?, ?>) node).get("category"))) {
					return true;
				}
			}
			return false;
		};
		// A hammerhead dents a keel-less boat (max 7): kits recommended.
		assertTrue(kitShown.apply("hammerhead shark", "none"));
		// The same shark cannot touch a dragon keel (max 0): no kits.
		assertFalse(kitShown.apply("hammerhead shark", "dragon"),
			"a mob doing 0 damage to your keel needs no repair kits");
		// Land mobs never see the category.
		assertFalse(kitShown.apply("general graardor", "none"));
	}
}

package com.loadoutlab.model;

import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import static org.junit.jupiter.api.Assertions.*;

/**
 * Andrew (client test 2026-10-19): Drakes suggested Water Surge while
 * thralls and Death Charge were on - an invalid state, since both are
 * cast from Arceuus and a standard autocast needs the standard book.
 * The rule he picked: the card stands down. A card whose autocast is on
 * another book carries an arceuusStandDown reason; the render shows its
 * number without the thrall fold and says why. Melee and ranged cards,
 * powered staves and Arceuus spells are untouched.
 */
class ArceuusStandDownTest {
	private static final Map<String, Object> BOOKS = Map.of(
		"Water Surge", "standard", "Ice Barrage", "ancient", "Dark Demonbane", "arceuus");

	private static Map<String, Object> card(String spell) {
		Map<String, Object> card = new LinkedHashMap<>();
		card.put("spell", spell);
		card.put("dps", 9.56);
		return card;
	}

	private static List<Object> page(String yoursSpell, String bisSpell) {
		Map<String, Object> magic = new LinkedHashMap<>();
		magic.put("yours", card(yoursSpell));
		magic.put("bis", card(bisSpell));
		Map<String, Object> melee = new LinkedHashMap<>();
		melee.put("yours", card(null));
		Map<String, Object> styles = new LinkedHashMap<>();
		styles.put("melee", melee);
		styles.put("magic", magic);
		Map<String, Object> mob = new LinkedHashMap<>();
		mob.put("styles", styles);
		List<Object> mobs = new ArrayList<>();
		mobs.add(mob);
		return mobs;
	}

	@SuppressWarnings("unchecked")
	private static String reason(List<Object> mobs, String style, String side) {
		Map<String, Object> styles = (Map<String, Object>) ((Map<?, ?>) mobs.get(0)).get("styles");
		Map<String, Object> card = (Map<String, Object>) ((Map<?, ?>) styles.get(style)).get(side);
		return (String) card.get("arceuusStandDown");
	}

	@Test
	@DisplayName("a standard or Ancients autocast stands thralls and Death Charge down, with the book named")
	void otherBooksStandDown() {
		List<Object> mobs = page("Water Surge", "Ice Barrage");
		CommandEngine.arceuusStandDown(mobs, BOOKS, true);
		assertEquals("Water Surge autocasts from the standard book", reason(mobs, "magic", "yours"));
		assertEquals("Ice Barrage autocasts from the ancient book", reason(mobs, "magic", "bis"));
		assertNull(reason(mobs, "melee", "yours"), "a melee card has no autocast");
	}

	@Test
	@DisplayName("an Arceuus spell, a powered staff and an unknown spell keep the fold")
	void arceuusAndStavesKeepIt() {
		List<Object> mobs = page("Dark Demonbane", null);
		CommandEngine.arceuusStandDown(mobs, BOOKS, true);
		assertNull(reason(mobs, "magic", "yours"));
		assertNull(reason(mobs, "magic", "bis"));
		List<Object> unknown = page("Mystery Bolt", null);
		CommandEngine.arceuusStandDown(unknown, BOOKS, true);
		assertNull(reason(unknown, "magic", "yours"), "no book on record, nothing to contradict");
	}

	@Test
	@DisplayName("with neither thralls nor Death Charge on, no card is marked")
	void nothingWantedNothingMarked() {
		List<Object> mobs = page("Water Surge", "Water Surge");
		CommandEngine.arceuusStandDown(mobs, BOOKS, false);
		assertNull(reason(mobs, "magic", "yours"));
		assertNull(reason(mobs, "magic", "bis"));
	}
}

package com.loadoutlab.model;

import java.util.Map;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import static org.junit.jupiter.api.Assertions.*;

/**
 * Field report 2026-08-31 (Not on Hand): "If i click and remove the prayer
 * shown, when I try to add it back there is no longer an option to do so."
 *
 * <p>The assume icons ARE the pickers. An empty assume label used to return
 * a null node, which erased both icons - picking None removed the only
 * control that could undo it. The empty state is now a real node with
 * sentinel values (-1), which the render side draws as the prayer-book
 * wings and the muted dash, both still clickable.
 */
class AssumeSentinelTest {
	@Test
	@DisplayName("an empty assume label yields sentinel pickers, never null")
	void emptyLabelKeepsThePickers() {
		for (String label : new String[]{null, ""}) {
			Map<String, Object> node = RenderModel.assumeNode(label);
			assertNotNull(node, "a null node erases the pickers (label=" + label + ")");
			assertEquals(-1, node.get("prayerSprite"), "sentinel prayer sprite");
			assertEquals(-1, node.get("boostItem"), "sentinel boost item");
			assertEquals("No prayer or boost", node.get("text"));
		}
	}

	@Test
	@DisplayName("real labels still resolve their icons")
	void realLabelsUnchanged() {
		Map<String, Object> node = RenderModel.assumeNode("Piety + Super combat");
		assertNotNull(node);
		assertTrue((int) node.get("prayerSprite") > 0, "Piety resolves a sprite");
		assertTrue((int) node.get("boostItem") > 0, "Super combat resolves an item");
	}

	/** Andrew 2026-09-02: the boost potion is a supply to bring - unless
	 * the raid hands it out (CoX overloads, ToA salts). */
	@Test
	@DisplayName("a raid-supplied boost is flagged so the supplies row does not pack it")
	void raidSuppliedBoostsAreFlagged() {
		Map<String, Object> potion = RenderModel.assumeNode("Rigour + Divine ranging potion");
		assertEquals(23733, potion.get("boostItem"));
		assertEquals(false, potion.get("boostSupplied"));
		assertEquals(true, RenderModel.assumeNode("Piety + Overload (+)").get("boostSupplied"));
		assertEquals(true, RenderModel.assumeNode("Piety + Smelling salts").get("boostSupplied"));
		assertEquals(false, RenderModel.assumeNode("Augury + Saturated heart").get("boostSupplied"));
	}
}

package com.loadoutlab.model;

import com.loadoutlab.data.DataService;
import com.loadoutlab.data.GearSlot;
import com.loadoutlab.data.LoadoutData;
import com.loadoutlab.data.MonsterStats;
import com.loadoutlab.data.WildernessMonsters;
import com.loadoutlab.engine.CombatStyle;
import com.loadoutlab.engine.OptimizationRequest;
import com.loadoutlab.engine.OwnedItems;
import com.loadoutlab.engine.PlayerLevels;
import com.loadoutlab.engine.PrayerUnlocks;
import com.loadoutlab.engine.RequirementProfile;
import com.loadoutlab.optimizer.OptimizerService;
import java.util.Collections;
import java.util.HashMap;
import java.util.Map;
import java.util.concurrent.CountDownLatch;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicReference;
import org.junit.jupiter.api.BeforeAll;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertTrue;

/** Andrew, field 2026-09-27 (Frost Nagua): "i'm seeing my occult necklace
 * count as bis but when i sim a amulet of fire the dps goes up". The gold
 * border compared slots with the game-best set, which casts from a Shadow;
 * on a Fire Bolt card the fire amulet beats the occult. The border now
 * stands only where nothing in the game beats the item IN YOUR SET. */
class BisBorderTest {
	private static final int OCCULT = 12002;
	private static final int PURGING_STAFF = 29594;
	private static final int SHADOW = 27275;

	private static LoadoutData data;

	@BeforeAll
	static void load() {
		data = new DataService().load();
	}

	private static OptimizerService.StyleResult magicAtFrostNagua(Map<Integer, Integer> owned) throws Exception {
		MonsterStats mob = data.searchMonsters("frost nagua", 1).get(0);
		OptimizerService service = new OptimizerService(data);
		try {
			CountDownLatch done = new CountDownLatch(1);
			AtomicReference<Map<CombatStyle, OptimizerService.StyleResult>> out = new AtomicReference<>();
			com.loadoutlab.engine.ComputeParams p = new com.loadoutlab.engine.ComputeParams();
			p.inWilderness = WildernessMonsters.isExclusive(mob);
			service.bestPerStyle(mob, PlayerLevels.MAXED, PlayerLevels.MAXED, PrayerUnlocks.ALL,
				RequirementProfile.MAXED, new OwnedItems(owned, true), 1, p,
				Collections.emptyMap(), Collections.emptySet(), Collections.emptyMap(), null, 0,
				Collections.<Integer>emptySet(), result -> {
					out.set(result);
					done.countDown();
				});
			assertTrue(done.await(120, TimeUnit.SECONDS), "compute finished");
			return out.get().get(CombatStyle.MAGIC);
		} finally {
			service.shutdown();
		}
	}

	@SuppressWarnings("unchecked")
	private static boolean neckBordered(OptimizerService.StyleResult result, Map<Integer, Integer> owned) {
		Map<String, Object> card = RenderModel.card(result, false, -1, owned::containsKey,
			Collections.emptySet());
		Map<String, Object> gear = (Map<String, Object>) card.get("gear");
		Map<String, Object> neck = (Map<String, Object>) gear.get("neck");
		return Boolean.TRUE.equals(neck.get("bisMatch"));
	}

	@Test
	@DisplayName("an occult on a Fire Bolt card loses the border: a fire amulet beats it in that set")
	void boltCard() throws Exception {
		Map<Integer, Integer> owned = new HashMap<>();
		owned.put(PURGING_STAFF, 1);
		owned.put(OCCULT, 1);
		OptimizerService.StyleResult result = magicAtFrostNagua(owned);
		assertEquals(OCCULT, result.owned.get(0).getLoadout().get(GearSlot.NECK).getId());
		assertEquals(OCCULT, result.overallBest.getLoadout().get(GearSlot.NECK).getId(),
			"game best (a Shadow) wears the occult");
		assertTrue(result.beaten.contains(GearSlot.NECK), "the neck is beaten in the Fire Bolt set");
		assertFalse(neckBordered(result, owned), "no gold border on the occult");
	}

	@Test
	@DisplayName("the same occult under a Shadow keeps the border")
	void shadowCard() throws Exception {
		Map<Integer, Integer> owned = new HashMap<>();
		owned.put(SHADOW, 1);
		owned.put(OCCULT, 1);
		OptimizerService.StyleResult result = magicAtFrostNagua(owned);
		assertEquals(SHADOW, result.owned.get(0).getLoadout().getWeapon().getId());
		assertFalse(result.beaten.contains(GearSlot.NECK));
		assertTrue(neckBordered(result, owned), "nothing beats the occult here");
	}
}

package com.loadoutlab.model;

import com.loadoutlab.data.DataService;
import com.loadoutlab.data.LoadoutData;
import com.loadoutlab.data.MonsterStats;
import com.loadoutlab.data.TripSupplies;
import java.util.ArrayList;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.function.IntPredicate;
import java.util.stream.Collectors;
import org.junit.jupiter.api.BeforeAll;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import static org.junit.jupiter.api.Assertions.*;

/**
 * Boss teleports (ISS-01M5RMNK62507Q42KKCJ9A7AEE, Kendyy and Andrew on
 * Discord 2026-10-24: "specific teleport items like the giantsoul amulet for
 * royal titans/obor/bryophta. zulrah has the specific zulrah teleport (or
 * master scroll book)"; Andrew's answers: "in the inventory for a boss", the
 * best one you own, a curated wiki-checked list).
 */
class BossTeleportTest {
	private static final String CATEGORY = "bossTeleport";
	private static final int ZUL_ANDRA = 12938;
	private static final int GIANTSOUL = 30638;
	private static final int RING_OF_SHADOWS = 28327;
	private static final int ARDEAGLAIS = 34033;
	private static final int PASSAGE_5 = 21146;
	private static LoadoutData data;

	@BeforeAll
	static void load() {
		data = new DataService().load();
	}

	private static final class CaptureLink extends CompanionLink {
		Map<String, Object> published;

		@Override
		public void publishPage(Map page) {
			published = page;
		}
	}

	/** The boss-teleport supply nodes of one trip: a mob by name, or a curated group. */
	private static List<Map<?, ?>> teleports(String query, boolean group, IntPredicate owns,
		Map<String, String> defaults, IntPredicate unlocked) {
		PageState state = new PageState();
		CaptureLink link = new CaptureLink();
		CommandEngine engine = new CommandEngine(data, state, (m, p, onDone) -> {
		}, link);
		engine.setStoreOps(new TestStoreOps());
		engine.setOwnedCheck(owns);
		engine.setSupplyDefaults(() -> defaults);
		engine.setUnlocks(unlocked);
		if (group) {
			engine.execute("select", Map.of("query", query));
			List<MonsterStats> mobs = state.rosterMobs();
			List<Map<com.loadoutlab.engine.CombatStyle, com.loadoutlab.optimizer.OptimizerService.StyleResult>> empty =
				new ArrayList<>();
			for (int i = 0; i < mobs.size(); i++) {
				empty.add(Map.of());
			}
			engine.onRosterResults(mobs, empty);
		} else {
			MonsterStats mob = data.searchMonsters(query, 1).get(0);
			engine.execute("select", Map.of("id", mob.getId()));
			engine.onResults(mob, Map.of());
		}
		try {
			javax.swing.SwingUtilities.invokeAndWait(() -> {
			});
		} catch (Exception ex) {
			throw new AssertionError(ex);
		}
		Map<?, ?> entry = (Map<?, ?>) ((List<?>) link.published.get("entries")).get(0);
		List<Map<?, ?>> out = new ArrayList<>();
		for (Object node : (List<?>) entry.get("supplies")) {
			if (CATEGORY.equals(((Map<?, ?>) node).get("category"))) {
				out.add((Map<?, ?>) node);
			}
		}
		return out;
	}

	private static List<Map<?, ?>> teleports(String mob, IntPredicate owns) {
		return teleports(mob, false, owns, Map.of(CATEGORY, "DETECT_BEST"), v -> false);
	}

	private static int itemId(Map<?, ?> node) {
		return ((Number) node.get("itemId")).intValue();
	}

	@Test
	@DisplayName("Zulrah with a Zul-andra teleport owned packs it - an inventory supply, not the utility strip")
	void zulrahPacksItsScroll() {
		List<Map<?, ?>> nodes = teleports("zulrah", id -> id == ZUL_ANDRA);
		assertEquals(1, nodes.size());
		assertEquals(ZUL_ANDRA, itemId(nodes.get(0)));
		assertEquals("Boss teleport", TripSupplies.label(CATEGORY));
		assertTrue(TripSupplies.options(CATEGORY).stream().noneMatch(o -> o.utility), "carried in the inventory");
	}

	@Test
	@DisplayName("the Royal Titans pair packs one giantsoul amulet")
	void royalTitansPackOneAmulet() {
		List<Map<?, ?>> nodes = teleports("Royal Titans", true, id -> id == GIANTSOUL,
			Map.of(CATEGORY, "DETECT_BEST"), v -> false);
		assertEquals(1, nodes.size(), "one amulet for the pair");
		assertEquals(GIANTSOUL, itemId(nodes.get(0)));
	}

	@Test
	@DisplayName("a mob no teleport serves gets no boss teleport, owning everything")
	void nonBossGetsNone() {
		assertTrue(teleports("abyssal demon", id -> true).isEmpty());
	}

	@Test
	@DisplayName("Zulrah's menu offers only the teleports that serve Zulrah")
	void menuListsTheBossOptionsOnly() {
		List<?> options = (List<?>) teleports("zulrah", id -> id == ZUL_ANDRA).get(0).get("options");
		assertEquals(List.of("ZUL_ANDRA_TELEPORT"),
			options.stream().map(o -> ((Map<?, ?>) o).get("key")).collect(Collectors.toList()));
	}

	@Test
	@DisplayName("the Mad Angel packs the Ardeaglais teleport, else the necklace of passage; its menu lists both, scroll first")
	void madAngelTeleports() {
		assertEquals(ARDEAGLAIS, itemId(teleports("mad angel", id -> id == ARDEAGLAIS || id == PASSAGE_5).get(0)));
		assertEquals(PASSAGE_5, itemId(teleports("mad angel", id -> id == PASSAGE_5).get(0)));
		List<?> options = (List<?>) teleports("mad angel", id -> id == PASSAGE_5).get(0).get("options");
		assertEquals(List.of("ARDEAGLAIS_TELEPORT", "NECKLACE_OF_PASSAGE"),
			options.stream().map(o -> ((Map<?, ?>) o).get("key")).collect(Collectors.toList()));
	}

	@Test
	@DisplayName("a stored giantsoul choice falls back to the best Zulrah teleport you own")
	void choiceForAnotherBossFallsBack() {
		List<Map<?, ?>> nodes = teleports("zulrah", false, id -> id == ZUL_ANDRA || id == GIANTSOUL,
			Map.of(CATEGORY, "GIANTSOUL_AMULET"), v -> false);
		assertEquals(ZUL_ANDRA, itemId(nodes.get(0)));
	}

	@Test
	@DisplayName("Duke Sucellus gets the ring of shadows only once its Ghorrock teleport is unlocked")
	void ringNeedsItsTablet() {
		assertTrue(teleports("duke sucellus", false, id -> id == RING_OF_SHADOWS,
			Map.of(CATEGORY, "DETECT_BEST"), v -> false).isEmpty(), "ring owned, Ghorrock still locked");
		List<Map<?, ?>> nodes = teleports("duke sucellus", false, id -> id == RING_OF_SHADOWS,
			Map.of(CATEGORY, "DETECT_BEST"), v -> v == 15142);
		assertEquals(RING_OF_SHADOWS, itemId(nodes.get(0)));
	}

	@Test
	@DisplayName("scrolls stored in the master scroll book read as owned - Zul-andra, Key master and Ardeaglais; the ring's set unlocks read back")
	void scrollBookCountsAsOwned() {
		assertEquals(Set.of(ZUL_ANDRA, 13249, ARDEAGLAIS), com.loadoutlab.collection.PotionStorage.owned(
			v -> v == 5683 ? 3 : v == 5684 ? 1 : v == 15749 ? 2 : 0).keySet());
		assertTrue(com.loadoutlab.collection.PotionStorage.tracks(5683), "a scroll stored or used re-reads ownership");
		assertEquals(Map.of(), com.loadoutlab.collection.PotionStorage.owned(v -> 0));
		assertEquals(Set.of(15142), TripSupplies.unlocked(v -> v == 15142 ? 1 : 0));
	}

	@Test
	@DisplayName("every boss a teleport names exists in the monster corpus")
	void everyBossExists() {
		Set<String> names = data.getMonsters().stream().map(m -> m.getName().toLowerCase()).collect(Collectors.toSet());
		for (TripSupplies.Option option : TripSupplies.options(CATEGORY)) {
			assertTrue(option.monsters.length > 0, option.key + " names its bosses");
			for (String boss : option.monsters) {
				assertTrue(names.contains(boss), option.key + " names " + boss + ", which the corpus lacks");
			}
		}
	}
}

package com.loadoutlab.model;

import com.loadoutlab.data.CombatAchievements;
import com.loadoutlab.data.DataService;
import com.loadoutlab.data.LoadoutData;
import com.loadoutlab.data.MonsterStats;
import com.loadoutlab.engine.*;
import java.util.List;
import java.util.Map;
import java.util.concurrent.atomic.AtomicInteger;
import java.util.concurrent.atomic.AtomicReference;
import org.junit.jupiter.api.BeforeAll;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import static org.junit.jupiter.api.Assertions.*;

/**
 * Stage 2 of the combat achievement chips (ISS-01M5XC7XYMMEN3Q4QC6CGZFVPK):
 * the task data, the caTask and requirements params into the compute, the
 * page's task list, the style lock and manual magic with no weapon.
 */
class CaChipsTest {
    private static LoadoutData data;

    @BeforeAll
    static void load() {
        data = new DataService().load();
    }

    private static final class Link extends CompanionLink {
        private Map<String, Object> last;

        @Override
        public void publishPage(Map page) { last = page; }

        @Override
        public Map<String, Object> lastPage() { return last; }
    }

    @Test
    @DisplayName("the four tasks load with their rules")
    void tasksLoad() {
        SetRules smasher = CombatAchievements.byId(161).getRules();
        assertEquals(java.util.Set.of("verac's flail"), smasher.getWeapons());
        assertTrue(smasher.getBanned().contains("ring of recoil") && smasher.getBanned().contains("echo boots"));
        assertEquals(java.util.Set.of(CombatStyle.MAGIC), CombatAchievements.byId(72).getRules().getStyles());
        SetRules.Rule weight = CombatAchievements.byId(631).getRules().getRules().get(0);
        assertEquals(List.of("weight", "<", 40.0), List.of(weight.getStat(), weight.getOp(), weight.getValue()));
        SetRules fit = CombatAchievements.byId(641).getRules();
        assertEquals(18, fit.getWeapons().size());
        assertTrue(fit.isNoWeaponMagic());
        assertEquals("Prayer Smasher", CombatAchievements.tasksFor(mob("Kalphite Queen")).get(0).getName());
    }

    @Test
    @DisplayName("caTask and requirements reach the compute as one set-param each, undo in one step, and a new search clears the task")
    void paramsReachTheCompute() throws Exception {
        AtomicInteger computes = new AtomicInteger();
        AtomicReference<ComputeParams> last = new AtomicReference<>();
        PageState state = new PageState();
        Link link = new Link();
        CommandEngine engine = new CommandEngine(data, state, (mob, p, onDone) -> {
            computes.incrementAndGet();
            last.set(p);
        }, link);
        // One form by id: the name opens the two-phase group, and the chips are single-mob.
        assertTrue(engine.execute("select", Map.of("id", mob("Kalphite Queen").getId())));
        assertNull(last.get().setRules, "no task, no requirements: no rules");
        engine.onResults(mob("Kalphite Queen"), Map.of());
        javax.swing.SwingUtilities.invokeAndWait(() -> { }); // the page publishes on the EDT
        @SuppressWarnings("unchecked")
        List<Map> tasks = (List<Map>) link.lastPage().get("caTasks");
        assertEquals("Prayer Smasher", tasks.get(0).get("name"));

        int before = computes.get();
        assertTrue(engine.execute("set-param", Map.of("param", "caPicks", "value", "161")));
        assertEquals(before + 1, computes.get(), "one recompute");
        assertEquals(java.util.Set.of("verac's flail"), last.get().setRules.getWeapons());

        assertTrue(engine.execute("set-param", Map.of("param", "requirements", "value", "prayer>=12;nonsense;def_ranged>=100")));
        assertEquals(2, last.get().setRules.getRules().size(), "the bad part is ignored");
        assertEquals("prayer", last.get().setRules.getRules().get(0).getStat());
        assertEquals(java.util.Set.of("verac's flail"), last.get().setRules.getWeapons(), "task and requirements together");

        assertTrue(engine.execute("undo", Map.of()));
        assertEquals("", state.paramsNode().get("requirements"), "undone in one step");

        assertTrue(engine.execute("select", Map.of("query", "vorkath")));
        assertEquals("", state.paramsNode().get("caPicks"), "a new search clears the task");
    }

    private static MonsterStats mob(String name) {
        return data.getMonsters().stream().filter(m -> m.getName().equalsIgnoreCase(name))
            .findFirst().orElseThrow(AssertionError::new);
    }

    private static List<DpsResult> best(String monster, CombatStyle style, SetRules rules) {
        OptimizationRequest request = new OptimizationRequest(mob(monster), style, PlayerLevels.MAXED,
            PrayerBonuses.bestAvailable(PlayerLevels.MAXED, new PrayerUnlocks(true, true, true, true, true)),
            null, 0, CandidateMode.ALL_STANDARD, true, false, OwnedItems.EMPTY, RequirementProfile.MAXED, 3)
            .withSetRules(rules);
        return new LoadoutOptimizer().optimize(data, request);
    }

    @Test
    @DisplayName("Mage of the Ruins: the style lock leaves melee with no set and magic with one")
    void styleLock() {
        SetRules mage = CombatAchievements.byId(72).getRules();
        assertTrue(best("Crazy archaeologist", CombatStyle.MELEE, mage).isEmpty());
        assertFalse(best("Crazy archaeologist", CombatStyle.MAGIC, mage).isEmpty());
    }

    @Test
    @DisplayName("Trying to fit in: magic casts with no weapon, since no Vampyrium weapon is a staff")
    void manualMagic() {
        List<DpsResult> results = best("Maggot King", CombatStyle.MAGIC, CombatAchievements.byId(641).getRules());
        assertFalse(results.isEmpty());
        assertNull(results.get(0).getLoadout().getWeapon());
    }
}

