import com.loadoutlab.testsupport.InMemoryConfigManager;
import java.util.ArrayList;
import java.util.HashSet;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Set;
import org.junit.jupiter.api.BeforeAll;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import static org.junit.jupiter.api.Assertions.*;

/**
 * Pins tied to sims (ISS-01M5HJ84ADBHWB2302G66WW2G4, Andrew 2026-10-22:
 * "it is showing me a fang, i dont have fang and i don't have it simmed" -
 * "yeah i think the ladder pin is causing this"). A tried swap simmed AND
 * pinned the fang; removing the sim left the pin. The engine's commands
 * against the REAL profile store.
 */
class PinsTiedToSimsTest {
	private static LoadoutData data;
	private MonsterProfileStore store;
	private final Set<Integer> owned = new HashSet<>();
	private final Set<Integer> globalSims = new HashSet<>();
	private CommandEngine engine;
	private int babaId;

	@BeforeAll
	static void load() {
		data = new DataService().load();
	}

	private static int id(String prefix) {
		return data.getGearItems().stream()
			.filter(g -> g.getNameLower().startsWith(prefix) && g.isStandardGear() && !data.isVariant(g.getId()))
			.findFirst().orElseThrow(() -> new AssertionError("no " + prefix)).getId();
	}

	@BeforeEach
	void setUp() {
		store = new MonsterProfileStore(InMemoryConfigManager.create(), new Gson());
		store.loadScope("std.1");
		engine = new CommandEngine(data, new PageState(), (mob, p, onDone) -> {
		}, new CompanionLink());
		engine.setStoreOps(new TestStoreOps() {
			@Override
			public Map<String, Map<GearSlot, Integer>> allPins(int monsterId) {
				return store.allPins(monsterId);
			}

			@Override
			public void pin(int monsterId, String scope, GearSlot slot, int itemId) {
				store.pin(monsterId, scope, slot, itemId);
			}

			@Override
			public void unpin(int monsterId, String scope, GearSlot slot) {
				store.unpin(monsterId, scope, slot);
			}

			@Override
			public void simForMob(int monsterId, int itemId) {
				store.addSim(monsterId, itemId, String.valueOf(itemId));
			}

			@Override
			public void removeMobSim(int monsterId, int itemId) {
				store.removeMobSim(monsterId, itemId);
			}

			@Override
			public List<Map> mobSims(int monsterId) {
				List<Map> out = new ArrayList<>();
				store.allSims(monsterId).forEach((simId, name) -> {
					Map<String, Object> row = new LinkedHashMap<>();
					row.put("id", simId);
					row.put("name", name);
					out.add(row);
				});
				return out;
			}

			@Override
			public boolean toggleSim(int itemId) {
				if (!globalSims.remove(itemId)) {
					globalSims.add(itemId);
				}
				return true;
			}
		});
		engine.setOwnedCheck(item -> owned.contains(item) || globalSims.contains(item));
		MonsterStats baba = data.searchMonsters("ba-ba", 1).get(0);
		babaId = baba.getId();
		assertTrue(engine.execute("select", Map.of("id", babaId)));
	}

	private Integer pinned(GearSlot slot) {
		return store.pinsFor(babaId, "MELEE").get(slot);
	}

	private Map<String, Object> fang() {
		return Map.of("slot", "weapon", "itemId", id("osmumten's fang"), "label", "Osmumten's fang");
	}

	@Test
	@DisplayName("removing the sim of a tried fang drops its pin too; one undo brings both back")
	void removeSimDropsPin() {
		int fang = id("osmumten's fang");
		assertTrue(engine.execute("ladder-try", fang()));
		assertEquals(Integer.valueOf(fang), pinned(GearSlot.WEAPON));
		assertTrue(engine.execute("remove-mob-sim", Map.of("itemId", fang, "label", "Osmumten's fang")));
		assertTrue(store.allSims(babaId).isEmpty());
		assertNull(pinned(GearSlot.WEAPON), "Andrew's Ba-Ba: the fang is gone with its sim");
		assertTrue(engine.execute("undo", Map.of()));
		assertTrue(store.allSims(babaId).containsKey(fang));
		assertEquals(Integer.valueOf(fang), pinned(GearSlot.WEAPON), "undo restores the pin");
	}

	@Test
	@DisplayName("an item you own keeps its pin when a sim of it goes")
	void ownedKeepsPin() {
		int fang = id("osmumten's fang");
		owned.add(fang);
		store.addSim(babaId, fang, "fang");
		store.pin(babaId, MonsterProfileStore.ALL, GearSlot.WEAPON, fang);
		assertTrue(engine.execute("remove-mob-sim", Map.of("itemId", fang, "label", "Osmumten's fang")));
		assertEquals(Integer.valueOf(fang), pinned(GearSlot.WEAPON));
	}

	@Test
	@DisplayName("Clear all sims drops their pins; undo restores them")
	void clearSimsDropsPins() {
		int fang = id("osmumten's fang");
		int torva = id("torva platebody");
		assertTrue(engine.execute("ladder-try", fang()));
		assertTrue(engine.execute("ladder-try", Map.of("slot", "body", "itemId", torva, "label", "Torva platebody")));
		assertTrue(engine.execute("clear-mob-list", Map.of("kind", "mobSims")));
		assertEquals(Map.of(), store.allPins(babaId));
		assertTrue(engine.execute("undo", Map.of()));
		assertEquals(Integer.valueOf(fang), pinned(GearSlot.WEAPON));
		assertEquals(Integer.valueOf(torva), pinned(GearSlot.BODY));
	}

	@Test
	@DisplayName("turning a global sim off drops its pin on the shown mob; undo restores")
	void globalSimOffDropsPin() {
		int fang = id("osmumten's fang");
		assertTrue(engine.execute("toggle-sim", Map.of("itemId", fang, "label", "Osmumten's fang")));
		assertTrue(engine.execute("pin", Map.of("slot", "weapon", "itemId", fang)));
		assertTrue(engine.execute("toggle-sim", Map.of("itemId", fang, "label", "Osmumten's fang")));
		assertFalse(globalSims.contains(fang));
		assertNull(pinned(GearSlot.WEAPON));
		assertTrue(engine.execute("undo", Map.of()));
		assertTrue(globalSims.contains(fang));
		assertEquals(Integer.valueOf(fang), pinned(GearSlot.WEAPON));
	}

	@Test
	@DisplayName("the pin list: pin an item into its own slot, remove one, clear all - each undoable")
	void pinList() {
		int fang = id("osmumten's fang");
		int torva = id("torva platebody");
		assertTrue(engine.execute("pin-for-mob", Map.of("itemId", fang, "label", "Osmumten's fang")));
		assertTrue(engine.execute("pin-for-mob", Map.of("itemId", torva, "label", "Torva platebody")));
		assertEquals(Integer.valueOf(fang), pinned(GearSlot.WEAPON), "into the item's own slot");
		assertEquals(Integer.valueOf(torva), pinned(GearSlot.BODY));

		assertTrue(engine.execute("remove-mob-pin",
			Map.of("itemId", fang, "label", "Osmumten's fang", "scope", "ALL", "slot", "weapon")));
		assertNull(pinned(GearSlot.WEAPON));
		assertTrue(engine.execute("undo", Map.of()));
		assertEquals(Integer.valueOf(fang), pinned(GearSlot.WEAPON));

		assertTrue(engine.execute("clear-mob-list", Map.of("kind", "mobPins")));
		assertEquals(Map.of(), store.allPins(babaId));
		assertTrue(engine.execute("undo", Map.of()));
		assertEquals(Integer.valueOf(torva), pinned(GearSlot.BODY));
		assertEquals(Integer.valueOf(fang), pinned(GearSlot.WEAPON));
	}
}

package com.loadoutlab.model;

import com.loadoutlab.data.DataService;
import com.loadoutlab.data.LoadoutData;
import com.loadoutlab.data.MonsterStats;
import java.util.List;
import java.util.Map;
import java.util.Set;
import org.junit.jupiter.api.BeforeAll;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import static org.junit.jupiter.api.Assertions.*;

/**
 * Ragnarrok2023, YouTube 2026-10-20: "3 iteming" on PvP worlds - an iron
 * using blighted supplies with skull prevention on wants the 3 kept
 * items as BiS plus a gp allowance for the rest. The wilderness risk
 * model already does exactly that; a PvP world turns it on for ANY mob
 * without the wilderness weapon buff. High Risk worlds keep nothing
 * (wiki: all items lost, Protect Item unusable).
 */
class PvpWorldTest {

	private static LoadoutData data;

	@BeforeAll
	static void load() {
		data = new DataService().load();
	}

	private static PageState pvp(int mode) {
		PageState state = new PageState();
		state.setParam("pvpWorld", mode);
		state.setParam("riskBudgetGp", 75_000);
		return state;
	}

	@Test
	@DisplayName("a PvP world with a bound cap keeps 3 items, 4 with Protect Item")
	void pvpWorldKeepsThree() {
		PageState state = pvp(1);
		assertEquals(3, state.computeParams().maxTradeables);
		state.setParam("protectItem", true);
		assertEquals(4, state.computeParams().maxTradeables);
	}

	@Test
	@DisplayName("a High Risk world keeps nothing, Protect Item or not")
	void highRiskKeepsNothing() {
		PageState state = pvp(2);
		assertEquals(0, state.computeParams().maxTradeables);
		state.setParam("protectItem", true);
		assertEquals(0, state.computeParams().maxTradeables);
	}

	@Test
	@DisplayName("a PvP world never switches on the wilderness weapon buff")
	void pvpWorldIsNotTheWilderness() {
		assertEquals(false, pvp(1).computeParams().inWilderness);
		assertEquals(false, pvp(2).computeParams().inWilderness);
	}

	@Test
	@DisplayName("the mode clamps to off / PvP / High Risk and is off by default")
	void modeClamps() {
		PageState state = new PageState();
		assertEquals(0, state.paramsNode().get("pvpWorld"));
		state.setParam("pvpWorld", 7);
		assertEquals(2, state.paramsNode().get("pvpWorld"));
		state.setParam("pvpWorld", -3);
		assertEquals(0, state.paramsNode().get("pvpWorld"));
		state.setParam("riskBudgetGp", 75_000);
		assertEquals(-1, state.computeParams().maxTradeables, "off means unconstrained off the wilderness");
	}

	@Test
	@DisplayName("the client-side flag is its own param, like f2pWorld")
	void hereFlagIsSeparate() {
		PageState state = new PageState();
		assertTrue(state.setParam("pvpWorldHere", true));
		assertEquals(Boolean.TRUE, state.paramsNode().get("pvpWorldHere"));
		assertEquals(0, state.paramsNode().get("pvpWorld"), "being on one does not pick the mode");
	}

	private static final class CaptureLink extends CompanionLink {
		Map<String, Object> published;

		@Override
		public void publishPage(Map page) {
			published = page;
		}
	}

	/** Graardor's page under the given mode, with a bank and a casting trip. */
	private static Map<?, ?> graardorEntry(int mode, Set<Integer> bank) {
		PageState state = new PageState();
		CaptureLink link = new CaptureLink();
		CommandEngine engine = new CommandEngine(data, state,
			(mob, p, onDone) -> {
			},
			link);
		engine.setStoreOps(new TestStoreOps());
		engine.setOwnedCheck(bank::contains);
		engine.setSupplyDefaults(() -> Map.of(
			com.loadoutlab.data.TripSupplies.FOOD, "DETECT_BEST"));
		engine.setMagicLevel(99);
		MonsterStats mob = data.searchMonsters("general graardor", 1).get(0);
		state.setParam("pvpWorld", mode);
		engine.execute("select", Map.of("id", mob.getId()));
		assertEquals(mode, state.paramsNode().get("pvpWorld"), "a selection keeps the world mode");
		state.setParam("riskBudgetGp", 75_000);
		state.setParam("thralls", true);
		engine.onResults(mob, WildernessReportTest.styles(data, mob));
		try {
			javax.swing.SwingUtilities.invokeAndWait(() -> {
			});
		} catch (Exception ex) {
			throw new AssertionError(ex);
		}
		assertNotNull(link.published, "a page published");
		Map<?, ?> entry = (Map<?, ?>) ((List<?>) link.published.get("entries")).get(0);
		return Map.of("entry", entry, "report", String.valueOf(link.published.get("reportText")));
	}

	@Test
	@DisplayName("a PvP-world report prices a death on a non-wilderness boss")
	void pvpReportCarriesRisk() {
		String report = (String) graardorEntry(1, Set.of()).get("report");
		assertTrue(report.contains("Risk:"), "a PvP-world answer must price a death:\n" + report);
		assertTrue(report.contains("PvP world: yes"), report);
		assertTrue(report.contains("Risk cap:"), report);
		String tame = (String) graardorEntry(0, Set.of()).get("report");
		assertFalse(tame.contains("Risk:"), "off means no risk talk");
		assertTrue(((String) graardorEntry(2, Set.of()).get("report")).contains("PvP world: High Risk"));
	}

	@Test
	@DisplayName("a PvP world offers only a locked pouch and prefers banked blighted food")
	void pvpKitAndSupplies() {
		Set<Integer> bank = Set.of(27281, 27509, 13441, 24592);
		Map<?, ?> entry = (Map<?, ?>) graardorEntry(1, bank).get("entry");
		Map<?, ?> mobNode = (Map<?, ?>) ((List<?>) entry.get("mobs")).get(0);
		assertEquals(27509, mobNode.get("castingPouch"), "the unlocked divine pouch is lost on a PvP death");
		assertTrue(supplyNames(entry).contains("Blighted anglerfish"), supplyNames(entry).toString());

		Map<?, ?> land = (Map<?, ?>) graardorEntry(0, bank).get("entry");
		assertFalse(supplyNames(land).contains("Blighted anglerfish"), "blighted food stays off normal worlds");
	}

	private static List<String> supplyNames(Map<?, ?> entry) {
		List<String> names = new java.util.ArrayList<>();
		for (Object supply : (List<?>) entry.get("supplies")) {
			names.add(String.valueOf(((Map<?, ?>) supply).get("name")));
		}
		return names;
	}
}

package com.loadoutlab.model;

import com.loadoutlab.data.DataService;
import com.loadoutlab.data.LoadoutData;
import com.loadoutlab.data.MonsterStats;
import com.loadoutlab.engine.CombatStyle;
import com.loadoutlab.engine.OptimizationRequest;
import com.loadoutlab.engine.OwnedItems;
import com.loadoutlab.engine.PlayerLevels;
import com.loadoutlab.engine.PrayerUnlocks;
import com.loadoutlab.engine.RequirementProfile;
import com.loadoutlab.optimizer.OptimizerService;
import com.loadoutlab.optimizer.ServiceCalls;
import java.util.Collections;
import java.util.HashMap;
import java.util.Map;
import java.util.concurrent.CountDownLatch;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicReference;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import static org.junit.jupiter.api.Assertions.*;

/**
 * Andrew 2026-09-02: the raid boosts live in the boost picker, not on a
 * chip. The picker already lists Overload (+) and Smelling salts; the
 * "Raid boost" chip was a second control for the same choice, so it goes
 * and DETECT on a raid mob resolves to the raid's own boost.
 */
class RaidBoostPickerTest {
	@Test
	@DisplayName("raidBoost is no longer a page param - the picker owns the choice")
	void raidBoostIsNotAPageParam() {
		PageState state = new PageState();
		assertFalse(state.setParam("raidBoost", false), "an unknown param is ignored");
		assertFalse(state.paramsNode().containsKey("raidBoost"));
	}

	@Test
	@DisplayName("DETECT on a raid mob assumes the raid boost; outside a raid it never does")
	void detectAssumesTheRaidBoost() throws Exception {
		LoadoutData data = new DataService().load();
		OptimizerService service = new OptimizerService(data);
		try {
			assertTrue(boostLabel(service, data, "tekton").contains("Overload (+)"),
				"CoX supplies overload (+)");
			assertFalse(boostLabel(service, data, "vorkath").contains("Overload (+)"),
				"no raid, no raid boost");
		} finally {
			service.shutdown();
		}
	}

	private static String boostLabel(OptimizerService service, LoadoutData data, String name)
		throws Exception {
		MonsterStats mob = data.searchMonsters(name, 1).get(0);
		Map<Integer, Integer> owned = new HashMap<>();
		owned.put(4151, 1); // abyssal whip: a melee set exists, no potions banked
		CountDownLatch done = new CountDownLatch(1);
		AtomicReference<Map<CombatStyle, OptimizerService.StyleResult>> got = new AtomicReference<>();
		ServiceCalls.bestPerStyle(service, mob, PlayerLevels.MAXED, PlayerLevels.MAXED,
			PrayerUnlocks.ALL, RequirementProfile.MAXED, new OwnedItems(owned, true),
			owned.hashCode(), false, false, "", Collections.emptySet(), -1,
			OptimizationRequest.DEFAULT_RISK_BUDGET_GP, false, Collections.emptySet(), 0,
			results -> {
				got.set(results);
				done.countDown();
			});
		assertTrue(done.await(120, TimeUnit.SECONDS));
		String label = got.get().get(CombatStyle.MELEE).boostLabel;
		return label == null ? "" : label;
	}
}

package com.loadoutlab.model;

import com.loadoutlab.data.DataService;
import com.loadoutlab.data.LoadoutData;
import java.util.List;
import java.util.Map;
import org.junit.jupiter.api.BeforeAll;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import static org.junit.jupiter.api.Assertions.*;

/**
 * Field reports 2026-08-31: raids opened at Inv 3 instead of 8 ("it must
 * not be counting theater of blood as a raid" - ToB has no supplied boost,
 * so the boost-coverage heuristic missed it), and the slayer-task chip lit
 * for raid selections (Skeletal Mystic's corpus slayer flag). The GROUP
 * DATA now owns both facts: its inventory seeds the slider, its raid flag
 * suppresses the task context.
 */
class RaidSelectionTest {
	private static LoadoutData data;

	@BeforeAll
	static void load() {
		data = new DataService().load();
	}

	private static final class CaptureLink extends CompanionLink {
		Map<String, Object> published;

		@Override
		public void publishPage(Map page) {
			published = page;
		}
	}

	private static Map<String, Object> selectGroup(String group,
		PageState state, CaptureLink link) {
		CommandEngine engine = new CommandEngine(data, state,
			(mob, p, onDone) -> {
			},
			link);
		engine.execute("select", Map.of("query", group));
		try {
			javax.swing.SwingUtilities.invokeAndWait(() -> {
			});
		} catch (Exception ex) {
			throw new AssertionError(ex);
		}
		return state.paramsNode();
	}

	@Test
	@DisplayName("every raid opens at its declared inventory - ToB included")
	void raidsOpenAtTwelve() {
		for (String raidName : new String[]{"Theatre of Blood (Entry)",
			"Theatre of Blood (Hard)", "Chambers of Xeric", "Tombs of Amascut"}) {
			PageState state = new PageState();
			Map<String, Object> params = selectGroup(raidName, state, new CaptureLink());
			// 12 since 2026-10-18 (mrapw: the shadow set lost at 10 in ToA).
			assertEquals(12, params.get("maxSwaps"), raidName + " must open at 12");
			assertEquals(Boolean.TRUE, params.get("raidSelection"), raidName);
		}
	}

	@Test
	@DisplayName("non-raid groups keep the 4-swap default and no raid flag")
	void groupsKeepFour() {
		PageState state = new PageState();
		Map<String, Object> params = selectGroup("Dagannoth Kings", state, new CaptureLink());
		assertEquals(4, params.get("maxSwaps"));
		assertEquals(Boolean.FALSE, params.get("raidSelection"));
	}

	@Test
	@DisplayName("the entry carries the raid flag the chip row suppresses on")
	void entryCarriesTheFlag() {
		PageState state = new PageState();
		CaptureLink link = new CaptureLink();
		CommandEngine engine = new CommandEngine(data, state,
			(mob, p, onDone) -> {
			},
			link);
		engine.execute("select", Map.of("query", "Chambers of Xeric"));
		List<com.loadoutlab.data.MonsterStats> mobs = state.rosterMobs();
		assertNotNull(mobs, "the group select must set a roster");
		List<Map<com.loadoutlab.engine.CombatStyle, com.loadoutlab.optimizer.OptimizerService.StyleResult>> empty =
			new java.util.ArrayList<>();
		for (int i = 0; i < mobs.size(); i++) {
			empty.add(Map.of());
		}
		engine.onRosterResults(mobs, empty);
		try {
			javax.swing.SwingUtilities.invokeAndWait(() -> {
			});
		} catch (Exception ex) {
			throw new AssertionError(ex);
		}
		assertNotNull(link.published);
		Map<?, ?> entry = (Map<?, ?>) ((List<?>) link.published.get("entries")).get(0);
		assertEquals(Boolean.TRUE, entry.get("raidSelection"));
	}

	@Test
	@DisplayName("a raid selection sheds stale wilderness and task context")
	void staleContextResets() {
		// The field setup: a wildy session left Wilderness + On task + a
		// risk cap behind, then a ToA select inherited all three and the
		// risk optimizer picked cheap-to-lose junk over real gear.
		PageState state = new PageState();
		state.setParam("inWilderness", true);
		state.setParam("onTask", true);
		state.setParam("riskBudgetGp", 75000);
		Map<String, Object> params = selectGroup("Tombs of Amascut", state, new CaptureLink());
		assertEquals(Boolean.FALSE, params.get("inWilderness"),
			"no ToA member is wilderness-capable - the param must reset");
		assertEquals(Boolean.FALSE, params.get("onTask"),
			"raids are never a slayer-task context");
	}

	@Test
	@DisplayName("arrow-nav opens each mob on its own recommended style (issue #15)")
	void lensClearsTheStickyTab() {
		PageState state = new PageState();
		state.setParam("selectedTab", "magic");
		state.setParam("lensIndex", 1);
		assertEquals("", state.paramsNode().get("selectedTab"),
			"a lens change must drop the previous mob's explicit tab");
	}
}

