			@Override
			public void simForMob(int monsterId, int itemId) {
				calls.add("sim " + monsterId + " " + itemId);
			}

			@Override
			public void removeMobSim(int monsterId, int itemId) {
				calls.add("unsim " + monsterId + " " + itemId);
