package com.loadoutlab.model;

import com.loadoutlab.data.DataService;
import com.loadoutlab.data.LoadoutData;
import com.loadoutlab.data.MonsterStats;
import java.util.Map;
import org.junit.jupiter.api.BeforeAll;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import static org.junit.jupiter.api.Assertions.*;

/**
 * A wilderness answer must say what it costs on death. Field report
 * 2026-08-22 (Artio): the CARD carried the risk line and the copied
 * report never mentioned risk at all, so a wildy answer read as
 * riskless on paper.
 */
class WildernessReportTest {
	private static LoadoutData data;

	@BeforeAll
	static void load() {
		data = new DataService().load();
	}

	private static String reportFor(String query) {
		CaptureLink link = new CaptureLink();
		PageState state = new PageState();
		CommandEngine engine = new CommandEngine(data, state,
			(mob, p, onDone) -> {
			},
			link);
		assertTrue(engine.execute("select", Map.of("query", query)));
		MonsterStats mob = state.mob();
		assertNotNull(mob, query + " selected");
		engine.onResults(mob, styles(mob));
		flushEdt();
		assertNotNull(link.published, "a page published");
		String report = (String) link.published.get("reportText");
		assertNotNull(report, "the page carries a report");
		return report;
	}

	private static Map<com.loadoutlab.engine.CombatStyle,
		com.loadoutlab.optimizer.OptimizerService.StyleResult> styles(MonsterStats mob) {
		return styles(data, mob);
	}

	/** Real per-style results for a mob - shared with WikiCalcExportTest. */
	static Map<com.loadoutlab.engine.CombatStyle,
		com.loadoutlab.optimizer.OptimizerService.StyleResult> styles(LoadoutData data, MonsterStats mob) {
		com.loadoutlab.optimizer.OptimizerService service =
			new com.loadoutlab.optimizer.OptimizerService(data);
		try {
			java.util.concurrent.CountDownLatch done = new java.util.concurrent.CountDownLatch(1);
			java.util.concurrent.atomic.AtomicReference<Map<com.loadoutlab.engine.CombatStyle,
				com.loadoutlab.optimizer.OptimizerService.StyleResult>> out =
				new java.util.concurrent.atomic.AtomicReference<>();
			com.loadoutlab.optimizer.ServiceCalls.bestPerStyle(service, mob,
				com.loadoutlab.engine.PlayerLevels.MAXED,
				com.loadoutlab.engine.PlayerLevels.MAXED,
				com.loadoutlab.engine.PrayerUnlocks.ALL,
				com.loadoutlab.engine.RequirementProfile.MAXED,
				com.loadoutlab.engine.OwnedItems.EMPTY, 0,
				false, false, "",
				new java.util.EnumMap<>(com.loadoutlab.engine.CombatStyle.class), -1,
				com.loadoutlab.engine.OptimizationRequest.DEFAULT_RISK_BUDGET_GP, false, false,
				java.util.Collections.emptySet(), 0,
				java.util.Collections.emptyMap(), null, 0, java.util.Collections.emptySet(),
				r -> {
					out.set(r);
					done.countDown();
				});
			assertTrue(done.await(300, java.util.concurrent.TimeUnit.SECONDS));
			return out.get();
		} catch (InterruptedException ex) {
			throw new AssertionError(ex);
		} finally {
			service.shutdown();
		}
	}

	private static void flushEdt() {
		try {
			javax.swing.SwingUtilities.invokeAndWait(() -> {
			});
		} catch (Exception ex) {
			throw new AssertionError(ex);
		}
	}

	@Test
	@DisplayName("a wilderness boss report states the per-death risk")
	void wildernessReportCarriesRisk() {
		String report = reportFor("artio");
		assertTrue(report.contains("Risk:"),
			"the wildy report must price a death:\n" + report);
		assertTrue(report.contains("Risk cap:"),
			"the params must show the cap state:\n" + report);
	}

	@Test
	@DisplayName("a non-wilderness report stays quiet about risk")
	void tameReportHasNoRiskLine() {
		String report = reportFor("general graardor");
		assertFalse(report.contains("Risk:"), "no risk talk outside the wilderness");
	}

	private static final class CaptureLink extends CompanionLink {
		Map<String, Object> published;

		@Override
		public void publishPage(Map page) {
			published = page;
		}
	}
}

package com.loadoutlab.model;

import com.loadoutlab.data.DataService;
import com.loadoutlab.data.LoadoutData;
import com.loadoutlab.data.MonsterStats;
import java.util.List;
import java.util.Map;
import java.util.Set;
import org.junit.jupiter.api.BeforeAll;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import static org.junit.jupiter.api.Assertions.*;

/**
 * Field report 2026-08-31 (Andrew, with the wiki passage): the divine rune
 * pouch is LOST on a pvp death in the Wilderness unless trouver-locked, so
 * the wilderness never recommends an unlocked pouch - a locked one (divine
 * 27509, then regular 24416) or none at all. Land trips are unchanged.
 */
class WildyPouchTest {
	private static LoadoutData data;

	@BeforeAll
	static void load() {
		data = new DataService().load();
	}

	private static final class CaptureLink extends CompanionLink {
		Map<String, Object> published;

		@Override
		public void publishPage(Map page) {
			published = page;
		}
	}

	private Object pouchFor(Set<Integer> bank, boolean wildy) {
		// Callisto is wilderness-EXCLUSIVE (select forces the param), so the
		// land case uses Graardor - a Callisto trip cannot be a land trip.
		PageState state = new PageState();
		CaptureLink link = new CaptureLink();
		CommandEngine engine = new CommandEngine(data, state,
			(mob, p, onDone) -> {
			},
			link);
		engine.setStoreOps(new TestStoreOps());
		engine.setOwnedCheck(bank::contains);
		engine.setMagicLevel(99);
		MonsterStats mob = data.searchMonsters(wildy ? "callisto" : "general graardor", 1).get(0);
		engine.execute("select", Map.of("id", mob.getId()));
		state.setParam("thralls", true); // a casting trip, so the kit renders
		if (wildy) {
			state.setParam("inWilderness", true);
		}
		engine.onResults(mob, Map.of());
		try {
			javax.swing.SwingUtilities.invokeAndWait(() -> {
			});
		} catch (Exception ex) {
			throw new AssertionError(ex);
		}
		Map<?, ?> entry = (Map<?, ?>) ((List<?>) link.published.get("entries")).get(0);
		Map<?, ?> mobNode = (Map<?, ?>) ((List<?>) entry.get("mobs")).get(0);
		return mobNode.get("castingPouch");
	}

	@Test
	@DisplayName("the wilderness never recommends an unlocked pouch - locked or nothing")
	void wildyPouchIsLockedOrNothing() {
		// Unlocked divine owned: recommended on land, NEVER in the wildy.
		assertEquals(27281, pouchFor(Set.of(27281), false));
		assertNull(pouchFor(Set.of(27281), true),
			"an unlocked divine pouch is LOST on a pvp death - never recommended");
		// A trouver-locked pouch is the wildy answer when owned.
		assertEquals(27509, pouchFor(Set.of(27281, 27509), true));
		assertEquals(24416, pouchFor(Set.of(24416), true));
	}

	/** Andrew's rule 2026-08-31: the inventory is part of what is lost or
	 * kept. Trip quantities are unknown, so the kit is listed by FATE:
	 * locked pouch and untradeable cape kept; the runes (a locked pouch
	 * does not protect its contents - wiki) and every supply pick lost. */
	@Test
	@DisplayName("the carried kit joins the lost/kept lists by fate")
	void carriedKitFates() {
		Map<String, List<String>> fates = CommandEngine.wildyCarriedFates(
			27509, true, List.of("Anglerfish", "Super restore"), true);
		assertEquals(List.of("Divine rune pouch (locked - kept)", "Magic cape (kept)"),
			fates.get("kept"));
		assertEquals(List.of("Trip runes (lost)", "Anglerfish (lost)", "Super restore (lost)"),
			fates.get("lost"));
		assertEquals(List.of("Rune pouch (locked - kept)"),
			CommandEngine.wildyCarriedFates(24416, false, List.of(), false).get("kept"));
		// No pouch, no cape, no casts, no supplies: nothing to say.
		Map<String, List<String>> none = CommandEngine.wildyCarriedFates(-1, false, List.of(), false);
		assertTrue(none.get("kept").isEmpty() && none.get("lost").isEmpty());
	}
}

