import java.util.Collections;
import java.util.Map;
import java.util.Set;
import java.util.concurrent.CountDownLatch;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicReference;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import static org.junit.jupiter.api.Assertions.*;

/**
 * Best in game is the true ceiling (ISS-01M5JM0FATFKQ93PS3Z5MV54M1, Andrew 2026-10-22: "in the
 * old client, i was able to generate a better "BiS" set than what came up in
 * search" - his Obligator exclusion was holding the ceiling down; answer
 * "BiS ignores exclusions (Recommended)").
 */
class BisIgnoresExclusionsTest {
	private static OptimizerService.StyleResult melee(LoadoutData data, MonsterStats mob,
		Map<CombatStyle, Set<Integer>> excluded) throws Exception {
		OptimizerService service = new OptimizerService(data);
		try {
			CountDownLatch done = new CountDownLatch(1);
			AtomicReference<Map<CombatStyle, OptimizerService.StyleResult>> out = new AtomicReference<>();
			ComputeParams p = new ComputeParams();
			p.specWeapon = false;
			service.bestPerStyle(mob, PlayerLevels.MAXED, PlayerLevels.MAXED, PrayerUnlocks.ALL,
				RequirementProfile.MAXED, new OwnedItems(Map.of(4151, 1), true), 1, p,
				excluded, Collections.emptySet(), Collections.emptyMap(), null, 0,
				Collections.<Integer>emptySet(), result -> {
					out.set(result);
					done.countDown();
				});
			assertTrue(done.await(300, TimeUnit.SECONDS));
			return out.get().get(CombatStyle.MELEE);
		} finally {
			service.shutdown();
		}
	}

	@Test
	@DisplayName("excluding the best weapon leaves Best in game wearing it - exclusions shape Yours only")
	void exclusionsLeaveTheCeiling() throws Exception {
		LoadoutData data = new DataService().load();
		MonsterStats demon = data.searchMonsters("abyssal demon", 1).get(0);
		int bisWeapon = melee(data, demon, Map.of()).overallBest.getLoadout().getWeapon().getId();
		OptimizerService.StyleResult excluded = melee(data, demon, Map.of(CombatStyle.MELEE, Set.of(bisWeapon)));
		assertEquals(bisWeapon, excluded.overallBest.getLoadout().getWeapon().getId(),
			"the ceiling ignores the exclusion");
	}
}

package com.loadoutlab.optimizer;

import com.loadoutlab.data.DataService;
import com.loadoutlab.data.GearItem;
import com.loadoutlab.data.GearSlot;
import com.loadoutlab.data.LoadoutData;
import com.loadoutlab.data.MonsterStats;
import com.loadoutlab.data.SpellStats;
import com.loadoutlab.engine.CombatStyle;
import com.loadoutlab.engine.OptimizationRequest;
import com.loadoutlab.engine.OwnedItems;
import com.loadoutlab.engine.PlayerLevels;
import com.loadoutlab.engine.PrayerUnlocks;
import com.loadoutlab.engine.RequirementProfile;
import java.util.Collections;
import java.util.HashMap;
import java.util.Map;
import java.util.concurrent.CountDownLatch;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicReference;
import org.junit.jupiter.api.BeforeAll;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertTrue;

/** Field report (Andrew, 2026-09-08): simmed chaos gauntlets never beat
 * the tormented bracelet on a Fire Bolt card. The per-slot pool keeps the
 * top ten by raw magic stats and the gauntlets score zero there - their
 * value lives in the DPS model, like the leaf-bladed battleaxe. Same for
 * the element amulets, which tie a crowd of glories at +10. */
class BoltGearPoolTest {
	private static LoadoutData data;
	private static MonsterStats goblin;

	@BeforeAll
	static void load() {
		data = new DataService().load();
		goblin = data.searchMonsters("Goblin", 1).get(0);
	}

	@Test
	@DisplayName("chaos gauntlets reach the beam past ten better-statted gloves and win the Fire Bolt card")
	void gauntlets() throws Exception {
		Map<Integer, Integer> owned = own("staff of fire", "occult necklace", "chaos gauntlets", "tormented bracelet",
			"barrows gloves", "infinity gloves", "dragon gloves", "rune gloves", "lunar gloves", "bloodbark gauntlets",
			"adamant gloves", "swampbark gauntlets", "regen bracelet", "mystic gloves");
		assertEquals(777, slot(owned, "Fire Bolt", GearSlot.HANDS).getId(), "chaos gauntlets: 16 max hit beats 13");
	}

	@Test
	@DisplayName("an amulet of air reaches the beam past ten +10 necks and wins the Wind Bolt card")
	void elementAmulet() throws Exception {
		Map<Integer, Integer> owned = own("staff of air", "occult necklace", "amulet of air", "amulet of fury",
			"amulet of glory", "amulet of magic", "amulet of magic (t)", "dragonbone necklace", "bonecrusher necklace",
			"3rd age amulet", "amulet of the damned", "amulet of power", "amulet of glory (t)");
		assertEquals(34407, slot(owned, "Wind Bolt", GearSlot.NECK).getId(), "amulet of air: 14 max hit beats 13");
	}

	private static Map<Integer, Integer> own(String... names) {
		Map<Integer, Integer> owned = new HashMap<>();
		for (String name : names) {
			owned.put(byName(name).getId(), 1);
		}
		return owned;
	}

	private static GearItem byName(String nameLower) {
		for (GearItem g : data.getGearItems()) {
			if (g.getNameLower().equals(nameLower)) {
				return g;
			}
		}
		throw new AssertionError("missing from the gear data: " + nameLower);
	}

	private static GearItem slot(Map<Integer, Integer> owned, String spellName, GearSlot slot) throws Exception {
		SpellStats spell = data.getSpells().stream().filter(s -> s.getName().equals(spellName)).findFirst().orElseThrow();
		OptimizerService service = new OptimizerService(data);
		try {
			CountDownLatch done = new CountDownLatch(1);
			AtomicReference<Map<CombatStyle, OptimizerService.StyleResult>> out = new AtomicReference<>();
			ServiceCalls.bestPerStyle(service, goblin, PlayerLevels.MAXED, PlayerLevels.MAXED,
				PrayerUnlocks.ALL, RequirementProfile.MAXED, new OwnedItems(owned, true), 1, false, false, "",
				Collections.emptySet(), -1, OptimizationRequest.DEFAULT_RISK_BUDGET_GP, false, Collections.emptySet(), 0,
				Collections.emptyMap(), spell, results -> {
					out.set(results);
					done.countDown();
				});
			assertTrue(done.await(120, TimeUnit.SECONDS));
			return out.get().get(CombatStyle.MAGIC).owned.get(0).getLoadout().get(slot);
		} finally {
			service.shutdown();
		}
	}
}

package com.loadoutlab.optimizer;

import com.loadoutlab.engine.BoostProfile;
import com.loadoutlab.engine.CombatStyle;
import com.loadoutlab.engine.OwnedItems;
import com.loadoutlab.engine.PlayerLevels;
import java.util.HashMap;
import java.util.Map;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import static org.junit.jupiter.api.Assertions.*;

/**
 * Risk-capped wilderness searches never assume a heart (field spec
 * 2026-07-18): both hearts are tradeable and worth far more than any
 * sane risk cap - the magic assumption falls back to the potion.
 */
class BoostSelectorTest {
	@Test
	@DisplayName("a risk-capped wildy search downgrades the heart to a magic potion")
	void noHeartsUnderARiskCap() {
		Map<Integer, Integer> owned = new HashMap<>();
		owned.put(27641, 1); // saturated heart
		owned.put(3040, 1);  // magic potion(4) - the fallback must be OWNED now
		OwnedItems bag = new OwnedItems(owned, true);
		assertEquals(BoostProfile.SATURATED_HEART,
			BoostSelector.bestFor(CombatStyle.MAGIC, bag, false, false));
		assertEquals(BoostProfile.MAGIC,
			BoostSelector.bestFor(CombatStyle.MAGIC, bag, false, true));
	}

	@Test
	@DisplayName("the BiS ceiling assumes divine potions for melee and ranged")
	void ceilingPrefersDivine() {
		assertEquals(BoostProfile.DIVINE_SUPER_COMBAT,
			BoostSelector.ceilingFor(CombatStyle.MELEE, false));
		assertEquals(BoostProfile.DIVINE_RANGING,
			BoostSelector.ceilingFor(CombatStyle.RANGED, false));
		assertEquals(BoostProfile.SATURATED_HEART,
			BoostSelector.ceilingFor(CombatStyle.MAGIC, false),
			"the heart out-boosts the flat divine magic potion");
	}

	@Test
	@DisplayName("owned divine potions are preferred over the base assumption")
	void ownedDivinePreferred() {
		Map<Integer, Integer> owned = new HashMap<>();
		owned.put(23691, 1); // divine super combat (2) - any dose counts
		owned.put(23733, 1); // divine ranging (4)
		owned.put(23754, 1); // divine magic (1)
		OwnedItems bag = new OwnedItems(owned, true);
		assertEquals(BoostProfile.DIVINE_SUPER_COMBAT,
			BoostSelector.bestFor(CombatStyle.MELEE, bag, false, false));
		assertEquals(BoostProfile.DIVINE_RANGING,
			BoostSelector.bestFor(CombatStyle.RANGED, bag, false, false));
		assertEquals(BoostProfile.DIVINE_MAGIC,
			BoostSelector.bestFor(CombatStyle.MAGIC, bag, false, false));
	}

	@Test
	@DisplayName("an empty bank assumes NO boost - not a potion you do not own")
	void emptyBankAssumesNothing() {
		// RE-PINNED 2026-08-25. This test previously asserted SUPER_COMBAT /
		// RANGING / MAGIC for an EMPTY bank, encoding the old "tradeables are
		// always assumed" rule. Field report from a fresh ironman: the card
		// claimed "Assumes: Ranging potion" with none in the bank and the panel
		// set to detect from bank. The old expectations were the defect.
		OwnedItems empty = new OwnedItems(new HashMap<>(), true);
		assertEquals(BoostProfile.NONE,
			BoostSelector.bestFor(CombatStyle.MELEE, empty, false, false));
		assertEquals(BoostProfile.NONE,
			BoostSelector.bestFor(CombatStyle.RANGED, empty, false, false));
		assertEquals(BoostProfile.NONE,
			BoostSelector.bestFor(CombatStyle.MAGIC, empty, false, false));
	}

	@Test
	@DisplayName("owning the base potion still assumes it")
	void ownedBasePotionsAreAssumed() {
		Map<Integer, Integer> owned = new HashMap<>();
		owned.put(12695, 1);  // super combat potion(4)
		owned.put(2444, 1);   // ranging potion(4)
		owned.put(3040, 1);   // magic potion(4)
		OwnedItems bag = new OwnedItems(owned, true);
		assertEquals(BoostProfile.SUPER_COMBAT,
			BoostSelector.bestFor(CombatStyle.MELEE, bag, false, false));
		assertEquals(BoostProfile.RANGING,
			BoostSelector.bestFor(CombatStyle.RANGED, bag, false, false));
		assertEquals(BoostProfile.MAGIC,
			BoostSelector.bestFor(CombatStyle.MAGIC, bag, false, false));
	}

	@Test
	@DisplayName("bastion outranks ranging, battlemage outranks magic - even divine ones")
	void bastionAndBattlemageOutrankThePlainFamily() {
		Map<Integer, Integer> owned = new HashMap<>();
		owned.put(22461, 1);  // bastion potion(4)
		owned.put(22449, 1);  // battlemage potion(4)
		OwnedItems bag = new OwnedItems(owned, true);
		assertEquals(BoostProfile.BASTION,
			BoostSelector.bestFor(CombatStyle.RANGED, bag, false, false));
		assertEquals(BoostProfile.BATTLEMAGE,
			BoostSelector.bestFor(CombatStyle.MAGIC, bag, false, false));

		// Same offensive numbers plus a defence half, so bastion/battlemage win
		// even against the DIVINE plain variants (owner call 2026-08-25).
		owned.put(23733, 1);  // divine ranging potion(4)
		owned.put(23745, 1);  // divine magic potion(4)
		OwnedItems both = new OwnedItems(owned, true);
		assertEquals(BoostProfile.BASTION,
			BoostSelector.bestFor(CombatStyle.RANGED, both, false, false));
		assertEquals(BoostProfile.BATTLEMAGE,
			BoostSelector.bestFor(CombatStyle.MAGIC, both, false, false));
	}

	@Test
	@DisplayName("a divine bastion owner is told to bring the divine one, not the plain")
	void divineBastionAndBattlemage() {
		Map<Integer, Integer> owned = new HashMap<>();
		owned.put(24635, 1);  // divine bastion potion(4)
		owned.put(24623, 1);  // divine battlemage potion(4)
		OwnedItems bag = new OwnedItems(owned, true);
		// Same boost numbers as the plain pair, but the label drives the
		// "what to bring" icon (AssumeIcons) - collapsing them would point a
		// divine-only owner at a potion they do not have, which is the very
		// bug this release fixes.
		assertEquals(BoostProfile.DIVINE_BASTION,
			BoostSelector.bestFor(CombatStyle.RANGED, bag, false, false));
		assertEquals(BoostProfile.DIVINE_BATTLEMAGE,
			BoostSelector.bestFor(CombatStyle.MAGIC, bag, false, false));
	}

	@Test
	@DisplayName("reachable magic never assumes MAXED or an unowned potion")
	void reachableMagicIsHonest() {
		// Unknown levels -> 0, never 99 (the old fallback seeded Death
		// Charge ON for a fresh login, F2P included: field report 2026-08-27).
		assertEquals(0, BoostSelector.reachableMagic(null, null, null));

		PlayerLevels base85 = new PlayerLevels(70, 70, 70, 70, 85, 70, 70);
		OwnedItems nothing = new OwnedItems(new HashMap<>(), true);
		assertEquals(85, BoostSelector.reachableMagic(base85, null, nothing),
			"no boost owned - reachable is just the base");

		Map<Integer, Integer> heart = new HashMap<>();
		heart.put(27641, 1); // saturated heart: +4 then +10% -> 85 + 12 = 97
		assertEquals(97, BoostSelector.reachableMagic(base85, null,
			new OwnedItems(heart, true)));

		// A live boost the player already drank counts even if unowned now.
		PlayerLevels live91 = new PlayerLevels(70, 70, 70, 70, 91, 70, 70);
		assertEquals(91, BoostSelector.reachableMagic(base85, live91, nothing));

		// A live DRAIN never drags reachable below base.
		PlayerLevels drained = new PlayerLevels(70, 70, 70, 70, 60, 70, 70);
		assertEquals(85, BoostSelector.reachableMagic(base85, drained, nothing));
	}

	@Test
	@DisplayName("an owned heart still beats an owned divine magic potion")
	void heartBeatsDivineMagic() {
		Map<Integer, Integer> owned = new HashMap<>();
		owned.put(27641, 1); // saturated heart
		owned.put(23745, 1); // divine magic (4)
		OwnedItems bag = new OwnedItems(owned, true);
		assertEquals(BoostProfile.SATURATED_HEART,
			BoostSelector.bestFor(CombatStyle.MAGIC, bag, false, false));
		assertEquals(BoostProfile.DIVINE_MAGIC,
			BoostSelector.bestFor(CombatStyle.MAGIC, bag, false, true),
			"under a risk cap the heart falls to the divine potion when owned");
	}
}

