import com.loadoutlab.engine.PlayerLevels;
import com.loadoutlab.engine.OwnedItems;
import com.loadoutlab.engine.PrayerUnlocks;
import com.loadoutlab.engine.RequirementProfile;
import net.runelite.api.Skill;
import java.util.Collections;
import java.util.EnumMap;
import java.util.HashMap;
import java.util.Map;
import java.util.concurrent.CountDownLatch;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicReference;
import org.junit.jupiter.api.BeforeAll;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import static org.junit.jupiter.api.Assertions.*;

/**
 * Field report 2026-08-27: "it's saying my bis on obor is a rune scimitar but
 * my attack is only 10 so i can't use that."
 *
 * <p>The ceiling gated on RequirementProfile.MAXED, so it named gear the player
 * could not wear and quoted a DPS that can never occur - reaching the 40 Attack
 * a rune scimitar needs changes the number it was quoting. It now uses the same
 * requirement profile as the Yours side, leaving OWNERSHIP as the only
 * difference between the two, which is the gap the comparison exists to show.
 *
 * <p>The goldens cannot catch this: FixtureBank is a maxed account, where the
 * two requirement profiles agree.
 */
class LowLevelCeilingTest {
	private static LoadoutData data;

	@BeforeAll
	static void load() {
		data = new DataService().load();
	}

	/** A fresh account: 10 Attack, nothing trained, every quest unstarted. */
	private static RequirementProfile freshAccount() {
		Map<Skill, Integer> levels = new HashMap<>();
		for (Skill s : Skill.values()) {
			levels.put(s, 1);
		}
		levels.put(Skill.ATTACK, 10);
		levels.put(Skill.HITPOINTS, 10);
		return new RequirementProfile(levels, Collections.emptySet());
	}

	@Test
	@DisplayName("the BiS ceiling never names gear the player cannot equip")
	void ceilingRespectsThePlayersRequirements() throws Exception {
		MonsterStats obor = data.searchMonsters("obor", 1).get(0);
		RequirementProfile fresh = freshAccount();
		PlayerLevels levels = new PlayerLevels(10, 1, 1, 10, 1, 1, 1);

		OptimizerService service = new OptimizerService(data);
		try {
			CountDownLatch done = new CountDownLatch(1);
			AtomicReference<Map<CombatStyle, OptimizerService.StyleResult>> out =
				new AtomicReference<>();
			ServiceCalls.bestPerStyle(service, obor,
				levels, levels, PrayerUnlocks.ALL,
				fresh, new OwnedItems(new HashMap<>(), true), 0,
				false, false, "", new EnumMap<>(CombatStyle.class), -1,
				OptimizationRequest.DEFAULT_RISK_BUDGET_GP, false, false,
				Collections.emptySet(), 0,
				Collections.emptyMap(), null, 0, Collections.emptySet(),
				r -> {
					out.set(r);
					done.countDown();
				});
			assertTrue(done.await(300, TimeUnit.SECONDS), "the Obor query timed out");

			OptimizerService.StyleResult melee = out.get().get(CombatStyle.MELEE);
			assertNotNull(melee, "no melee result for Obor");
			assertNotNull(melee.overallBest, "no game-best set for Obor");

			for (GearSlot slot : GearSlot.values()) {
				GearItem worn = melee.overallBest.getLoadout().get(slot);
				if (worn == null) {
					continue;
				}
				// Levels only: the ceiling never trims on the quest log (2026-09-09).
				assertTrue(fresh.withAllQuests().canEquip(worn.getRequirements()),
					"the ceiling put on " + worn.getName()
						+ ", which a 10 Attack account cannot equip");
			}
		} finally {
			service.shutdown();
		}
	}
}

package com.loadoutlab.optimizer;

import com.loadoutlab.data.DataService;
import com.loadoutlab.data.GearSlot;
import com.loadoutlab.data.LoadoutData;
import com.loadoutlab.data.MonsterStats;
import com.loadoutlab.engine.CombatStyle;
import com.loadoutlab.engine.ComputeParams;
import com.loadoutlab.engine.MultiTool;
import com.loadoutlab.engine.OwnedItems;
import com.loadoutlab.engine.PlayerLevels;
import com.loadoutlab.engine.PrayerUnlocks;
import com.loadoutlab.engine.RequirementProfile;
import java.util.Collections;
import java.util.HashMap;
import java.util.Map;
import java.util.concurrent.CountDownLatch;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicReference;
import org.junit.jupiter.api.BeforeAll;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import static org.junit.jupiter.api.Assertions.*;

/**
 * The Multi card's rows (Andrew 2026-10-19): with the Multi switch on, a
 * multi-able mob's compute also ranks the three multi tools - the best
 * ancient burst/barrage set, the best chinchompa set, the venator bow
 * set - each a full per-target StyleResult; a mob outside the multi
 * list computes nothing extra, and a tool the player does not own has
 * no Yours side.
 */
class MultiToolsTest {
	private static final int BLACK_CHIN = 11959;
	private static final int VENATOR = 27610;
	private static final int ADAMANT_ARROW = 890;
	private static final int DRAGON_2H = 7158;
	private static final int DRAGON_CLAWS = 13652;
	private static final int BLOOD_RUNE = 565;
	private static final int DEATH_RUNE = 560;
	private static final int WATER_RUNE = 555;
	private static LoadoutData data;

	@BeforeAll
	static void load() {
		data = new DataService().load();
	}

	private static Map<CombatStyle, OptimizerService.StyleResult> compute(String query, Map<Integer, Integer> owned, boolean multiView) throws Exception {
		return compute(query, owned, multiView, 3);
	}

	private static Map<CombatStyle, OptimizerService.StyleResult> compute(String query, Map<Integer, Integer> owned, boolean multiView, int stack) throws Exception {
		MonsterStats mob = data.searchMonsters(query, 1).get(0);
		OptimizerService service = new OptimizerService(data);
		CountDownLatch done = new CountDownLatch(1);
		AtomicReference<Map<CombatStyle, OptimizerService.StyleResult>> out = new AtomicReference<>();
		ComputeParams p = new ComputeParams();
		p.multiView = multiView;
		p.multiStack = stack;
		service.bestPerStyle(mob, PlayerLevels.MAXED, PlayerLevels.MAXED, PrayerUnlocks.ALL,
			RequirementProfile.MAXED, new OwnedItems(owned, true), 1, p,
			Collections.emptyMap(), Collections.emptySet(), Collections.emptyMap(), null, 0,
			Collections.<Integer>emptySet(), result -> {
				out.set(result);
				done.countDown();
			});
		assertTrue(done.await(120, TimeUnit.SECONDS), "compute timed out");
		return out.get();
	}

	private static Map<Integer, Integer> kit(boolean chins, boolean venator, boolean runes) {
		Map<Integer, Integer> owned = new HashMap<>();
		for (String name : new String[]{"rune scimitar", "rune full helm", "rune platebody", "rune platelegs",
			"ancient staff", "mystic robe top", "mystic robe bottom", "magic shortbow", "black d'hide body", "black d'hide chaps"}) {
			data.getGearItems().stream().filter(g -> g.getNameLower().equals(name) && g.isStandardGear())
				.findFirst().ifPresent(g -> owned.put(g.getId(), 1));
		}
		if (chins) {
			owned.put(BLACK_CHIN, 5000);
		}
		if (venator) {
			// The bow fires arrows (wiki: any arrow up to dragon); without
			// them the owned row is rightly empty.
			owned.put(VENATOR, 1);
			owned.put(ADAMANT_ARROW, 1000);
		}
		if (runes) {
			owned.put(BLOOD_RUNE, 1000);
			owned.put(DEATH_RUNE, 1000);
			owned.put(WATER_RUNE, 1000);
		}
		return owned;
	}

	private static Map<String, OptimizerService.StyleResult> tools(Map<CombatStyle, OptimizerService.StyleResult> results) {
		for (OptimizerService.StyleResult r : results.values()) {
			if (r.multiTools != null) {
				return r.multiTools;
			}
		}
		return null;
	}

	@Test
	@DisplayName("Greater Nechryaels with the switch on rank barrage, chins, the venator bow and Hallowfell, each a per-target set")
	void nechryaelsHaveThreeTools() throws Exception {
		Map<String, OptimizerService.StyleResult> tools = tools(compute("greater nechryael", kit(true, true, true), true));
		assertNotNull(tools, "the multi tools ride the results");
		assertEquals(4, tools.size(), "barrage, chins, venator and Hallowfell (ISS-01M5TPEWE9AQM3B55ZH02PHGE4)");
		assertEquals(MultiTool.HALLOWFELL_SWORD, tools.get(MultiTool.HALLOWFELL.key).overallBest.getLoadout().get(GearSlot.WEAPON).getId(), "the ceiling wields Hallowfell");
		OptimizerService.StyleResult barrage = tools.get(MultiTool.BARRAGE.key);
		assertEquals("Ice Barrage", barrage.owned.get(0).getSpellName(), "a maxed mage barrages");
		assertEquals(BLACK_CHIN, tools.get(MultiTool.CHINS.key).owned.get(0).getLoadout().get(GearSlot.WEAPON).getId());
		assertEquals(VENATOR, tools.get(MultiTool.VENATOR.key).owned.get(0).getLoadout().get(GearSlot.WEAPON).getId());
		assertEquals(VENATOR, tools.get(MultiTool.VENATOR.key).overallBest.getLoadout().get(GearSlot.WEAPON).getId(), "the ceiling wears it too");
	}

	@Test
	@DisplayName("a tool you do not own has no Yours side; the ceiling still shows it")
	void unownedToolHasNoYours() throws Exception {
		Map<String, OptimizerService.StyleResult> tools = tools(compute("greater nechryael", kit(true, false, true), true));
		assertNotNull(tools);
		assertTrue(tools.get(MultiTool.VENATOR.key).owned.isEmpty(), "no venator bow, no Yours row");
		assertNotNull(tools.get(MultiTool.VENATOR.key).overallBest);
		assertFalse(tools.get(MultiTool.CHINS.key).owned.isEmpty());
	}

	@Test
	@DisplayName("at a stack of nine the chins row's spec is the d2h over the claws; at one it is not (Andrew 2026-10-19)")
	void multiSpecAtTheStack() throws Exception {
		Map<Integer, Integer> owned = kit(true, false, false);
		owned.put(DRAGON_2H, 1);
		owned.put(DRAGON_CLAWS, 1);
		// At three the claws' four hits per 50% still edge three Powerstabs
		// per 60%; at nine the stack is decisive.
		OptimizerService.StyleResult atNine = tools(compute("greater nechryael", owned, true, 9)).get(MultiTool.CHINS.key);
		assertNotNull(atNine.specWeapon, "a spec rides the chins row");
		assertEquals(DRAGON_2H, atNine.specWeapon.getId(), "Powerstab hits the whole stack");
		OptimizerService.StyleResult atOne = tools(compute("greater nechryael", owned, true, 1)).get(MultiTool.CHINS.key);
		assertNotEquals(DRAGON_2H, atOne.specWeapon == null ? 0 : atOne.specWeapon.getId(), "one target: the claws win as ever");
	}

	@Test
	@DisplayName("the switch off, or a mob outside the multi list, computes no tools")
	void offOrNotMultiAble() throws Exception {
		assertNull(tools(compute("greater nechryael", kit(true, true, true), false)), "switch off");
		assertNull(tools(compute("vorkath", kit(true, true, true), true)), "Vorkath is single-way");
	}
}

package com.loadoutlab.optimizer;

import com.loadoutlab.data.DataService;
import com.loadoutlab.data.GearItem;
import com.loadoutlab.data.GearSlot;
import com.loadoutlab.data.LoadoutData;
import com.loadoutlab.data.MonsterStats;
import com.loadoutlab.engine.CandidateMode;
import com.loadoutlab.engine.CombatStyle;
import com.loadoutlab.engine.DpsResult;
import com.loadoutlab.engine.IncomingDpsCalculator;
import com.loadoutlab.engine.LoadoutOptimizer;
import com.loadoutlab.engine.OptimizationRequest;
import com.loadoutlab.engine.OwnedItems;
import com.loadoutlab.engine.PlayerLevels;
import com.loadoutlab.engine.PrayerBonuses;
import com.loadoutlab.engine.PrayerUnlocks;
import com.loadoutlab.engine.RequirementProfile;
import com.loadoutlab.engine.TestRequests;
import java.util.Collections;
import java.util.HashMap;
import java.util.Map;
import java.util.concurrent.CountDownLatch;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicReference;
import org.junit.jupiter.api.BeforeAll;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import static org.junit.jupiter.api.Assertions.*;

/**
 * The dev-mode defensive modes (ISS-01M5G5CZC9SK46499FACRSJ8ZT), Andrew's
 * definitions: Tanky = the minimum DTPS, Balanced = the best DTPS/DPS -
 * least damage taken per damage dealt. Graardor ranged is the July
 * reference case; the pool is every buyable item (budget, no bank).
 */
class OptimizeModeTest {
	private static LoadoutData data;

	@BeforeAll
	static void load() {
		data = new DataService().load();
	}

	private static OptimizerService.StyleResult run(String mob, CombatStyle style,
		OptimizerService.OptimizeMode mode) throws Exception {
		MonsterStats monster = data.searchMonsters(mob, 1).get(0);
		OptimizerService service = new OptimizerService(data);
		try {
			CountDownLatch done = new CountDownLatch(1);
			AtomicReference<Map<CombatStyle, OptimizerService.StyleResult>> out = new AtomicReference<>();
			com.loadoutlab.engine.ComputeParams p = new com.loadoutlab.engine.ComputeParams();
			p.specWeapon = false;
			p.upgradeBudgetGp = 2_000_000_000;
			p.optimizeMode = mode.name();
			service.bestPerStyle(monster, PlayerLevels.MAXED, PlayerLevels.MAXED, PrayerUnlocks.ALL,
				RequirementProfile.MAXED, OwnedItems.EMPTY, 1, p,
				Collections.emptyMap(), Collections.emptySet(), Collections.emptyMap(), null, 0,
				Collections.<Integer>emptySet(), result -> {
					out.set(result);
					done.countDown();
				});
			assertTrue(done.await(300, TimeUnit.SECONDS), "compute finished");
			return out.get().get(style);
		} finally {
			service.shutdown();
		}
	}

	private static double dtps(String mob, OptimizerService.StyleResult result) {
		return IncomingDpsCalculator.calculate(data.searchMonsters(mob, 1).get(0),
			result.owned.get(0).getLoadout(), 99, 99).totalDps;
	}

	@Test
	@DisplayName("a defense-weighted beam can pick pure-defence gear (ring of suffering over archers ring)")
	void weightedBeamSeesDefenceGear() {
		MonsterStats graardor = data.searchMonsters("general graardor", 1).get(0);
		Map<Integer, Integer> owned = new HashMap<>();
		owned.put(861, 1);    // magic shortbow
		owned.put(892, 500);  // rune arrows
		owned.put(11771, 1);  // archers ring (i)
		owned.put(19710, 1);  // ring of suffering (i)
		OptimizationRequest base = TestRequests.of(graardor, CombatStyle.RANGED, PlayerLevels.MAXED,
			PrayerBonuses.bestAvailable(PlayerLevels.MAXED, PrayerUnlocks.ALL), null, 0,
			CandidateMode.OWNED_ONLY, true, false, new OwnedItems(data.canonicalizeOwned(owned), true), 1);
		LoadoutOptimizer optimizer = new LoadoutOptimizer();
		GearItem offence = optimizer.optimize(data, base).get(0).getLoadout().get(GearSlot.RING);
		DpsResult tanky = optimizer.optimize(data, base.withDefenseWeight(50)).get(0);
		assertEquals("Archers ring (i)", offence.getName());
		assertEquals("Ring of suffering (i)", tanky.getLoadout().get(GearSlot.RING).getName());
	}

	@Test
	@DisplayName("Tanky takes the least damage, Balanced has the best DTPS/DPS, Max DPS deals the most")
	void modesHonourTheirObjectives() throws Exception {
		String mob = "general graardor";
		OptimizerService.StyleResult max = run(mob, CombatStyle.RANGED, OptimizerService.OptimizeMode.MAX_DPS);
		OptimizerService.StyleResult balanced = run(mob, CombatStyle.RANGED, OptimizerService.OptimizeMode.BALANCED);
		OptimizerService.StyleResult tanky = run(mob, CombatStyle.RANGED, OptimizerService.OptimizeMode.TANKY);
		assertNull(max.modeTrade, "Max DPS makes no trade");
		double dMax = max.owned.get(0).getDps();
		assertTrue(dMax >= balanced.owned.get(0).getDps() - 1e-9);
		assertTrue(dMax >= tanky.owned.get(0).getDps() - 1e-9);
		assertTrue(dtps(mob, tanky) <= dtps(mob, max) + 1e-9);
		assertTrue(dtps(mob, tanky) <= dtps(mob, balanced) + 1e-9);
		double rMax = dtps(mob, max) / dMax;
		double rBalanced = dtps(mob, balanced) / balanced.owned.get(0).getDps();
		double rTanky = dtps(mob, tanky) / tanky.owned.get(0).getDps();
		assertTrue(rBalanced <= rMax + 1e-9, "Balanced's DTPS/DPS beats Max DPS's");
		assertTrue(rBalanced <= rTanky + 1e-9, "and Tanky's");
		assertTrue(dtps(mob, tanky) < dtps(mob, max) - 1e-6, "Graardor ranged has a real trade to make");
		assertNotNull(tanky.modeTrade);
		assertNull(tanky.modeTrade.reason);
		assertTrue(tanky.modeTrade.dmgCutPct > 0, "the card can show the damage cut");
		assertTrue(tanky.modeTrade.dpsLossPct >= 0, "and the DPS cost");
		assertEquals(OptimizerService.OptimizeMode.TANKY, tanky.modeTrade.mode);
	}

	@Test
	@DisplayName("a partly modeled monster keeps Max DPS and says why")
	void partialCoverageKeepsMaxDps() throws Exception {
		OptimizerService.StyleResult max = run("blue dragon", CombatStyle.MELEE, OptimizerService.OptimizeMode.MAX_DPS);
		OptimizerService.StyleResult tanky = run("blue dragon", CombatStyle.MELEE, OptimizerService.OptimizeMode.TANKY);
		assertNotNull(tanky.modeTrade);
		assertEquals("partial damage data", tanky.modeTrade.reason);
		assertEquals(max.owned.get(0).getDps(), tanky.owned.get(0).getDps(), 1e-9);
	}

	@Test
	@DisplayName("when the max-DPS set takes ~0 damage, every mode keeps it")
	void zeroDamageKeepsMaxDps() throws Exception {
		// One magic attack, prayed off entirely.
		OptimizerService.StyleResult max = run("aberrant spectre", CombatStyle.MELEE, OptimizerService.OptimizeMode.MAX_DPS);
		OptimizerService.StyleResult balanced = run("aberrant spectre", CombatStyle.MELEE, OptimizerService.OptimizeMode.BALANCED);
		assertNotNull(balanced.modeTrade);
		assertEquals("takes ~0 damage", balanced.modeTrade.reason);
		assertEquals(max.owned.get(0).getDps(), balanced.owned.get(0).getDps(), 1e-9);
	}
}

package com.loadoutlab.optimizer;

import com.loadoutlab.data.DataService;
import com.loadoutlab.data.LoadoutData;
import com.loadoutlab.data.MonsterStats;
import com.loadoutlab.engine.CombatStyle;
import com.loadoutlab.engine.OptimizationRequest;
import com.loadoutlab.engine.OwnedItems;
import com.loadoutlab.engine.PlayerLevels;
import com.loadoutlab.engine.RequirementProfile;
import java.util.HashMap;
import java.util.Map;
import java.util.Set;
import java.util.concurrent.CountDownLatch;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicReference;
import org.junit.Assert;
import org.junit.Test;

public class OptimizerServiceTest {
	@Test
	public void defenceDrainMakesTheWarhammerTheSpecPickOnTankyBosses() throws Exception {
		LoadoutData data = new DataService().load();
		// Dagannoth Rex (255 defence, 255 hp; not a GWD boss, whose carried
		// god protection would take the one Inventory slot): a drain pays off over the
		// whole kill, so the warhammer wins. A fire giant (120 defence, 130
		// hp) dies before a drain earns back its lost hits, so the dagger's
		// burst wins. A goblin dies in one attack - no spec beats just
		// attacking, so none is carried (value-over-replacement).
		MonsterStats rex = data.searchMonsters("dagannoth rex", 1).get(0);
		MonsterStats fireGiant = data.searchMonsters("fire giant", 1).get(0);
		MonsterStats goblin = data.searchMonsters("goblin", 1).get(0);
		Map<Integer, Integer> owned = new HashMap<>();
		owned.put(4151, 1);   // whip - main weapon
		owned.put(1215, 1);   // dragon dagger - burst spec
		owned.put(13576, 1);  // dragon warhammer - drain spec
		// Super combat potion: this scenario's "a goblin dies in one attack"
		// premise depends on the boosted max hit. Boosts now gate on ownership
		// (2026-08-25), so the bank has to actually hold the potion the test
		// assumes - otherwise the goblin survives and a spec DOES pay.
		owned.put(12695, 1);
		OptimizerService service = new OptimizerService(data);
		try {
			Assert.assertEquals("Dragon warhammer", specPick(service, rex, owned));
			Assert.assertEquals("Dragon dagger", specPick(service, fireGiant, owned));
			Assert.assertNull("a one-hit kill is not worth a spec slot",
				specPick(service, goblin, owned));
		} finally {
			service.shutdown();
		}
	}

	@Test
	public void togglingAConditionMidLoadAbandonsTheStaleComputationAndDeliversTheNewOne() throws Exception {
		LoadoutData data = new DataService().load();
		MonsterStats graardor = data.searchMonsters("general graardor", 1).get(0);
		Map<Integer, Integer> owned = new HashMap<>();
		owned.put(4151, 1); // abyssal whip
		OptimizerService service = new OptimizerService(data);
		try {
			CountDownLatch fresh = new CountDownLatch(1);
			java.util.concurrent.atomic.AtomicInteger staleDelivered = new java.util.concurrent.atomic.AtomicInteger();
			// Stale request (off-task), immediately superseded by the toggle.
			com.loadoutlab.optimizer.ServiceCalls.bestPerStyle(service, graardor, PlayerLevels.MAXED, PlayerLevels.MAXED,
				com.loadoutlab.engine.PrayerUnlocks.ALL, RequirementProfile.MAXED,
				new OwnedItems(owned, true), owned.hashCode(), false, false, "",
				java.util.Collections.emptySet(), -1, OptimizationRequest.DEFAULT_RISK_BUDGET_GP, false, java.util.Collections.emptySet(), 0, results -> staleDelivered.incrementAndGet());
			// The toggle: same monster, on-task, fired before the stale run ends.
			com.loadoutlab.optimizer.ServiceCalls.bestPerStyle(service, graardor, PlayerLevels.MAXED, PlayerLevels.MAXED,
				com.loadoutlab.engine.PrayerUnlocks.ALL, RequirementProfile.MAXED,
				new OwnedItems(owned, true), owned.hashCode(), false, true, "",
				java.util.Collections.emptySet(), -1, OptimizationRequest.DEFAULT_RISK_BUDGET_GP, false, java.util.Collections.emptySet(), 0, results -> fresh.countDown());
			Assert.assertTrue(fresh.await(120, TimeUnit.SECONDS));
			Assert.assertEquals("the superseded request must never deliver", 0, staleDelivered.get());
		} finally {
			service.shutdown();
		}
	}

	private static String specPick(OptimizerService service, MonsterStats monster,
		Map<Integer, Integer> owned) throws Exception {
		CountDownLatch done = new CountDownLatch(1);
		AtomicReference<Map<CombatStyle, OptimizerService.StyleResult>> out = new AtomicReference<>();
		com.loadoutlab.optimizer.ServiceCalls.bestPerStyle(service, monster, PlayerLevels.MAXED, PlayerLevels.MAXED, com.loadoutlab.engine.PrayerUnlocks.ALL, RequirementProfile.MAXED,
			new OwnedItems(owned, true), owned.hashCode(), false, false, "", java.util.Collections.emptySet(), -1, OptimizationRequest.DEFAULT_RISK_BUDGET_GP, false, java.util.Collections.emptySet(), 0, results -> {
				out.set(results);
				done.countDown();
			});
		Assert.assertTrue(done.await(120, TimeUnit.SECONDS));
		OptimizerService.StyleResult melee = out.get().get(CombatStyle.MELEE);
		// A spec that adds nothing over just attacking is not carried (the
		// value-over-replacement model): null means "no spec worth a slot".
		return melee == null || melee.spec == null ? null : melee.spec.getDisplayName();
	}

	@Test
	public void pinningOneStyleReusesTheOtherStylesCachedAnswers() throws Exception {
		LoadoutData data = new DataService().load();
		MonsterStats goblin = data.searchMonsters("goblin", 1).get(0);
		Map<Integer, Integer> owned = new HashMap<>();
		owned.put(4151, 1); // abyssal whip
		owned.put(1215, 1); // dragon dagger - a pinnable melee weapon
		OptimizerService service = new OptimizerService(data);
		try {
			Map<CombatStyle, OptimizerService.StyleResult> first =
				resultsFor(service, goblin, owned, java.util.Collections.emptyMap());
			// Pin the dagger for MELEE only: the ranged and magic answers are
			// unchanged queries and must come back as the SAME cached objects,
			// not fresh recomputes.
			Map<CombatStyle, Map<com.loadoutlab.data.GearSlot, Integer>> pins =
				java.util.Map.of(CombatStyle.MELEE,
					java.util.Map.of(com.loadoutlab.data.GearSlot.WEAPON, 1215));
			Map<CombatStyle, OptimizerService.StyleResult> pinned =
				resultsFor(service, goblin, owned, pins);
			Assert.assertSame("ranged must be the cached result",
				first.get(CombatStyle.RANGED), pinned.get(CombatStyle.RANGED));
			Assert.assertSame("magic must be the cached result",
				first.get(CombatStyle.MAGIC), pinned.get(CombatStyle.MAGIC));
			Assert.assertNotSame("melee must be recomputed around the pin",
				first.get(CombatStyle.MELEE), pinned.get(CombatStyle.MELEE));
			Assert.assertEquals("the pin must be honored", 1215,
				pinned.get(CombatStyle.MELEE).owned.get(0).getLoadout().getWeapon().getId());
		} finally {
			service.shutdown();
		}
	}

	private static Map<CombatStyle, OptimizerService.StyleResult> resultsFor(
		OptimizerService service, MonsterStats monster, Map<Integer, Integer> owned,
		Map<CombatStyle, Map<com.loadoutlab.data.GearSlot, Integer>> pins) throws Exception {
		CountDownLatch done = new CountDownLatch(1);
		AtomicReference<Map<CombatStyle, OptimizerService.StyleResult>> out = new AtomicReference<>();
		com.loadoutlab.optimizer.ServiceCalls.bestPerStyle(service, monster, PlayerLevels.MAXED, PlayerLevels.MAXED,
			com.loadoutlab.engine.PrayerUnlocks.ALL, RequirementProfile.MAXED,
			new OwnedItems(owned, true), 1, false, false, "",
			java.util.Collections.emptySet(), -1, OptimizationRequest.DEFAULT_RISK_BUDGET_GP,
			false, java.util.Collections.emptySet(), 0, 			pins, null, results -> {
				out.set(results);
				done.countDown();
			});
		Assert.assertTrue(done.await(120, TimeUnit.SECONDS));
		return out.get();
	}

	@Test
	public void aStyleScopedExclusionRecomputesOnlyThatStyle() throws Exception {
		LoadoutData data = new DataService().load();
		MonsterStats goblin = data.searchMonsters("goblin", 1).get(0);
		Map<Integer, Integer> owned = new HashMap<>();
		owned.put(4151, 1); // abyssal whip
		owned.put(1333, 1); // rune scimitar - the fallback once the whip is excluded
		OptimizerService service = new OptimizerService(data);
		try {
			Map<CombatStyle, Set<Integer>> none = uniformExclusions(java.util.Collections.emptySet());
			Map<CombatStyle, OptimizerService.StyleResult> first =
				resultsForExcluding(service, goblin, owned, none);
			Assert.assertEquals("whip wins melee before the exclusion", 4151,
				first.get(CombatStyle.MELEE).owned.get(0).getLoadout().getWeapon().getId());

			// Exclude the whip for the MELEE card only: ranged and magic are
			// unchanged queries and must come back as the same cached objects.
			Map<CombatStyle, Set<Integer>> meleeOnly = uniformExclusions(java.util.Collections.emptySet());
			meleeOnly.put(CombatStyle.MELEE, Set.of(4151));
			Map<CombatStyle, OptimizerService.StyleResult> excluded =
				resultsForExcluding(service, goblin, owned, meleeOnly);
			Assert.assertNotEquals("the melee card must drop the excluded whip", 4151,
				excluded.get(CombatStyle.MELEE).owned.get(0).getLoadout().getWeapon().getId());
			Assert.assertSame("ranged must be the cached result",
				first.get(CombatStyle.RANGED), excluded.get(CombatStyle.RANGED));
			Assert.assertSame("magic must be the cached result",
				first.get(CombatStyle.MAGIC), excluded.get(CombatStyle.MAGIC));
		} finally {
			service.shutdown();
		}
	}

	private static Map<CombatStyle, Set<Integer>> uniformExclusions(Set<Integer> set) {
		Map<CombatStyle, Set<Integer>> byStyle = new java.util.EnumMap<>(CombatStyle.class);
		for (CombatStyle style : CombatStyle.concreteValues()) {
			byStyle.put(style, set);
		}
		return byStyle;
	}

	private static Map<CombatStyle, OptimizerService.StyleResult> resultsForExcluding(
		OptimizerService service, MonsterStats monster, Map<Integer, Integer> owned,
		Map<CombatStyle, Set<Integer>> excludedByStyle) throws Exception {
		CountDownLatch done = new CountDownLatch(1);
		AtomicReference<Map<CombatStyle, OptimizerService.StyleResult>> out = new AtomicReference<>();
		com.loadoutlab.optimizer.ServiceCalls.bestPerStyle(service, monster, PlayerLevels.MAXED, PlayerLevels.MAXED,
			com.loadoutlab.engine.PrayerUnlocks.ALL, RequirementProfile.MAXED,
			new OwnedItems(owned, true), 1, false, false, "",
			excludedByStyle, -1, OptimizationRequest.DEFAULT_RISK_BUDGET_GP,
			false, false, java.util.Collections.emptySet(), 0, 			java.util.Collections.emptyMap(), null, java.util.Collections.emptySet(), results -> {
				out.set(results);
				done.countDown();
			});
		Assert.assertTrue(done.await(120, TimeUnit.SECONDS));
		return out.get();
	}

	@Test
	public void crossStyleSpecWeaponsCompeteOnEverySet() throws Exception {
		// Field request 2026-07-17: "sometimes you want to use magic +
		// chally" - the spec swap is its own weapon switch, so a MELEE
		// spec weapon must surface on the MAGIC set when it is the best
		// special owned. Owned: a trident (the magic set) + a dragon
		// dagger (melee spec) and nothing else spec-worthy.
		LoadoutData data = new DataService().load();
		MonsterStats monster = data.searchMonsters("ankou", 1).get(0);
		Map<Integer, Integer> owned = new HashMap<>();
		owned.put(11907, 1);  // trident of the seas
		owned.put(1215, 1);   // dragon dagger
		OptimizerService service = new OptimizerService(data);
		try {
			CountDownLatch done = new CountDownLatch(1);
			AtomicReference<Map<CombatStyle, OptimizerService.StyleResult>> out = new AtomicReference<>();
			com.loadoutlab.optimizer.ServiceCalls.bestPerStyle(service, monster, PlayerLevels.MAXED, PlayerLevels.MAXED,
				com.loadoutlab.engine.PrayerUnlocks.ALL, RequirementProfile.MAXED,
				new OwnedItems(owned, true), 1, false, false, "",
				java.util.Collections.emptySet(), -1,
				OptimizationRequest.DEFAULT_RISK_BUDGET_GP,
				false, java.util.Collections.emptySet(), 0,
								java.util.Collections.emptyMap(), null, results -> {
					out.set(results);
					done.countDown();
				});
			Assert.assertTrue(done.await(120, TimeUnit.SECONDS));
			OptimizerService.StyleResult magic = out.get().get(CombatStyle.MAGIC);
			Assert.assertNotNull(magic);
			Assert.assertFalse("premise: the trident set exists", magic.owned.isEmpty());
			Assert.assertNotNull("the melee dagger specs for the magic set", magic.spec);
			Assert.assertEquals(1215, magic.specWeapon.getId());
			Assert.assertTrue(magic.specExpectedDamage > 0);
		} finally {
			service.shutdown();
		}
	}

	@Test
	public void ownedSpecWeaponSurfacesOnTheStyleResult() throws Exception {
		LoadoutData data = new DataService().load();
		// A fire giant, not a goblin: enough HP that a spec earns its slot
		// (a goblin dies in one hit, so the value model carries no spec).
		MonsterStats monster = data.searchMonsters("fire giant", 1).get(0);
		Map<Integer, Integer> owned = new HashMap<>();
		owned.put(4151, 1);   // abyssal whip - the sustained-DPS weapon
		owned.put(1215, 1);   // dragon dagger - the spec weapon
		OptimizerService service = new OptimizerService(data);
		try {
			CountDownLatch done = new CountDownLatch(1);
			AtomicReference<Map<CombatStyle, OptimizerService.StyleResult>> out = new AtomicReference<>();
			com.loadoutlab.optimizer.ServiceCalls.bestPerStyle(service, monster, PlayerLevels.MAXED, PlayerLevels.MAXED, com.loadoutlab.engine.PrayerUnlocks.ALL, RequirementProfile.MAXED,
				new OwnedItems(owned, true), 1, false, false, "", java.util.Collections.emptySet(), -1, OptimizationRequest.DEFAULT_RISK_BUDGET_GP, false, java.util.Collections.emptySet(), 0, results -> {
					out.set(results);
					done.countDown();
				});
			Assert.assertTrue(done.await(60, TimeUnit.SECONDS));

			OptimizerService.StyleResult melee = out.get().get(CombatStyle.MELEE);
			Assert.assertNotNull(melee);
			Assert.assertFalse(melee.owned.isEmpty());
			// The whip wins sustained DPS; the dagger is still surfaced as
			// the spec weapon with a positive expected special-attack hit.
			Assert.assertNotNull(melee.spec);
			Assert.assertEquals("Dragon dagger", melee.spec.getDisplayName());
			Assert.assertEquals(1215, melee.specWeapon.getId());
			Assert.assertTrue(melee.specExpectedDamage > 0);
			// The win-over-replacement value is surfaced and positive.
			Assert.assertTrue("the spec must add positive dps to be carried",
				melee.specDpsAdded > 0);
			// The game-best section carries its own spec - the strongest
			// special attack that exists, regardless of ownership.
			Assert.assertNotNull(melee.gameSpec);
			Assert.assertNotNull(melee.gameSpecWeapon);
			Assert.assertTrue(melee.gameSpecExpectedDamage >= melee.specExpectedDamage);
			// Both sides of the Yours|BiS toggle carry their own defensive
			// story - the BiS DTPS is computed vs the BiS armour, not yours.
			Assert.assertNotNull(melee.incoming);
			Assert.assertNotNull(melee.gameIncoming);
			Assert.assertTrue(melee.gameIncoming.unprayedDps > 0);
		} finally {
			service.shutdown();
		}
	}
}

