import com.loadoutlab.data.MonsterStats;
import com.loadoutlab.engine.CombatStyle;
import com.loadoutlab.engine.OptimizationRequest;
import com.loadoutlab.engine.OwnedItems;
import com.loadoutlab.engine.PlayerLevels;
import com.loadoutlab.engine.PrayerUnlocks;
import com.loadoutlab.engine.RequirementProfile;
import java.util.Collections;
import java.util.HashMap;
import java.util.Map;
import java.util.concurrent.CountDownLatch;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicReference;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertTrue;

/** Discord (Apathy, 2026-09-06): camping Lunar for Cure Me at Zulrah -
 * the magic card should then offer built-in staves only, since no Lunar
 * spell autocasts. The lock is the engine's job; the card's book picker
 * sets it (restored 2026-09-08 - the merge-back lost the control). */
class SpellbookLockTest {
	@Test
	@DisplayName("a Lunar lock leaves the magic card to the powered staves: the trident wins over a standard-book staff of fire that would otherwise outcast it")
	void lunarLock() throws Exception {
		LoadoutData data = new DataService().load();
		MonsterStats zulrah = data.searchMonsters("Zulrah", 1).get(0);
		Map<Integer, Integer> owned = new HashMap<>();
		owned.put(11905, 1); // trident of the seas
		owned.put(1387, 1); // staff of fire
		owned.put(12002, 1); // occult necklace
		OptimizerService service = new OptimizerService(data);
		try {
			assertEquals(11905, weapon(service, zulrah, owned, "lunar"), "lunar: built-in only");
			assertEquals(11905, weapon(service, zulrah, owned, ""), "auto at 99 Magic: the trident still wins");
			assertEquals(1387, weapon(service, zulrah, owned, "standard", 11905), "standard lock with the trident excluded: the staff of fire casts");
		} finally {
			service.shutdown();
		}
	}

	private static int weapon(OptimizerService service, MonsterStats monster, Map<Integer, Integer> owned,
		String lock, Integer... excluded) throws Exception {
		CountDownLatch done = new CountDownLatch(1);
		AtomicReference<Map<CombatStyle, OptimizerService.StyleResult>> out = new AtomicReference<>();
		ServiceCalls.bestPerStyle(service, monster, PlayerLevels.MAXED, PlayerLevels.MAXED,
			PrayerUnlocks.ALL, RequirementProfile.MAXED, new OwnedItems(owned, true), 1, false, false, lock,
			java.util.Set.of(excluded), -1, OptimizationRequest.DEFAULT_RISK_BUDGET_GP, false, Collections.emptySet(), 0,
			results -> {
				out.set(results);
				done.countDown();
			});
		assertTrue(done.await(120, TimeUnit.SECONDS));
		return out.get().get(CombatStyle.MAGIC).owned.get(0).getLoadout().getWeapon().getId();
	}
}

package com.loadoutlab.optimizer;

import com.loadoutlab.data.DataService;
import com.loadoutlab.data.GearItem;
import com.loadoutlab.data.GearSlot;
import com.loadoutlab.data.LoadoutData;
import org.junit.jupiter.api.BeforeAll;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import java.util.List;
import java.util.stream.Collectors;

import static org.junit.jupiter.api.Assertions.assertEquals;

/**
 * A weapon and its twin are one weapon to the strip. The battlestaffs
 * (ISS-01M5PKSQBAP823XNC13QBW8830, Andrew 2026-10-24: "just consider that
 * as the same weapon and if the user has the mystic version use that and if
 * they don't sim the other but don't waste both slots") and the tridents
 * (ISS-01M5PTHS4MAVKFB8C1QXF0KTS1: "combine trident of the seas/swamp and
 * their (e) version - those have the same damage just hold a different
 * number of charges"): the worn one stands, else the owned twin, else the
 * base - the twin's sim rung never sits beside the base.
 */
class StaffFamilyFoldTest {
	private static LoadoutData data;

	@BeforeAll
	static void load() {
		data = new DataService().load();
	}

	private static GearItem item(String name) {
		return data.getGearItems(GearSlot.WEAPON).stream()
			.filter(g -> g.getNameLower().equals(name) && g.isStandardGear() && !data.isVariant(g.getId()))
			.findFirst().orElseThrow(() -> new AssertionError("corpus is missing " + name));
	}

	private static OptimizerService.Rung rung(String name, boolean owned) {
		return new OptimizerService.Rung(item(name), 5.0, 0, owned, null);
	}

	private static List<String> fold(GearItem worn, OptimizerService.Rung... rungs) {
		return OptimizerService.foldStaffFamilies(List.of(rungs), worn).stream()
			.map(r -> r.item.getNameLower()).collect(Collectors.toList());
	}

	@Test
	@DisplayName("an owned battlestaff beside an unowned mystic: the battlestaff stands; owned mystic beside an owned battlestaff: the mystic; a lone staff stays")
	void theOwnedTwinStands() {
		assertEquals(List.of("smoke battlestaff", "lava battlestaff", "purging staff"),
			fold(null, rung("smoke battlestaff", true), rung("mystic smoke staff", false), rung("lava battlestaff", true), rung("purging staff", true)));
		assertEquals(List.of("mystic smoke staff", "purging staff"),
			fold(null, rung("smoke battlestaff", true), rung("mystic smoke staff", true), rung("purging staff", true)));
		assertEquals(List.of("mystic fire staff"), fold(null, rung("mystic fire staff", false)));
	}

	@Test
	@DisplayName("the worn weapon stands for its family: a worn battlestaff shows no unowned mystic rung but keeps an owned one; a worn mystic shows no battlestaff rung")
	void theWornOneStands() {
		assertEquals(List.of("purging staff"),
			fold(item("smoke battlestaff"), rung("mystic smoke staff", false), rung("purging staff", true)));
		assertEquals(List.of("mystic smoke staff"),
			fold(item("smoke battlestaff"), rung("mystic smoke staff", true)));
		assertEquals(List.of(), fold(item("mystic smoke staff"), rung("smoke battlestaff", true)));
	}

	@Test
	@DisplayName("the tridents fold the same way: the (e) stands when owned, the plain trident otherwise, for the seas and the swamp")
	void tridentsFold() {
		assertEquals(List.of("trident of the seas", "trident of the swamp (e)"),
			fold(null, rung("trident of the seas", true), rung("trident of the seas (e)", false),
				rung("trident of the swamp", true), rung("trident of the swamp (e)", true)));
		assertEquals(List.of("trident of the seas (e)"),
			fold(item("trident of the swamp"), rung("trident of the seas (e)", true), rung("trident of the swamp (e)", false)));
	}
}

package com.loadoutlab.optimizer;

import com.loadoutlab.data.DataService;
import com.loadoutlab.data.LoadoutData;
import com.loadoutlab.data.MonsterStats;
import com.loadoutlab.engine.*;
import java.util.Collections;
import java.util.Map;
import java.util.concurrent.CountDownLatch;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicReference;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import static org.junit.jupiter.api.Assertions.*;

/**
 * TonyDAnnunzio (YouTube 2026-10-18): "it just says computing now". A
 * throw inside the optimizer's worker used to drop the callback, leaving
 * the card on Computing for good. A compute that fails now answers with
 * an empty result so the card shows its empty state and Reload works.
 */
class ThrowingComputeTest {
	@Test
	@DisplayName("a compute whose request the engine rejects still calls back, empty")
	void throwingComputeStillAnswers() throws Exception {
		LoadoutData data = new DataService().load();
		MonsterStats graardor = data.searchMonsters("general graardor", 1).get(0);
		OptimizerService service = new OptimizerService(data);
		try {
			CountDownLatch done = new CountDownLatch(1);
			AtomicReference<Map<CombatStyle, OptimizerService.StyleResult>> out = new AtomicReference<>();
			// A null requirement profile blows up inside the candidate pool,
			// on the worker thread - the shape of any unexpected engine throw.
			ServiceCalls.bestPerStyle(service, graardor, PlayerLevels.MAXED, PlayerLevels.MAXED,
				PrayerUnlocks.ALL, null, new OwnedItems(Map.of(4151, 1), true), 1,
				false, false, "", Collections.emptySet(), -1,
				OptimizationRequest.DEFAULT_RISK_BUDGET_GP, false, Collections.emptySet(), 0,
				results -> { out.set(results); done.countDown(); });
			assertTrue(done.await(30, TimeUnit.SECONDS), "the compute must call back even when it throws");
			assertTrue(out.get().isEmpty(), "a failed compute answers empty: " + out.get().keySet());
		} finally {
			service.shutdown();
		}
	}
}

package com.loadoutlab.optimizer;

import com.loadoutlab.data.DataService;
