import com.loadoutlab.data.MonsterStats;
import com.loadoutlab.engine.CombatStyle;
import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import org.junit.jupiter.api.BeforeAll;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.assertNotNull;
import static org.junit.jupiter.api.Assertions.assertTrue;

/** Raid stipulations ride the group data (Andrew 2026-09-10: "it's probably
 * ok to have specific raid-specific stipulations for each grouping").
 * N's ToA reports (Discord 2026-09-09) are the bank shape here. */
class ToaStipulationsTest {
	private static LoadoutData data;
	private static List<MonsterStats> toa;

	@BeforeAll
	static void load() {
		data = new DataService().load();
		toa = MonsterGroups.load(data).stream().filter(g -> g.getName().equals("Tombs of Amascut"))
			.findFirst().orElseThrow().getMobs();
	}

	private static Map<Integer, Integer> bank() {
		Map<Integer, Integer> owned = new HashMap<>();
		for (String name : new String[]{"neitiznot faceguard", "fire cape", "amulet of rancour", "osmumten's fang",
			"crystal helm", "crystal body", "crystal legs", "barrows gloves", "primordial boots", "berserker ring (i)",
			"ava's assembler", "necklace of anguish", "bow of faerdhinen", "saradomin d'hide boots", "ring of shadows",
			"tumeken's shadow", "ahrim's robetop", "ahrim's robeskirt", "occult necklace", "imbued zamorak cape",
			"tormented bracelet", "eternal boots", "bandos chestplate", "bandos godsword", "dragon dagger", "noxious halberd"}) {
			owned.put(byName(name).getId(), 1);
		}
		return owned;
	}

	private static GearItem byName(String nameLower) {
		GearItem best = null;
		for (GearItem g : data.getGearItems()) {
			if (g.getNameLower().equals(nameLower) && g.isStandardGear()
				&& (best == null || "Charged".equals(g.getVersion()) || "Active".equals(g.getVersion())
					|| "Undamaged".equals(g.getVersion()) || "Normal".equals(g.getVersion()))) {
				best = g;
			}
		}
		if (best == null) {
			throw new AssertionError("missing from the gear data: " + nameLower);
		}
		return best;
	}

	private static OptimizerService.StyleResult result(OptimizerService.RosterResult roster, String nickPart, CombatStyle style) {
		for (int j = 0; j < roster.mobs.size(); j++) {
			if (roster.mobs.get(j).label().contains(nickPart)) {
				return roster.perMob.get(j).get(style);
			}
		}
		throw new AssertionError("no roster mob matching " + nickPart);
	}

	@Test
	@DisplayName("the Wardens' spec is the dragon dagger when one is banked, even with a godsword beside it")
	void wardensSpecIsTheDagger() throws Exception {
		OptimizerService service = new OptimizerService(data);
		try {
			OptimizerService.RosterResult roster = ServiceCalls.runRoster(service, toa, bank(), 16, Collections.emptyMap());
			OptimizerService.StyleResult core = result(roster, "Core", CombatStyle.MELEE);
			assertNotNull(core.specWeapon, "the core dump has a spec");
			assertTrue(core.specWeapon.getNameLower().contains("dragon dagger"), core.specWeapon.getName());
			// The kit carries ONE spec weapon for the trip, so the Wardens'
			// dagger rides every card - Ba-Ba included.
			OptimizerService.StyleResult baba = result(roster, "Ba-Ba", CombatStyle.MELEE);
			assertNotNull(baba.specWeapon);
			assertTrue(baba.specWeapon.getNameLower().contains("dragon dagger"), baba.specWeapon.getName());
		} finally {
			service.shutdown();
		}
	}

	@Test
	@DisplayName("at a ten-slot inventory the shared kit still dresses Elidinis' Warden P2 in the shadow set: the P2 Wardens weigh 3x")
	void wardenP2DecidesTheKit() throws Exception {
		OptimizerService service = new OptimizerService(data);
		try {
			OptimizerService.RosterResult roster = ServiceCalls.runRoster(service, toa, bank(), 10, Collections.emptyMap());
			OptimizerService.StyleResult p2 = result(roster, "Elidinis' Warden", CombatStyle.MAGIC);
			String worn = p2.owned.get(0).getLoadout().getGear().values().stream()
				.map(GearItem::getNameLower).collect(java.util.stream.Collectors.joining(", "));
			assertTrue(worn.contains("occult necklace"), worn);
			assertTrue(worn.contains("ahrim's robeskirt"), worn);
		} finally {
			service.shutdown();
		}
	}
}

package com.loadoutlab.optimizer;

import com.loadoutlab.engine.CandidateMode;
import com.loadoutlab.engine.CombatStyle;
import com.loadoutlab.engine.DpsCalculator;
import com.loadoutlab.engine.DpsResult;
import com.loadoutlab.engine.Loadout;
import com.loadoutlab.engine.OptimizationRequest;
import com.loadoutlab.engine.OwnedItems;
import com.loadoutlab.engine.PlayerLevels;
import com.loadoutlab.engine.PrayerBonuses;
import com.loadoutlab.engine.SpecialAttack;
import com.loadoutlab.engine.TestRequests;

import com.loadoutlab.data.DataService;
import com.loadoutlab.data.GearItem;
import com.loadoutlab.data.GearSlot;
import com.loadoutlab.data.LoadoutData;
import com.loadoutlab.data.MonsterDefences;
import com.loadoutlab.data.MonsterStats;
import java.util.Collections;
import java.util.EnumMap;
import org.junit.jupiter.api.BeforeAll;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import static org.junit.jupiter.api.Assertions.*;

/**
 * Division, the Tonalztics of ralos special (wiki-verified 2026-08-09):
 * 50% cost, +50% accuracy, two glaives, and each landed hit drains the
 * target's DEFENCE by 12.5% of its MAGIC level - modeled as 25% per
 * landed spec. It shines exactly where a DWH cannot reach (the wiki's
 * example: Zulrah's 300 Magic and Defence).
 */
class TonalzticsTest {
	private static LoadoutData data;

	@BeforeAll
	static void load() {
		data = new DataService().load();
	}

	private static GearItem byName(String nameLower, String version) {
		for (GearItem g : data.getGearItems()) {
			if (g.getNameLower().equals(nameLower)
				&& (version == null || version.equals(g.getVersion()))) {
				return g;
			}
		}
		throw new AssertionError("missing: " + nameLower);
	}

	@Test
	@DisplayName("the registry matches both charge states as a ranged drain spec")
	void registryMatch() {
		SpecialAttack charged = SpecialAttack.match(
			byName("tonalztics of ralos", "Charged"));
		assertNotNull(charged, "charged must carry Division");
		assertEquals(CombatStyle.RANGED, charged.getStyle());
		assertTrue(charged.drainsDefence(), "Division is a drain spec");
		assertEquals(50, charged.getEnergyCost());
	}

	@Test
	@DisplayName("the drain measures off the target's Magic level, floored at zero")
	void drainArithmetic() {
		SpecialAttack division = SpecialAttack.match(
			byName("tonalztics of ralos", "Charged"));
		// A Zulrah-shaped dummy: 300 Defence, 300 Magic -> one landed
		// spec removes 25% of 300 = 75 Defence.
		MonsterStats zulrahLike = new MonsterStats(
			-43, "Gaze Dummy", "", 500, 800, 3, 300, 300, 0,
			new MonsterDefences(150, 150, 150, 100, 0, 60, 60, 60),
			null, Collections.emptyList(), false, "", 0);
		assertEquals(225, division.drainedDefence(zulrahLike, 40.0));
		// A magic-1 target barely drains - the DWH's territory instead.
		MonsterStats brute = new MonsterStats(
			-44, "Brute Dummy", "", 500, 800, 3, 300, 1, 0,
			new MonsterDefences(150, 150, 150, 100, 0, 60, 60, 60),
			null, Collections.emptyList(), false, "", 0);
		assertEquals(300, division.drainedDefence(brute, 40.0));
	}

	@Test
	@DisplayName("Division earns positive drain value on a high-magic tank")
	void drainValue() {
		GearItem tonalztics = byName("tonalztics of ralos", "Charged");
		SpecialAttack division = SpecialAttack.match(tonalztics);
		MonsterStats zulrahLike = new MonsterStats(
			-43, "Gaze Dummy", "", 500, 800, 3, 300, 300, 0,
			new MonsterDefences(150, 150, 150, 100, 0, 60, 60, 60),
			null, Collections.emptyList(), false, "", 0);
		OptimizationRequest request = TestRequests.of(zulrahLike,
			CombatStyle.RANGED, PlayerLevels.MAXED,
			PrayerBonuses.bestAvailable(PlayerLevels.MAXED), null, 0,
			CandidateMode.ALL_STANDARD, true, false, OwnedItems.EMPTY, 1);

		EnumMap<GearSlot, GearItem> worn = new EnumMap<>(GearSlot.class);
		worn.put(GearSlot.WEAPON, byName("magic shortbow (i)", null));
		worn.put(GearSlot.AMMO, byName("amethyst arrow", null));
		DpsResult main = new DpsCalculator().calculate(request, new Loadout(worn));
		assertNotNull(main);

		EnumMap<GearSlot, GearItem> specWorn = new EnumMap<>(GearSlot.class);
		specWorn.put(GearSlot.WEAPON, tonalztics);
		DpsResult specBase = new DpsCalculator().calculate(request, new Loadout(specWorn));
		assertNotNull(specBase);
		double expected = division.expectedDamage(specBase, zulrahLike, PlayerLevels.MAXED);
		assertTrue(expected > 0, "two glaives must expect damage");

		OptimizerService service = new OptimizerService(data);
		try {
			double added = service.specDpsAdded(new DpsCalculator(), division,
				specBase, expected, request, main, false);
			assertTrue(added > 0,
				"draining 75 defence off a 300/300 tank must add dps: " + added);
		} finally {
			service.shutdown();
		}
	}
}

package com.loadoutlab.optimizer;

import com.loadoutlab.data.DataService;
import com.loadoutlab.data.GearItem;
import com.loadoutlab.data.LoadoutData;
import com.loadoutlab.data.MonsterStats;
import com.loadoutlab.engine.CombatStyle;
import com.loadoutlab.engine.OwnedItems;
import com.loadoutlab.engine.PlayerLevels;
import com.loadoutlab.engine.PrayerUnlocks;
import com.loadoutlab.engine.RequirementProfile;
import java.util.Collections;
import java.util.HashMap;
import java.util.Map;
import java.util.Set;
import java.util.concurrent.CountDownLatch;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicReference;
import org.junit.Assert;
import org.junit.Test;

/**
 * The Wardens' core is THE spec-dump phase (field report 2026-08-06:
 * "ToA is missing the crucial heart phase with the DDS spec") - with a
 * dagger in the bank, the melee card at the core must surface its spec
 * at a positive win-over-replacement.
 */
public class WardenCoreSpecTest {
	@Test
	public void ddsSpecSurfacesAtTheCore() throws Exception {
		LoadoutData data = new DataService().load();
		MonsterStats core = data.searchMonsters("tumeken's warden", 8).stream()
			.filter(m -> m.getVersion().startsWith("Core-ejected"))
			.findFirst().orElseThrow();

		GearItem dds = null;
		GearItem whip = null;
		GearItem chally = null;
		for (GearItem g : data.getGearItems()) {
			if (g.getNameLower().equals("dragon dagger") && g.isStandardGear()) {
				dds = g;
			}
			if (g.getNameLower().equals("abyssal whip")) {
				whip = g;
			}
			if (g.getNameLower().equals("crystal halberd") && g.isStandardGear()) {
				chally = g;
			}
		}
		Assert.assertNotNull(dds);
		Assert.assertNotNull(chally);

		// The chally competes and must LOSE: the 1x1 core denies its sweep
		// the second hit (field report 2026-08-06: "it should recommend DDS
		// instead of chally").
		Map<Integer, Integer> owned = new HashMap<>();
		owned.put(whip.getId(), 1);
		owned.put(dds.getId(), 1);
		owned.put(chally.getId(), 1);

		OptimizerService service = new OptimizerService(data);
		CountDownLatch done = new CountDownLatch(1);
		AtomicReference<Map<CombatStyle, OptimizerService.StyleResult>> out = new AtomicReference<>();
		Map<CombatStyle, Set<Integer>> excludedByStyle = new java.util.EnumMap<>(CombatStyle.class);
		ServiceCalls.bestPerStyle(service, core,
			PlayerLevels.MAXED, PlayerLevels.MAXED, PrayerUnlocks.ALL,
			RequirementProfile.MAXED, new OwnedItems(owned, true), 1,
			false, false, "", excludedByStyle, -1,
			com.loadoutlab.engine.OptimizationRequest.DEFAULT_RISK_BUDGET_GP,
			false, false, Collections.emptySet(), 0,
			Collections.emptyMap(), null, Collections.emptySet(),
			results -> {
				out.set(results);
				done.countDown();
			});
		Assert.assertTrue("compute timed out", done.await(120, TimeUnit.SECONDS));
		OptimizerService.StyleResult melee = out.get().get(CombatStyle.MELEE);
		Assert.assertNotNull(melee);
		Assert.assertNotNull("the dagger must enter the spec competition at the core",
			melee.specWeapon);
		Assert.assertTrue("the classic dump must be the pick, was: "
				+ melee.specWeapon.label(),
			melee.specWeapon.getNameLower().startsWith("dragon dagger"));
		Assert.assertTrue("the spec must price a positive win-over-replacement",
			melee.specDpsAdded > 0);
	}
}

package com.loadoutlab.optimizer;

import com.loadoutlab.data.DataService;
import com.loadoutlab.data.GearItem;
import com.loadoutlab.data.GearSlot;
import com.loadoutlab.data.LoadoutData;
import com.loadoutlab.data.MonsterStats;
import com.loadoutlab.engine.*;
import java.util.Collections;
import java.util.EnumMap;
import java.util.Map;
import java.util.concurrent.CountDownLatch;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicReference;
import org.junit.jupiter.api.BeforeAll;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import static org.junit.jupiter.api.Assertions.*;

/**
 * A weapon pin binds only its own styles (ISS-01M5TH7V74GYQKRN231XRCM6BE,
 * Andrew 2026-10-25, the Enraged Warden with a trident pinned: "i only have a
 * magic set availalbe but clearly have a more applicaable range set with the
 * bowfa").
 */
class WeaponPinStyleTest {
	private static LoadoutData data;

	@BeforeAll
	static void load() {
		data = new DataService().load();
	}

	private static int id(String name, String version) {
		return data.getGearItems().stream()
			.filter(g -> g.getNameLower().equals(name) && g.getVersion().equalsIgnoreCase(version))
			.findFirst().orElseThrow(() -> new AssertionError(name + " (" + version + ")")).getId();
	}

	private static String weapon(OptimizerService.StyleResult result) {
		GearItem weapon = result.owned.get(0).getLoadout().get(GearSlot.WEAPON);
		return weapon == null ? "none" : weapon.getNameLower();
	}

	@Test
	@DisplayName("a trident pinned for every style: magic wears it, ranged still builds with the bow of faerdhinen")
	void pinKeepsToItsStyle() throws Exception {
		MonsterStats warden = data.searchMonsters("tumeken's warden", 1).get(0);
		int trident = id("trident of the seas", "charged");
		int bowfa = id("bow of faerdhinen", "charged");
		OwnedItems owned = new OwnedItems(Map.of(trident, 1, bowfa, 1), true);
		Map<CombatStyle, Map<GearSlot, Integer>> pins = new EnumMap<>(CombatStyle.class);
		for (CombatStyle style : CombatStyle.values()) { pins.put(style, Map.of(GearSlot.WEAPON, trident)); }
		OptimizerService service = new OptimizerService(data);
		try {
			CountDownLatch done = new CountDownLatch(1);
			AtomicReference<Map<CombatStyle, OptimizerService.StyleResult>> out = new AtomicReference<>();
			service.bestPerStyle(warden, PlayerLevels.MAXED, PlayerLevels.MAXED, PrayerUnlocks.ALL,
				RequirementProfile.MAXED, owned, 1, new ComputeParams(), Collections.emptyMap(), Collections.emptySet(),
				pins, null, 0, Collections.<Integer>emptySet(), result -> {
					out.set(result);
					done.countDown();
				});
			assertTrue(done.await(300, TimeUnit.SECONDS));
			assertEquals("trident of the seas", weapon(out.get().get(CombatStyle.MAGIC)));
			OptimizerService.StyleResult ranged = out.get().get(CombatStyle.RANGED);
			assertFalse(ranged.owned.isEmpty(), "ranged still builds");
			assertEquals("bow of faerdhinen", weapon(ranged));
		} finally {
			service.shutdown();
		}
	}
}

package com.loadoutlab.profile;

import com.loadoutlab.data.GearItem;
import com.loadoutlab.data.LoadoutData;
import com.loadoutlab.engine.PlayerLevels;
import com.loadoutlab.engine.PrayerUnlocks;
import com.loadoutlab.engine.RequirementProfile;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import net.runelite.api.Skill;

/**
 * A deterministic mid-to-high level fixture account for benchmarks and
 * golden-output captures: 40+ bank items resolved BY NAME against the
 * loaded dataset (never hardcoded ids, so a data refresh cannot silently
 * shift the fixture to different items), mid-90s combat levels, piety and
 * rigour unlocked but not augury/deadeye.
 */
public final class FixtureBank {
	private static final String[] BANK_NAMES = {
		// Melee
		"Abyssal whip",
		"Dragon scimitar",
		"Dragon dagger",
		"Dragon defender",
		"Amulet of fury",
		"Amulet of glory",
		"Fire cape",
		"Barrows gloves",
		"Dragon boots",
		"Berserker ring",
		"Warrior ring",
		"Helm of neitiznot",
		"Fighter torso",
		"Dragon platelegs",
		"Bandos chestplate",
		"Bandos tassets",
		"Granite maul",
		// Ranged
		"Magic shortbow",
		"Rune crossbow",
		"Toxic blowpipe",
		"Rune arrow",
		"Adamant bolts",
		"Black d'hide body",
		"Black d'hide chaps",
		"Black d'hide vambraces",
		"Snakeskin boots",
		"Ava's accumulator",
		"Archers ring",
		// Magic
		"Mystic hat",
		"Mystic robe top",
		"Mystic robe bottom",
		"Mystic boots",
		"Mystic gloves",
		"Occult necklace",
		"Ancient staff",
		"Slayer's staff",
		"Trident of the seas",
		"Mage's book",
		"Seers ring",
		// Utility / defense
		"Ring of recoil",
		"Anti-dragon shield",
		"Toktz-ket-xil",
		"Rune kiteshield",
		"Rune platebody",
		"Rune platelegs",
	};

	private FixtureBank() {
	}

	public static PlayerProfile profile(LoadoutData data) {
		PlayerLevels levels = new PlayerLevels(90, 92, 85, 94, 89, 77, 90);
		PrayerUnlocks unlocks = new PrayerUnlocks(true, true, false, false, false);
		Map<Skill, Integer> reqLevels = new LinkedHashMap<>();
		reqLevels.put(Skill.ATTACK, 90);
		reqLevels.put(Skill.STRENGTH, 92);
		reqLevels.put(Skill.DEFENCE, 85);
		reqLevels.put(Skill.RANGED, 94);
		reqLevels.put(Skill.MAGIC, 89);
		reqLevels.put(Skill.PRAYER, 77);
		reqLevels.put(Skill.HITPOINTS, 90);
		reqLevels.put(Skill.SLAYER, 75);
		reqLevels.put(Skill.AGILITY, 70);
		reqLevels.put(Skill.CRAFTING, 70);
		reqLevels.put(Skill.FLETCHING, 70);
		reqLevels.put(Skill.HERBLORE, 70);
		reqLevels.put(Skill.CONSTRUCTION, 70);
		reqLevels.put(Skill.FARMING, 70);
		reqLevels.put(Skill.HUNTER, 70);
		reqLevels.put(Skill.THIEVING, 70);
		reqLevels.put(Skill.MINING, 70);
		reqLevels.put(Skill.SMITHING, 70);
		reqLevels.put(Skill.FISHING, 70);
		reqLevels.put(Skill.COOKING, 70);
		reqLevels.put(Skill.FIREMAKING, 70);
		reqLevels.put(Skill.WOODCUTTING, 70);
		reqLevels.put(Skill.RUNECRAFT, 60);
		RequirementProfile requirements = new RequirementProfile(
			reqLevels, RequirementProfile.MAXED.getCompletedQuests());
		return new PlayerProfile(levels, levels, unlocks, requirements, bank(data), true);
	}

	/** Item ids for the fixture bank, resolved by name; fails loudly on a miss. */
	public static Map<Integer, Integer> bank(LoadoutData data) {
		Map<Integer, Integer> owned = new LinkedHashMap<>();
		// Potions are consumables, not gear, so they cannot be resolved by name
		// from the equipment corpus - they go in by id.
		//
		// These are EXACTLY what the pre-0.4.1 rule assumed for free ("tradeable
		// potions are always assumed"). Boosts now gate on ownership, so a
		// fixture with tbow-tier gear and an empty potion shelf would have
		// silently dropped every golden to unboosted numbers. Stocking it keeps
		// the goldens exercising the boosted math AND makes the diff prove the
		// point: for a bank that HAS the potions, 0.4.1 changes nothing.
		owned.put(12695, 1);  // super combat potion(4)
		owned.put(2444, 1);   // ranging potion(4)
		owned.put(3040, 1);   // magic potion(4)
		// The premium combat runes, for the same reason - the spell gate (also
		// 0.4.1) drops blood/death/soul/wrath spells from a bank without
		// them, and a runeless fixture would quietly narrow the goldens to
		// strike spells. Stocked, they prove the gate changes nothing for a
		// player who HAS the runes.
		owned.put(565, 10000);   // blood rune
		owned.put(560, 10000);   // death rune
		owned.put(566, 10000);   // soul rune
		owned.put(21880, 10000); // wrath rune
		List<String> missing = new ArrayList<>();
		for (String name : BANK_NAMES) {
			GearItem item = firstByName(data, name);
			if (item == null) {
				missing.add(name);
			} else {
				owned.put(item.getId(), 1);
			}
		}
		if (!missing.isEmpty()) {
			throw new IllegalStateException("Fixture bank items not in dataset: " + missing);
		}
		return owned;
	}

	private static GearItem firstByName(LoadoutData data, String name) {
		GearItem fallback = null;
		for (GearItem item : data.getGearItems()) {
			if (!item.getName().equalsIgnoreCase(name) || !item.isStandardGear()
				|| data.isVariant(item.getId())) {
				continue;
			}
			if (item.getVersion().isEmpty()) {
				return item;
			}
			if (fallback == null) {
				fallback = item;
			}
		}
		return fallback;
	}
}

package com.loadoutlab.profile;

import com.loadoutlab.data.DataService;
import com.loadoutlab.data.GearItem;
import com.loadoutlab.data.GearSlot;
import com.loadoutlab.data.LoadoutData;
import com.loadoutlab.data.MonsterStats;
import com.loadoutlab.engine.CombatStyle;
import com.loadoutlab.engine.DpsResult;
import com.loadoutlab.engine.PvpRisk;
import com.loadoutlab.optimizer.OptimizerService;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.Map;
import java.util.concurrent.CountDownLatch;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicReference;

/**
 * The mock environment: run any Loadout Lab query from the command line
 * against a PlayerProfile - no client, no game login.
 *
 *   ./gradlew query -Pargs="vorkath"
 *   ./gradlew query -Pargs="callisto --low-risk 3 --slayer"
 *   ./gradlew query -Pargs="callisto --low-risk 3 --risk-budget 25000"
 *   ./gradlew query -Pargs="green dragon --profile /path/to/profile.json"
 *   ./gradlew query -Pargs="zulrah --maxed"
 *
 * Default profile: ~/.runelite/loadout-lab/profile.json (the plugin
 * exports your real account there on every in-game query). --maxed uses
 * a maxed account owning nothing (game-best only).
 */
public final class HeadlessQuery {
	private HeadlessQuery() {
	}

	public static void main(String[] args) throws Exception {
		System.out.println(run(args));
	}

	public static String run(String[] args) throws Exception {
		StringBuilder monsterName = new StringBuilder();
		Path profilePath = Path.of(System.getProperty("user.home"),
			".runelite", "loadout-lab", "profile.json");
		boolean maxed = false;
		boolean slayer = false;
		boolean f2p = false;
		boolean antifirePotion = false;
		boolean wilderness = false;
		String spellbook = "";
		int lowRisk = -1;
		int riskBudget = com.loadoutlab.engine.OptimizationRequest.DEFAULT_RISK_BUDGET_GP;
		int upgradeBudget = 0;
		java.util.Set<Integer> excluded = new java.util.HashSet<>();
		for (int i = 0; i < args.length; i++) {
			switch (args[i]) {
				case "--profile": profilePath = Path.of(args[++i]); break;
				case "--maxed": maxed = true; break;
				case "--slayer": slayer = true; break;
				case "--f2p": f2p = true; break;
				case "--antifire-potion": antifirePotion = true; break;
				case "--wilderness": wilderness = true; break;
				case "--spellbook": spellbook = args[++i]; break;
				case "--low-risk": lowRisk = Integer.parseInt(args[++i]); break;
				case "--risk-budget": riskBudget = Integer.parseInt(args[++i]); break;
				case "--budget": upgradeBudget = Integer.parseInt(args[++i]); break;
				// Comma-separated item ids - reproduce a client report with
				// the player's exclusion list (config: loadoutlab.excludedItems).
				case "--exclude":
					for (String id : args[++i].split(",")) {
						excluded.add(Integer.parseInt(id.trim()));
					}
					break;
				default: monsterName.append(monsterName.length() > 0 ? " " : "").append(args[i]);
			}
		}
		PlayerProfile profile = maxed ? PlayerProfileTestSupport.maxed()
			: PlayerProfile.fromJson(Files.readString(profilePath));

		LoadoutData data = new DataService().load();
		java.util.List<MonsterStats> hits = data.searchMonsters(monsterName.toString(), 1);
		if (hits.isEmpty()) {
			return "No monster matches '" + monsterName + "'";
		}
		MonsterStats monster = hits.get(0);

		OptimizerService service = new OptimizerService(data);
		try {
			CountDownLatch done = new CountDownLatch(1);
			AtomicReference<Map<CombatStyle, OptimizerService.StyleResult>> out = new AtomicReference<>();
			java.util.Map<CombatStyle, java.util.Set<Integer>> excludedByStyle =
				new java.util.EnumMap<>(CombatStyle.class);
			for (CombatStyle style : CombatStyle.concreteValues()) {
				excludedByStyle.put(style, excluded);
			}
			boolean inWilderness = wilderness
				|| com.loadoutlab.data.WildernessMonsters.isExclusive(monster);
			com.loadoutlab.optimizer.ServiceCalls.bestPerStyle(service, monster, profile.realLevels, profile.boostedLevels,
				profile.prayerUnlocks, profile.requirements, profile.ownedItems(),
				profile.owned.hashCode(), f2p, slayer, spellbook,
				excludedByStyle, lowRisk, riskBudget, antifirePotion, inWilderness,
				java.util.Collections.emptySet(), upgradeBudget,
				java.util.Collections.emptyMap(), null, java.util.Collections.emptySet(),
				results -> {
					out.set(results);
					done.countDown();
				});
			if (!done.await(180, TimeUnit.SECONDS)) {
				return "Query timed out";
			}
			return render(monster, out.get(), lowRisk);
		} finally {
			service.shutdown();
		}
	}

	private static String render(MonsterStats monster,
		Map<CombatStyle, OptimizerService.StyleResult> results, int lowRisk) {
		StringBuilder sb = new StringBuilder("=== vs ").append(monster.label()).append(" ===\n");
		for (CombatStyle style : new CombatStyle[]{CombatStyle.MELEE, CombatStyle.RANGED, CombatStyle.MAGIC}) {
			OptimizerService.StyleResult result = results.get(style);
			sb.append("\n[").append(style).append("]\n");
			if (result == null || result.owned.isEmpty()) {
				sb.append("  yours: no usable set\n");
			} else {
				DpsResult best = result.owned.get(0);
				sb.append(String.format("  yours: %.2f dps (max %d, %.0f%% acc)  assumes: %s%n",
					best.getDps(), best.getMaxHit(), best.getAccuracy() * 100, result.boostLabel));
				for (GearSlot slot : GearSlot.values()) {
					GearItem item = best.getLoadout().get(slot);
					if (item != null) {
						sb.append(String.format("    %-7s %s%n", slot, item.label()));
					}
				}
				if (best.getSpellName() != null) {
					sb.append("    spell   ").append(best.getSpellName()).append('\n');
				}
				if (result.specWeapon != null) {
					sb.append(String.format("    spec    %s (adds ~%.2f dps, avg %.0f dmg)%n",
						result.specWeapon.label(), result.specDpsAdded, result.specExpectedDamage));
				}
				if (result.incoming != null && result.incoming.protectPrayer != null) {
					sb.append(String.format("    incoming ~%.2f dps praying %s (~%.2f unprayed)%n",
						result.incoming.totalDps, result.incoming.protectPrayer,
						result.incoming.unprayedDps));
				}
				if (lowRisk >= 0) {
					PvpRisk.Assessment risk = PvpRisk.assess(best.getLoadout(), result.specWeapon, lowRisk);
					sb.append(String.format("    risk    %s gp (%d kept)%n",
						formatGp(risk.riskGp), lowRisk));
				}
			}
			if (result != null && result.overallBest != null) {
				sb.append(String.format("  game best: %.2f dps  assumes: %s%n",
					result.overallBest.getDps(), result.gameBoostLabel));
			}
		}
		return sb.toString();
	}

	/** Compact gp: 1.20B / 45.3M / 820k / 950. */
	private static String formatGp(long gp) {
		if (gp >= 1_000_000_000L) {
			return String.format("%.2fB", gp / 1_000_000_000.0);
		}
		if (gp >= 1_000_000L) {
			return String.format("%.1fM", gp / 1_000_000.0);
		}
		return gp >= 1_000L ? gp / 1_000L + "k" : String.valueOf(gp);
	}
}

package com.loadoutlab.profile;

import com.loadoutlab.engine.PlayerLevels;
import com.loadoutlab.engine.PrayerUnlocks;
import com.loadoutlab.engine.RequirementProfile;
import java.util.Map;
import java.util.Set;
import net.runelite.api.Skill;
import org.junit.Assert;
import org.junit.Test;

public class PlayerProfileTest {
	@Test
	public void aProfileSurvivesTheJsonRoundTripExactly() {
		PlayerProfile original = new PlayerProfile(
			new PlayerLevels(75, 80, 70, 85, 77, 52, 82),
			new PlayerLevels(80, 85, 70, 89, 77, 52, 82),
			new PrayerUnlocks(true, false, true, false, false),
			new RequirementProfile(Map.of(Skill.ATTACK, 75, Skill.SLAYER, 60),
				Set.of("Dragon Slayer I", "Monkey Madness I")),
			Map.of(4151, 1, 11832, 1, 12934, 5000),
			true);
		PlayerProfile copy = PlayerProfile.fromJson(original.toJson());
		Assert.assertEquals(75, copy.realLevels.getAttack());
		Assert.assertEquals(89, copy.boostedLevels.getRanged());
		Assert.assertTrue(copy.prayerUnlocks.piety());
		Assert.assertFalse(copy.prayerUnlocks.rigour());
		Assert.assertTrue(copy.prayerUnlocks.augury());
		Assert.assertEquals(Integer.valueOf(60), copy.requirements.getLevels().get(Skill.SLAYER));
		Assert.assertTrue(copy.requirements.getCompletedQuests().contains("Monkey Madness I"));
		Assert.assertEquals(Integer.valueOf(5000), copy.owned.get(12934));
		Assert.assertTrue(copy.bankScanned);
	}

	@Test
	public void theHeadlessRunnerAnswersAQueryWithoutAClient() throws Exception {
		String out = HeadlessQuery.run(new String[]{"vorkath", "--maxed"});
		Assert.assertTrue(out, out.contains("vs Vorkath"));
		Assert.assertTrue(out, out.contains("game best:"));
		Assert.assertTrue(out, out.contains("[Ranged]"));
	}

	@Test
	public void aMockUserWithABankDrivesOwnedResults() throws Exception {
		PlayerProfile mock = new PlayerProfile(PlayerLevels.MAXED, PlayerLevels.MAXED,
			PrayerUnlocks.ALL, RequirementProfile.MAXED,
			Map.of(4151, 1, 1712, 1), true);
		java.nio.file.Path file = java.nio.file.Files.createTempFile("profile", ".json");
		java.nio.file.Files.writeString(file, mock.toJson());
		String out = HeadlessQuery.run(new String[]{"goblin", "--profile", file.toString()});
		Assert.assertTrue(out, out.contains("Abyssal whip"));
		Assert.assertTrue(out, out.contains("Amulet of glory"));
	}

	/** Field report 2026-09-01: a 45-prayer account saw Piety after logging
	 * out - the snapshot was dropped and the MAXED fallback priced a
	 * stranger wearing its bank. Logout keeps the last character; only a
	 * different character replaces it. */
	@Test
	public void theLastCharactersSnapshotSurvivesLogoutButNotASwitch() {
		long me = 1234L;
		Assert.assertTrue("logout keeps the last character",
			PlayerProfile.snapshotSurvives(me, -1));
		Assert.assertTrue("same character re-login keeps it",
			PlayerProfile.snapshotSurvives(me, me));
		Assert.assertFalse("a different character replaces it",
			PlayerProfile.snapshotSurvives(me, 5678L));
		Assert.assertFalse("a hashless snapshot is replaced once the hash arrives",
			PlayerProfile.snapshotSurvives(-1, me));
	}
}

