package com.loadoutlab.profile;

import com.loadoutlab.data.DataService;
import com.loadoutlab.data.LoadoutData;
import com.loadoutlab.data.MonsterStats;
import com.loadoutlab.engine.CombatStyle;
import com.loadoutlab.optimizer.OptimizerService;
import java.util.Arrays;
import java.util.Collections;
import java.util.Locale;
import java.util.Map;
import java.util.concurrent.CountDownLatch;
import java.util.concurrent.TimeUnit;

/**
 * Wall-clock benchmark for the full optimizer path (patterned on
 * HeadlessQuery): times OptimizerService.bestPerStyle end-to-end for a
 * representative matrix of monsters x optimize modes x risk flags, using
 * the FixtureBank account. Warm JVM: one full untimed warmup pass, then
 * PASSES timed passes; the median per cell is reported.
 *
 *   ./gradlew benchmark
 */
public final class QueryBenchmark {
	private static final int[] RISKS = {-1, 3};
	private static final int PASSES = 3;

	private static String[] MONSTERS = {"general graardor", "zulrah", "callisto"};

	private QueryBenchmark() {
	}

	public static void main(String[] args) throws Exception {
		// Optional: --only <monster substring> narrows the matrix (profiling).
		for (int i = 0; i + 1 < args.length; i++) {
			if ("--only".equals(args[i])) {
				MONSTERS = new String[]{args[i + 1]};
			}
		}
		LoadoutData data = new DataService().load();
		PlayerProfile profile = FixtureBank.profile(data);
		OptimizerService service = new OptimizerService(data);
		int[] fingerprint = {1};
		try {
			// Warmup: one untimed full pass so the JIT sees every path.
			for (String monster : MONSTERS) {
				for (int risk : RISKS) {
					runOnce(service, data, profile, monster, risk, fingerprint);
				}
			}
			// The friction + pin cell: a revenant (salve territory) with the
			// salve owned AND pinned, risk-capped - the per-trial rebuild-veto
			// and pinned-risk-floor paths the standard matrix never touches.
			runPinnedSalve(service, data, profile, fingerprint);
			System.out.println("monster            risk  median_ms  passes_ms");
			for (String monster : MONSTERS) {
				for (int risk : RISKS) {
					long[] times = new long[PASSES];
					for (int pass = 0; pass < PASSES; pass++) {
						times[pass] = runOnce(service, data, profile, monster, risk, fingerprint);
					}
					long[] sorted = times.clone();
					Arrays.sort(sorted);
					System.out.println(String.format(Locale.ROOT,
						"%-18s %-5s %9d  %s",
						monster, risk < 0 ? "off" : ("lr" + risk),
						sorted[PASSES / 2], Arrays.toString(times)));
				}
			}
			long[] times = new long[PASSES];
			for (int pass = 0; pass < PASSES; pass++) {
				times[pass] = runPinnedSalve(service, data, profile, fingerprint);
			}
			long[] sorted = times.clone();
			Arrays.sort(sorted);
			System.out.println(String.format(Locale.ROOT,
				"%-18s %-5s %9d  %s",
				"rev demon+salvepin", "lr3",
				sorted[PASSES / 2], Arrays.toString(times)));
		} finally {
			service.shutdown();
		}
	}

	/**
	 * The risk-constrained + pinned scenario: revenant demon at lr3 with a
	 * salve amulet(ei) added to the fixture bank and pinned in every style.
	 * The salve is friction gear, so every trial runs the rebuild veto, and
	 * the pin keeps the pinned-risk-floor path live.
	 */
	private static long runPinnedSalve(OptimizerService service, LoadoutData data,
		PlayerProfile profile, int[] fingerprint) throws Exception {
		com.loadoutlab.data.GearItem salve = null;
		for (com.loadoutlab.data.GearItem item : data.getGearItems()) {
			if ("salve amulet(ei)".equalsIgnoreCase(item.getName())
				&& item.isStandardGear() && !data.isVariant(item.getId())) {
				salve = item;
				break;
			}
		}
		if (salve == null) {
			throw new IllegalStateException("salve amulet(ei) not in dataset");
		}
		java.util.Map<Integer, Integer> owned =
			new java.util.LinkedHashMap<>(profile.ownedItems().getQuantities());
		owned.put(salve.getId(), 1);
		java.util.Map<com.loadoutlab.engine.CombatStyle,
			java.util.Map<com.loadoutlab.data.GearSlot, Integer>> pins = new java.util.EnumMap<>(
			com.loadoutlab.engine.CombatStyle.class);
		for (com.loadoutlab.engine.CombatStyle style : com.loadoutlab.engine.CombatStyle.concreteValues()) {
			pins.put(style, java.util.Map.of(com.loadoutlab.data.GearSlot.NECK, salve.getId()));
		}
		MonsterStats monster = data.searchMonsters("revenant demon", 1).get(0);
		CountDownLatch done = new CountDownLatch(1);
		long start = System.nanoTime();
		com.loadoutlab.optimizer.ServiceCalls.bestPerStyle(service, monster, profile.realLevels, profile.boostedLevels,
			profile.prayerUnlocks, profile.requirements,
			new com.loadoutlab.engine.OwnedItems(owned, true),
			fingerprint[0]++, false, false, "",
			Collections.emptySet(), 3,
			com.loadoutlab.engine.OptimizationRequest.DEFAULT_RISK_BUDGET_GP, false,
			Collections.emptySet(), 0,
			pins, null,
			(Map<CombatStyle, OptimizerService.StyleResult> results) -> done.countDown());
		if (!done.await(600, TimeUnit.SECONDS)) {
			throw new IllegalStateException("benchmark cell timed out: pinned salve");
		}
		return (System.nanoTime() - start) / 1_000_000L;
	}

	private static long runOnce(OptimizerService service, LoadoutData data,
		PlayerProfile profile, String monsterName,
		int lowRisk, int[] fingerprint) throws Exception {
		MonsterStats monster = data.searchMonsters(monsterName, 1).get(0);
		CountDownLatch done = new CountDownLatch(1);
		long start = System.nanoTime();
		// A fresh fingerprint per run defeats the result cache, so every
		// run measures a full computation.
		com.loadoutlab.optimizer.ServiceCalls.bestPerStyle(service, monster, profile.realLevels, profile.boostedLevels,
			profile.prayerUnlocks, profile.requirements, profile.ownedItems(),
			fingerprint[0]++, false, false, "",
			Collections.emptySet(), lowRisk,
			com.loadoutlab.engine.OptimizationRequest.DEFAULT_RISK_BUDGET_GP, false,
			Collections.emptySet(), 0,
			(Map<CombatStyle, OptimizerService.StyleResult> results) -> done.countDown());
		if (!done.await(600, TimeUnit.SECONDS)) {
			throw new IllegalStateException("benchmark cell timed out: " + monsterName);
		}
		return (System.nanoTime() - start) / 1_000_000L;
	}
}

package com.loadoutlab.profile;

import com.loadoutlab.data.DataService;
import com.loadoutlab.data.LoadoutData;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.ArrayList;
import java.util.List;

/**
 * Golden-output capture: runs HeadlessQuery.run for the benchmark matrix
 * (monsters x optimize modes x risk flags), for both the maxed profile and
 * the FixtureBank account, and prints every rendered result with a header.
 * Redirect to a file and diff across changes - the optimizer contract is
 * that this output is byte-identical unless a behavior change is intended.
 *
 *   ./gradlew -q golden > golden.txt
 */
public final class QueryGolden {
	private static final String[] MONSTERS = {"general graardor", "zulrah", "callisto"};
	private static final String[] MODES = {"max_dps", "balanced"};
	private static final int[] RISKS = {-1, 3};

	/** The BROAD sweep: one config each, but across the monsters that
	 * trigger the engine's per-monster and per-item conditionals - undead
	 * (salve), dragonfire, slayer-only, golembane, vampyre, demonbane,
	 * wilderness/revenant, raid-supplied boosts, and the multi-form
	 * bosses. Every name here is one an existing test already resolves,
	 * so a miss means the corpus moved, not that the name was invented.
	 * This is the net under any change to DpsCalculator's conditionals. */
	private static final String[] BROAD = {
		"ankou", "aberrant spectre", "vorkath", "king black dragon", "green dragon",
		"revenant demon", "revenant dragon", "alchemical hydra", "tormented demon",
		"gargoyle", "dust devil", "kurask", "rockslug", "grey golem", "scurrius",
		"corporeal beast", "araxxor", "tekton", "great olm", "zebak", "kree'arra",
		"kril", "dusk", "dawn", "abomination", "hellhound", "goblin",
	};

	private QueryGolden() {
	}

	public static void main(String[] args) throws Exception {
		LoadoutData data = new DataService().load();
		PlayerProfile fixture = FixtureBank.profile(data);
		Path fixturePath = Files.createTempFile("loadout-lab-fixture", ".json");
		fixturePath.toFile().deleteOnExit();
		Files.writeString(fixturePath, fixture.toJson());

		System.out.println("fixture bank ids: " + FixtureBank.bank(data).keySet());
		for (String profileKind : new String[]{"maxed", "fixture"}) {
			for (String monster : MONSTERS) {
				for (String mode : MODES) {
					for (int risk : RISKS) {
						List<String> query = new ArrayList<>();
						for (String word : monster.split(" ")) {
							query.add(word);
						}
						if ("maxed".equals(profileKind)) {
							query.add("--maxed");
						} else {
							query.add("--profile");
							query.add(fixturePath.toString());
						}
						query.add("--mode");
						query.add(mode);
						if (risk >= 0) {
							query.add("--low-risk");
							query.add(String.valueOf(risk));
						}
						System.out.println("##### " + profileKind + " | " + monster
							+ " | " + mode + " | risk=" + (risk < 0 ? "off" : risk));
						System.out.println(HeadlessQuery.run(query.toArray(new String[0])));
					}
				}
			}
		}

		// The BROAD conditional sweep: both profiles, max dps, risk off.
		for (String profileKind : new String[]{"maxed", "fixture"}) {
			for (String monster : BROAD) {
				List<String> query = new ArrayList<>();
				for (String word : monster.split(" ")) {
					query.add(word);
				}
				if ("maxed".equals(profileKind)) {
					query.add("--maxed");
				} else {
					query.add("--profile");
					query.add(fixturePath.toString());
				}
				System.out.println("##### broad | " + profileKind + " | " + monster);
				System.out.println(HeadlessQuery.run(query.toArray(new String[0])));
			}
		}
	}
}

package com.loadoutlab.profile;

import com.loadoutlab.data.DataService;
import com.loadoutlab.data.GearItem;
import com.loadoutlab.data.GearSlot;
import com.loadoutlab.data.LoadoutData;
import com.loadoutlab.data.MonsterGroups;
import com.loadoutlab.data.MonsterStats;
import com.loadoutlab.engine.CombatStyle;
import com.loadoutlab.engine.DpsResult;
import com.loadoutlab.engine.OptimizationRequest;
import com.loadoutlab.engine.PlayerLevels;
import com.loadoutlab.engine.PrayerUnlocks;
import com.loadoutlab.engine.RequirementProfile;
import com.loadoutlab.optimizer.OptimizerService;
import java.util.Collections;
import java.util.List;
import java.util.Map;
import java.util.concurrent.CountDownLatch;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicReference;

/**
 * Golden-output capture for the ROSTER path - the multi-mob canvas that
 * {@link QueryGolden} (single-mob only) never touches: bestPerStyleAcross,
 * the cross-style kit search, slot/ammo unification and per-mob spec
 * picks. Together with QueryGolden this is the behaviour net a refactor of
 * OptimizerService or the engine must not move.
 *
 * Prints, per curated group and bench size, every mob's per-style answer
 * (worn set, spec, dps) plus the shared kit.
 *
 *   ./gradlew -q rosterGolden > roster-golden.txt
 *
 * The contract: byte-identical output unless a behaviour change is intended.
 */
public final class RosterGolden {
	/** Curated groups chosen for path coverage: multi-style immunities and
	 * synthetic phase variants (TDs, Grotesque Guardians), raid-supplied
	 * boosts (CoX/ToA), a wilderness roster (risk model), and a plain
	 * multi-mob roster. Resolved by name against the curated list - a name
	 * that stops resolving fails loudly rather than silently shrinking
	 * the matrix. */
	private static final String[] GROUPS = {
		"Tormented Demons",
		"Grotesque Guardians",
		"Chambers of Xeric",
		"Tombs of Amascut",
		"Dagannoth Kings",
		"Royal Titans",
	};

	/** Bench sizes: 0 = strictly one worn set (no carried swaps), 1 = the
	 * pre-bench default, 3 = a small tribrid kit, 8 = the raid preset. */
	private static final int[] BENCHES = {0, 1, 3, 8};

	private RosterGolden() {
	}

	public static void main(String[] args) throws Exception {
		LoadoutData data = new DataService().load();
		List<MonsterGroups.MonsterGroup> groups = MonsterGroups.load(data);
		PlayerProfile fixture = FixtureBank.profile(data);

		for (String wanted : GROUPS) {
			MonsterGroups.MonsterGroup group = null;
			for (MonsterGroups.MonsterGroup candidate : groups) {
				if (candidate.getName().equalsIgnoreCase(wanted)) {
					group = candidate;
					break;
				}
			}
			if (group == null) {
				System.out.println("##### MISSING GROUP: " + wanted);
				continue;
			}
			for (int bench : BENCHES) {
				System.out.println("##### " + group.getName() + " | mobs=" + group.getMobs().size()
					+ " | bench=" + bench);
				System.out.println(run(data, group.getMobs(), fixture, bench));
			}
		}
	}

	private static String run(LoadoutData data, List<MonsterStats> mobs,
		PlayerProfile profile, int bench) throws Exception {
		OptimizerService service = new OptimizerService(data);
		try {
			CountDownLatch done = new CountDownLatch(1);
			AtomicReference<OptimizerService.RosterResult> out = new AtomicReference<>();
			com.loadoutlab.optimizer.ServiceCalls.bestPerStyleAcross(service, mobs,
				profile.realLevels, profile.boostedLevels, profile.prayerUnlocks,
				profile.requirements, profile.ownedItems(), profile.owned.hashCode(),
				false, false, "", Collections.emptyMap(), -1,
				OptimizationRequest.DEFAULT_RISK_BUDGET_GP, false, false,
				Collections.emptySet(), 0, bench,
				Collections.emptyMap(), null, Collections.emptySet(),
				roster -> {
					out.set(roster);
					done.countDown();
				});
			if (!done.await(300, TimeUnit.SECONDS)) {
				return "roster query timed out";
			}
			return render(out.get());
		} finally {
			service.shutdown();
		}
	}

	private static String render(OptimizerService.RosterResult roster) {
		StringBuilder sb = new StringBuilder();
		for (int i = 0; i < roster.mobs.size(); i++) {
			sb.append("--- ").append(roster.mobs.get(i).label()).append('\n');
			Map<CombatStyle, OptimizerService.StyleResult> perStyle = roster.perMob.get(i);
			for (CombatStyle style : new CombatStyle[]{CombatStyle.MELEE, CombatStyle.RANGED, CombatStyle.MAGIC}) {
				OptimizerService.StyleResult result = perStyle == null ? null : perStyle.get(style);
				sb.append("  [").append(style).append("] ");
				if (result == null || result.owned == null || result.owned.isEmpty()) {
					sb.append("no usable set\n");
					continue;
				}
				DpsResult best = result.owned.get(0);
				sb.append(String.format("%.4f dps (max %d, %.1f%% acc) assumes: %s%n",
					best.getDps(), best.getMaxHit(), best.getAccuracy() * 100, result.boostLabel));
				sb.append("      worn:");
				for (GearSlot slot : GearSlot.values()) {
					GearItem item = best.getLoadout().get(slot);
					if (item != null) {
						sb.append(' ').append(item.label()).append(',');
					}
				}
				sb.append('\n');
				if (best.getSpellName() != null) {
					sb.append("      spell: ").append(best.getSpellName()).append('\n');
				}
				if (result.specWeapon != null) {
					sb.append(String.format("      spec: %s (adds ~%.3f dps, avg %.2f)%n",
						result.specWeapon.label(), result.specDpsAdded, result.specExpectedDamage));
				}
				sb.append("      inventory:");
				for (GearItem carried : result.bench == null ? List.<GearItem>of() : result.bench) {
					sb.append(' ').append(carried.label()).append(',');
				}
				sb.append('\n');
				if (result.overallBest != null) {
					sb.append(String.format("      game best: %.4f%n", result.overallBest.getDps()));
				}
			}
		}
		return sb.toString();
	}
}

package com.loadoutlab.render;

import java.awt.Font;
import java.awt.FontMetrics;
import java.awt.image.BufferedImage;
import java.io.InputStream;
import java.nio.charset.StandardCharsets;
import java.util.LinkedHashSet;
import java.util.Set;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import static org.junit.jupiter.api.Assertions.*;

/**
 * Andrew (2026-10-15), first run on a Windows client: "oof the animation is
 * fucked up" - the flask mood's rows slid sideways. Java's logical Monospaced
 * font there draws ASCII in Courier New at one width and borrows Braille,
 * block elements and shades from Segoe UI Symbol at others. The moods are
 * drawn for one advance width (the Mac's Menlo), so the plugin bundles a face
 * that has the whole alphabet at one width (DejaVu Sans Mono, Menlo's
 * ancestor, turned out to have no Braille) and every platform draws the same.
 */
class AsciiLoaderFontTest {
	private static final String FRAMES = "/com/loadoutlab/render/loader_frames.txt";

	@Test
	@DisplayName("the art draws in DejaVu Sans Mono (Menlo's parent: the shades the frames were tuned on) and Braille in Cascadia Mono")
	void bundledFontsLoad() {
		// Andrew (2026-10-15): "looks better shape wise but the color tone is off in the
		// potion" - Cascadia's medium shade inks 21% of its cell, DejaVu's 48%.
		Font art = AsciiLoader.moodFont();
		assertEquals("DejaVu Sans Mono", art.getFamily(), "the art face, not a platform fallback");
		assertEquals(12, art.getSize());
		assertEquals("Cascadia Mono", AsciiLoader.BRAILLE_FONT.getFamily());
		assertTrue(shadeInk(art, '\u2592') >= 0.40, "the medium shade must read dark: " + shadeInk(art, '\u2592'));
	}

	/** Ink coverage of one glyph's cell at 12 pt, 0..1. */
	private static double shadeInk(Font font, char glyph) {
		BufferedImage img = new BufferedImage(20, 24, BufferedImage.TYPE_INT_ARGB);
		java.awt.Graphics2D g = img.createGraphics();
		g.setFont(font);
		g.setColor(java.awt.Color.WHITE);
		FontMetrics m = g.getFontMetrics();
		g.drawString(String.valueOf(glyph), 2, m.getAscent() + 2);
		g.dispose();
		long ink = 0;
		for (int y = 0; y < img.getHeight(); y++) {
			for (int x = 0; x < img.getWidth(); x++) {
				ink += img.getRGB(x, y) >>> 24;
			}
		}
		return ink / 255.0 / (m.charWidth(glyph) * (m.getAscent() + m.getDescent()));
	}

	@Test
	@DisplayName("every distinct character of the frames resource is drawable, at one advance width")
	void framesFitTheFont() throws Exception {
		Font font = AsciiLoader.moodFont();
		Font braille = AsciiLoader.BRAILLE_FONT;
		Set<Integer> glyphs = new LinkedHashSet<>();
		try (InputStream in = AsciiLoaderFontTest.class.getResourceAsStream(FRAMES)) {
			assertNotNull(in, "frames resource");
			String text = new String(in.readAllBytes(), StandardCharsets.UTF_8);
			text.codePoints().filter(cp -> cp > ' ' && cp != '\n' && cp != '\r').forEach(glyphs::add);
		}
		// Frames are HTML: tags and entities are not glyphs.
		glyphs.removeIf(cp -> cp == '<' || cp == '>' || cp == '&' || cp == ';' || cp == '=' || cp == '\'' || cp == '"');
		assertTrue(glyphs.size() > 50, "the frames use a real alphabet: " + glyphs.size());
		FontMetrics metrics = new BufferedImage(8, 8, BufferedImage.TYPE_INT_ARGB).createGraphics().getFontMetrics(font);
		int width = metrics.charWidth('M');
		StringBuilder missing = new StringBuilder();
		StringBuilder uneven = new StringBuilder();
		FontMetrics brailleMetrics = new BufferedImage(8, 8, BufferedImage.TYPE_INT_ARGB).createGraphics().getFontMetrics(braille);
		for (int cp : glyphs) {
			// Braille cells draw in the Braille face; everything else in the art face.
			boolean isBraille = cp >= 0x2800 && cp <= 0x28FF;
			Font face = isBraille ? braille : font;
			int w = (isBraille ? brailleMetrics : metrics).charWidth(cp);
			if (!face.canDisplay(cp)) {
				missing.append(String.format(" U+%04X", cp));
			} else if (w != width) {
				uneven.append(String.format(" U+%04X=%d", cp, w));
			}
		}
		assertEquals("", missing.toString(), "glyphs the font cannot draw");
		assertEquals("", uneven.toString(), "glyphs drawn at a width other than " + width);
	}

	@Test
	@DisplayName("a frame's lines end at the same x whatever glyph class they use - the pre element draws in the bundled face")
	void preDrawsInTheBundledFace() throws Exception {
		// Andrew (2026-10-15), after the bundled font: "the animation of the flask
		// is still bad". Swing's stylesheet gives pre its own font-family rule,
		// which overrode the component font the pane was given.
		AsciiLoader loader = new AsciiLoader();
		loader.show("ABCDEFGHIJ\n" + "█".repeat(10) + "\n" + "⣿".repeat(10) + "\n" + "░".repeat(10));
		loader.setSize(400, 200);
		String text = loader.getDocument().getText(0, loader.getDocument().getLength());
		Set<Integer> ends = new LinkedHashSet<>();
		Set<Integer> heights = new LinkedHashSet<>();
		int start = 0;
		for (int i = 0; i <= text.length(); i++) {
			if (i == text.length() || text.charAt(i) == '\n') {
				if (i > start) {
					ends.add((int) loader.modelToView2D(i).getX());
					heights.add((int) loader.modelToView2D(start).getHeight());
				}
				start = i + 1;
			}
		}
		assertEquals(1, ends.size(), "line ends at x = " + ends);
		assertEquals(1, heights.size(), "a Braille row must not be taller than the others: " + heights);
	}
}

package com.loadoutlab.render;

import java.util.List;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import static org.junit.jupiter.api.Assertions.*;

class AsciiLoaderTest {
	@Test
	@DisplayName("the frames resource parses into steady-sized moods")
	void framesParseSteady() {
		List<List<String>> land = new java.util.ArrayList<>();
		java.util.Map<String, List<List<String>>> pools = new java.util.HashMap<>();
		AsciiLoader.load(land, pools);
		assertFalse(land.isEmpty());
		List<List<String>> sea = pools.getOrDefault("sea", List.of());
		assertFalse(sea.isEmpty(), "the sea pool ships with at least one mood");
		// Raid pools (Andrew 2026-09-02: "hit raids first"): the Obelisk is
		// hand-drawn; Verzik, Olm and Zulrah are Braille renders of the real
		// wiki sprites ("make these look like the actual monster sprites").
		for (String key : new String[]{"toa", "tob", "cox", "tfa", "zulrah", "cerberus", "brutus", "dbrutus", "madangel", "guardians", "kraken", "thermy", "vetion", "kbd", "kq", "muspah", "jad", "zuk", "dks", "barrows", "moons", "tormented", "gorilla", "sire", "sol", "hunllef", "huey", "nex", "titans", "maggot", "yama", "scurrius", "obor", "bryophyta", "crab", "duke", "vardorvis", "leviathan", "whisperer", "callisto", "artio", "venenatis", "spindel", "scorpia", "chaos", "drgreen", "drblue", "drred", "drblack", "drmetal", "vorkath", "hydra", "araxxor", "fanatic", "graardor", "kree", "kril", "zilyana", "corp", "archaeologist", "doom", "nightmare", "mimic", "shaman", "hespori", "sarachnis", "gryphon", "skotizo"}) {
			assertFalse(pools.getOrDefault(key, List.of()).isEmpty(), key + " pool has a mood");
		}
		// Three sea moods (sail, cannon, kraken - Andrew 2026-09-02) at the
		// land flask's 19x9, so the compute block keeps one shape.
		assertEquals(3, sea.size(), "sail, cannon, kraken");
		boolean wideMood = false;
		for (List<String> frames : sea) {
			String[] lines = frames.get(0).split("\n");
			assertEquals(12, lines.length, "sea frames are 12 rows like every mood since pass eight");
			assertTrue(lines[0].length() >= 19, "sea frames are at least the flask's width");
			wideMood |= lines[0].length() > 19;
		}
		// The cannon mood spreads out so the shot has a real trajectory
		// (Andrew 2026-09-02); moods may differ in width, one plays per compute.
		assertTrue(wideMood, "the cannon mood is wider than the flask");
		List<List<String>> moods = new java.util.ArrayList<>(land);
		for (List<List<String>> pool : pools.values()) {
			moods.addAll(pool);
		}
		for (List<String> frames : moods) {
			assertTrue(frames.size() > 1, "a mood animates - two frames minimum");
			String[] first = frames.get(0).split("\n");
			for (String frame : frames) {
				String[] lines = frame.split("\n");
				// Same height and width every frame, or the centred
				// block wobbles mid-animation.
				assertEquals(first.length, lines.length, "frame height drifted");
				for (String line : lines) {
					line = line.replaceAll("<[^>]*>", "");
					assertEquals(first[0].replaceAll("<[^>]*>", "").length(), line.length(), "frame width drifted");
					for (char c : line.toCharArray()) {
						// ASCII, or the Braille block: the sprite renders use
						// U+2800 dots for detail. Braille is the ONE exception
						// to the ASCII rule, pending Andrew's tofu check in the
						// client (Swing on macOS Tahoe boxed symbol glyphs once).
						boolean braille = c >= 0x2800 && c <= 0x28FF;
						boolean block = c >= 0x2580 && c <= 0x259F;  // solid fills by brightness
						// CP437 flavour (Andrew 2026-09-02): double box strokes and
						// corners, the triple bar, and yen for scale texture.
						boolean cp437 = (c >= 0x2550 && c <= 0x256C) || c == 0x2261 || c == 0xA5;
						assertTrue((c >= 32 && c < 127) || braille || block || cp437,
							"frame char outside the palette: " + (int) c);
					}
				}
			}
		}
	}

	@Test
	@DisplayName("the loader is an HTML pane, so a frame's cells can carry their own colours")
	void loaderDrawsHtml() {
		javax.swing.text.JTextComponent pane = new AsciiLoader();
		assertTrue(pane instanceof javax.swing.JEditorPane, "frames are HTML (Andrew 2026-09-03: colour per pixel at zero cost)");
	}
}

